import java.util.Scanner

object KMP {
  // i 番目の直前 res(i) 文字が先頭の res(i) 文字と等しい
  def table(w: Array[Int]): Array[Option[Int]] = {
    val n = w.length
    val res = Array.fill[Option[Int]](n+1)(None)
    var i = 2
    for (i <- 2 to n) {
      res(i-1) match {
        case Some(l) => if (w(i-1) == w(l)) res(i) = Some(l+1)
                        else res(i) = None
        case None => if (w(i-1) == w(0)) res(i) = Some(1)
                     else res(i) = None
      }
    }
    res
  }
  def enumerate(s: List[Int], w: List[Int]): List[Int] = {
    val ss = s.toArray
    val ww = w.toArray
    var m = 0
    var i = 0
    var res = List[Int]()
    val t = table(ww)
    while (m + i < ss.length) {
      if (ss(m+i) == ww(i)) {
        i += 1
        if (i == ww.length) {
          res = m :: res
          m = m + i - t(i).getOrElse(0)
          i = t(i).getOrElse(0)
        }
      } else {
        m = m + i - t(i).getOrElse(-1)
        i = t(i).getOrElse(0)
      }
    }
    res.reverse
  }
}

case class Input(as: List[Int], bs: List[Int]) {
  def solved: Output = {
    val n = as.length
    val a = as.toArray
    val cs = List.tabulate(n)(i => a(i) ^ a((i+1)%n))
    val b = bs.toArray
    val ds = List.tabulate(2*n-1)(i => b(i%n) ^ b((i+1)%n))
    val ks = KMP.enumerate(ds, cs).map(k => (n-k)%n).sorted
    Output(ks.map(k => (k, a(k%n)^b(0))))
  }
}

