  class KMP(word: Array[Long]) {
    private[this] val kmp: Array[Int] = Array.ofDim[Int](word.length + 1)
    2 to word.length foreach { i =>
      // kmp(i-1)以下しか参照されないからOK
      kmp(i) = longestPrefix(kmp(i - 1), word(i - 1))
    }

    def findMatches(text: Array[Long]): ArrayBuffer[Int] = {
      val res = ArrayBuffer[Int]()
      var j = 0
      REP(text.length) { i =>
        j = longestPrefix(j, text(i))
        if (j == word.length) res += i - word.length + 1
      }
      res
    }

    def longestPrefix(matched: Int, c: Long): Int = {
      var j = matched
      var continues = true
      while(continues) {
        if (j < word.length && word(j) == c) {
          j += 1
          continues = false
        } else if (j == 0) continues = false
        else j = kmp(j)
      }
      j
    }

    def getKmp = kmp
  }
}

