struct RollingHash {
	vector<T>hash[2], p[2];
	T MOD[2] = { MOD1,MOD2 };
	T B[2] = { B1,B2 };
	//RollingHash(const string &s) {
	//	int N = s.size();
	//	for (int k = 0; k < 2; k++) {
	//		hash[k].assign(N + 1, 0);
