vector<bool> check(ll N, VLL A, VLL B) {
	ull a = 0;
	for (ll n = 0; n < N; n++) {
		a = a * MOD + A[n];
	}
	ull t = 1;
	for (ll n = 0; n < N-1; n++)t *= MOD;
	vector<bool> flags(N, false);
	ull b = 0;
	for (ll n = 0; n < N; n++) {
		b = b*MOD + B[n];
	}
	for (ll n = 0; n < N; n++) {
		if (a == b)flags[n] = (flags[n] | true);
		a -= A[n] * t;
		a *= MOD;
		a += A[n + N];
	}
	b = 0;
	for (ll n = 0; n < N; n++) {
		b = b * MOD + (1-B[n]);
	}
	for (ll n = 0; n < N; n++) {
		if (a == b)flags[n] = (flags[n] | true);
		a -= A[n] * t;
		a *= MOD;
		a += A[n + N];
	}
	return flags;
}

