const size_t SIZE = 2e5 + 10;
ll A[SIZE], B[SIZE], C[3 * SIZE], Z[3 * SIZE];
ll N;

void z() {
    Z[0] = 3 * SIZE;
    ll i = 1, j = 0;
    while (i < 3 * SIZE) {
        while (i+j < 3 * SIZE && C[j] == C[i+j]) ++j;
        Z[i] = j;
        if (j == 0) { ++i; continue;}
        ll k = 1;
        while (i+k < 3 * SIZE && k+Z[k] < j) Z[i+k] = Z[k], ++k;
        i += k; j -= k;
    }
}

int main() {
    cin >> N;
    for (ll i = 0; i < N; i++) cin >> A[i];
    for (ll i = 0; i < N; i++) cin >> B[i];
    for (ll i = 0; i < N; i++) {
        C[i] = A[i] ^ A[(i + 1) % N];
        C[i + N] = C[i + 2 * N] = B[i] ^ B[(i + 1) % N];
    }

    z();
    V<PLL> ans;
    for (ll i = N; i < 2 * N; i++) {
        if (Z[i] < N) continue;
        ll a = A[0], b = B[i % N];
        ans.emplace_back((N - i % N) % N, (a ^ b));
    }
    sort(ALL(ans));
    for (PLL p : ans) {
        ll a, b;
        tie(a, b) = p;
        cout << a << ' ' << b << endl;
    }
    return 0;
}

