template<class T> vll KMP(const T &s, const T &t){
	ll N=(ll)s.size(), M=(ll)t.size(), j=-1, m=0, i=0;
	vll table(M+1, -1), ret;
	REP(k, M){
		while (j>=0 && t[k]!=t[j]) j=table[j];
		table[k+1] = ++j;
	}
	while (m+i < N){
		if (t[i] == s[m+i]) {
			if (++i == M) {
				ret.push_back(m);
				m = m+i-table[i];
				i = table[i];
			}
		}
		else {
			m = m+i-table[i];
			if (i > 0) i = table[i];
		}
	}
	return move(ret);
}

void solve()
{
	ll N;  cin >> N;
	vector<ll> a = cinv<ll>(N);
	vector<ll> b = cinv<ll>(N);
	if (N==1){
		ll k = 0;
		ll x = a[0]^b[0];
		cout << k << " " << x << '\n';
	}

	vll bb(N);
	rep(i, 0, N-1){
		bb[i] = b[i]^b[(i+1)%N];
	}
	vll aa(N);
	rep(i, 0, N-1){
		aa[i] = a[i]^a[(i+1)%N];
	}

	vll bbb = bb;
	bbb.insert(bbb.end(), bb.begin(), bb.end()-1);

	vll idxes = KMP(bbb, aa);
	ll sz = Size(idxes);

	vpll ans;
	dep(i, 0, sz-1){
		ll kk = idxes[i];
		ll x = a[0] ^ b[kk];
		ll k = (N-kk)%N;
		ans.emplace_back(k,x);
	}
	sort(ALL(ans));
	EACH(e, ans){
		cout << e.first << " " << e.second << '\n';
	}
}


int main(){
	solve();
	return 0;
}

