    RollingHash<> hash1A({}, b1), hash1B({}, b1);
    auto eq = [&](int la, int ra, int lb, int rb){
        int64_t v1A = hash1A.between(la, ra);
        int64_t v1B = hash1B.between(lb, rb);
        return (v1A == v1B);
    };

    for(int k=0; k<30; k++){
