	ll z = 100,ex[2][200010];
	vector<ll> v,w[2];
	rolling_hash(vector<ll> &s){
		int i,j,n = s.size();
		for(i=0;i<n;i++){
			v.push_back(s[i] + 1);
		}
		w[0].assign(n + 1,0),w[1].assign(n + 1,0);
		ex[0][0] = 1,ex[1][0] = 1;
		for(i=0;i<n;i++){
			for(j=0;j<2;j++){
				w[j][i + 1] = (w[j][i]*z + v[i])%mod[j];
				ex[j][i + 1] = ex[j][i]*z%mod[j];
			}
