    auto fail = get_fail(pattern.data(), n);
    rng(j, 0, 2) {
      vi t(2 * n - 1);
      rng(k, 0, 2 * n - 1) { t[k] = get_bit(a[k], i) ^ j; }
      auto shifts = KMP_match(pattern.data(), n, t.data(), 2 * n - 1, fail);
      FOR(x, shifts) { match[i][x] = j; }
    }
  }
  rng(k, 0, n) {
