struct LLRollingHash {
// long long に対するRollingHash
public:
    ll n1, n2;
    ll max_n;
    ll base1, base2;
    ll mod1, mod2;
    vector<ll> base_table = {128ll, 243ll, 125ll,
                             1340132568ll, 1025585316ll, 216ll};
    vector<ll> mod_table =  {2000000011ll, 2000000033ll, 2000000063ll,
                             2147467057ll, 2147483353ll, 3000001811ll};
    vector<ll> base1_pow, base2_pow;
    vector<ll> table11, table12, table21, table22;

    LLRollingHash(vector<ll> v1, vector<ll> v2) {
        n1 = v1.size();
        n2 = v2.size();
        max_n = max(n1, n2);
        table11.resize(n1 + 1, 0ll);table12.resize(n1 + 1, 0ll);
        table21.resize(n2 + 1, 0ll);table22.resize(n2 + 1, 0ll);
        base1_pow.resize(max_n + 1, 1ll);base2_pow.resize(max_n + 1, 1ll);
        ll idx1 = clock() % 3, idx2 = 3 + clock() % 3;
        base1 = base_table[idx1], base2 = base_table[idx2];
        mod1 = mod_table[idx1], mod2 = mod_table[idx2];
        ll tmp1 = 0, tmp2 = 0;
        for(ll i=0;i<n1;i++){
            tmp1 = tmp1 * base1 + v1[i];
            tmp2 = tmp2 * base2 + v1[i];
            tmp1 %= mod1;
            tmp2 %= mod2;
            table11[i+1] = tmp1;
            table12[i+1] = tmp2;
        }
        tmp1 = 0; tmp2 = 0;
        for(ll i=0;i<n2;i++){
            tmp1 = tmp1 * base1 + v2[i];
            tmp2 = tmp2 * base2 + v2[i];
            tmp1 %= mod1;
            tmp2 %= mod2;
            table21[i+1] = tmp1;
            table22[i+1] = tmp2;
        }
        for(ll i=0;i<max_n;i++){
            base1_pow[i+1] = (base1_pow[i] * base1) % mod1;
            base2_pow[i+1] = (base2_pow[i] * base2) % mod2;
        }

    }

    bool check(ll n, ll idx1, ll idx2){
        // 一つ目の配列のidx1番目(0-index)からn文字と
        // 二つ目の配列のidx2番目(0-index)からn文字が一致するかどうかを確かめる
        assert(idx1 + n <= n1);
        assert(idx2 + n <= n2);
        ll mod1pow = mod1 - base1_pow[n];
        ll mod2pow = mod2 - base2_pow[n];
        ll hash11, hash12, hash21, hash22;
        hash11 = (table11[n + idx1] + (table11[idx1] * mod1pow)) % mod1;
        hash12 = (table12[n + idx1] + (table12[idx1] * mod2pow)) % mod2;
        hash21 = (table21[n + idx2] + (table21[idx2] * mod1pow)) % mod1;
        hash22 = (table22[n + idx2] + (table22[idx2] * mod2pow)) % mod2;
        if(hash11 == hash21 && hash12 == hash22){
            return true;
        }else{
            return false;
        }
    }
};


