#include <bits/stdc++.h>
using namespace std;


int N;
vector<int> a, b;


vector<int> make_next(const vector<int> &P)
{
    int m = P.size();
    vector<int> next(m);
    int q, k;
    next[0] = 0;
    for (q = 1, k = 0; q < m; ++q) {
        while (k > 0 && P[q] != P[k])
            k = next[k - 1];
        if (P[q] == P[k])
            k++;
        next[q] = k;
    }
    return next;
}


vector<int> kmp(const vector<int> &T, const vector<int> &P)
{
    vector<int> res;
    int n = T.size();
    int m = P.size();
    vector<int> next = make_next(P);
    int i, q;
    for (i = 0, q = 0; i < n; ++i) {
        while (q > 0 && P[q] != T[i])
            q = next[q - 1];
        if (P[q] == T[i])
            q++;
        if (q == m) {
            res.push_back(i - m + 1);
            q = next[q - 1];
        }
    }
    return res;
}


void solve()
{
    vector<int> vt(2*N-1);
    vector<int> vp(N);
    vector<int> pos;
    map<int, int> m1, m2;

    reverse(a.begin(), a.end());
    reverse(b.begin(), b.end());

    for (int i = 0; i < 2*N; i++) {
        if (i < N) {
            vt[i] = b[i] & 1;
            b[i] >>= 1;
        } else {
            vt[i] = vt[i - N];
        }
    }
    for (int i = 0; i < N; i++) {
        vp[i] = a[i] & 1;
        a[i] >>= 1;
    }
    pos = kmp(vt, vp);
    for (int k : pos)
        m1[k] = 0;
    for (int i = 0; i < N; i++)
        vp[i] = 1 - vp[i];
    pos = kmp(vt, vp);
    for (int k : pos)
        m1[k] = 1;

    for (int e = 1; e < 30; e++) {
        for (int i = 0; i < 2*N; i++) {
            if (i < N) {
                vt[i] = b[i] & 1;
                b[i] >>= 1;
            } else {
                vt[i] = vt[i - N];
            }
        }
        for (int i = 0; i < N; i++) {
            vp[i] = a[i] & 1;
            a[i] >>= 1;
        }
        pos = kmp(vt, vp);
        for (int k : pos) {
            if (m1.count(k))
                m2[k] = m1[k];
        }
        for (int i = 0; i < N; i++)
            vp[i] = 1 - vp[i];
        pos = kmp(vt, vp);
        for (int k : pos) {
            if (m1.count(k))
                m2[k] = m1[k] + (1 << e);
        }
        swap(m1, m2);
        m2.clear();
    }

    for (const auto kx : m1)
        cout << kx.first << " " << kx.second << endl;
}


int main()
{
    cin >> N;
    a.resize(N);
    b.resize(N);
    for (int i = 0; i < N; i++)
        cin >> a[i];
    for (int i = 0; i < N; i++)
        cin >> b[i];
    solve();
    return 0;
}

