const int maxn = 1e5 + 10 ;

int a[maxn] , b[maxn] , aa[2*maxn] , bb[2*maxn] , p[maxn] , n ;

vector<pair<int,int> > ans ;

void prefix()
{
    int now = p[0] = -1 ;
    int len = n ;
    for(int i = 1 ; i < len ; ++i)
    {
        while(now!=-1 && bb[now+1]!=bb[i]) now = p[now] ;
        if(bb[now+1]==bb[i]) p[i] = ++now ;
        else p[i] = now = -1 ;
    }
}

int kmp()
{
    prefix() ;
    int cnt = 0 , now = -1 ;
    for(int i = 0 ; i < 2*n ; ++i)
    {
        while(now != -1 && bb[now+1]!=aa[i]) now = p[now] ;
        if(bb[now+1]==aa[i]) ++now ;
        else now = -1 ;
        if(now==n-1)
        {
            int xx = i-n+1 ;
            ans.push_back({xx,a[xx-1]^b[n-1]}) ;
            now = p[now] ; ++cnt ;
        }
    }
}

int main()
{
    scanf("%d",&n) ;
    for(int i = 0 ; i < n ; ++i) scanf("%d",&a[i]) ;
    for(int i = 0 ; i < n ; ++i) scanf("%d",&b[i]) ;
    aa[n-1] = a[n-1]^a[0] , bb[n-1] = b[n-1]^b[0] ;
    for(int i = 0 ; i < n - 1 ; ++i) aa[i] = a[i]^a[i+1] , bb[i] = b[i]^b[i+1] ;
    for(int i = n ; i < 2*n ; ++i) aa[i] = aa[i-n] ;
    kmp() ;
    sort(ans.begin(),ans.end()) ;
    int siz = ans.size() ;
    for(int i = 0 ; i < siz ; ++i)
    {
        if(ans[i].first==n) continue ;
        printf("%d %d\n",ans[i].first,ans[i].second) ;
    }
    return 0 ;
}

