void zcalc(vector < int > a){
    int l = 0;
    int r = 0;
    int n = a.size();
    for (int i = 1; i < n; i++){
        if (i <= r){
            z[i] = min(z[i - l], r - i + 1);
        }
        while(i + z[i] < n && a[i + z[i]] == a[z[i]]){
                z[i]++;
            }
        if (i + z[i] - 1 > r){
            l = i;
            r = i + z[i] - 1;
        }
    }
}
