class KMP
{
public:
    string pattern;
    int plen;
    vector<int> table;
    KMP(const string& s) : pattern(s), plen((int)pattern.size()), table(plen+1){
        table[0] = -1;
        int j = -1;
        for(int i = 0; i < plen; i++){
            while(j >= 0 && pattern[i] != pattern[j]) j = table[j];
            if(pattern[i+1] == pattern[++j]) table[i+1] = table[j];
            else table[i+1] = j;
        }
    }
    void search(const string& text, vector<int>& res){
        int head = 0, j = 0, tlen = (int)text.size();
        while(head + j < tlen){
            if(pattern[j] == text[head + j]){
                if(++j != plen) continue;
                res.push_back(head);
            }
            head += j - table[j], j = max(table[j], 0);
        }
    }
};
int n;
int ans[200005];
int cnt[200005];
void solve(int bit,bool f, string c, string d){
    for(int i = 0; i < n; i++)c.push_back(c[i]);
    show(c);
    show(d);
    KMP kmp(d);
    vector<int> res;
    kmp.search(c, res);
    show(bit, f, res);
    for(auto x : res){
        if(f)ans[x]+=1<<bit;
        cnt[x]++;
    }
}
