int h[maxn];
int p[maxn];

int get(int i) {
  if (i == 0) return h[n - 1];
  return norm(mul(norm(h[n - 1] - mul(h[i - 1], p[n - i])), p[i]) + h[i - 1]);
}

void solve(int k, int ok) {
  int H = 0;
  for (int i = 0; i < n; ++i)
    H = norm(mul(H, 2) + bitk(b[i], k));

  h[0] = bitk(a[0], k) ^ ok;
  for (int i = 1; i < n; ++i)
    h[i] = mul(h[i - 1], 2) + (bitk(a[i], k) ^ ok);

  for (int i = 0; i < n; ++i)
    if (get(i) == H)
      cnt[i] ++;
}

