        A.resize(S.size()+1);
        A[0] = -1;
        ll j = -1;
        for(int i = 0; i < S.size(); ++i){
            while(j >= 0 && S[i] != S[j]) j = A[j];
            ++j;
            if(S[i + 1] == S[j]) A[i + 1] = A[j];
            else A[i + 1] = j;
        }
    }

    ll search(Type T, ll pos = 0){
        ll i = pos, j = 0;
        while(i < S.size() && j < T.size()){
            if(S[i] == T[j]) ++i, ++j;
            else if(!j) ++i;
            else j = A[j];
        }
        if(j == T.size()) return i-j;
        return -1;
    }
};

