void Zalgorithm(vector<int> &vec, const vector<int> &str) {
  int sz = str.size();
  vec.assign(sz, 0);
  vec[0] = sz;
  int i = 1, j = 0;
  while (i < sz) {
    while (i+j < sz && str[j] == str[i+j]) ++j;
    vec[i] = j;
    if (j == 0) {
      ++i;
      continue;
    }
    int k = 1;
    while (i+k < sz && k+vec[k] < j) {
      vec[i+k] = vec[k];
      ++k;
    }
    i += k; j -= k;
  }
}

void solve() {
  int n; cin >> n;
  vi a(n), b(n);
  rep(i,n) cin >> a[i];
  rep(i,n) cin >> b[i];

  vi c(n), d(n);
  rep(i,n-1) c[i] = a[i] ^ a[i+1];
  c[n-1] = a[n-1] ^ a[0];
  rep(i,n-1) d[i] = b[i] ^ b[i+1];
  d[n-1] = b[n-1] ^ b[0];

  vi arr(3*n);
  rep(i,n) arr[i] = d[i];
  rep(i,n) arr[n+i] = arr[2*n+i] = c[i];

  vi Zs;
  Zalgorithm(Zs, arr);

  vector<pii> ans;
  rep(i,n) {
    if (Zs[n+i] >= n) {
      ans.push_back(pii(i, (a[i]^b[0])));
    }
  }
  cout << ans << endl;
}


