struct KMP{
	vector<int> A;
	KMP(T &s){
		A.resize(s.size()+1,-1);
		int x = -1;
		for(int i=0;i<s.size();i++){
			while(x>=0&&s[i]!=s[x]){
				x=A[x];
			}
			x++;
			if(i!=s.size()-1){
				if(s[i+1] == s[x]) {
					A[i+1] = A[x];
					continue;
				}
			}
			A[i+1] = x;
		}
	}


	//文字列[0,pos]の接尾辞と接頭辞が何文字一致しているか
	//(i+1)-get_length(i)で[0,i]の最小周期
	int get_length(int pos){
		return A[pos+1];
	}

};


