template <typename T>
struct RollingHash
{
	int size;
	int n;
	vector<ll> factor;
	ll b = 0;
	ll mod = 0;
	ll hash = 0;
	queue<T> q;

	void init(int _n, ll _b = (ll)1e8 + 7, ll _mod = (ll)1e9 + 7)
	{
		n = _n;
		b = _b;
		mod = _mod;
		auto temp = 1ll;
		for (auto i = 0; i < n; ++i)
		{
			factor.push_back(temp);
			temp = temp * b % mod;
		}
	}

	void add(ll val)
	{
		if ((int)q.size() >= n)
		{
			hash = (((hash - q.front() * factor[n - 1]) % mod) + mod) % mod;
			q.pop();
		}
		hash = hash * b % mod;
		hash = (hash + val) % mod;
		q.push(val);
	}

	ll getHash() { return hash; }
};

ll calcHash(vector<ll>& list, ll factor, ll mod)
{
	auto hash = 0ll;
	for (auto i = 0; i < (int)list.size(); ++i)
	{
		hash = hash * factor % mod;
		hash = (hash + list[i]) % mod;
	}

	return hash;
}

