vector<int> makeTable(vector<int> s) {
  int n = s.size();
  vector<int> ret(n+1);
  ret[0] = -1;
  int j = -1;
  rep(i,0,n) {
    while(j >= 0 && s[i] != s[j]) j = ret[j];
    ret[i+1] = ++j;
  }
  return ret;
}

vector<int> kmp(vector<int> s, vector<int> w) {
  vector<int> table = makeTable(w), ret;
  int m = 0, i = 0, n = s.size();
  while(m+i < n) {
    if (w[i] == s[m+i]) {
      if (++i == (int)(w.size())) {
        ret.push_back(m);
        m = m+i-table[i];
        i = table[i];
      }
    } else {
      m = m+i-table[i];
      if (i > 0) i = table[i];
    }
  }
  return ret;
}

