struct SuffixArray {
    vector<int> sa;
    const vector<int> s;

    SuffixArray(const vector<int>& str) : s(str) {
        int n = s.size(), k;
        sa.resize(n);
        iota(sa.begin(), sa.end(), 0);
        vector<int> rank(s.begin(), s.end()), tmp(n);
        auto cmp = [&](int i, int j) {
            if (rank[i] != rank[j]) return rank[i] < rank[j];
            else return rank[(i+k) % n] < rank[(j+k) % n];
        };
        for (k = 1; k < n; k *= 2) {
            sort(sa.begin(), sa.end(), cmp);
            tmp[sa[0]] = 0;
            for (int i = 1; i < n; i++) {
                tmp[sa[i]] = tmp[sa[i-1]] + (cmp(sa[i-1], sa[i]) ? 1 : 0);
            }
            swap(rank, tmp);
        }
    }

    int operator[](int k) const {
        return sa[k];
    }

    bool lt_substr(const vector<int>& t, int si = 0, int ti = 0) {
        int n = s.size();
        for (int i = 0; i < min(s.size(), t.size()); i++) {
            if (s[(si + i) % n] < t[(ti + i) % n]) return true;
            if (s[(si + i) % n] > t[(ti + i) % n]) return false;
        }
        return false;
    }

    int lower_bound(const vector<int>& t) {
        int lb = -1, ub = sa.size();
        while (ub - lb > 1) {
            int m = (lb + ub) / 2;
            if (lt_substr(t, sa[m])) lb = m;
            else ub = m;
        }
        return ub;
    }

    int upper_bound(vector<int>& t) {
        t.back()++;
        int i = lower_bound(t);
        t.back()--;
        return i;
    }
};

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(0);

    int N;
    cin >> N;
    vector<int> a(N), b(N);
