template <typename S>
struct RollingHash {
private:
    static const u64 MASK30 = (1ull << 30) - 1;
    static const u64 MASK31 = (1ull << 31) - 1;
    static const u64 mod = (1ull << 61) - 1;
    static const u64 POSITIVIZER = mod * ((1ull << 3) - 1);

    static u64 Mul (u64 a, u64 b) {
        u64 au = a >> 31;
        u64 ad = a & MASK31;
        u64 bu = b >> 31;
        u64 bd = b & MASK31;
        u64 mid = ad * bu + au * bd;
        u64 midu = mid >> 30;
        u64 midd = mid & MASK30;
        return (au * bu * 2 + midu + (midd << 31) + ad * bd);
    }

    static u64 CalcMod(u64 val) {
        val = (val & mod) + (val >> 61);
        if (val >= mod) val -= mod;
        return val;
    }

    vector<u64> hash,power;

public:
    static u64 &base() {static u64 base = 0; return base;}
    static void set (u64 b) {base() = b;}

    static inline u64 generate_base() {
        mt19937_64 mt(chrono::steady_clock::now().time_since_epoch().count());
        uniform_int_distribution<u64> rand(1, RollingHash::mod - 1);
        return rand(mt);
    }

    RollingHash(const S &s) {
        int sz = s.size();
        hash.assign(sz + 1,0);
        power.assign(sz + 1,1);
        for (int i = 0; i < sz; i++) {
            power[i+1] = CalcMod(Mul(power[i],base()));
            hash[i+1] = CalcMod(Mul(hash[i],base()) + s[i] + 1);
        }
    }

    u64 get(int l, int r) { // [l,r) (0-indexed)
        u64 ret;
        ret = CalcMod(hash[r] + POSITIVIZER - Mul(hash[l],power[r-l]));
        return ret;
    }

    static u64 gethash(const S &s) {
        u64 ret = 0;
        for (int i = 0; i < s.size(); ++i) {
            ret = CalcMod(Mul(ret,base()) + s[i] + 1);
        }
        return ret;
    }

	int LCP(RollingHash &b, int l1, int r1, int l2, int r2) {
		int len = min(r1 - l1, r2 - l2);
    	int low = -1, high = len + 1;
    	while(high - low > 1) {
      		int mid = (low + high) / 2;
      		if(get(l1, l1 + mid) == b.get(l2, l2 + mid)) low = mid;
      		else high = mid;
    	}
    	return (low);
	}
};

