void compute(int n){
	f[0] = 0;
	int i = 1, j = 0;
	while(i < n){
		if(a[i] == a[j]){
			f[i] = j + 1;
			i++; j++;
		}else if(j){
			j = f[j - 1];
		}else{
			f[i] = 0;
			i++;
		}
	}
}

