const int B = 30;

int main() {
    int N; cin >> N;
    vector<string> as(B, ""), bs(B, ""), bs_rev(B, "");
    for(int i=0; i<N; i++) {
        ll v; cin >> v;
        for(int k=0; k<B; k++) {
            as[k] += (char)('0' + (v >> k & 1));
        }
    }
    for(int i=0; i<N; i++) {
        ll v; cin >> v;
        for(int k=0; k<B; k++) {
            bs[k] += (char)('0' + (v >> k & 1));
            bs_rev[k] += (char)('0' + !(v >> k & 1));
        }
    }

    vector<int> shift_a(B), shift_b(B), shift_b_rev(B);
    for(int x=0; x<B; x++) {
        string s = as[x] + as[x];
        SuffixArray sa(s);
        for(size_t i=0; i<=s.size(); i++) {
            int res = sa.getIdx(i);
            if(0 <= res and res < as[x].size()) {
                shift_a[x] = res;
                break;
            }
        }

        as[x] = as[x].substr(shift_a[x]) + as[x].substr(0, shift_a[x]);
        // fprintf(stderr, "as = %s, res = %d\n", as[x].c_str(), shift_a[x]);
    }

    for(int x=0; x<B; x++) {
        string s = bs[x] + bs[x];
        SuffixArray sa(s);
        for(size_t i=0; i<=s.size(); i++) {
            int res = sa.getIdx(i);
            if(0 <= res and res < bs[x].size()) {
                shift_b[x] = res;
                break;
            }
        }
        bs[x] = bs[x].substr(shift_b[x]) + bs[x].substr(0, shift_b[x]);
        // fprintf(stderr, "bs = %s, re = %d\n", bs[x].c_str(), shift_b[x]);
    }

    for(int x=0; x<B; x++) {
        string s = bs_rev[x] + bs_rev[x];
        SuffixArray sa(s);
        for(size_t i=0; i<=s.size(); i++) {
            int res = sa.getIdx(i);
            if(0 <= res and res < bs_rev[x].size()) {
                shift_b_rev[x] = res;
                break;
            }
        }
        bs_rev[x] = bs_rev[x].substr(shift_b_rev[x]) + bs_rev[x].substr(0, shift_b_rev[x]);
        // fprintf(stderr, "bs_rev = %s, res = %d\n", bs_rev[x].c_str(), shift_b_rev[x]);
    }

    // シフト量としてありえるもの
    vector< vector<int> > valid(B), valid_rev(B);
    vector< vector<int> > divs(B);
    {
        vector<int> tmp;
        for(int i=1; i*i<=N; i++) {
            if(N % i == 0) {
                tmp.emplace_back(i);
                if(N / i != i) tmp.emplace_back(N / i);
            }
        }
        sort(tmp.begin(), tmp.end());

        for(int d : tmp) {
            for(int i=0; i<B; i++) {
                bool valid = true;
                string t = as[i].substr(0, d);
                for(size_t j=0; j<as[i].size(); j+=d) {
                    valid &= (t == as[i].substr(j, d));
                }
                if(valid) divs[i].emplace_back(d);
            }
        }
    }

    for(int x=0; x<B; x++) {
        if(as[x] == bs[x]) {
            // fprintf(stderr, "equal: %d\n", x);
            int shift = (shift_a[x] - shift_b[x] + N) % N;
            valid[x].emplace_back(shift);

            int orig = shift;
            for(auto d : divs[x]) {
                while(true) {
                    (shift += d) %= N;
                    if(orig == shift) break;
                    valid[x].emplace_back(shift);
                }
                shift = orig;
            }
        }
        if(as[x] == bs_rev[x]) {
            // fprintf(stderr, "equal rev: %d\n", x);
            int shift = (shift_a[x] - shift_b_rev[x] + N) % N;
            valid_rev[x].emplace_back(shift);

            int orig = shift;
            for(auto d : divs[x]) {
                while(true) {
                    (shift += d) %= N;
                    if(orig == shift) break;
                    valid_rev[x].emplace_back(shift);
                }
                shift = orig;
            }
        }
    }

    for(int i=0; i<B; i++) {
        sort(valid[i].begin(), valid[i].end());
        valid[i].erase(unique(valid[i].begin(), valid[i].end()), valid[i].end());

        sort(valid_rev[i].begin(), valid_rev[i].end());
        valid_rev[i].erase(unique(valid_rev[i].begin(), valid_rev[i].end()), valid_rev[i].end());
    }

    vector< vector< vector<int> > > cand(N, vector< vector<int> >(B));
    for(int i=0; i<B; i++) {
        for(auto k : valid[i]) cand[k][i].emplace_back(0);
    }
    for(int i=0; i<B; i++) {
        for(auto k : valid_rev[i]) cand[k][i].emplace_back(1);
    }

    vector< pair<int, int> > ans;
    auto dfs = [&](auto&& f, int idx, int b, int X) -> void {
        if(b == B) {
            ans.emplace_back(idx, X);
            return;
        }
        for(auto e : cand[idx][b]) {
            // fprintf(stderr, "cand %d %d: %d\n", idx, b, e);
            X ^= (e << b);
            f(f, idx, b+1, X);
            X ^= (e << b);
        }
    };

    for(int i=0; i<N; i++) {
        bool ok = true;
        for(int j=0; j<B; j++) ok &= (cand[i][j].size > 0);
        if(ok) dfs(dfs, i, 0, 0);
    }

    sort(ans.begin(), ans.end());
    for(auto e : ans) {
        int k, x; tie(k, x) = e;
        printf("%d %d\n", k, x);
    }

    /*
    for(int i=0; i<B; i++) {
        fprintf(stderr, "valid (%d):", i);
        for(auto e : valid[i]) cerr << " " << e;
        cerr << endl;
        fprintf(stderr, "valid_rev (%d):", i);
        for(auto e : valid_rev[i]) cerr << " " << e;
        cerr << endl;
    }
    */


    return 0;
}

