struct Suffix {
    int index;
    pair<int, int> rk;
    Suffix(int index, pair<int, int> rk) : index(index), rk(rk) {}
};

vector<int> suffix_array(vector<int>& v) {
    int n = v.size();
    vector<Suffix> suffixes;
    for (int i = 0; i < n; i++) suffixes.push_back({i, {v[i], v[(i+1) % n]}});
    vector<int> ind(n);
    for (int k = 2; k < n; k *= 2) {
        sort(suffixes.begin(), suffixes.end(), [](const auto& s1, const auto& s2) {
            return s1.rk < s2.rk;
        });
        for (int i = 0; i < n; i++) ind[suffixes[i].index] = i;

        int rank = -1;
        pair<int, int> prev(-1, -1);

        for (int i = 0; i < n; i++) {
            if (suffixes[i].rk != prev) rank++;
            prev = suffixes[i].rk;
            suffixes[i].rk = {rank, suffixes[ind[(suffixes[i].index + k) % n]].rk.first};
        }
    }
    vector<int> ret(n);
    for (int i = 0; i < n; i++) ret[i] = suffixes[i].index;
    return ret;
}

int bin_search(vector<int>& a, vector<int>& b, vector<int>& sa, bool lower) {
    int n = a.size();
    int lb = -1, ub = n;
    while (ub - lb > 1) {
        int m = (lb + ub) / 2;
        bool flag = false;
        for (int i = 0; i < n; i++) {
            int j = (sa[m] + i) % n;
            if (a[i] < b[j]) {
                ub = m;
                flag = true;
                break;
            }
            if (a[i] > b[j]) {
                lb = m;
                flag = true;
                break;
            }
        }
        if (!flag) {
            if (lower) ub = m;
            else lb = m;
        }
    }
    return ub;
}

