        for (int j = 0; j < N; j++) {
            c[j] = a[j] >> i & 1;
            d[j] = b[j] >> i & 1;
        }
        auto sa = suffix_array(d);
        int lb = bin_search(c, d, sa, true);
        int ub = bin_search(c, d, sa, false);
        for (int j = lb; j < ub; j++) cnt[(N - sa[j]) % N]++;

        for (int j = 0; j < N; j++) c[j] = 1 - c[j];
        lb = bin_search(c, d, sa, true);
        ub = bin_search(c, d, sa, false);
        for (int j = lb; j < ub; j++) cnt[(N - sa[j]) % N]++;
    }
