        return 0;
    }

    map<int, VEC(int)> bbMap;
    FOR(i, 0, N - 1)
        bbMap[B[i] ^ B[i + 1]].push_back(i + 1);

    int start = -1, choices = 0;
    FOR(i, 0, N) {
        // If this is not the start of the new sequence.
        // then, a[i] ^ a[i - 1] must be in bbMap.
        // Otherwise, 
        int key = A[i] ^ A[(i + N - 1) % N];
        if (bbMap.find(key) == bbMap.end()) {
            // this must be the beginning.
            int x = A[i] ^ B[0];
            bool good = true;
            FOR(j, 0, N)
