            int k = i - 2 * n + 1;
            k = n - k;
            out.push_back(make_pair(k, A[1 + k] ^ B[1]));
        }
    }
    sort(out.begin(), out.end());

    for(pair<int, int> p : out) {
        cout << p.first << " " << p.second << "\n";
    }

    return 0;
}

