void Z_algo(vector<int> s, vector<int>& z){
	int c = 0, n = s.size();
	z.resize(n, 0);
	for(int i=1; i<n; i++){
		if(i+z[i-c] < c+z[c]){
			z[i] = z[i-c];
		}else{
			int j = max(0, c+z[c]-i);
			while(i+j < n && s[j] == s[i+j]) j++;
			z[i] = j;
			c = i;
		}
	}
	z[0] = n;
}

int main(){
	int N; cin >> N;
	vector<int> a(N), b(N);
	vector<int> s, z;
	rep(i, N) cin >> a[i];
	rep(i, N) cin >> b[i];
	rep(i, N) s.pb(b[i]^b[(i+1)%N]);
	rep(i, 2*N) s.pb(a[i%N]^a[(i+1)%N]);
	Z_algo(s, z);
	REP(i, N, 2*N){
		if(z[i] >= N) cout << i%N << " " << (a[i%N]^b[0]) << endl;
	}
	return 0;
}

