struct RollingHash {
    ll base1;
    ll base2;
    ll mod1;
    ll mod2;
    vector<ll> hash1;
    vector<ll> hash2;
    vector<ll> pow1;
    vector<ll> pow2;

    RollingHash()
        : base1(1009), base2(1007), mod1(1000000007), mod2(1000000009) {}

    void init(vector<ll> s) {
        int n = s.size();

        hash1.assign(n + 1, 0);
        hash2.assign(n + 1, 0);
        pow1.assign(n + 1, 1);
        pow2.assign(n + 1, 1);

        for (int i = 0; i < n; i++) {
            hash1[i + 1] = (hash1[i] + s[i]) * base1 % mod1;
            hash2[i + 1] = (hash2[i] + s[i]) * base2 % mod2;
            pow1[i + 1] = pow1[i] * base1 % mod1;
            pow2[i + 1] = pow2[i] * base2 % mod2;
        }
    }

    pair<ll, ll> get(int l, int r) {
        ll t1 = ((hash1[r] - hash1[l] * pow1[r - l]) % mod1 + mod1) % mod1;
        ll t2 = ((hash2[r] - hash2[l] * pow2[r - l]) % mod2 + mod2) % mod2;
        return make_pair(t1, t2);
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);

    ll n;
    cin >> n;
    vector<ll> a(n), b(n), s(n), t(2 * n);
    vector<pair<ll, ll>> ans;
    rep(i, 0, n) cin >> a[i];
    rep(i, 0, n) cin >> b[i];
    rep(i, 0, n) {
        s[i] = a[i] ^ a[(i + 1) % n];
        t[i] = t[i + n] = b[i] ^ b[(i + 1) % n];
    }
    RollingHash x, y;
    x.init(s);
    y.init(t);
    pair<ll, ll> sh = x.get(0, n);

    rep(i, 0, n) {
        if (sh == y.get(i, i + n)) {
            ans.emplace_back((n - i) % n, a[0] ^ b[i]);
        }
    }

    sort(ans.begin(), ans.end());
    for (auto p : ans) {
        cout << p.first << ' ' << p.second << endl;
    }

    return 0;
}

