    ll len=0;
    ll i=1,n=pat.size();
    while(i<n)
    {
        if(pat[len]==text[i])
        {
            ++len;
            lps[i]=len;
            ++i;
        }
        else
        {
            if(len)
                len=lps[len-1];
            else
            {
                lps[i]=0;
                ++i;
            }
        }
    }
}
