        isb[i] = char('1' - sb[i] + '0');
    }
    using namespace Hash;
    PolyHash hash_a(sa), hash_b(sb), hash_ib(isb);
    for (int k = 0; k < isz(b); k++) {
        cnt[k] += (
            hash_b(0, isz(b)) == hash_a(k, isz(b)) ||
            hash_ib(0, isz(b)) == hash_a(k, isz(b))
        );
    }
}
