ll KMPMatch(string src, string pat){
    int ini[pat.size()], i=1, j=0;
    ini[0] = 0;
    while(i<pat.size()){
       if(pat[i] == pat[j]) j++, ini[i] = j, i++;
       else if(j == 0) ini[i] = 0, i++;
       else j = ini[j - 1];
    }
    i = j = 0;
    vll ret;
    while(j<pat.size()&&i<src.size()){
       if(src[i] == pat[j]) i++, j++;
       else if(j == 0) i++;
       else j = ini[j - 1];
       if(j==pat.size()) return i - pat.size();
    }
    return -1;
}
