using P = pair<int, int>;

struct RollingHash {
    const int b1 = 1007, b2 = 2009;
    const int mod1 = 1e9 + 7, mod2 = 1e9 + 9;
    vector<ll> h1, h2, p1, p2;

    RollingHash(const vector<ll> &s) {
        int n = s.size();
        h1.resize(n + 1, 0);
        h2.resize(n + 1, 0);
        p1.resize(n + 1, 1);
        p2.resize(n + 1, 1);
        for(int i = 0; i < n; i++) {
            h1[i + 1] = (h1[i] * b1 + s[i]) % mod1;
            h2[i + 1] = (h2[i] * b2 + s[i]) % mod2;
            p1[i + 1] = (p1[i] * b1) % mod1;
            p2[i + 1] = (p2[i] * b2) % mod2;
        }
    }

    pair<ll, ll> get(int l, int r) {
        ll res1 = h1[r] - h1[l] * p1[r - l] % mod1;
        if(res1 < 0) {
            res1 += mod1;
        }
        ll res2 = h2[r] - h2[l] * p2[r - l] % mod2;
        if(res2 < 0) {
            res2 += mod2;
        }
        return make_pair(res1, res2);
    }

    int get_lcp(int a, int b) {
        int len = min((int)h1.size() - a, (int)h1.size() - b);
        int ok = 0, ng = len;
        while(ng - ok > 1) {
            int mid = (ok + ng) >> 1;
            (get(a, a + mid) == get(b, b + mid) ? ok : ng) = mid;
        }
        return ok;
    }

    int get_lcp(RollingHash &t, int a, int b) {
        int len = min((int)h1.size() - a, (int)h1.size() - b);
        int ok = 0, ng = len;
        while(ng - ok > 1) {
            int mid = (ok + ng) >> 1;
            (get(a, a + mid) == t.get(b, b + mid) ? ok : ng) = mid;
        }
        return ok;
    }
};

