//--------------------------------------------------------------------


void solve() {
    i64 N = RD();
    auto A = RD_VEC(N);
    auto B = RD_VEC(N);

    vector<i64> X(N);
    REP(i, N) {
        X[i] = A[i] ^ A[(i+1)%N];
    }
    vector<i64> Y(N);
    REP(i, N) {
        Y[i] = B[i] ^ B[(i+1)%N];
    }
    DBG(X, Y);

    vector<i64> T(X);
    T.emplace_back(INF);
    T.insert(end(T), begin(Y), end(Y));
    T.insert(end(T), begin(Y), end(Y));
    DBG(T);

    auto z = ALL(z_function, T);

    vector<pair<i64,i64>> ans;
    REP(i, N) {
        if(z[N+1+i] != N) continue;

        i64 k = (N-i)%N;
        i64 x = A[(i+k)%N] ^ B[i];

        ans.emplace_back(k, x);
    }

    ALL(sort, ans);

    ALL(for_each, ans, LIFT(PRINTLN));
}

signed main() {


    solve();

    return 0;
}

