  rep (i, N) cerr << foo[i] << " ";
  cerr << endl;

  rep (i, N) cerr << bar[i] << " ";
  cerr << endl;
*/

  ll shuuki_foo = N;
  ll shuuki_bar = N;

  rep (i, N) {
    if (i == 0) continue;
    if (N % i) continue;
    bool flag = true;
    rep (j, N) {
      if (foo[j] != foo[(j + i) % N]) {
        flag = false;
        break;
      }
    }
    if (flag) {
      shuuki_foo = i;
      break;
    }
  }

  rep (i, N) {
    if (i == 0) continue;
    if (N % i) continue;
    bool flag = true;
    rep (j, N) {
      if (bar[j] != bar[(j + i) % N]) {
        flag = false;
        break;
      }
    }
    if (flag) {
      shuuki_bar = i;
      break;
    }
  }

  // cerr << shuuki_foo << ", " << shuuki_bar << endl;

  if (shuuki_foo != shuuki_bar) return;

  ll aaa = -1;
  rep (i, shuuki_foo) {
    bool flag = true;
    rep (j, shuuki_foo) {
      if (bar[j] != foo[(j + i) % N]) {
        flag = false;
        break;
      }
    }
    if (flag) aaa = i;
  }

  if (aaa == -1) return;

  for (ll k = aaa; k < N; k += shuuki_foo) {
    ll x = A[k] ^ B[0];
    cout << k << " " << x << endl;
  }
}

