void solve() {
    in(N);
    na(A, N);
    na(B, N);
    if (A == B) {
        rep(i, N) {
            out(i, A[0] ^ B[0]);
        }
        return;
    }
    set_shuffle();
    auto P = iota(0, N);
    int pn = sz(P);
    shuffle(P);
    int pi = 0;
    int lim = 600 * 100;
    bool never = 1;
    using MS=std::chrono::milliseconds;
    MS time;
    auto pk = iota(0, N);
    shuffle(pk);
    set_time();

    rep(i, N) {
        int k = pk[i];
        int x = A[k] ^B[0];
        if (never && calc_time(300)) {
            auto part = calc_time();
            auto can = MS(1900) - part;
            auto predict = ceil((N-k),k) * part;
            lim *= predict / can;
            never = 0;
        }
        rep(i, lim) {
            int p = P[pi];
            if (p >= k) {
                if ((A[p] ^ x) != B[p - k])goto end;
            } else {
                if ((A[p] ^ x) != B[p - k + N])goto end;
            }
            if (++pi >= pn)pi = 0;
        }
        out(k, x);
        end:;
    }

}
