void solve(const vector<int>& A, const vector<int>& B, vector<int>& mask, int bit) {
  int n = A.size() - 1, m = B.size();
  vector<int> f(m);
  f[0] = 0;
  int k = 0;
  for (int i = 1; i < m; ++i) {
    for (; k > 0 && B[k] != B[i]; k = f[k - 1]);
    if (B[k] == B[i]) k++;
    f[i] = k;
  }
  k = 0;
  for (int i = 0; i < n; ++i) {
    for (; k > 0 && B[k] != A[i]; k = f[k - 1]);
    if (B[k] == A[i]) k++;
    if (k == m) {
      mask[i - m + 1] |= bit;
      k = f[k - 1];
    }
  }
}

