    c[N - 1] = a[N - 1] ^ a[0];
    d[N - 1] = b[N - 1] ^ b[0];
    for (int i = N; i < 2*N; i++) c[i] = c[i - N];
    auto pos = kmp(c, d);
    for (int k : pos) cout << k << " " << (b[0] ^ a[k]) << endl;
}


