struct rolling_hash{
	ll z = 100;
	vector<ll> v,w[2],ex[2];
	rolling_hash(vector<ll> &s){
		int i,j,n = s.size();
		for(i=0;i<n;i++){
			v.push_back(s[i] + 1);
		}
		w[0].assign(n + 1,0),w[1].assign(n + 1,0);
		ex[0].assign(n + 1,0),ex[1].assign(n + 1,0);
		ex[0][0] = 1,ex[1][0] = 1;
		for(i=0;i<n;i++){
			for(j=0;j<2;j++){
				w[j][i + 1] = (w[j][i]*z + v[i])%mod[j];
				ex[j][i + 1] = ex[j][i]*z%mod[j];
			}
		}
	}
	inline pll get(int l, int r){//[l,r)
		ll x = (w[0][r] - ex[0][r - l]*w[0][l]%mod[0] + mod[0])%mod[0];
		ll y = (w[1][r] - ex[1][r - l]*w[1][l]%mod[1] + mod[1])%mod[1];
		return {x,y};
	}
};

