vector<ll> zalgo(string S){
  vector<ll>A(S.length());
  int c = 0;
  for (int i = 1; i < S.size(); i++){
      if (i+A[i-c] < c+A[c]) {
        A[i] = A[i-c];
      } else {
        int j = max(0ll, c+A[c]-i);
        while (i+j < S.size() && S[j] == S[i+j]) ++j;
        A[i] = j;
        c = i;
      }
  }
  A[0]=S.length();
  return A;
};
