int lps[7000099];
string text;
string pattern;
vector<int> match_index;

void build_lps() {
    int N = pattern.size();
    for(int i = 2;i <= N;i++) {
        int prev = i-1;
        while(prev != 0) {
            if(pattern[lps[prev]] == pattern[i-1]) {
                lps[i] = lps[prev]+1;
                break;
            }
            prev = lps[prev];
        }
    }
}

void find_pattern() {
    int i = 0, j = 1;
    while(i < text.size()) {
        if(j == 1 && pattern[j-1] != text[i]) {
            i += 1;
        }
        else if(j == pattern.size() && pattern[j-1] == text[i]) {
            match_index.push_back(i+1-pattern.size());
            i++;
            j = lps[j]+1;
        }
        else if(pattern[j-1] == text[i]) {
            i++;j++;
        } else {
            j = lps[j-1]+1;
        }
    }
}

