int lps[N];

void computeLPS(vll &pat, int n) {
	int len = 0;
	lps[0] = 0;
	int i = 1; 
	while(i < n) {
		if (pat[i] == pat[len]) {
			++len;
			lps[i] = len;
			++i;
		} else {
			if (len != 0) 
				len = lps[len-1];
			else
				lps[i++] = 0;
		}
	}
}

vint KMP(vll &pat, vll &txt, int n) {
	vint ans;
	computeLPS(pat, n);
	int i = 0, j = 0;
	while(i < 2*n-1) {
		if (pat[j] == txt[i]) {
			i++; j++;
		}
		if (j == n) {
			ans.push_back((n-i+j)%n);
			j = lps[j-1];
	//		cerr << "found i: " << i << ", j: " << j << nl;
		} else if (i < 2*n && pat[j] != txt[i]) {
			if (j != 0) 
				j = lps[j-1];
			else 
				i++;
		}
	}
	return ans;
}

