#include <bits/stdc++.h>
using namespace std;

const long long Mod = 1000000007, Base = 1009;
vector<long long> poww;

struct RollingHash {
  long long ssize, maxssize;
  string s;
  vector<long long> hash;
  RollingHash(string inis = "") {
    maxssize = inis.size() + 10;
    init(inis);
  }
  void init(string inis = "") {
    s = inis;
    ssize = s.size();
    sethash();
  }
  void sethash() {
    ssize = s.size();
    hash.assign(ssize + 1, 0);
    for(int i = 0; i < ssize; ++i) {
      if(i != 0) hash[i + 1] = hash[i] * Base % Mod;
      hash[i + 1] += s[i];
      hash[i + 1] %= Mod;
    }
  }
  // [l,r),0-indexed
  long long calchash(int l, int r) {
    long long ans;
    ans = hash[r];
    ans -= hash[l] * poww[r - l] % Mod;
    while(ans < 0) ans += Mod;
    ans %= Mod;

    return ans;
  }
};

long long n;
vector<long long> a, b;
RollingHash rh[3][30];

void solve();

int main() {
  cin >> n;
  poww.assign(3 * n, 0);
  poww[0] = 1;
  for(int i = 1; i < 3 * n; ++i)
    poww[i] = poww[i - 1] * Base % Mod;

  a.resize(n);
  b.resize(n);
  for(int i = 0; i < n; ++i) cin >> a[i];
  for(int i = 0; i < n; ++i) cin >> b[i];
  solve();
  return 0;
}

void solve() {
  for(int i = 0; i < 30; ++i) {
    string s, t;
    for(int j = 0; j < n; ++j) {
      s += '0' + (a[j] >> i & 1);
      t += '0' + 1 - (a[j] >> i & 1);
    }
    s += s;
    t += t;
    rh[0][i] = RollingHash(s);
    rh[1][i] = RollingHash(t);
  }
  for(int i = 0; i < 30; ++i) {
    string s;
    for(int j = 0; j < n; ++j) s += '0' + (b[j] >> i & 1);
    s;
    rh[2][i] = RollingHash(s);
  }
  for(int i = 0; i < n; ++i) {
    bool ch = 1;
    for(int j = 0; j < 30; ++j)
      if(rh[0][j].calchash(i, i + n) !=
             rh[2][j].calchash(0, n) &&
         rh[1][j].calchash(i, i + n) !=
             rh[2][j].calchash(0, n))
        ch = 0;
    if(ch) cout << i << " " << (a[i] ^ b[0]) << endl;
  }
}

