int n,a[200010],b[200010],c[200010],d[200010],z[600010];
vector <int> s;

void calcZ()
{
	int lb=0,ub=0;
	repn(i,s.size()-1)
	{
		if(s[i]!=s[0]) continue;
		if(i>ub)
		{
			int p=i;
			while(p<s.size()&&s[p]==s[p-i]) p++;
			lb=i;
			ub=p-1;
			z[i]=p-i;
		}
		else
		{
			int j=i-lb;
			if(j+z[j]-1<ub-lb) z[i]=z[j];
			else
			{
				int p=ub+1;
				while(p<s.size()&&s[p]==s[p-i]) p++;
				z[i]=p-i;
				lb=i;
				ub=p-1;
			}
		}
	}
}

