        if (d[k+1] == d[i]) ++k;
        nex[i] = k;
    }
}

inline void KMP()
{
    for (int i = 1, j = 0, k; i <= 2*n-2; ++i) {
        while (j && c[i] != d[j+1]) j = nex[j];
