void inline z_init(string &s, vector<int> &z) {
	int len = (int) s.size();
	z = vector<int>(len, 0);
	for (int i = 1, l = 0, r = 0; i < len; ++i) {
		if (i <= r)  z[i] = min(r - i + 1, z[i - l]);
		for (; i + z[i] < len && s[z[i]] == s[i + z[i]]; ++z[i]);
		if (i + z[i] - 1 > r)  l = i, r = i + z[i] - 1;
	}
}

void inline solve(int k) {
	string dat;
	loop (i, n) {
		t[i] = a[i] >> k & 1;
	}
	loop (i, n) {
		s[i] = b[i] >> k & 1;
		s[i + n] = s[i];
	}
	loop (i, n) {
		dat += t[i] ^ 48;
	}
	dat += '#';
	loop (i, 2 * n) {
		dat += s[i] ^ 48;
	}
	vector<int> z;
	z_init(dat, z);
	circ (i, n, 2 * n) {
		vis[k][(n + 1 - i + n) % n] |= z[i] == n;
	}
	dat = "";
	loop (i, n) {
		dat += t[i] ^ 1 ^ 48;
	}
	dat += '#';
	loop (i, 2 * n) {
		dat += s[i] ^ 48;
	}
	z_init(dat, z);
	circ (i, n, 2 * n) {
		vis[k][(n + 1 - i + n) % n] |= z[i] == n;
	}
}

