void prefix()
{
    int now = p[0] = -1 ;
    int len = n ;
    for(int i = 1 ; i < len ; ++i)
    {
        while(now!=-1 && bb[now+1]!=bb[i]) now = p[now] ;
        if(bb[now+1]==bb[i]) p[i] = ++now ;
        else p[i] = now = -1 ;
    }
}

int kmp()
{
    prefix() ;
    int cnt = 0 , now = -1 ;
    for(int i = 0 ; i < 2*n ; ++i)
    {
        while(now != -1 && bb[now+1]!=aa[i]) now = p[now] ;
        if(bb[now+1]==aa[i]) ++now ;
        else now = -1 ;
        if(now==n-1)
        {
            int xx = i%n ;
            ans.push_back({i-1,a[xx]^b[(xx+i-1)%n]}) ;
            now = p[now] ; ++cnt ;
        }
    }
}

