class Rollinghash{
    ll MASK30 = (1LL << 30) - 1;
    ll MASK31 = (1LL << 31) - 1;
    ll MD = (1LL << 61) - 1;
    ll MASK61 = MD;

    //a*b mod 2^61-1を返す関数(最後にModを取る)
    ll Mul(ll a, ll b){
        ll au = a >> 31;
        ll ad = a & MASK31;
        ll bu = b >> 31;
        ll bd = b & MASK31;
        ll mid = ad * bu + au * bd;
        ll midu = mid >> 30;
        ll midd = mid & MASK30;
        return CalcMod(au * bu * 2 + midu + (midd << 31) + ad * bd);
    }

    //mod 2^61-1を計算する関数
    ll CalcMod(ll x)
    {
        ll xu = x >> 61;
        ll xd = x & MASK61;
        ll res = xu + xd;
        if (res >= MD) res -= MD;
        return res;
    }
    static inline ll generate_base() {
        mt19937_64 mt(chrono::steady_clock::now().time_since_epoch().count());
        uniform_int_distribution<ll> rand(2,(1LL<<61)-3);
        return rand(mt);
    }

    ll base=generate_base();

    vl hash,power;

public:
    Rollinghash(vl &s){
        ll n=s.size();
        hash.assign(n+1,0);
        power.assign(n+1,1);
        rep(i,n){
            power[i+1]=Mul(power[i],base)%MD;
            hash[i+1]=(Mul(hash[i],base)+s[i])%MD;
        }
    }
    ll get(int l,int r){
        return (hash[r]+MD-Mul(hash[l],power[r-l])%MD)%MD;
    }
    int LCP(int l0,int r0,int l1,int r1){
        int ok=0,ng=min(r0-l0,r1-l1);
        while(abs(ok-ng)>1){
            int rh_mid=(ok+ng)/2;
            if(get(l0,l0+rh_mid)==get(l1,l1+rh_mid)) ok=rh_mid;
            else ng=rh_mid;
        }
        return ok;
    }
};

int main() {
    ios::sync_with_stdio(false);
