double pi = 3.14159265358979323846;
void fft(double* XR, double* XI, double* SP, int FFN) {
	if (FFN == 0)return;
	if (FFN == 1) {
		double T[4];
		T[0] = XR[0] + XR[1];
		T[1] = XI[0] + XI[1];
		T[2] = XR[0] - XR[1];
		T[3] = XI[0] - XI[1];
		XR[0] = T[0]; XR[1] = T[2];
		XI[0] = T[1]; XI[1] = T[3];
	}
	else {
		long long L = 1;
		L <<= FFN;
		for (long long I = 0; I < L; I++) {
			if (I % 2) SP[I / 2 + L / 2] = XR[I];
			else SP[I / 2] = XR[I];
		}
		for (long long I = 0; I < L; I++) {
			XR[I] = SP[I];
		}
		for (long long I = 0; I < L; I++) {
			if (I % 2) SP[I / 2 + L / 2] = XI[I];
			else SP[I / 2] = XI[I];
		}
		for (long long I = 0; I < L; I++) {
			XI[I] = SP[I];
		}
		fft(XR, XI, SP, FFN - 1);
		fft(&XR[L / 2], &XI[L / 2], SP, FFN - 1);
		double T[6];
		for (long long I = 0; I < L / 2; I++) {
			T[0] = XR[I]; T[1] = XI[I];
			T[2] = XR[I + L / 2]; T[3] = XI[I + L / 2];
			T[4] = T[2] * cos((2 * I * pi) / L) - T[3] * sin((2 * I * pi) / L);
			T[5] = T[2] * sin((2 * I * pi) / L) + T[3] * cos((2 * I * pi) / L);
			XR[I] = T[0] + T[4];
			XI[I] = T[1] + T[5];
			XR[I + L / 2] = T[0] - T[4];
			XI[I + L / 2] = T[1] - T[5];
		}
	}
}
