				ar[i] = ah[i];
				br[i] = bh[i];
				e[i] = 0;
			}
			fft(ar, ai, c, k);
			fft(br, bi, c, k);
			for (int i = 0; i < u; i++) {
				c[i] = ar[i] * br[i] - ai[i] * bi[i];
				ai[i] = ai[i] * br[i] + ar[i] * bi[i];
				ai[i] = (-ai[i]) / m;
				ar[i] = c[i] / m;
			}
			fft(ar, ai, c, k);
			for (int i = 0; i <= 2 * n; i++) {
				ar[i] += 0.5;
				v = ar[i];
				e[i % n] += v;
			}
			for (int i = 0; i < n; i++) {
				if (e[i] == as)g[i] = 1;
			}
		}
		if (as + bs == n) {
			for (int i = 0; i < 256 * 1024; i++) {
				ar[i] = 0;
				br[i] = 0;
				ai[i] = 0;
				bi[i] = 0;
			}
			for (int i = 0; i < n; i++) {
				ar[i] = ah[i];
				br[i] = 1 - bh[i];
				e[i] = 0;
			}
			fft(ar, ai, c, k);
			fft(br, bi, c, k);
			for (int i = 0; i < u; i++) {
				c[i] = ar[i] * br[i] - ai[i] * bi[i];
				ai[i] = ai[i] * br[i] + ar[i] * bi[i];
				ai[i] = (-ai[i]) / m;
				ar[i] = c[i] / m;
			}
			fft(ar, ai, c, k);
			for (int i = 0; i <= 2 * n; i++) {
				ar[i] += 0.5;
				v = ar[i];
				e[i % n] += v;
			}
			for (int i = 0; i < n; i++) {
				if (e[i] == as) {
					g[i] = 1;
					if (ans[(i + 1) % n] != -1)ans[(i + 1) % n] += (1 << j);
				}
			}
		}
		for (int i = 0; i < n; i++) {
			if (g[i] == 0)ans[(i + 1) % n] = -1;
		}
	}
	for (int i = 0; i < n; i++) {
		if (ans[i] != -1) {
			printf("%d %lld\n", i, ans[i]);
		}
	}
