void build(bool c[],int n)
{
	int j=fail[0]=-1;
	for(int i=1;i<=n;i++)
	{
		while(j>=0 && c[i-1]!=c[j]) j=fail[j];
		fail[i]=++j;
	}
}

vector <pair<int,int> > solve(int bit)
{
	bit=1<<bit;
	for(int i=0;i<n;i++)
	{
		pattern[i]=b[i] & bit;
	}
	for(int i=0;i<n;i++)
	{
		c[i]=a[i] & bit;
	}
	for(int i=n;i<n+n;i++)
	{
		c[i]=c[i-n];
	}
	build(pattern,n);
	vector <pair<int,int> > res;
	for(int rev=0;rev<2;rev++)
	{
		for(int i=0,j=0;i<n+n;i++)
		{
			while(j>=0 && c[i]!=pattern[j]) j=fail[j];
			j++;
			if(j==n) res.push_back(mp(i-n+1,rev)),j=fail[j];
		}
		for(int i=0;i<n+n;i++)
		{
			c[i]=c[i]^1;
		}
	}
	return res;
}

