template<int64_t mod=int64_t(1e9+7)>
struct RollingHash{
    vector<int64_t> hash;
    vector<int64_t> base_pow;
    int64_t base;

    RollingHash(vector<int> S, int64_t base_=-1):base(base_){
        if(base < 0) base = 1000 + randint() % 10000;
        if(S.size() > 0) initialize(S);
    }

    void initialize(string& S){
        int N = S.size();
        vector<int> s(N);
        for(int i=0; i<N; i++) s[i] = S[i];
        initialize(s);
    }

    void initialize(vector<int>& S){
        int sz = S.size();
        hash.resize(sz+1);
        base_pow.resize(sz+1);
        hash[0] = 0;
        base_pow[0] = 1;
        for(int i=1; i<=sz; i++){
            hash[i] = (hash[i-1] * base + S[i-1]) % mod;
            base_pow[i] = base_pow[i-1] * base % mod;
        }
    }

    // 0-indexed, [a, b)
    int64_t between(int a, int b){
        return (mod + hash[b] - hash[a] * base_pow[b-a] % mod) % mod;
    }
};

