template<class T> vector<int> kmp_makeTable(T &s) {    int n = s.size();    vector<int> ret(n + 1);    ret[0] = -1;    int j = -1;    for (int i = 0; i < n; i++) {        while (j >= 0 && s[i] != s[j]) j = ret[j];        ret[i + 1] = ++j;    }    return ret;}
// str の中に word とマッチする場所のリストを返す
// ret のそれぞれの要素 el は, 「str[el] からの文字列が word と一致する」ことを示す
template<class T> vector<int> kmp(T &str, T &word) {    vector<int> table = kmp_makeTable(word), ret;    int m = 0, i = 0, n = str.size();    while (m + i < n) {        if (word[i] == str[m + i]) {            if (++i == (int) (word.size())) {                ret.push_back(m);                m = m + i - table[i];                i = table[i];            }        } else {            m = m + i - table[i];            if (i > 0) i = table[i];        }    }    return ret;}

template<class T> vector<int> z_algorithm(T &s) {    vector<int> prefix(s.size());    for (int i = 1, j = 0; i < s.size(); i++) {        if (i + prefix[i - j] < j + prefix[j]) {            prefix[i] = prefix[i - j];        } else {            int k = max(0, j + prefix[j] - i);            while (i + k < s.size() && s[k] == s[i + k]) ++k;            prefix[i] = k;            j = i;        }    }    prefix[0] = (int) s.size();    return prefix;}
/*@formatter:on*/
template<class T> vector<int> z_algorithm(T &A, T word) {
    int w = sz(word);
    word += A;
    vector<int> z = z_algorithm(word);
    vi res(sz(A));
    rep(i, w, sz(z)) {
        res[i-w] = min(w, z[i - w]);
    }
    return res;
}


