vector<int> kmp()
{
    int i, q, k;
    vector<int> res;

    nxt[0] = 0;
    for (q = 1, k = 0; q < N; ++q) {
        while (k > 0 && vp[q] != vp[k])
            k = nxt[k - 1];
        if (vp[q] == vp[k])
            k++;
        nxt[q] = k;
    }

    for (i = 0, q = 0; i < 2*N-1; ++i) {
        while (q > 0 && vp[q] != vt[i])
            q = nxt[q - 1];
        if (vp[q] == vt[i])
            q++;
        if (q == N) {
            res.push_back(i - N + 1);
            q = nxt[q - 1];
        }
    }
    return res;
}


void solve()
{
    vector<int> c(N);
    vector<int> d(N);
    vector<int> pos;
    nxt.resize(N);
    vt.resize(2*N-1);
    vp.resize(N);

    for (int i = 0; i < N - 1; i++) {
        c[i] = a[N - 1 - i] ^ a[N - 2 - i];
        d[i] = b[N - 1 - i] ^ b[N - 2 - i];
