template<class T>void z_algorithm(T &s, vector<int> &ans) {
  ans.resize(s.size(), 0);
  for(int i = 1, j = 0; i < s.size(); i++) {
    if (i + ans[i - j] < j + ans[j]) {
      ans[i] = ans[i - j];
    } else {
      int k = max(0, j + ans[j] - i);
      while (i + k < s.size() && s[k] == s[i + k]) ++k;
      ans[i] = k;
      j = i;
    }
  }
  ans[0] = (int)s.size();
}

