template<class T> vector<int> makeTable(T &s) {
    int n = s.size();
    vector<int> ret(n + 1);
    ret[0] = -1;
    int j = -1;
    for (int i = 0; i < n; i++) {
        while (j >= 0 && s[i] != s[j]) j = ret[j];
        ret[i + 1] = ++j;
    }
    return ret;
}

// str の中に word とマッチする場所のリストを返す
// ret のそれぞれの要素 el は, 「str[el] からの文字列が word と一致する」ことを示す
template<class T> vector<int> kmp(T &str, T &word) {
    vector<int> table = makeTable(word), ret;
    int m = 0, i = 0, n = str.size();
    while (m + i < n) {
        if (word[i] == str[m + i]) {
            if (++i == (int) (word.size())) {
                ret.push_back(m);
                m = m + i - table[i];
                i = table[i];
            }
        } else {
            m = m + i - table[i];
            if (i > 0) i = table[i];
        }
    }
    return ret;
}

template<class T> vector<int> z_algorithm(T &s) {
    vector<int> prefix(s.size());
    for (int i = 1, j = 0; i < s.size(); i++) {
        if (i + prefix[i - j] < j + prefix[j]) {
            prefix[i] = prefix[i - j];
        } else {
            int k = max(0, j + prefix[j] - i);
            while (i + k < s.size() && s[k] == s[i + k]) ++k;
            prefix[i] = k;
            j = i;
        }
    }
    prefix[0] = (int) s.size();
    return prefix;
}

template<class MeetSemiLattice> struct SparseTable { /*@formatter:on*/   vector<vector<MeetSemiLattice> > dat;
    vector<int> height;
    SparseTable() {}
    SparseTable(vector<MeetSemiLattice> &v) { init(v); }
    void init(vector<MeetSemiLattice> &v) {
        int n = (int) v.size(), h = 0;
        while ((1 << h) < n) ++h;
        dat.assign(h, ::vector<MeetSemiLattice>(1 << h));
        height.assign(n + 1, 0);
        for (int i = 2; i <= n; i++) height[i] = height[i >> 1] + 1;
        for (int i = 0; i < n; ++i) dat[0][i] = v[i];
        for (int i = 1; i < h; ++i) for (int j = 0; j < n; ++j) dat[i][j] = min(dat[i - 1][j], dat[i - 1][min(j + (1 << (i - 1)), n - 1)]);
    }
    MeetSemiLattice get(int a, int b) { return min(dat[height[b - a]][a], dat[height[b - a]][b - (1 << height[b - a])]); }
};
// Suffix Array ( Manber&Myers: O(n (logn)^2) )
template<class T> struct SA {
    T str;
    vector<int> sa;
    vector<int> lcpv;
    inline int &operator[](int i) { return sa[i]; }
    void init(T &str_) {
        str = str_;
        buildSA();
        calcLCP();
    }
    vector<int> rank_sa, tmp_rank_sa;
    struct CompareSA {
        int n, k;
        vector<int> &rank;
        CompareSA(int n, int k, vector<int> &rank_sa) : n(n), k(k), rank(rank_sa) {}
        bool operator()(int i, int j) {
            if (rank[i] != rank[j]) return (rank[i] < rank[j]);
            else {
                int rank_ik = (i + k <= n ? rank[i + k] : -1);
                int rank_jk = (j + k <= n ? rank[j + k] : -1);
                return (rank_ik < rank_jk);
            }
        }
    };
    void buildSA() {
        int n = (int) str.size();
        sa.resize(n + 1), lcpv.resize(n + 1), rank_sa.resize(n + 1), tmp_rank_sa.resize(n + 1);
        for (int i = 0; i < n; ++i) sa[i] = i, rank_sa[i] = (int) str[i];
        sa[n] = n, rank_sa[n] = -1;
        for (int k = 1; k <= n; k *= 2) {
            CompareSA csa(n, k, rank_sa);
            sort(sa.begin(), sa.end(), csa);
            tmp_rank_sa[sa[0]] = 0;
            for (int i = 1; i <= n; ++i) {
                tmp_rank_sa[sa[i]] = tmp_rank_sa[sa[i - 1]];
                if (csa(sa[i - 1], sa[i])) ++tmp_rank_sa[sa[i]];
            }
            for (int i = 0; i <= n; ++i) rank_sa[i] = tmp_rank_sa[i];
        }
    }
    vector<int> rsa;
    SparseTable<int> st;
    void calcLCP() {
        int n = (int) str.size();
        rsa.resize(n + 1);
        for (int i = 0; i <= n; ++i) rsa[sa[i]] = i;
        lcpv.resize(n + 1);
        lcpv[0] = 0;
        int cur = 0;
        for (int i = 0; i < n; ++i) {
            int pi = sa[rsa[i] - 1];
            if (cur > 0) --cur;
            for (; pi + cur < n && i + cur < n; ++cur) { if (str[pi + cur] != str[i + cur]) break; }
            lcpv[rsa[i] - 1] = cur;
        }
        st.init(lcpv);
    }
    SA(T &str_) : str(str_) {
        buildSA();
        calcLCP();
    }
    //範囲重複可
    int lcp_dup(int a, int b) { if(a>b)swap(a,b);return st.get(min(rsa[a], rsa[b]), max(rsa[a], rsa[b])); }
    int lcp_not(int a, int b) { if(a>b)swap(a,b);return min(lcp_dup(a, b), b - a); }
    int max_lcp_dup() {
        int res = 0;
        rep(i, sz(str)) { rep(j, i + 1, sz(str)) { chma(res, lcp_dup(i, j)); }}
        return res;
    }
    int max_lcp_not() {
        int res = 0;
        rep(i, sz(str)) { rep(j, i + 1, sz(str)) { chma(res, lcp_not(i, j)); }}
        return res;
    }/*@formatter:on*/
};




