struct MP {
  int n;
  vector<int> a;
  T t;

  MP(const T& arr) {
    n = arr.size();
    a = vector<int>(n + 1);
    t = arr;

    a[0] = -1;
    int j = -1;
    for (int i = 0; i < n; i++) {
      while (j >= 0 && t[j] != t[i]) j = a[j];
      j++;
      a[i + 1] = j;
    }
