vector<int> KMP(const vector<ll> &target, const vector<ll> &pattern) {
    vector<int> res;
    int len_t = (int)target.size(), len_p = (int)pattern.size();

    // create table
    std::vector<int> table(len_p);
    table.at(0) = 0;
    int j = 0;
    for (int i=1; i<len_p; i++) {
        if (pattern.at(i) == pattern.at(j)) {
            table.at(i) = j;
            j++;
        } else {
            table.at(i) = j;
            j = 0;
        }
    }

    // search pattern in target
    int cur_t = 0, cur_p = 0;
    while (cur_t < len_t && cur_p < len_p) {
        if (target.at(cur_t) == pattern.at(cur_p)) {
            cur_p++; cur_t++;
        } else if (cur_p == 0) {
            cur_t++;
        } else {
            cur_p = table.at(cur_p);
        }
    }
    if (cur_p == len_p) {
        int ind = cur_t - cur_p;
        bool syuuki = true;
        int cnt0 = 1;
        for (int i=1; i<len_p; i++) {
            if (table.at(i) == 0) cnt0++;
            else if (table.at(i) != table.at(i-1) + 1) {
                syuuki = false;
                break;
            }
        }
        res.push_back(ind);
        cnt0--;
        if (len_p%cnt0 != 0) syuuki = false;
        if (syuuki) {
            ind += cnt0;
            while (ind < len_p) {
                res.push_back(ind);
                ind += cnt0;
            }
        }
    }
    return res;
}

