vector<int> to_xor(vector<int> x)
{
    int n = x.size();
    vector<int> ret(n);
    for (int i = 0; i < n; i++)
    {
        ret[i] = x[i] ^ x[(i + 1) % n];
    }
    return ret;
}

template <typename T>
class MP
{
    long long n;
    T t;
    vector<long long> table;

public:
    MP(const T &str)
    {
        this->t = T(str);
        this->n = t.size();
        this->table = vector<long long>(this->n + 1, -1);
        long long j = -1;
        for (long long i = 0; i < this->n; i++)
        {
            while (j != -1 && this->t[j] != this->t[i])
            {
                j = this->table[j];
            }
            j++;
            this->table[i + 1] = j;
        }
    }

    int operator[](const int i)
    {
        return this->table[i];
    }

    vector<long long> find_from(const T &s)
    {
        vector<long long> res;
        long long j = 0;
        for (long long i = 0; i < s.size(); i++)
        {
            while (j != -1 && this->t[j] != s[i])
            {
                j = this->table[j];
            }
            j++;
            if (j == this->n)
            {
                res.push_back(i - j + 1);
                j = this->table[j];
            }
        }
        return res;
    }
};

