vector<int> z_algorithm(const vector<ll> &s) {
	vector<int> prefix(s.size());
	for(int i = 1, j = 0; i < s.size(); i++) {
		if(i + prefix[i - j] < j + prefix[j]) {
			prefix[i] = prefix[i - j];
		} else {
			int k = max(0, j + prefix[j] - i);
			while(i + k < s.size() && s[k] == s[i + k]) ++k;
			prefix[i] = k;
			j = i;
		}
		// debug(prefix);
		// debug(i);
		// debug(j);
		// debug(prefix[j]);
		// debug(j + prefix[j]);
		// cout << "\n";
	}
	prefix[0] = (int)s.size();
	return prefix;
}
