struct rollingHash
{
    int hash_mod=1000000007;
    int hash=10007;
    vi ha;
    vi pow_hash;
    rollingHash(const vi& s)
    {
        int nn=(int)s.size();
        ha.assign(nn+1,0);
        pow_hash.assign(nn+1,1);
        for(int i=0;i<nn;++i)
        {
            ha[i+1]=((ll)ha[i]*hash+s[i])%hash_mod;
            pow_hash[i+1]=((ll)pow_hash[i]*hash)%hash_mod;
        }
    }
    int get(int l,int r)
    {
        return (ha[r]+hash_mod-((ll)ha[l]*pow_hash[r-l])%hash_mod)%hash_mod;
    }
};

