using namespace std;
typedef long long LL;
const int h = 126257;
const int mod = 1e9+7;
int a[200001], b[400001];
LL p[400001];
int A[30][400001];
int B[2][30][200001];
int main(){
    int n;
    scanf("%d", &n);
    for(int i=1;i<=n;i++) scanf("%d", &a[i]);
    for(int i=1;i<=n;i++) scanf("%d", &b[i]);
    for(int i=n+1;i<=n+n;i++) a[i] = a[i-n];

    p[0] = 1;
    for(int i=1;i<=n+n;i++) p[i] = p[i-1]*h%mod;
    for(int i=1;i<=n+n;i++){
        for(int j=0;j<30;j++){
            A[j][i] = (A[j][i-1] + ((a[i]>>j)&1)*p[i])%mod;
        }
    }
    for(int i=1;i<=n;i++){
        for(int j=0;j<30;j++){
            B[0][j][i] = (B[0][j][i-1] + ((b[i]>>j)&1)*p[i])%mod;
            B[1][j][i] = (B[1][j][i-1] + ((1-((b[i]>>j)&1))*p[i]))%mod;
        }
    }

    for(int i=1;i<=n;i++){
        int x = a[i]^b[1];

        bool ok = 1;
        for(int j=0;j<30;j++){
            if((x>>j)&1){
                int Pa = (A[j][i+n-1] - A[j][i-1] + mod)%mod*p[n+n-(i+n-1)]%mod;
                int Pb = B[1][j][n]*p[n+n-n]%mod;
                if(Pa != Pb){
                    ok = 0;
                    break;
                }
            }
            else{
                int Pa = (A[j][i+n-1] - A[j][i-1] + mod)%mod*p[n+n-(i+n-1)]%mod;
                int Pb = B[0][j][n]*p[n+n-n]%mod;
                if(Pa != Pb){
                    ok = 0;
                    break;
                }
            }
        }
        if(ok) printf("%d %d\n", i-1, x);
    }
}

