#include <bits/stdc++.h>
using namespace std;
int n,a[200005],b[200005],aa[200005],bb[200005],rnk[200005],nrnk[200005],x[200005],cnt[200005];
vector<int> t1[200005],t2[200005];
void go(int b,int val)
{
    vector<int> v;
	for (int i=0;i<n;i++)
	{
	    rnk[i]=aa[i];
	    v.push_back(i);
	}
	int cr=1;
	for (int k=0;k<18;k++)
	{
		for (int i=0;i<=n;i++)
		{
			t1[i].clear();
			t2[i].clear();
		}
		for (int i:v)
		t1[rnk[(i+(1<<k))%n]].push_back(i);
		for (int _=0;_<=cr;_++)
		{
			for (int i:t1[_])
			t2[rnk[i]].push_back(i);
		}
		v.clear();
		for (int _=0;_<=cr;_++)
		{
			for (int i:t2[_])
			v.push_back(i);
		}
		cr=0;
		for (int i=0;i<n;i++)
		{
			if (!i)
			nrnk[v[i]]=0;
			else if (rnk[v[i]]!=rnk[v[i-1]] || rnk[(v[i]+(1<<k))%n]!=rnk[(v[i-1]+(1<<k))%n])
			cr++;
			nrnk[v[i]]=cr;
		}
		for (int i=0;i<n;i++)
		rnk[i]=nrnk[i];
	}
	int st=0,cur=0;
	while (st<n)
	{
		while (cur<n && aa[(v[st]+cur)%n]==bb[cur])
		cur++;
		if (cur==n)
		break;
		st++;
	}
	if (st==n)
	return;
	for (int i=0;i<n;i++)
	{
		if (aa[(v[st]+i)%n]!=bb[i])
		return;
	}
	for (int i=0;i<n;i++)
	{
		if (rnk[i]==rnk[v[st]])
		{
			cnt[i]++;
			x[i]|=(val<<b);
		}
	}
}
int main()
{
	scanf("%d",&n);
	for (int i=0;i<n;i++)
	scanf("%d",&a[i]);
	for (int i=0;i<n;i++)
	scanf("%d",&b[i]);
	for (int i=0;i<30;i++)
	{
		for (int j=0;j<n;j++)
		{
			aa[j]=((a[j]>>i)&1);
			bb[j]=((b[j]>>i)&1);
		}
		for (int j=0;j<2;j++)
		{
			go(i,j);
			for (int k=0;k<n;k++)
			aa[k]^=1;
		}
	}
	for (int i=0;i<n;i++)
	{
		if (cnt[i]==30)
		printf("%d %d\n",i,x[i]);
	}
}

