void solve() {
    in(N);
    na(A, N);
    na(B, N);
    auto ta = A, tb = B;
    A *= 3;
    B *= 3;
    rep(i, N * 3 - 1) {
        A[i] ^= A[i + 1];
        B[i] ^= B[i + 1];
    }
    resize(A, N * 2);
    resize(B, N);
    roll ra(A), rb(B);
    deb(A);
    deb(B);
    auto has = rb();
    rep(k, N) {
        if (ra(k, k + N) == has) {
            out(k, ta[k] ^ tb[0]);
        }
    }
}

