    while (i < pat.size()) { 
        if(len == 0){
           //setting the offset here
           matcher = pat[len]^pat[i]; 
           lps[i] = ++len;
           i++;
        }else if (pat[i] == (pat[len] ^ matcher)) { 
            lps[i] = ++len;
            i++; 
        } 
        else // (pat[i] != pat[len]) 
        { 
            len = lps[len - 1]; 
        } 
    } 
}
