  // さて複数位置一致する場合は、AもBもともに、ある数列の n 回の繰り返しになっていないといけない
  // A = C x n, B = D x n
  // C[i] == B[(i+l)%(N/n)]

  vector<u64> cs(N), ds(N);
  cs[0] = as.back()^as[0];
  F0R(i, N-1) {
    cs[i+1] = as[i] ^ as[i + 1];
  }
  ds[0] = bs.back() ^ bs[0];
  F0R(i, N - 1) {
    ds[i+1] = bs[i] ^ bs[i + 1];
  }

  // 先頭からの文字列が、途中から反復していないか、
  // していればその文字数を記録する
  // ABCDABD
  // 0000120
  vector<int> ts(N);
  ts[0] = 0;
  FOR(i, 1, N) {
    if (ds[ts[i-1]] == ds[i]) {
      ts[i] = ts[i-1]+1;
    }
    else ts[i] = 0;
  }

  // cs内からdsを探す
  int skip = 0;
  for(int i=0;i<N;/*NOP*/) {

    bool match = true;
    FOR(j, skip, N) {
      int k = j + i;
      if (k >= N) k -= N;
      if (ds[j] != cs[k]) {
        match = false;

        i += j + 1;
        if (j > 0) {
          i -= ts[j - 1];
          skip = ts[j - 1];
        }
        break;
      }
    }

    if (match) {
      cout << i << " " << (bs[0] ^ as[i]) << newl;
      i += N - ts.back();
      skip = ts.back();
    }
  }
}
