  for (int i = 0; i < N-1; i++) {
    modn <<= 1;
    modn %= M;
  }

  bool ok[N + 1];
  memset(ok, true, sizeof(ok));
  for (int i = 0; i < 30; i++) {
    bool ok2[N + 1];
