		int au=a>>31;
		int ad=a&MASK31;
		int bu=b>>31;
		int bd=b&MASK31;
		int mid=ad*bu+au*bd;
		int midu=mid>>30;
		int midd=mid&MASK30;
		return calcmod(au*bu*2+midu+(midd<<31)+ad*bd);
	}
