            hash[i+1]=(mul(hash[i],Base)+s[i])%MOD;
            power[i+1]=mul(power[i],Base)%MOD;
        }
    }
    int get_hash(int l,int r){
        //[l,r)
        return (hash[r]-mul(hash[l],power[r-l])+MOD)%MOD;
    }
    int lcp(int x,int y){
        //Longest Common Prefix
        // [x,n) , [y,n)
        //Returns Maximum Length
        int len=min(hash.size()-y,hash.size()-x);
        int ok=0,ng=len+1;
        while(ng-ok>1){
            int mid=(ok+ng)/2;
            if(get_hash(x,x+mid)==get_hash(y,y+mid))ok=mid;
            else ng=mid;
        }
        return ok;
    }
    int lcs(int x,int y){
        //Longest Common Suffix
        // [0,x) , [0,y)
        //Returns Maximum Length
        int len=min(x,y);
        int ok=0,ng=len+1;
        while(ng-ok>1){
            int mid=(ok+ng)/2;
            if(get_hash(x-mid,x)==get_hash(y-mid,y))ok=mid;
            else ng=mid;
        }
        return ok;
    }
};
