	c[cnt++] = -1;
	lop(i, 0, n) c[cnt++] = a1[i];
	lop(i, 0, n) c[cnt++] = a1[i];

	int k = 3 * n + 1;
	// bug(cnt, k);

	lop(i, 1, k)
	{
		int j = kmp[i - 1];
		while (j and c[i] != c[j] ) j = kmp[j - 1];
		if ( c[i] == c[j] ) j++;
