        compb[i] = lower_bound(tb.begin(),tb.end(),b[i%N]) - tb.begin();
    }

    RH rhb;
    rhb.init(compb);

    map<ull,vector<int>> mp;
    for(int k = 0; k < N;k++){
        ull hash_b = rhb.h(k,k+N);
        mp[hash_b].push_back(k);
    }

    vector<pll> ans;
    for(auto p:mp){
        vector<int>& ks = p.second;

        bool ok = true;
