const int maxn = 4e5 + 10;
bool mat[maxn];
int n, A[maxn], B[maxn], dataA[maxn], dataB[maxn];

void kmp(int *A, int *B) {
  static int nxt[maxn];
  for (int i = 2, j = 0; i <= n; i++) {
    while (j && B[i] != B[j + 1]) j = nxt[j];
    j += B[i] == B[j + 1], nxt[i] = j;
  }
  for (int i = 1, j = 0; i <= n * 2; i++) {
    while (j && A[i] != B[j + 1]) j = nxt[j];
    j += A[i] == B[j + 1];
    if (j == n) {
      mat[i - n + 1] = 1, j = nxt[j];
    }
  }
}

int main() {
  n = read();
  rep(i, 1, n) A[i] = read();
  rep(i, 1, n) B[i] = read();
  rep(i, 1, n) dataA[i] = A[i] ^ A[i % n + 1];
  rep(i, 1, n) dataB[i] = B[i] ^ B[i % n + 1];
  rep(i, 1, n) dataA[n + i] = dataA[i];
  kmp(dataA, dataB);
  rep(i, 1, n) if (mat[i]) {
    printf("%d %d\n", i - 1, A[i] ^ B[1]);
  }
  return 0;
}

