int A[maxN], B[maxN], T[maxN], pi[maxN], n;
vector <pair <int, int> > ans;

void ins(int k)
{
	int x = A[0] ^ B[--k];
	if (k != 0)
		k = n-k;
	ans.pb({k, x});
}

void solve()
