		scanf ("%d", B+i);
	A[n] = A[0], B[n] = B[0];
	int m = 0;
	FOR(i, 0, n)
		T[++m] = A[i] ^ A[i+1];
	T[++m] = -1;
	FOR(_, 0, 2)
		FOR(i, 0, n)
			T[++m] = B[i] ^ B[i+1];
