// 文章Sに対して，ワードWの開始位置のvectorを返す
vector<ll> KMP(vector<ll>& W, vector<ll>& S) {
    int N = W.size();
    vector<int> T(N+1);
    T[0] = -1;
    ll j = -1;
    rep(i,W.size()){
        while (j >= 0 && W[i] != W[j]) j = T[j];
        T[i+1] = ++j;
    }
    vector<ll> res;
    ll m = 0, i = 0;
    while (m+i < S.size()) {
        if (W[i] == S[m+i]) {
            if (++i == (ll)W.size()) {
                res.push_back((N-m)%N);
                m = m+i-T[i];
                i = T[i];
            }
        } else {
            m = m+i-T[i];
            if (i > 0) i = T[i];
        }
    }
    return res;
}

