template < typename T >
vector< int > KMPTable(T &B) {
	int N = B.size();
	vector< int > table(N + 1, -1);
	int j = -1;
	for (int i = 0; i < N; i++) {
		while (j >= 0 && B[i] != B[j])
			j = table[j];
		table[i + 1] = ++j;
	}
	return table;
}
template < typename T >
vector< int > KMPSearch(T &A, T &B) {
	int N = A.size(), M = B.size();
	vector< int > table = KMPTable(B);
	vector< int > ret;
	for (int i = 0, k = 0; i < N; i++) {
		while (k >= 0 && A[i] != B[k])
			k = table[k];
		++k;
		if (k >= M) {
			ret.push_back(i - M + 1);
			k = table[k];
		}
	}
	return ret;
}
