vector<int> prefix_function_kmp(vector<int> s){
    int n=s.size();
    vector<int> pi(n,0);
    for(int i=1;i<n;i++){
        int j=pi[i-1];
        while(j>0&&s[i]!=s[j]){
            j=pi[j-1];
        }
        if(s[i]==s[j]){
            j++;
        }
        pi[i]=j;
    }

    return pi;
}

vector<int> search_substring_kmp(vector<int> ns,vector<int> s){
    vector<int> pi=prefix_function_kmp(ns);
    vector<int> result;
    for(int i=2*s.size();i<ns.size()-1;i++){
        if(pi[i]==s.size()){
            result.push_back(i-2*s.size());
        }
    }
    return result;
}

