vector<int> z_function(vector<int> &s)
{
	int n=s.size();
	vector<int> z(n);
	for(int i=1,l=0,r=0;i<n;i++)
	{
		if(i<=r)
			z[i]=min(r-i+1, z[i-l]);
		while(i+z[i]<n && s[z[i]]==s[i+z[i]])
			z[i]++;
		if(i+z[i]-1>r)
			l=i, r=i+z[i]-1;
	}
	return z;
}

vector<int> work(vector<int> &a, vector<int> &b)
{
	vector<int> cur;
	for(auto &it:b)
		cur.push_back(it);
	cur.push_back(-1);
	for(auto &it:a)
		cur.push_back(it);
	vector<int> z = z_function(cur);
	vector<int> ans;
	for(int i = n + 1; i < z.size(); i++)
	{
		if(z[i] == n && i - n - 1 < n)
			ans.push_back(i - n - 1);
	}
	return ans;
}

