struct RollingHash {
	//string text; // text
	int n; // number of characters
	int base1 = 1009;
	int base2 = 1007;
	ll mod1 = (ll)1e9 + 9;
	ll mod2 = (ll)1e9 + 7;
	ll* pow1;
	ll* pow2;
	ll* hash1;
	ll* hash2;
	/* constructor */
	RollingHash(vector<int> a) {
		//text = s;
		n = a.size();
		hash1 = new ll[n + 1];
		hash2 = new ll[n + 1];
		pow1 = new ll[n + 1];
		pow2 = new ll[n + 1];
		hash1[0] = hash2[0] = 0;
		pow1[0] = pow2[0] = 1;
		for (int i = 0; i < n; ++i) {
			hash1[i + 1] = (hash1[i] + a[i]) * base1 % mod1;
			hash2[i + 1] = (hash2[i] + a[i]) * base2 % mod2;
			pow1[i + 1] = pow1[i] * base1 % mod1;
			pow2[i + 1] = pow2[i] * base2 % mod2;
		}
	}
	/* text[l,l+1,...,r-1]のハッシュ値を計算 */
	pair<ll, ll> get(int l, int r) {
		pair<ll, ll> p;
		p.first = ((hash1[r] - hash1[l] * pow1[r - l] % mod1) + mod1) % mod1;
		p.second = ((hash2[r] - hash2[l] * pow2[r - l] % mod2) + mod2) % mod2;
		return p;
	}
};


vector<int> XOR(vector<int> a, int b) {
	int n = a.size();
	vector<int> res(n);
	for (int i = 0; i < n; ++i) res[i] = a[i] ^ b;
	return res;
}

string VecToStr(vector<int>* a) {
	string res = ""; int sz = (*a).size();
	for (int i = 0; i < sz; ++i)
		res += '0' + (*a)[i];
	return res;
}

vector<int> cyclic(vector<int>* s1, vector<int>* s2) {
	vector<int> s22(2 * (*s1).size());
	for (int i = 0; i < 2 * (*s1).size(); ++i)
		s22[i] = (*s2)[i % (*s1).size()];
	RollingHash r1(*s1), r2(s22);
	vector<int> res;
	int sz = (*s1).size();
	for (int i = 0; i < sz; ++i) {
		if (r1.get(0, sz) == r2.get(i, i + sz))
			res.push_back(i);
	}
	return res;
}

