V<int> z_algo(const string &s){
    int n=s.size();
    V<int> prefix(n);
    for(int i=1,j=0;i<n;i++){
        if(i+prefix[i-j]<j+prefix[j]){
            //すでに計算済みの場所である
            prefix[i]=prefix[i-j];
        }else{
            // わからないところを愚直に調べる
            int k=max(0,j+prefix[j]-i);
            while(i+k<n&&s[k]==s[i+k])k++;
            prefix[i]=k;
            j=i;
        }
    }
    prefix[0]=n;
    return prefix;
}
