const ll B = 31;
const ll MOD = 1000000007;

const ll B2 = 37;
const ll MOD2 = 998244353;
const int MAXN = 100010;


void solve()
{
	int n = inp();
	vector<int> a(n*2+2);
	for (int i = 1; i <= n; ++i)
		a[i] = inp();
	auto ta = a;
	a[0] = a[n];
	for (int i = n; i >= 1; --i)
		a[i] = a[i] ^ a[i - 1];

	vector<int> b(2*n+2);
	for (int i = 1; i <= n; ++i)
		b[i] = b[i+n] = inp();
	auto tb = b;
	b[0] = b[n];
	for (int i = n * 2; i >= 1; --i)
		b[i] = b[i] ^ b[i - 1];

	vector<ll> h(2 * n + 2), h2(2*n+2);
	for (int i = 1; i <= n * 2; ++i)
	{
		h[i] = (h[i - 1] * B + b[i])%MOD;
		h2[i] = (h2[i - 1] * B2 + b[i]) % MOD2;
	}
	vector<ll> g(2 * n + 2), g2(2 * n + 2);
	for (int i = 1; i <= n * 2; ++i)
	{
		g[i] = (g[i - 1] * B + a[i]) % MOD;
		g2[i] = (g2[i - 1] * B2 + a[i]) % MOD2;
	}
	ll hash = g[n], hash2 = g2[n];
	vector<pair<int, int>> ans;
	for (int i = 2 * n - 1; i >= n; --i)
	{
		ll tmp = (h[i] - h[i - n] * power(B, n, MOD) % MOD + MOD) % MOD;
		ll tmp2 = (h2[i] - h2[i - n] * power(B2, n, MOD2) % MOD2 + MOD2) % MOD2;

		if (tmp == hash && tmp2 == hash2)
		{
			int k = (n - (i - n)) % n;
			ans.push_back({ k, ta[n] ^ tb[n - k] });
		}
	}
	sort(ans.begin(), ans.end());
	for (auto e : ans)
		printf("%d %d\n", e.X, e.Y);
}

