#include <bits/stdc++.h>
using namespace std;

struct RollingHash {
  long long Mod[2], Base[2];
  long long ssize, maxssize;
  vector<string> s;
  vector<long long> pow[2];
  vector<vector<long long>> hash[2];
  RollingHash(const long long len = 3000000) {
    Mod[0] = 1000000007;
    Mod[1] = 1000000009;
    Base[0] = 1009;
    Base[1] = 1007;
    maxssize = len;
    for(int t = 0; t < 2; ++t) {
      pow[t].assign(len + 1, 0);
      pow[t][0] = 1;
      for(int i = 1; i <= len; ++i)
        pow[t][i] = pow[t][i - 1] * Base[t] % Mod[t];
    }
  }
  void add(const string &_s) {
    int id = s.size();
    s.push_back(_s);
    sethash(id);
  }
  void changestr(const string &_s, int id) {
    assert(id < (int)s.size());
    s[id] = _s;
    sethash(id);
  }
  void sethash(const int &id) {
    int len = s[id].size();
    for(int t = 0; t < 2; ++t) {
      hash[t].push_back(vector<long long>(len + 1, 0));
      for(int i = 0; i < len; ++i) {
        if(i != 0)
          hash[t][id][i + 1] =
              hash[t][id][i] * Base[t] % Mod[t];
        hash[t][id][i + 1] += s[id][i];
        hash[t][id][i + 1] %= Mod[t];
      }
    }
  }
  // [l,r),0-indexed
  pair<long long, long long> calchash(const int &id,
                                      const int &l,
                                      const int &r) {
    long long ans[2];
    for(int t = 0; t < 2; ++t) {
      ans[t] = hash[t][id][r];
      ans[t] -= hash[t][id][l] * pow[t][r - l] % Mod[t];
      while(ans[t] < 0) ans[t] += Mod[t];
      ans[t] %= Mod[t];
    }
    return make_pair(ans[0], ans[1]);
  }
  inline bool issame(const int &idl, const int &ll,
                     const int &lr, const int &idr,
                     const int &rl, const int &rr) {
    return calchash(idl, ll, lr) == calchash(idr, rl, rr);
  }
};

long long n;
vector<long long> a, b;
RollingHash rh;

void solve();

int main() {
  cin >> n;
  a.resize(n);
  b.resize(n);
  for(int i = 0; i < n; ++i) cin >> a[i];
  for(int i = 0; i < n; ++i) cin >> b[i];
  solve();
