}

void solve() {
  for(int i = 0; i < 30; ++i) {
    string s, t, r;
    for(int j = 0; j < n; ++j) {
      s += '0' + (a[j] >> i & 1);
      t += '0' + 1 - (a[j] >> i & 1);
      r += '0' + (b[j] >> i & 1);
    }
    s += s;
    t += t;
    r += r;
    rh.add(s);
    rh.add(t);
    rh.add(r);
  }
  for(int i = 0; i < n; ++i) {
    bool ch = 1;
    for(int j = 0; j < 30; ++j)
      if(!rh.issame(j * 3, i, i + n, 2 + j * 3, 0, n) &&
         !rh.issame(1 + j * 3, i, i + n, 2 + j * 3, 0, n))
        ch = 0;
    if(ch) cout << i << " " << (a[i] ^ b[0]) << endl;
  }
}

