typedef long long ll;

int n;

vector<int> calc(vector<int> s)
{
	vector<int> ans(s.size()+1);

	ans[0]=-1;
	int j=-1;

	for(int i=0;i<s.size();i++)
	{
		while(j>-1&&s[j]!=s[i])j=ans[j];

		ans[i+1]=(++j);
	}

	return ans;
}

vector<int> matchIndex(vector<int> s,vector<int> t)
{
	vector<int> ret;
	vector<int> a=calc(t);

	for(int m=0,i=0;m<=s.size()-t.size();)
	{
		while(m+i<s.size()&&i<t.size()&&s[m+i]==t[i])i++;

		if(i==t.size())ret.pb(m);

		m+=max(i-a[i],1);

		i=max(a[i],0);
	}

	return ret;
}

