void KMP(int sh)
{
	for (int i = 1, j = 0; i < n; i++)
	{
		while (j && (b[i] & 1 << sh) != (b[j] & 1 << sh))
			j = f[j - 1];
		if ((b[i] & 1 << sh) == (b[j] & 1 << sh))
			j++;
		f[i] = j;
	}
	for (int i = 1, j = 0; i < 2 * n; i++)
	{
		while (j && (a[i] & 1 << sh) != (b[j] & 1 << sh))
			j = f[j - 1];
		if ((a[i] & 1 << sh) == (b[j] & 1 << sh))
			j++;
		if (j == n)
			cnt[i-n]++, j = f[j - 1];
	}

	for (int i = 1, j = 0; i < 2 * n; i++)
	{
		while (j && (a[i] & 1 << sh) == (b[j] & 1 << sh))
			j = f[j - 1];
		if ((a[i] & 1 << sh) != (b[j] & 1 << sh))
			j++;
		if (j == n)
			cnt[i - n]++, ans[i - n] |= 1 << sh, j = f[j - 1];
	}
}

