int main()
{
	cin.tie(0);
	ios::sync_with_stdio(false);

	ll N;
	cin >> N;

	vector<ll> as(N);
	vector<ll> bs(N);

	for (ll i = 0; i < N; ++i) {
		cin >> as[i];
	}
	for (ll i = 0; i < N; ++i) {
		cin >> bs[i];
	}

	vector<ll> diff_as(N * 2 - 1);
	vector<ll> diff_bs(N);
	for (ll i = 0; i < N; ++i) {
		diff_as[i] = as[(i + N) % N] ^ as[(i - 1 + N) % N];
		diff_bs[i] = bs[(i + N) % N] ^ bs[(i - 1 + N) % N];
	}
	for (ll i = 0; i < N - 1; ++i) {
		diff_as[N + i] = diff_as[i];
	}

	ll begin_idx = find(diff_bs, diff_as);
	vector<pair<ll, ll>> results;
	if (begin_idx >= 0) {
		for (ll i = 0; i < N - 1; ++i) {
			diff_bs.emplace_back(diff_bs[i]);
		}
		vector<ll> lengths = z_algorithm(diff_bs);

		ll res_index;
		for (ll i = 0; i < N; ++i) {
			if (lengths[i] >= N) {
				res_index = (begin_idx + i) % N;
				results.emplace_back(res_index, as[res_index] ^ bs[0]);
			}
		}
	}

	for (ll i = 0; i < results.size(); ++i) {
		cout << results[i].first << " " << results[i].second << endl;
	}

	return 0;
}

#include <bits/stdc++.h>
using namespace std;
const int N = 2e5 + 5;

int n, a[N], b[N], axor[N], bxor[N];
int c[N], pi[3 * N];

int main() {
  ios::sync_with_stdio(false); cin.tie(0); cout.tie(0);
  cin >> n;
  for (int i = 0; i < n; ++i) cin >> a[i];
  for (int i = 0; i < n; ++i) cin >> b[i];
  for (int i = 0; i < n; ++i) {
    axor[i] = a[i] ^ a[(i + 1) % n];
    bxor[i] = b[i] ^ b[(i + 1) % n];
  }
  for (int i = 0; i < n; ++i) c[i] = bxor[i];
  c[n] = -1;
  for (int i = 0; i < n; ++i) c[n + 1 + i] = c[2 * n + 1 + i] = axor[i];

  int m = 3 * n;
  for (int i = 1; i <= m; ++i) {
    int j = pi[i - 1];
    while (j > 0 && c[i] != c[j]) j = pi[j - 1];
    if (c[i] == c[j]) ++j;
    pi[i] = j;
  }

  for (int i = 2 * n; i < m; ++i) {
    if (pi[i] == n) {
      int k = i - 2 * n;
      cout << k << " " << (a[k] ^ b[0]) << "\n";
    }
  }
  return 0;
}

