template <typename S>
struct RollingHash {
private:
    static const u64 mod = (1ull << 61) - 1;
    const u64 MASK30 = (1ull << 30) - 1;
    const u64 MASK31 = (1ull << 31) - 1;
    const u64 POSITIVIZER = mod * ((1ull << 3) - 1);
    u64 base;
    vector<u64> power;

    u64 Mul (u64 a, u64 b) {
        u64 au = a >> 31;
        u64 ad = a & MASK31;
        u64 bu = b >> 31;
        u64 bd = b & MASK31;
        u64 mid = ad * bu + au * bd;
        u64 midu = mid >> 30;
        u64 midd = mid & MASK30;
        return (au * bu * 2 + midu + (midd << 31) + ad * bd);
    }

    u64 CalcMod(u64 val) {
        val = (val & mod) + (val >> 61);
        if (val >= mod) val -= mod;
        return val;
    }

public:
    static inline u64 generate_base() {
        mt19937_64 mt(chrono::steady_clock::now().time_since_epoch().count());
        uniform_int_distribution<u64> rand(1, RollingHash::mod - 1);
        return rand(mt);
    }

    RollingHash(int N, u64 base) : power(N+1,1), base(base) {
        for (int i = 0; i < N; ++i) {
            power[i+1] = CalcMod(Mul(power[i],base));
        }
    }

    vector<u64> gethash(const S &s) {
        int sz = s.size();
        vector<u64> ret(sz+1);
        for (int i = 0; i < sz; ++i) {
            ret[i+1] = CalcMod(Mul(ret[i],base) + s[i] + 1);
        }
        return ret;
    }

    // [l,r) (0-indexed)
    u64 getrange(const vector<u64> &hash, int l, int r) {
        return CalcMod(hash[r] + POSITIVIZER - Mul(hash[l],power[r-l]));
    }

    u64 getval(const S &s) {
        u64 ret = 0;
        for (int i = 0; i < s.size(); ++i) {
            ret = CalcMod(Mul(ret,base) + s[i] + 1);
        }
        return ret;
    }

    u64 connect(u64 hl, u64 hr, int rlen) {
        return CalcMod(CalcMod(Mul(hl,power[rlen])) + hr);
    }

	int LCP(const vector<u64> &a, const vector<u64> &b, int l1, int r1, int l2, int r2) {
		int len = min(r1 - l1, r2 - l2);
    	int low = -1, high = len + 1;
    	while (high - low > 1) {
      		int mid = (low + high) / 2;
      		if (getrange(a, l1, l1 + mid) == getrange(b, l2, l2 + mid)) low = mid;
      		else high = mid;
    	}
    	return low;
	}
};


