using namespace std;

template <class String>
std::vector<size_t> knuth_morris_pratt(const String &text, const String &pattern) {

    const size_t N = text.size();
    const size_t M = pattern.size();

    if (M == 0) {
        std::vector<size_t> result(N + 1);
        for (size_t i = 0; i <= N; ++i) {
            result[i] = i;
        }
        return result;
    }

    int i, j;

    // lps[i] is the length of the longest proper prefix and suffix of pattern[:i + 1].
    std::vector<size_t> lps(M);
    lps[0] = 0;
    i = 1;
    j = 0;
    while (i < M) {
        if (pattern[i] == pattern[j]) {
            lps[i++] = ++j;
        } else if (j > 0) {
            j = lps[j - 1];
        } else {
            lps[i++] = 0;
        }
    }

    std::vector<size_t> result;
    i = 0;
    j = 0;
    while (i < N) {
        if (text[i] == pattern[j]) {
            ++i;
            if (j < M - 1) {
                ++j;
            } else {
                result.push_back(i - M);
                j = lps[M - 1];
            }
        } else if (j > 0) {
            j = lps[j - 1];
        } else {
            ++i;
        }
    }

    return result;
}

int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);

    int N;
    cin >> N;
    vector<int> a(N), b(N);
    REP(i, N) cin >> a[i];
    REP(i, N) cin >> b[i];

    if (N == 1) {
        cout << 0 << ' ' << (a[0] ^ b[0]) << endl;
        return 0;
    }

    vector<int> a_diff(2 * (N - 1)), b_diff(N - 1);
    REP(i, N - 1) {
        a_diff[i] = a[i + 1] ^ a[i];
        b_diff[i] = b[i + 1] ^ b[i];
    }
    a_diff[N - 1] = a[0] ^ a[N - 1];
    FOR(i, N, a_diff.size()) {
        a_diff[i] = a_diff[i - N];
    }

    vector<size_t> ks = knuth_morris_pratt(a_diff, b_diff);
    for (int k: ks) {
        int x = a[k] ^ b[0];
        cout << k << ' ' << x << '\n';
    }
    cout << flush;

    return 0;
}

