struct info
{
	int x,y;
	info(int x=0,int y=0):x(x),y(y) {}
	bool operator == (const info &rhs) const
	{
		return x==rhs.x && y==rhs.y;
	}
	info operator + (const info &rhs) const
	{
		return info(add(x,rhs.x,P1),add(y,rhs.y,P2));
	}
	info operator - (const info &rhs) const
	{
		return info(add(x,P1-rhs.x,P1),add(y,P2-rhs.y,P2));
	}
	info operator * (const info &rhs) const
	{
		return info(mul(x,rhs.x,P1),mul(y,rhs.y,P2));
	}
