ll POW(ll a, ll b) {ll c = 1; while (b > 0) {if (b & 1) {c = mul(a, c, mod);}a = mul(a, a, mod); b >>= 1;}return c;}

void solve() {
    int n; cin >> n;
    vector<int> A(n), B(n);
    rep (i, n) cin >> B[i];
    rep (i, n) cin >> A[i];
    mod = 1111111999999;
    int base = 1ll<<31;
    int hashA = 0, hashB = 0;
    rep (i, n) {
        hashA = mul(hashA, base, mod);
        hashB = mul(hashB, base, mod);
        hashA += (A[i] ^ A[(i + 1) % n]);
        hashB += (B[i] ^ B[(i + 1) % n]);
        if (hashA >= mod) hashA -= mod;
        if (hashB >= mod) hashB -= mod;
    }
    vector<int> ans;
    if (hashA == hashB) ans.emplace_back(0);
    int remo = POW(base, n - 1);
    rep (i, n-1) {
        hashB -= mul(remo, B[i]^B[(i+1)%n], mod);
        if (hashB < 0) hashB += mod;
        hashB = mul(hashB, base, mod);
        hashB += (B[i]^B[(i+1)%n]);
        if (hashB >= mod) hashB -= mod;
        if (hashA == hashB) ans.emplace_back(i + 1);
    }
    for (auto elm : ans) {
        cout << elm << " " << (A[0] ^ B[elm]) << endl;
    }
}

