        vec2[i] = Vec2[i] ^ Vec2[(i + 1) % n];
    }
    string s;
    string t;
    rep(i,n){
        string temp1 = to_string(vec1[i]);
        s.insert(s.size(),temp1);
        string temp2 = to_string(vec2[i]);
        t.insert(t.size(), temp2);
    }
    s.insert(s.size(), s);
    RollingHash tree(s, 1e9 + 7, 1e3 + 7);
    RollingHash tree2(s, 999999937, 1e3 + 7);
    RollingHash tree5(s, 1000000033, 1e3 + 7);
    RollingHash tree3(t, 1e9 + 7, 1e3 + 7);
    RollingHash tree4(t, 999999937, 1e3 + 7);
    RollingHash tree6(t, 1000000033, 1e3 + 7);
    VP res;
  //  cout<<s<<" "<<t<<endl;
