const int maxn = 2e5 + 10 ;

#define int long long

int a[maxn] , b[maxn] , aa[2*maxn] , bb[2*maxn] , p[maxn] , n ;

vector<pair<int,int> > ans ;

void prefix()
{
    int now = p[0] = -1 ;
    int len = n ;
    for(int i = 1 ; i < len ; ++i)
    {
        while(now!=-1 && bb[now+1]!=bb[i]) now = p[now] ;
        if(bb[now+1]==bb[i]) p[i] = ++now ;
        else p[i] = now = -1 ;
    }
}

int kmp()
{
    prefix() ;
    int cnt = 0 , now = -1 ;
    for(int i = 0 ; i < 2*n ; ++i)
    {
        while(now != -1 && bb[now+1]!=aa[i]) now = p[now] ;
        if(bb[now+1]==aa[i]) ++now ;
        else now = -1 ;
        if(now==n-1)
        {
            int xx = i-n+1 ;
            ans.push_back({xx,a[xx-1]^b[n-1]}) ;
            now = p[now] ; ++cnt ;
        }
    }
}

int32_t main()
{
    scanf("%lld",&n) ;
    for(int i = 0 ; i < n ; ++i) scanf("%lld",&a[i]) ;
