        roll rb(DS[b]);
        auto hb = rb(0, N);
        rep(x, 2) {
            vi C = bget1(A,b);
            C*=2;
            for_each(C,^=x);
            roll ra(C);
            rep(r, N) {
                //簡易チェック
                rep(3){
                    int i = ps[pi++];
                    if(pi>=N)pi=0;
                    if((C[r+i]) != DS[b][i])goto end;
                }
                if (ra(r, r + N) == hb) {
                    callr[r]++;
                    resr[r] += bit(b) * x;
                }
                end:;
            }
        }
    }
    rep(r, N) {
        if (callr[r] == 31) {
            out(r, A[r] ^ B[0]);
        }
    }
}
