	for (int i = 1; i < n; i++) {
		z[i] = max(0, min(r - i, z[i - l]));
		while (i + z[i] < n && a[z[i]] == a[i + z[i]]) {
			z[i]++;
		}
		if (i + z[i] > r) {
			l = i;
			r = i + z[i];
		}
	}
	return z;
}

vector<int> solve(vector<int> a, vector<int> b) {
	int n = (int)a.size();
	vector<int> to = a;
	to.push_back(2);
	for (auto t : b) {
		to.push_back(t);
	}
	for (auto t : b) {
		to.push_back(t);
	}
	auto zz = zf(to);
	vector<int> ans;
	for (int shift = 0, pnt = n + 1; shift < n; shift++, pnt++) {
		if (zz[pnt] == n) {
			ans.push_back(shift);
		}
	}
	return ans;
}

