    }
    vector<int> cnt(n);
    for (int bit = 0; bit < LIM; bit++) {
    	vector<int> na(n);
    	vector<int> nb(n);
    	for (int i = 0; i < n; i++) {
    		na[i] = ((a[i] >> bit) & 1);
