		cin >> a[i];
	}
	for (int i = 1; i <= n; i++) {
		cin >> b[i];
	}
	for (int i = 0; i < K; i++) {
		//cout << "i " << i << '\n';
		for (int j = 1; j <= n; j++) {
			c[j] = (a[j] >> i & 1);
			hc[j] = hc[j - 1] + p[j] * c[j];
			hci[j] = hci[j - 1] + p[j] * (1 - c[j]);

			d[j] = (b[j] >> i & 1);
			hd[j] = hd[j - 1] + p[j] * d[j];
			//cout << c[j];
		}
		//cout << '\n';
		//for (int j = 1; j <= n; j++) {
