		//cout << '\n';
		for (int j = 0; j < n; j++) {
			if (hc[j] * p[n - j] == hd[n] - hd[n - j] && hc[n] - hc[j] == hd[n - j] * p[j]) {
				//cout << "good " << j << '\n';
				continue;
			}	else if (hci[j] * p[n - j] == hd[n] - hd[n - j] && hci[n] - hci[j] == hd[n - j] * p[j]) {
				val[j] |= (1 << i);
