int main() {
  int N; std::cin >> N;
  for(int i = 0; i < N; ++i) std::cin >> a[i];
  for(int i = 0; i < N; ++i) std::cin >> b[i];
  for(int i = 0; i < N-1; ++i) c[i] = a[i]^a[i+1];
  for(int i = 0; i < 2*N-2; ++i) d[i] = b[i%N]^b[(i+1)%N];
  std::set<int> ans;
  // KMP
  int i = 2, j = 0;
  t[0] = -1; t[1] = 0;
  while(i < N-1) {
    if(c[i-1] == c[j]) t[i++] = ++j;
    else if(j > 0) j = t[j];
    else t[i++] = 0;
  }
  i = j = 0;
  while(j+i < 2*N-2) {
    if(c[i] == d[i+j]) {
      if(++i==N-1) {
        // found
        ans.insert((N-j)%N);
        --i;
      } else continue;
    }
    j += i - t[i];
    if(i > 0) i = t[i];
  }

  // ans
  for(auto k: ans) {
    int x = a[0]^b[(N-k)%N];
    std::cout << k << " " << x << std::endl;
  }
  return 0;
