            for (int i=1,j=0;i<=n;i++) {
                if (j==m) {j=nx[j];}
                while (j>0&&c[i]!=d[j+1]) {j=nx[j];}
                if (c[i]==d[j+1]) {j++;}
                if (i>=m&&j!=m) {bl[i-m]++;}
            }
            flg=1;
        }
        if (!flg) {
            return 0;
        }
        if (tmp1==tmp2&&m-tmp1==tmp2) {
            for (int j=0;j<=m;j++) {
                if (bl[j]==2) {ans[j]=1;}
            }
        } else {
            for (int j=0;j<=m;j++) {
                if (bl[j]==1) {ans[j]=1;}
            }
        }
    }
    for (int i=0;i<m;i++) {
        if (!ans[i]) {printf("%d %d\n",i,a[i+1]^b[1]);}
    }
    return 0;
