vector<int> z_algorithm(vector<int> &s){
    vector<int> v(s.size(), 0);
    int c = 0;
    For(i, 1, s.size()){
        if(i + v[i-c] < c + v[c]) v[i] = v[i-c];
        else{
            int j = max(0, c + v[c] - i);
            while(i + j < s.size() && s[j] == s[i+j]) ++j;
            v[i] = j;
            c = i;
        }
    }
    v[0] = s.size();
    return v;
}

