int nth_bit(int64_t num, int n){
    return (num >> n) & 1;
}

uint64_t randint(){
    static int64_t seed = chrono::duration_cast<chrono::milliseconds>(chrono::system_clock::now().time_since_epoch()).count();
    static mt19937_64 rnd(seed);
    return rnd();
}

template<int64_t mod=int64_t(1e9+7)>
struct RollingHash{
    vector<int64_t> hash;
    vector<int64_t> base_pow;
    int64_t base;

    RollingHash(vector<int> S, int64_t base_=-1):base(base_){
        if(base < 0) base = 1000 + randint() % 10000;
        if(S.size() > 0) initialize(S);
    }

    void initialize(string& S){
        int N = S.size();
        vector<int> s(N);
        for(int i=0; i<N; i++) s[i] = S[i];
        initialize(s);
    }

    void initialize(vector<int>& S){
        int sz = S.size();
        hash.resize(sz+1);
        base_pow.resize(sz+1);
        hash[0] = 0;
        base_pow[0] = 1;
        for(int i=1; i<=sz; i++){
            hash[i] = (hash[i-1] * base + S[i-1]) % mod;
            base_pow[i] = base_pow[i-1] * base % mod;
        }
    }

    // 0-indexed, [a, b)
    int64_t between(int a, int b){
        return (mod + hash[b] - hash[a] * base_pow[b-a] % mod) % mod;
    }
};

int main(){
    int N;
    cin >> N;
    vector<int> AA(N), BB(N);
    for(int i=0; i<N; i++) cin >> AA[i];
    for(int i=0; i<N; i++) cin >> BB[i];

    vector<int> num(N), A(N), B(N);
    int64_t b1 = 1000 + randint() % 10000;
    RollingHash<> hash1A({}, b1), hash1B({}, b1);
    auto eq = [&](int la, int ra, int lb, int rb){
        int64_t v1A = hash1A.between(la, ra);
        int64_t v1B = hash1B.between(lb, rb);
        return (v1A == v1B);
    };

    bitset<200000> ok;
    for(int k=0; k<30; k++){
        ok.reset();
        for(int i=0; i<N; i++){
            A[i] = nth_bit(AA[i], k);
            B[i] = nth_bit(BB[i], k);
        }
        hash1A.initialize(A);
        for(int t=0; t<2; t++){
            hash1B.initialize(B);
            for(int i=0; i<N; i++) if(eq(0, i, N-i, N) && eq(i, N, 0, N-i)) ok[i] = 1;
            for(int i=0; i<N; i++) B[i] = 1-B[i];
        }
        for(int i=0; i<N; i++) if(ok[i]) num[i]++;
    }
    for(int i=0; i<N; i++) if(num[i] == 30){
        cout << i << " " << (AA[i]^BB[0]) << endl;
    }
    return 0;
}

