    return ans;

  vector<ll> pi(P.size(), 0);
  for (ll i = 1, k = 0; i < P.size(); ++i) {
    while (k && P[k] != P[i])
      k = pi[k - 1];
    if (P[k] == P[i])
      ++k;
    pi[i] = k;
  }

  for (ll i = 0, k = 0; i < T.size(); ++i) {
    while (k && P[k] != T[i])
      k = pi[k - 1];
    if (P[k] == T[i])
      ++k;
    if (k == P.size()) {
      k = pi[k - 1];
      if (i - P.size() + 1 < P.size())
        ans.push_back(i - P.size() + 1);
