int a0hs[BN], a1hs[BN], bhs[BN];

/* subroutines */

inline int powmod(int a, int b) {
  int p = 1;
  while (b) {
    if (b & 1) p = (ll)p * a % MOD;
    a = (ll)a * a % MOD;
    b >>= 1;
  }
  return p;
}

void calcbhash(int n, ll as[], int hs[], int bit) {
  for (int k = 0; k < BN; k++) {
    hs[k] = 0;
    for (int i = 0; i < n; i++)
      if (((as[i] >> k) & 1) == bit)
	hs[k] = (hs[k] + eps[i]) % MOD;
  }
}

/* main */

int main() {
  int n;
  scanf("%d", &n);

  for (int i = 0; i < n; i++) scanf("%lld", as + i);
  for (int i = 0; i < n; i++) scanf("%lld", bs + i);

  eps[0] = 1;
  for (int i = 1; i < n; i++) eps[i] = (ll)eps[i - 1] * P % MOD;

  int invp = powmod(P, MOD - 2);

  calcbhash(n, as, a0hs, 1);
  calcbhash(n, as, a1hs, 0);
  calcbhash(n, bs, bhs, 1);

  for (int k = 0; k < n; k++) {
    int m = 0;
    ll x = 0;

    for (ll bm = 1; m < BN; m++, bm <<= 1) {
      if (a1hs[m] == bhs[m]) x |= bm;
      else if (a0hs[m] != bhs[m]) break;
    }

    if (m == BN)
      printf("%d %lld\n", k, x);

    for (int i = 0; i < BN; i++) {
      int abk0 = ((as[k] >> i) & 1), abk1 = abk0 ^ 1;

      a0hs[i] =
	((ll)(a0hs[i] + (MOD - abk0)) % MOD * invp % MOD
	 + abk0 * eps[n - 1]) % MOD;
      a1hs[i] =
	((ll)(a1hs[i] + (MOD - abk1)) % MOD * invp % MOD
	 + abk1 * eps[n - 1]) % MOD;
    }
  }
  return 0;
}

