void kmp(const vector<B> &txt, const vector<B> &pat) {
    int n = txt.size(), m = pat.size();

    table[0] = -1;
    for (int i = 0, j = -1; i < m; i++) {
        while (j >= 0 && pat[i] != pat[j]) {
            j = table[j];
        }
        table[i + 1] = ++j;
    }

    for (int i = 0, j = 0; i < n; i++) {
        while (j >= 0 && txt[i] != pat[j]) {
            j = table[j];
        }
        if (++j >= m) {
            matched[i - m + 1] = true;
            j = table[j];
        }
    }
}

void solve() {
    vector<B> c(2 * N), d(N);
    for (int i = 0; i < 2 * N; i++) {
        c[i] = a[i % N] ^ a[(i + 1) % N];
    }
    for (int i = 0; i < N; i++) {
        d[i] = b[i % N] ^ b[(i + 1) % N];
    }

