namespace MorrisPratt{
    template <typename T>
    vector<int> init(T pat){
        int n = pat.size(), j = -1;
        vector<int> f(n+1, -1);
        for(int i=0;i<n;++i){
            while(j>=0 and pat[i]!=pat[j]) j = f[j];
            f[i+1] = ++j;
        }
        return f;
    }

    template <typename T>
    vector<int> search(T& source, T& pat, vector<int> f={}){
        if(f.empty()){
            f = init(pat);
        }
        int n = source.size(), m = pat.size(), j = 0;
        vector<int> res;
        for(int i=0;i+j<n;){
            while(i+j<n and j<m and source[i+j]==pat[j]){
                ++j;
            }
            if(j==m){
                res.pb(i);
            }
            i = i + j - f[j];
            if(j){
                j = f[j];
            }
        }
        return res;
    }
}

using namespace MorrisPratt;

class FXorShift {
public:
    void solve(std::istream& in, std::ostream& out){
        ios_base::sync_with_stdio(false);
        in.tie(nullptr), out.tie(nullptr);
        int N;
        in>>N;
        vc<int> A(N), B(N), AA(N), BB(N);
        for(auto& a : A) in>>a;
        for(auto& b : B) in>>b;
        REP(i, N){
            AA[i] = A[i] ^ A[(i+1)%N];
            BB[i] = B[i] ^ B[(i+1)%N];
        }
        vc<int> f = init(BB), C(2*N-1);
        REP(i, N){
            C[i] = AA[i];
            if(i<N-1) C[i+N] = AA[i];
        }
        vc<int> ans = search(C, BB, f);
        for(auto& k : ans) out<<k<<' '<<(A[k]^B[0])<<'\n';
    }
};


int main() {
	FXorShift solver;
	std::istream& in(std::cin);
	std::ostream& out(std::cout);
	solver.solve(in, out);
	return 0;
}

