        d[i] = (b[i] ^ b[(i + 1)%N]);
    }

    string C = "", D = "";
    rep(i, 0, N){
        C += to_string(c[i]);
        D += to_string(d[i]);
    }
    C += C;
    RH rh(C), rh2(D);
    RollingHash<999999937> rh3(C), rh4(D);
    for(int i = 0; i < N; i++){
        if(rh.get(i, i + N) == rh2.get(0, N)){
            cout << i << " " << (a[i] ^ b[0]) << endl;
        }
    }

    return 0;
}

