}

vector<int> cyclic(vector<int> s1, vector<int> s2) {
	vector<int> s22(2 * s1.size());
	for (int i = 0; i < 2 * s1.size(); ++i)
		s22[i] = s2[i % s1.size()];
	RollingHash r1(s1), r2(s22);
	vector<int> res;
	int sz = s1.size();
	for (int i = 0; i < sz; ++i) {
		if (r1.get(0, sz) == r2.get(i, i + sz))
			res.push_back(i);
	}
	return res;
}

