int *buildFail(const vi &p) {
  int m = p.size();
  int *fail = new int[m+1];
  int j = fail[0] = -1;
  for (int i = 1; i <= m; ++i) {
    while (j >= 0 && p[j] != p[i-1]) j = fail[j];
    fail[i] = ++j;
  }
  return fail;
}
vi match(const vi &t, const vi &p, int *fail) {
  int n = t.size(), m = p.size();
  vi res;
  for (int i = 0, k = 0; i < n; ++i) {
    while (k >= 0 && p[k] != t[i]) k = fail[k];
    if (++k >= m) {
      res.pb(i - m + 1);
      k = fail[k];
    }
  }
  return res;
}

