// Sparse Table
template <class MeetSemiLattice> struct SparseTable {
    vector<vector<MeetSemiLattice>> dat;
    vector<int> height;

    SparseTable() {}
    SparseTable(const vector<MeetSemiLattice> &vec) { init(vec); }
    void init(const vector<MeetSemiLattice> &vec) {
        int n = (int)vec.size(), h = 0;
        while((1 << h) < n) ++h;
        dat.assign(h, vector<MeetSemiLattice>(1 << h));
        height.assign(n + 1, 0);
        for(int i = 2; i <= n; i++) height[i] = height[i >> 1] + 1;
        for(int i = 0; i < n; ++i) dat[0][i] = vec[i];
        for(int i = 1; i < h; ++i)
            for(int j = 0; j < n; ++j)
                dat[i][j] = min(dat[i - 1][j], dat[i - 1][min(j + (1 << (i - 1)), n - 1)]);
    }

    MeetSemiLattice get(int a, int b) {
        return min(dat[height[b - a]][a], dat[height[b - a]][b - (1 << height[b - a])]);
    }
};

// NlogN
struct SuffixArray {
    vector<int> SA;
    VL s;

    SuffixArray(const VL &str) { Build_SA(str); }

    void Build_SA(const VL &str) {
        s = str;
        SA.resize(s.size());
        iota(begin(SA), end(SA), 0);
        sort(begin(SA), end(SA), [&](const int &a, const int &b) {
            if(s[a] == s[b]) return (a > b);
            return (s[a] < s[b]);
        });
        vector<int> classes(s.size()), c(s.size()), cnt(s.size());
        for(int i = 0; i < s.size(); i++) {
            c[i] = s[i];
        }
        for(int len = 1; len < s.size(); len <<= 1) {
            for(int i = 0; i < s.size(); i++) {
                if(i > 0 && c[SA[i - 1]] == c[SA[i]] && SA[i - 1] + len < s.size() && c[SA[i - 1] + len / 2] == c[SA[i] + len / 2]) {
                    classes[SA[i]] = classes[SA[i - 1]];
                } else {
                    classes[SA[i]] = i;
                }
            }
            iota(begin(cnt), end(cnt), 0);
            copy(begin(SA), end(SA), begin(c));
            for(int i = 0; i < s.size(); i++) {
                int s1 = c[i] - len;
                if(s1 >= 0) SA[cnt[classes[s1]]++] = s1;
            }
            classes.swap(c);
        }
        SA.insert(SA.begin(), s.size());
    }

    int operator[](int k) const { return (SA[k]); }

    int size() const { return (s.size()); }

    bool lt_substr(VL &t, int si = 0, int ti = 0) {
        int sn = s.size(), tn = t.size();
        while(si < sn && ti < tn) {
            if(s[si] < t[ti]) return (true);
            if(s[si] > t[ti]) return (false);
            ++si, ++ti;
        }
        return (si >= sn && ti < tn);
    }

    int lower_bound(VL &t) {
        int low = -1, high = SA.size();
        while(high - low > 1) {
            int mid = (low + high) >> 1;
            if(lt_substr(t, SA[mid]))
                low = mid;
            else
                high = mid;
        }
        return (high);
    }

    pair<int, int> lower_upper_bound(VL &t) {
        int idx = lower_bound(t);
        int low = idx - 1, high = SA.size();
        t.back()++;
        while(high - low > 1) {
            int mid = (low + high) >> 1;
            if(lt_substr(t, SA[mid]))
                low = mid;
            else
                high = mid;
        }
        t.back()--;
        return (make_pair(idx, high));
    }

    void output() {
        for(int i = 0; i < size(); i++) {
            // cout << i << ": " << s.substr(SA[i]) << endl;
        }
    }
};

struct LCP {
    vector<int> lcp, rank;
    SparseTable<int> st;

    LCP(SuffixArray &SA) { Build_LCP(SA); }

    int operator[](int k) const { return (lcp[k]); }

    int size() const { return (lcp.size()); }

    void Build_LCP(SuffixArray &SA) {
        VL &s = SA.s;
        ll n = s.size();
        rank.resize(n + 1);
        for(int i = 0; i <= n; ++i) rank[SA[i]] = i;
        lcp.resize(n + 1);
        lcp[0] = 0;
        int cur = 0;
        for(int i = 0; i < n; ++i) {
            int pi = SA[rank[i] - 1];
            if(cur > 0) --cur;
            for(; pi + cur < n && i + cur < n; ++cur) {
                if(s[pi + cur] != s[i + cur]) break;
            }
            lcp[rank[i] - 1] = cur;
        }
        st.init(lcp);
    }

    // calc lcp
    int getLCP(int a, int b) { // lcp of str.sutstr(a) and str.substr(b)
        return st.get(min(rank[a], rank[b]), max(rank[a], rank[b]));
    }
};

void solve() {
    LCIN(N);
    VL a(N), b(N);
    VECCIN(a);
    VECCIN(b);
    VL dif;
    REP(i, N - 1) dif.emplace_back(b[i] ^ b[i + 1]);
    dif.emplace_back(-1);
    REP(i, 2 * N) { dif.emplace_back(a[i % N] ^ a[(i + 1) % N]); }
    SuffixArray sa(dif);
    LCP lcp(sa);
    VPL ans;
    REP(i, N) {
        if(lcp.getLCP(0, N + i) == N - 1) {
            ans.emplace_back(i, a[i] ^ b[0]);
        }
    }
    REP(i, sz(ans)) { COUT(ans[i].fi, ans[i].second); }
}

