bool loop(LL *a, int n, int k) {
	if (n % k != 0) {
		return false;
	}
	for (int i = 0; i < k; ++i) {
		LL b = a[i];
		for (int j = 0; j < (n / k); ++j) {
			if (a[j * k + i] != b) {
				return false;
			}
		}
	}
	return true;
}

int kmp(vector<LL> &S, vector<LL> &T) {
	int n = T.size();
	int *next = new int[n + 1];

	next[0] = -1;
	for (int i = 0; i < n - 1; ++i) {
		int p = next[i];
		while (p >= 0 && T[p] != T[i]) {
			p = next[p];
		}
		next[i + 1] = p + 1;
	}
	/*for (int i = 0; i < n; ++i) {
		cout << next[i] << ' ';
	}
	cout << endl;
	return false;*/

	int p = 0, q = 0;
	while (p < S.size()) {
		if (q == T.size()) {
			return (p - q) % n;
		}
		if ((q == -1) || (S[p] == T[q])) {
			++p; ++q;
		}
		else {
			q = next[q];
		}
	}
	return -1;

}

