template <class Type>
struct KMP
{
    vector<Type> s, w;
    KMP(vector<Type> s, vector<Type> w):s(s),w(w){}
    vector<int> T;//次の照合位置

    void KMP_table(){
        int j = 2;
        int k = 0;
        T.push_back(-1);
        T.push_back(0);
        while (j <= w.size())
        {
            if (w[j-1] == w[k]){
                T.push_back(k+1); j++; k++;
            }
            else if (k > 0)k = T[k];
            else {
                T.push_back(0); j++;
            }
        }
    }
    //wと一致するsの部分文字列の先頭のインデックスを全て求める
    vector<Type> kmp_search() {
        int m = 0;//s内の照合開始位置
        int i = 0;//w内の現在位置
        vector<Type> ReturnValue;//返り値
        while (m+i < s.size()) {
            if (w[i] == s[m+i]) {
                i++;
                if (i == w.size()) {
                    ReturnValue.push_back(m);
                    m = m+i-T[i];
                    if (i > 0)i = T[i];
                }
            }
            else{
                m = m+i-T[i];
                if (i > 0)i = T[i];
            }
        }
        return ReturnValue;
    }
};

