using namespace std;

long long Calc(long long A, long long B, long long M) {
	if (B == 0) return 1 % M;
	if (B % 2 == 0) {
		long long C = Calc(A, B / 2, M);
		return (C * C) % M;
	}
	return (A * Calc(A, B - 1, M)) % M;
}

int main() {
	long long N;
	cin >> N;
	vector<long long> A(N), B(N), XA(N), XB(N);
	for (int i = 0; i < N; i++) cin >> A[i];
	for (int i = 0; i < N; i++) cin >> B[i];
	for (int i = 0; i < N - 1; i++) XA[i] = A[i] ^ A[i + 1];
	XA[N - 1] = A[0] ^ A[N - 1];
	for (int i = 0; i < N - 1; i++) XB[i] = B[i] ^ B[i + 1];
	XB[N - 1] = B[0] ^ B[N - 1];
	vector<long long> Divs;
	for (long long i = 1; i * i <= N; i++) {
		if (N % i == 0) {
			Divs.push_back(i);
			if (i != N / i && i != 1) Divs.push_back(N / i);
		}
	}
	vector<long long> Loops;
	for (long long D : Divs) {
		bool check = true;
		for (int i = 0; i < N; i++) {
			if (XA[i] != XA[(i + D) % N]) check = false;
		}
		if (check) Loops.push_back(D);
	}
	vector<long long> Loops2;
	for (long long D : Divs) {
		bool check = true;
		for (int i = 0; i < N; i++) {
			if (XB[i] != XB[(i + D) % N]) check = false;
		}
		if (check) Loops2.push_back(D);
	}
	vector<bool> ANS1(N, false);
	for (long long L : Loops) {
		for (long long i = 0; i * L < N; i++) {
			ANS1[L * i] = true;
		}
	}
	vector<bool> ANS2(N, false);
	for (long long L : Loops2) {
		for (long long i = 0; i * L < N; i++) {
			ANS2[L * i] = true;
		}
	}
	vector<long long> ANS;
	for (int i = 0; i < N; i++) {
		if (ANS1[i] && ANS2[i]) ANS.push_back(i);
	}
	if (ANS.size() == 0) ANS.push_back(0);
	long long Hash = 0, HashB = 0, MOD = 998244353, X = 5, Z = Calc(X, N - 1, MOD);
	for (int i = 0; i < N; i++) Hash = (Hash * X) % MOD, Hash = (Hash + XA[i]) % MOD;
	for (int i = 0; i < N; i++) HashB = (HashB * X) % MOD, HashB = (HashB + XB[i]) % MOD;
	bool Acheck = false;
	long long ANSX = 0;
	for (int i = 0; i < N; i++) {
		if (Hash == HashB) {
			bool check = true;
			long long XOR = A[i] ^ B[0];
			for (int j = 0; j < N; j++) {
				if ((A[(i + j) % N] ^ XOR) != B[j]) check = false;
			}
			if (check) {
				Acheck = true;
				ANSX = i;
				break;
			}
		}
		Hash = (Hash + MOD - (XA[i] * Z) % MOD) % MOD;
		Hash = (Hash * X) % MOD;
		Hash = (Hash + XA[i]) % MOD;
	}
	if (!Acheck) cout << endl;
	else {
		for (long long i : ANS) {
			cout << ANSX + i << " " << (A[ANSX + i] ^ B[0]) << endl;
		}
	}
}

