void solve()
{
	for (int i = 1; i <= N; i++)
	{
		mp[b[i]] = i;
	}

	for (int i = 1; i <= N; i++)
	{
		press[mp[b[i]]].push_back(i);
	}

	bool match = false;
	ll slide = 0;
	while (slide < N)
	{
		bool same = true;
		for (int i = 1; i <= N; i++)
		{
			if (b[i] != a[i + slide])
			{
				if (mp[a[i + slide]] == 0)
				{
					slide += i;
				}
				else
				{
					ll lb = -1, ub = press[mp[a[i + slide]]].size();

					while (lb + 1 < ub)
					{
						ll mid = (lb + ub) / 2;
						if (press[mp[a[i + slide]]][mid] < i)
						{
							lb = mid;
						}
						else
						{
							ub = mid;
						}
					}

					if (lb = -1)
					{
						slide += i;
					}
					else
					{
						slide += N - press[mp[a[i + slide]]][lb];
					}
				}
				same = false;
				break;
			}
		}

		if (same)
		{
			match = true;
			break;
		}
	}

	if (match)
	{
		cout << slide << ' ' << (A[slide + 1] ^ B[1]) << endl;

		vector<ll> yaku;
		yaku.push_back(1);
		for (int i = 2; i <= sqrt(N); i++)
		{
			if (N % i != 0) continue;
			if (i == sqrt(N))
			{
				yaku.push_back(i);
			}
			else
			{
				yaku.push_back(i);
				yaku.push_back(N / i);
			}
		}
		ll range = N;
		for (int i = 0; i < yaku.size(); i++)
		{
			bool judge = true;
			for (int j = yaku[i] + 1; j < N; j++)
			{
				if (a[j] != a[j % yaku[i]])
				{
					judge = false;
					break;
				}
			}
			if (judge)
			{
				range = yaku[i];
				break;
			}
		}
		slide += range;
		while (slide < N)
		{
			cout << slide << ' ' << (A[slide + 1] ^ B[1]) << endl;
			slide += range;
		}
	}
}

