void solve(){
	int n;
	cin>>n;
	vi a(n),b(n);
	cin>>a>>b;
	int moves=(3e7)/n;
	moves=min(moves,3*n);
	vector<pair<int,int>>ans(n);
	int sz=0;
	for(int i=0;i<n;i++){
		int val=a[i]^b[0];
		int cnt=moves,flag=0;
		while(cnt--){
			int z=(rng())%n;
			if((a[(z+i)%n]^val)!=b[z]){
				flag++;
				break;
			}
		}
		if(!flag){
			ans[sz++]={i,val};
		}
	}
	int i=0;
	for(;i<sz;i++){
		int cnt=moves+100,flag=0;
		int val=ans[i].S,j=ans[i].F;
		while(cnt--){
			int z=(rng())%n;
			if((a[(z+j)%n]^val)!=b[z]){
				flag++;
				break;
			}
		}
		if(!flag){
			cout<<ans[i].F<<" "<<ans[i].S<<"\n";
		}
	}
}

