VI calc_hash(const VI& a){
    VI h(30);
    for(int b = 0; b < 30; ++b){
        for(int i = 0; i < a.size(); ++i){
            h[b] = (h[b] + ((a[i] >> b) & 1) * D[i]) % M7;
