ll mpow(ll base, ll exp, ll mod) {
  ll res = 1;
  while (exp) {
  if (exp % 2 == 1){
    res = (res * base) % mod;
  }
  exp >>= 1;
  base = (base * base) % mod;
  }
  return res;
}
