template <class T, class seq_t = std::vector<T>>
class Z_algorithm
{
    seq_t key;
    const size_t len;
    std::vector<size_t> z;
    bool is_built;
  public:
    Z_algorithm(const seq_t &_key) : key(_key), len(_key.size()), is_built(false) {}

    void build()
    {
        assert(len);
        is_built = true;
        z.assign(len, 0);
        for(size_t i{1}, j{0}; i != len; ++i)
        {
            if(z[i - j] + i < z[j] + j)
            {
                z[i] = z[i - j];
            }
            else
            {
                size_t k{z[j] + j > i ? z[j] + j - i : 0};
                while(k + i < len && key[k] == key[k + i]) ++k;
                z[i] = k;
                j = i;
            }
        }
        z.front() = len;
    }

    size_t size() const { return z.size(); }
    size_t operator[](size_t i) const { return build(), z[i]; }

    std::vector<size_t> pattern_search(const seq_t &str) const
    {
        seq_t tmp(key);
        tmp.insert(end(tmp), begin(str), end(str));
        Z_algorithm other(tmp);
        other.build();
        std::vector<size_t> res(other.z.begin() + len, other.z.end());
        for(size_t &x : res) if(x > len) x = len;
        return res;
    }
};

