        hashb += bx[i]*sp[i-1];
        hashb %= mod;
    }
    //
    forn(i,n){
        hasha += ax[i]*sp[i-1];
        hasha %= mod;
    }
    //
    //cout << "HASHB "   << hashb << '\n';
    if(hasha == hashb){
        cout << 0 <<' '<< ll(a[1]^b[1]) << '\n';
    }
    //
    //cout << "HASHES:\n";
    //cout << 1 << ' ' << hasha << '\n';
    forn(i,n-1){
        hasha -= ax[i];
        hasha = (hasha + mod)%mod;
        hasha *= im;
        hasha %= mod;
        hasha += sp[n-1]*ax[i];
        hasha %= mod;
        //cout << i+1 << ' ' << hasha << '\n';
        if(hasha == hashb){
            cout << i << ' ' << ll(a[i+1]^b[1]) << '\n';
        }
    }
    // 10^9 10^5 * 10^9
    // choose k
    // a[i+k] xor b[i] - same for all i
    // a[i+k] xor a[i+k+1] = b[i] xor b[i+1]
    // a[i] xor a[i+1] - cyclic shift of b[i] xor b[i+1]
}

