auto pre_kmp(const std::string &s) {
    std::vector<int> a(s.size() + 1);
    a[0] = -1;
    for (int i = 0, j = -1; i < s.size(); i++) {
        while (j >= 0 && s[i] != s[j]) j = a[j];
        j++;
        a[i + 1] = s[i + 1] == s[j] ? a[j] : j;
    }
    return a;
}

auto find(const std::string &s, const std::string &pat, const std::vector<int> &a, int ss = 0, int ts = 0) {
    for (int i = ss, j = ts; i < s.size(); i++) {
        while (j >= 0 && s[i] != pat[j]) j = a[j];
        if (++j == pat.size()) return i - pat.size() + 1;
    }
    return s.size();
}

auto find_all(const std::string &s, const std::string &pat, const std::vector<int> &a, int ss = 0, int ts = 0) {
    std::vector<int> ret;
    for (int i = ss, j = ts; i < s.size(); i++) {
        while (j >= 0 && s[i] != pat[j]) j = a[j];
        if (++j == pat.size()) {
            ret.push_back(i - pat.size() + 1);
            j = a[j];
        }
    }

    return ret;
}

