// Morris-Pratt
// S から T を探し、その出現位置を T が始まる位置として 0-indexed で全列挙する O(|S|)
// 文字列ならば T は string, 整数列ならば T は vector<int> 等にする
template<typename T> 
struct MP {
    int n;
    T t;
    vector<int> a; // t[:i] (1-indexed) の suffix と prefix の共通部分の長さ（重複する位置があってはならない）
    MP() {};
    MP(T const & t) : t(t) {
        n = t.size();
        a = vector<int>(n+1);
        a[0] = -1;
        int j = -1;
        for(int i=0; i<n; ++i) {
            while(j != -1 && t[j] != t[i]) j = a[j];
            j++;
            a[i+1] = j;
        }
    }
    int operator[] (int i) { return a[i]; }
    vector<int> findAll(T const& s) {
        vector<int> res;
        int j = 0;
        for(int i=0; i<s.size(); ++i) {
            while(j != -1 && t[j] != s[i]) j = a[j];
            j++;
            if (j == n) {
                res.push_back(i-j+1);
                j = a[j];
            }
        }
        return res;
    }
};

int main(){
    cin.tie(nullptr);
    ios::sync_with_stdio(false);

    int N; cin >> N;
    vector<int> a(N), b(N), c(N), d(N);
    rep(i, N) cin >> a[i];
    rep(i, N) cin >> b[i];
    rep(i, N) {
        c[i] = a[i] ^ a[(i+1)%N];
        d[i] = b[i] ^ b[(i+1)%N];
    }
    c.insert(c.end(), c.begin(), c.end());
    MP<vector<int>> mp(d);
    auto res = mp.findAll(c);
    for(auto k: res) {
        if (k>=N) continue;
        cout << k << " " << (a[k]^b[0]) << endl;
    }

    return 0;
}

