using ull = unsigned long long;

const ull MASK30 = (1ull << 30) - 1;
const ull MASK31 = (1ull << 31) - 1;
const ull MOD = (1ull << 61) - 1;
const ull POSITIVIZER = MOD * 3;

ull mul(ull a, ull b) {
    ull au = a >> 31;
    ull ad = a & MASK31;
    ull bu = b >> 31;
    ull bd = b & MASK31;
    ull mid = ad * bu + au * bd;
    ull midu = mid >> 30;
    ull midd = mid & MASK30;
    return au * bu * 2 + midu + (midd << 31) + ad * bd;
}

ull calc_mod(ull val) {
    val = (val & MOD) + (val >> 61);
    if (val > MOD) val -= MOD;
    return val;
}

ull power(ull base, int N) {
  ull res = 1;
  for (int i = 0; i < N; i++) res = calc_mod(mul(res, base));
  return res;
}

ull calc_hash(const vector<int>& a, ull base) {
  ull hash = 0;
  for (int x : a) {
    hash = calc_mod(mul(hash, base) + x);
  }
  return hash;
}

