    random_device seed_gen;
    default_random_engine engine(seed_gen());
    uniform_int_distribution<ull> dist(1ull << 30, 1ull << 59);
    ull base = dist(engine);
    ull pw = power(base, N);
    ull hash = calc_hash(a2, base), target = calc_hash(b2, base);
    for (int k = 0; k < N; k++) {
      if (hash == target) {
        cout << k << " " << (a[k] ^ b[0]) << endl;
      }
      hash = calc_mod(mul(hash, base));
      hash = calc_mod(hash + POSITIVIZER - mul(pw, a2[k]));
      hash = calc_mod(hash + a2[k]);
    }
  }
