template<class T>
struct MP {
  int n;
  vi a;
  T t;
  MP(){}
  MP(const T &t) : t(t){
    n = sz(t);
    a = vi(n+1);
    a[0] = -1;
    int j = -1;
    rep(i,0,n-1){
      while(j != -1 && t[j] != t[i])j = a[j];
      j++;
      a[i+1] = j;
    }
  }
  int operator[] (int i){
    return a[i];
  }
  vi findAll(const T& s){
    vi res;
    int j = 0;
    rep(i,0,sz(s)){
      if(j != -1 && s[i] != t[j])j = a[j];
      j++;
      if(j == n){
        res.pb(i-j+1);
        j = a[j];
      }
    }
    return res;
  }
};

