int main() {
  int N; std::cin >> N;
  for(int i = 0; i < N; ++i) std::cin >> a[i];
  for(int i = 0; i < N; ++i) std::cin >> b[i];
  for(int i = 0; i < N-1; ++i) c[i] = a[i]^a[i+1];
  for(int i = 0; i < 2*N-2; ++i) d[i] = b[i%N]^b[(i+1)%N];
  std::set<int> ans;
  // KMP
  int i = 1, j = 0;
  next_pos[1] = 0;
  while(i < N-1) {
    if(c[i] == c[j]) next_pos[++i] = ++j;
    else if(j == 0) next_pos[++i] = j;
    else j = next_pos[j];
  }
