    if(d[i] == c[j]) { ++i; ++j; }
    else if(j == 0) ++i;
    else j = next_pos[j];
    if(j == N-1) {
      ans.insert((N+N-1-i)%N);
      --i; --j;
      j = next_pos[j];
    }
