constexpr int P_MAX = 500000;

vector<int> table(P_MAX, 0); // ずらしテーブル

void make_table(vector<int> p, int m) {
    int j = 0;
    for(int i=1;i<m;++i) {
        table[i] = j;
        if(p[i] == p[j]) {
            ++j;
        } else {
            j = 0;
        }
    }
}

int kmp(vector<int> s, vector<int> p, int n, int m, int start=0) {
    int i = start, j = 0;
    while(i < n && j < m) {
        if(s[i] == p[j]) {
            ++i;
            ++j;
        } else if(j == 0) {
            ++i;
        } else {
            j = table[j];
        }
    }
    if(j == m) return i - m;
    return -1;
}
