  rep(i,0,n-1){
    res[i] = x[i]^x[(i+1)%n];
  }
  return res;
}

template<class T>
struct MP {
  int n;
  vi a;
  T t;
  MP(){}
  MP(const T &t) : t(t){
    n = sz(t);
    a = vi(n+1);
    a[0] = -1;
    int j = -1;
    rep(i,0,n-1){
      while(j != -1 && t[j] != t[i])j = a[j];
      j++;
      a[i+1] = j;
    }
  }
  int operator[] (int i){
    return a[i];
  }
  vi findAll(const T& s){
    vi res;
    int j = 0;
    rep(i,0,sz(s)-1){
      if(j != -1 && s[i] != t[j])j = a[j];
      j++;
      if(j == n){
        res.pb(i-j+1);
        j = a[j];
      }
    }
    return res;
  }
};

int main () {
  cin.tie(0);
  ios::sync_with_stdio(false);

  IN(n);
  vi a(n), b(n);
  rep0(i,n)IN(a[i]);
  rep0(i,n)IN(b[i]);
  vi xa = f(a), xb = f(b);
  xb.insert(xb.end(), xb.begin(), xb.end());
  MP<vi> mp(xa);
  vi res = mp.findAll(xb);
  vi ans;
  for(auto c : res){
    ans.pb(n-c);
  }
  sort(All(ans));
  for(auto c : ans){
    if(c >= n)continue;
    int x = a[c]^b[0];
    OUT(c, x);
  }
  return 0;
}

