template<class T, class U,class W> void replace(vector<W> &a, T key, U v) { rep(i,sz(a))if(a[i]==key)a[i]=v; }
template<class T, class U,class W> void replace(vector<vector<W>> &A, T key, U v) { rep(i,sz(A))replace(A[i], key, v); }
