template<typename T>
vector<size_t> kmp(vector<T> const &p, vector<T>const &t){
    vector<size_t> result;
    const int n = t.size();   // n: t
    const int m = p.size();   // m: p

    vector<T> h(m + 1);
    // make h
    int i_ = 0;
    int j_ = 1;
    while (j_ <=  m) {
        // make h with dammy at bottom of p
        while (i_ > 0 && (p[i_ - 1] != p[j_ - 1] || j_ == m + 1)) {
            i_ = h[i_ - 1];
        }
        ++i_, ++j_;
        h[j_ - 1] = (p[i_ - 1] == p[j_ - 1]) ?  h[i_ - 1] : i_;
    }

    // main
    int i = 1, j = 1;           // i -> p, j -> t
    while (j <= n) {
        while (i > 0 && p[i - 1] != t[j - 1]) {
            i = h[i - 1];
        }
        ++i, ++j;
        if (i >=  m + 1) result.push_back(j - m);
    }
    return result;
}

