int modminus(int a, int b, int N) {
  int ret = (a - b) % N;
  return (ret >= 0) ? ret : ret + N;
}

template<typename T>
std::vector<int> MP(const std::vector<T> &S) {
  int N = (int) S.size();
  std::vector<int> ret(N + 1);

  ret[0] = -1;

  int pos = -1;
  for(int i = 0; i < N; ++i) {
    while(pos >= 0 && S[i] != S[pos]) pos = ret[pos];
    ret[i + 1] = ++pos;
  }
  return ret;
}

template<typename T>
std::vector<int> KMP(const std::vector<T> &S, const std::vector<T> &P) {
  int N = (int) S.size();
  int M = (int) P.size();
  std::vector<int> table = MP(P);

  std::vector<int> ret;
  int head = 0;
  int pos = 0;
  while(head + pos < N) {
    if(S[head + pos] == P[pos]) {
      ++pos;
      if(pos == M) {
        ret.push_back(head);
        head += pos - table[pos];
        pos = (pos > 0) ? table[pos] : pos;
      }
    } else {
      head += pos - table[pos];
      pos = (pos > 0) ? table[pos] : pos;
    }
  }

  return ret;
}

int main() {
  int N;
  std::cin >> N;
  std::vector<int> a(N), b(N);
  rep(i, N) {
    std::cin >> a[i];
  }
  rep(i, N) {
    std::cin >> b[i];
  }

  std::vector<int> c(N), d(2 * N - 1);
  rep(i, N) {
    c[i] = a[i] ^ a[(i + 1) % N];
  }
  rep(i, 2 * N - 1) {
    d[i] = b[i % N] ^ b[(i + 1) % N];
  }

  std::vector<int> ks = KMP(d, c);

  for(int &k: ks) {
    k = modminus(0, k, N);
  }
  std::sort(ks.begin(), ks.end());

  for(int k : ks) {
    std::cout << k << ' ' << (a[k] ^ b[0]) << '\n';
  }

}

