void calc_prefix_array(vector<int> t) {
    int n = t.size();
    pref[0] = 0;
    int border = 0;
    for (int i=1; i<n; i++) {
        while (border > 0 && t[i] != t[border]) {
            border = pref[border - 1];
        }
        if (t[i] == t[border]) {
            border++;
        }
        else {
            border = 0;
        }
        pref[i] = border;
    }
}

void kmp(vector<int> pattern, vector<int> text) {
    vector<int> s;
    for (int i : pattern) s.pb(i);
    s.pb(-1000);
    for (int i : text) s.pb(i);
    calc_prefix_array(s);
    int k = pattern.size();
    for (int i=k+1; i<s.size(); i++) {
        if (pref[i] == k) pos.pb(i - 2 * k);
    }
}

