// Morris-Pratt
template<typename T> struct MP {
  T t; vector<int> a;
  int operator[](int i) { return a[i];}
  MP(const T& t): t(t) {
    a = vector<int>(t.size()+1);
    a[0] = -1;

    int j = -1;
    for (int i = 0; i < t.size(); ++i) {
      while (j != -1 && t[j] != t[i]) j = a[j];
      a[i+1] = ++j;
    }
  }
  vector<int> findAll(const T& s) {
    vector<int> res;
    int j = 0;
    for (int i = 0; i < s.size(); ++i) {
      while (j != -1 && t[j] != s[i]) j = a[j];
      if (++j == t.size()) {
        res.push_back(i-t.size()+1);
        j = a[j];
      }
    }
    return res;
  }
};

