typedef ModInt<1000000007> mint1;
typedef ModInt<1000000009> mint2;
int primes[10] = {10007, 10009, 10037, 10039, 10061, 10067, 10069, 10079, 10091, 10093};
bool isShuffle = true;
struct RollingHash {
    mint1 p1;
    mint2 p2;
    int n;
    vector<mint1> m1;
    vector<mint2> m2;
    vector<mint1> v1;
    vector<mint2> v2;

    RollingHash() {
        if (!isShuffle) {
            rep(i, 0, 101) {
                int a = getrand(0, 9);
                int b = getrand(0, 9);
                swap(primes[a], primes[b]);
            }
            isShuffle = true;
        }
        p1 = primes[0], p2 = primes[1];
    }

    void init(string s, char o = 'a') {
        vector<int> v;
        fore(c, s) v.push_back(c - o);
        init(v);
    }

    void init(vector<int> s) {
        n = s.size();
        m1.resize(n);
        m2.resize(n);
        v1.resize(n);
        v2.resize(n);

        m1[0] = 1;
        m2[0] = 1;
        v1[0] = s[0];
        v2[0] = s[0];

        rep(i, 1, n) {
            m1[i] = m1[i - 1] * p1;
            m2[i] = m2[i - 1] * p2;
            v1[i] = v1[i - 1] + m1[i] * s[i];
            v2[i] = v2[i - 1] + m2[i] * s[i];
        }
    }
    inline pair<mint1, mint2> hash(int l, int r) { // s[l..r]
        assert(l <= r);
        assert(r < n);
        mint1 a = v1[r];
        if (l) a -= v1[l - 1];
        a *= m1[n - 1 - r];

        mint2 b = v2[r];
        if (l) b -= v2[l - 1];
        b *= m2[n - 1 - r];

        return {a, b};
    }
    inline ll llhash(int l, int r) { // s[l..r]
        auto h = hash(l, r);
        return 1LL * h.first.get() * h.second.Mod + h.second.get();
    }
};

