// zarray
template<typename S>
void zarray(S s, std::vector<int>& Z) {
  int N = s.size(), L, R = 0;
  Z.resize(N);
  for(int i = 1; i < N; ++i) {
    if(i > R) {
      L = R = i;
      while(R < N && s[R-L]==s[R]) ++R;
      Z[i] = R-- -L;
    } else if(Z[i-L] < R-i+1) {
      Z[i] = Z[i-L];
    } else {
      L = i;
      while(R < N && s[R-L] == s[R]) ++R;
      Z[i] = R-- -L;
    }
  }
}

