template <typename Container>
void create_backtrace_table(
    const Container &w,
    std::vector<int> &t)
{
  t.clear();
  t.resize(w.size() + 1);

  t[0] = -1;
  t[1] = 0;

  size_t i = 2, j = 0;
  while(i < t.size()) {
    if(w[i-1] == w[j]) {
      t[i] = j + 1;
      i++; j++;
    } else if(j > 0) {
      j = t[j];
    } else {  // j==0
      t[i] = 0;
      i++;
    }
  }
}

template <typename Container>
void find_by_kmp(
    const Container &s,
    const Container &w,
    const std::vector<int> & t,
    std::vector<int> &pos)
{
  pos.clear();
  size_t m = 0; // index of s
  int i = 0; // index of w

  if(s.size() < w.size()) {
    return;
  }

  // std::cout << "start m = " << m << std::endl;
  while(m <= s.size()) {
    // std::cout << "m = " << m
    //           << " i = " << i
    //           << std::endl;
    // matching
    if(i < (int)w.size() && s[m + i] == w[i]) {
      i++;
      continue;
    }

    // matching complete or mismatch
    if(i == (int)w.size()) {
      pos.push_back(m);
    }

    m += i - t[i];
    if(i > 0) i = t[i];
  }
}

