const int MAX = 1000005;

long long fac[MAX], finv[MAX], inv[MAX];
void COMinit(){
    fac[0] = fac[1] = 1;
    finv[0] = finv[1] = 1;
    inv[1] = 1;
    for(int i = 2; i < MAX; i++){
        fac[i] = fac[i-1] * i % mod;
        inv[i] = mod - inv[mod%i] * (mod/i) % mod;
        finv[i] = finv[i-1] * inv[i] % mod;
    }
}
long long COM(int n, int k){
    if(n < k) return 0;
    if (n < 0 || k < 0) return 0;
    return fac[n] * (finv[k] * finv[n-k] % mod) % mod;
}


// lcp[i] := S と S[i:S.size()] の最長共通接頭辞の長さを記録した LCP 配列を O(|S|) で計算する
vector<int> Zalgo(const vector<int> & S){
    int N=(int)S.size();
    vector<int> res(N);
    res[0]=N;
    int i=1, j=0;
    while(i<N){
        while(i+j<N && S[j]==S[j+i]) ++j;
        res[i]=j;
        if(j==0) {++i; continue;}
        int k=1;
        while(i+k<N && k+res[k]<j) res[i+k]=res[k], ++k;
        i += k, j -= k;
    }
    return res;
}

