        int k = (i + 1) % n;
        da[i] = a[j] ^ a[k];
        db[i] = b[j] ^ b[k];
    }

    RollingHash A(da), B(db);
    for (int k = 0; k < n; ++k) {
        int len = A.getLCP(B, k, 0);
        if (len >= n) {
            cout << k << " " << (a[k] ^ b[0]) << endl;
        }
    }
}

