template<class T>
struct KMP
{
public:
  /**
   * @param N strのサイズ
   * @param K wordのサイズ
   */
  KMP(int N, int K);

  /** 検索対象の文字列 */
  vector<T> str;

  /** 検索元の文字列 */
  vector<T> word;

  /** 内部処理で使用する検索テーブル */
  vector<size_t> memo;

  /**
   * 前計算処理を行う. 
   * 本APIを呼ぶ前にstr, wordに入力する必要がある.
   */
  void preCalc();

  /**
   * prePos番目以降で、wordと一致するstrの部分文字列が開始されるindexを返す.
   * 本APIを呼ぶ前にKMP::preCalcを実行する必要がある.
   * 
   * @param prePos 探索を始めるindex
   * @return pos 見つからなかった場合は-1
   */
  ssize_t find(ssize_t prePos);

  vector<int> findAll();
};

template<class T>
KMP<T>::KMP(int N, int K)
  : str(N)
  , word(K)
  , memo(K+1)
{}

template<class T>
void KMP<T>::preCalc()
{
  size_t i = 0;
  size_t j = 1;
  memo[0] = -1;
  while (j < word.size()) {
    auto isMatch = word[i] == word[j];
    if (!isMatch && i > 0) {
      i = memo[i];
    }
    else {
      if (isMatch) {
        ++i;
      }
      ++j;
      memo[j] = i;
    }
  }
  return;
}

template<class T>
ssize_t KMP<T>::find(ssize_t prePos)
{
  int i = prePos;
  int j = 0;
  while (i < (int)str.size() && j < (int)word.size()) {
    if (str[i] == word[j]) {
      ++i;
      ++j;
    }
    else if (j == 0) {
      ++i;
    }
    else {
      j = memo[j];
    }
  }
  return (j == (int)word.size()) ? (i - j) : -1;
}

template<class T>
vector<int> KMP<T>::findAll()
{
  vector<int> res{};

  int i = 0;
  int j = 0;
  while (i < (int)str.size() && j < (int)word.size()) {
    if (str[i] == word[j]) {
      ++i;
      ++j;
    }
    else if (j == 0) {
      ++i;
    }
    else {
      j = memo[j];
    }
    if (j == (int)word.size()) {
      res.push_back(i-j);
      j = memo[j];
    }
  }
  return std::move(res);
}

