int N;
vector<int> a, b;
vector<int> nxt, vt, vp;


vector<int> kmp()
{
    int i, q, k;
    vector<int> res;

    nxt[0] = 0;
    for (q = 1, k = 0; q < N; ++q) {
        while (k > 0 && vp[q] != vp[k])
            k = nxt[k - 1];
        if (vp[q] == vp[k])
            k++;
        nxt[q] = k;
    }

    for (i = 0, q = 0; i < 2*N-1; ++i) {
        while (q > 0 && vp[q] != vt[i])
            q = nxt[q - 1];
        if (vp[q] == vt[i])
            q++;
        if (q == N) {
            res.push_back(i - N + 1);
            q = nxt[q - 1];
        }
    }
    return res;
}


void solve()
{
    vector<int> pos;
    vector<int> m1(N), m2(N);

    nxt.resize(N);
    vt.resize(2*N-1);
    vp.resize(N);
    reverse(a.begin(), a.end());
    reverse(b.begin(), b.end());

    for (int e = 0; e < 30; e++) {
        fill(m2.begin(), m2.end(), -1);
        for (int i = 0; i < 2*N; i++) {
            if (i < N) {
                vt[i] = b[i] & 1;
                b[i] >>= 1;
            } else {
                vt[i] = vt[i - N];
            }
        }
        for (int i = 0; i < N; i++) {
            vp[i] = a[i] & 1;
            a[i] >>= 1;
        }
        pos = kmp();
        for (int k : pos) {
            if (m1[k] >= 0)
                m2[k] = m1[k];
        }
        for (int i = 0; i < N; i++)
            vp[i] = 1 - vp[i];
        pos = kmp();
        for (int k : pos) {
            if (m1[k] >= 0)
                m2[k] = m1[k] + (1 << e);
        }
        swap(m1, m2);
    }

    for (int i = 0; i < N; i++) {
        if (m1[i] >= 0)
            cout << i << " " << m1[i] << endl;
    }
}


