template<class T>
vector<int> ZAlgorithm(const T& s) {
	int n = s.size(), i = 1, j = 0;
	vector<int> ret(n); ret[0] = n;
	while (i < n) {
		while (i + j < n && s[j] == s[i + j])j++;
		ret[i] = j;
		if (j == 0) { i++; continue; }
		int k = 1;
		while (i + k < n && k + ret[k] < j) { ret[i + k] = ret[k]; k++; }
		i += k; j -= k;
	}
	return ret;
}

