// ローリングハッシュ
class RollingHash {
    using int_type = unsigned long long;
    using hash_type = tuple<int_type, int_type, int_type>;
    const vector<int_type> base = {9929, 10007, 10009};
    const vector<int_type> mod = {999999929, 1000000007, 1000000009};
    vector<int_type> power[3], hash[3];

public:
    RollingHash(const string& s) {
        const int n = s.size();
        for (int i = 0; i < (int)mod.size(); ++i) {
            power[i].assign(n + 1, 1);
            hash[i].assign(n + 1, 0);
        }
        for (int i = 0; i < (int)mod.size(); ++i) {
            for (int j = 0; j < n; ++j) {
                power[i][j + 1] = power[i][j] * base[i] % mod[i];
                hash[i][j + 1] = hash[i][j] * base[i] % mod[i] + s[j];
                if (hash[i][j + 1] >= mod[i]) hash[i][j + 1] -= mod[i];
            }
        }
    }

    // s[l:r) のハッシュ
    inline hash_type get(int l, int r) const {
        vector<int_type> t(3);
        for (int i = 0; i < 3; ++i) {
            t[i] = (hash[i][r] + mod[i] - hash[i][l] * power[i][r - l] % mod[i]);
            if (t[i] >= mod[i]) t[i] -= mod[i];
        }
        return make_tuple(t[0], t[1], t[2]);
    }

    // LCP(s[l:], s[r:])
    inline int get_lcp(int l, int r) const {
        int lo = -1, hi = min(hash[0].size() - l, hash[0].size() - r);
        while (hi - lo > 1) {
            int mi = (lo + hi) >> 1;
            if (get(l, l + mi) == get(r, r + mi)) lo = mi;
            else hi = mi;
        }
        return lo;
    }

    // LCP(s[l1:r1], t[l2:r2])
    inline int get_lcp(RollingHash rh, int l1, int r1, int l2, int r2) const {
        int lo = -1, hi = min(r1 - l1 + 1, r2 - l2 + 1) + 1;
        while (hi - lo > 1) {
            int mi = (lo + hi) >> 1;
            if (get(l1, l1 + mi) == rh.get(l2, l2 + mi)) lo = mi;
            else hi = mi;
        }
        return lo;
    }
};

