int N;

bool same(int x, vector<int> XA, vector<int> XB)
{
    for (int i = 0; i < N; i++)
        if (XA[(i + x) % N] != XB[i % N])
            return false;
    return true;
}

int main()
{
    cin >> N;
    vector<int> A(N), B(N), XA(N), XB(N);
    vector<int> ans;
    for (int i = 0; i < N; i++)
        cin >> A[i];
    for (int i = 0; i < N; i++)
        cin >> B[i];
    for (int i = 0; i < N; i++)
        XA[i] = A[i % N] ^ A[(i + 1) % N], XB[i] = B[i % N] ^ B[(i + 1) % N];
    for (int i = 0; i < N; i++)
        if (same(i, XA, XB))
            ans.push_back(i);
    for (auto e : ans)
        cout << e << " " << (A[e] ^ B[0]) << endl;
}

