const int N = 210000;

int n, a[N], b[N], s[N << 1], t[N], nxt[N], abl[N], ans[N];

template <class T>
inline void read(T &x) {
    x = 0;
    char ch = getchar(), w = 0;
    while (!isdigit(ch)) w = ch == '-', ch = getchar();
    while (isdigit(ch)) x = (x << 1) + (x << 3) + (ch ^ 48), ch = getchar();
    x = w ? -x : x;
    return;
}

int main() {
    read(n);
    for (R int i = 1; i <= n; ++i) read(a[i]);
    for (R int i = 1; i <= n; ++i) read(b[i]);
    for (R int i = 29; ~i; --i) {
        for (R int j = 1; j <= n; ++j)
            s[j] = s[j + n] = a[j] & (1 << i), t[j] = b[j] & (1 << i);
        for (R int j = 1, k = 0; j < n; ++j) {
            while (k && t[j + 1] != t[k + 1]) k = nxt[k];
            if (t[j + 1] == t[k + 1]) ++k;
            nxt[j + 1] = k;
        }
        for (R int j = 0; j < n; ++j) abl[j] = -1;
        for (R int j = 0, k = 0; j < (n << 1) - 1; ++j) {
            while (k && s[j + 1] != t[k + 1]) k = nxt[k];
            if (s[j + 1] == t[k + 1]) ++k;
            if (k == n && j >= n - 1) abl[j + 1 - n] = 0, k = nxt[k];
        }
        for (R int j = 1; j <= n; ++j) s[j] = s[j + n] = ~a[j] & (1 << i);
        for (R int j = 0, k = 0; j < (n << 1) - 1; ++j) {
            while (k && s[j + 1] != t[k + 1]) k = nxt[k];
            if (s[j + 1] == t[k + 1]) ++k;
            if (k == n && j >= n - 1) abl[j + 1 - n] = 1, k = nxt[k];
        }
        for (R int j = 0; j < n; ++j) {
            if (abl[j] == -1 || ans[j] == -1) ans[j] = -1;
            else ans[j] ^= abl[j] << i;
        }
    }
    for (R int j = 0; j < n; ++j)
        if (ans[j] != -1) printf("%d %d\n", j, ans[j]);
    return 0;
}

