const int N=1000002;

void solve(){
	int n;
	cin>>n;
	vi a(n),b(n);
	cin>>a>>b;
	int moves=(1e7)/n;
	moves=min(moves,3*n);
	vector<pair<int,int>>ans(n);
	int sz=0;
	for(int i=0;i<n;i++){
		int val=a[i]^b[0];
		int cnt=moves,flag=0;
		while(cnt--){
			int z=(rng())%n;
			if((a[(z+i)%n]^val)!=b[z]){
				flag++;
				break;
			}
		}
		if(!flag){
			ans[sz++]={i,val};
		}
	}
	int i=0;
	for(;i<min(sz,350);i++){
		int l=ans[i].F,r=ans[i].S;
		int flag=0;
		for(int j=0;j<n;j++){
			if((a[(j+l)%n]^r)!=b[j]){
				flag++;
				break;
			}
		}
		if(!flag){
			cout<<ans[i].F<<' '<<ans[i].S<<"\n";
		}
	}
	for(;i<sz;i++){
		cout<<ans[i].F<<" "<<ans[i].S<<"\n";
	}
}

