  for (ll i = 0; i < N; i++) cin >> A.at(i);
  for (ll i = 0; i < N; i++) cin >> B.at(i);
  for (ll i = 0; i < N; i++) {
    p.at(i) = A.at(i) ^ A.at((i+1) % N);
    q.at(i) = B.at(i) ^ B.at((i+1) % N);
  }
  stringstream ssp, ssq;
  for (ll k = 0; k < N; k++) {
    ssp << setfill('0') << setw(8);
    ssp << p.at(k);
    ssq << setfill('0') << setw(8);
    ssq << q.at(k);
  }
  string p1 = ssp.str(); p1 += p1;
  string q1 = ssq.str();
  DLOG("p", p);
  DLOG("q", q);
  DLOG("p1", p1);
  DLOG("q1", q1);
  for (ll y : matches(q1, p1)) {
    if (y % 8 != 0) continue;
    ll k = y / 8;
    if (k == N) continue;
    cout << k << " " << (B.at(0) ^ A.at(k)) << endl;
  }

  return 0;
}

