    for (int i = 0; i < n; i++) {
        aa[i] = a[i] ^ (a[(i + 1) % n]);
        bb[i] = b[i] ^ (b[(i + 1) % n]);
    }

    vector<int> s;
    for (int i = 0; i < n; i++) {
        s.push_back(bb[i]);
    }
    s.push_back(-1);
    for (int i = 0; i < n; i++) {
        s.push_back(aa[i]);
    }
    for (int i = 0; i < n - 1; i++) {
        s.push_back(aa[i]);
    }

    vector<int> p(s.size() + 1);
    p[0] = -1;
    for (int i = 1; i < p.size(); i++) {
        int k = p[i - 1];
        while (k >= 0 && s[i - 1] != s[k]) k = p[k];
        p[i] = k + 1;
        if (p[i] == n) {
            int k = i - n - n - 1;
            int x = b[0] ^ a[k];
            cout << k << " " << x << "\n";
        }
    }

    return 0;
}

