ll mulmod(ll a, ll b, ll m) {
	ll r = a*b-(ll)((long double)a*b/m+.5)*m;
	return r < 0 ? r+m : r;
}

ll expmod(ll b, ll e, ll m) {
    if (e == 0) return 1;
    if (e&1) return mulmod(b, expmod(b, e-1, m), m);
    b = expmod(b, e>>1, m);
    return mulmod(b, b, m);
}

