const LL N = 1234567891;
const LL N2 = 1000000009;

LL a[200005],b[200005],c[200005],d[200005];
LL pc[200005],pd[200005],pwr[200005],pc2[200005],pd2[200005],pwr2[200005];
LL n,m;

LL judge(LL l,LL r){
	return (pc[n - 1] == (pd[r] - (pd[l - 1] * pwr[r - l + 1] % N) + N) % N) && (pc2[n - 1] == (pd2[r] - (pd2[l - 1] * pwr2[r - l + 1] % N2) + N2) % N2);
}

int main(){
	ios::sync_with_stdio(false);
	pwr[0] = 1; for(LL i = 1;i <= 200000;i ++) pwr[i] = (pwr[i - 1] * P) % N;
	pwr2[0] = 1; for(LL i = 1;i <= 200000;i ++) pwr2[i] = (pwr2[i - 1] * P) % N2;
	cin >> n;
	for(LL i = 1;i <= n;i ++) cin >> a[i];
	for(LL i = 1;i <= n;i ++) cin >> b[i];
	for(LL i = n + 1;i <= (n << 1);i ++) b[i] = b[i - n];

	for(LL i = 1;i < n;i ++) c[i] = a[i] ^ a[i + 1];
	for(LL i = 1;i < (n << 1);i ++) d[i] = b[i] ^ b[i + 1];

	for(LL i = 1;i < n;i ++) pc[i] = (pc[i - 1] * P + c[i]) % N;
	for(LL i = 1;i < (n << 1);i ++) pd[i] = (pd[i - 1] * P + d[i]) % N;
	for(LL i = 1;i < n;i ++) pc2[i] = (pc2[i - 1] * P + c[i]) % N2;
	for(LL i = 1;i < (n << 1);i ++) pd2[i] = (pd2[i - 1] * P + d[i]) % N2;

	for(LL i = n + 1;i >= 2;i --){
		if(judge(i,i + n - 2))
			cout << (n + 1 - i) << ' ' << (a[1] ^ b[i]) << endl;
	}
	return 0;
}

