	rep(i, n) s.push_back(da[i]);
	rep(i, n) s.push_back(da[i]);

	auto z = z_algorithm(s);
	const int offset = n + 1;

	vector<int> k, x;

	rep(i, n) {
		if(z[i + offset] != n) continue;
		k.push_back(i);
		x.push_back(b[0] ^ a[i]);
	}

	const int t = k.size();
	rep(i, t) cout << k[i] << " " << x[i] << endl;

	return 0;
}

