long long mod = 2000000001;
long long power[1 << 18];

long long N, A[1 << 18], B[1 << 18];
long long C0[1 << 18], C1[1 << 18], C2[1 << 18];
long long D0[1 << 18], D1[1 << 18];
bool flag[1 << 18];
long long ans[1 << 18];

void init() {
	power[0] = 1;
	for (int i = 1; i <= 200000; i++) power[i] = (2LL * power[i - 1]) % mod;
}

int main() {
	scanf("%lld", &N); init();
	for (int i = 0; i < N; i++) scanf("%lld", &A[i]);
	for (int i = 0; i < N; i++) scanf("%lld", &B[i]);

	for (int i = 29; i >= 0; i--) {
		for (int j = 0; j < N; j++) C1[j] = (A[j] / (1LL << i)) % 2;
		for (int j = 0; j < N; j++) C2[j] = (B[j] / (1LL << i)) % 2;
		for (int j = 0; j < N; j++) C0[j] = (1LL ^ C1[j]);

		// 2 について求める
		long long val = 0;
		for (int j = 0; j < N; j++) { val = val * 2LL + C2[j]; val %= mod; }

		// 1 について求める
		D1[0] = 0; for (int j = 1; j <= N; j++) D1[j] = (2LL * D1[j - 1] + C1[j - 1]) % mod;
		D0[0] = 0; for (int j = 1; j <= N; j++) D0[j] = (2LL * D0[j - 1] + C0[j - 1]) % mod;

		// それぞれ判定する
		for (int j = 0; j < N; j++) {
			long long val1 = (D1[N] - D1[j] * power[N - j] + mod * mod) % mod;
			long long val2 = D1[j];
			long long val3 = (val1 * power[j] + val2) % mod;

			long long rem1 = (D0[N] - D0[j] * power[N - j] + mod * mod) % mod;
			long long rem2 = D0[j];
			long long rem3 = (rem1 * power[j] + rem2) % mod;

			if (val != val3 && val != rem3) flag[j] = true;
			if (val == rem3) ans[j] += (1LL << i);
		}
	}

	// 最後
	for (int i = 0; i < N; i++) {
		if (flag[i] == false) printf("%lld %lld\n", 1LL * i, ans[i]);
	}
	return 0;
}

