void sort(vector<pair<pair<int,int>,int> > &v)
{
	for (int i=0;i<n;i++)
	{
		t1[i].clear();
		t2[i].clear();
	}
	for (auto p:v)
	t1[p.first.second].push_back(p);
	for (int i=0;i<n;i++)
	{
		for (auto p:t1[i])
		t2[p.first.first].push_back(p);
	}
	v.clear();
	for (int i=0;i<n;i++)
	{
		for (auto p:t2[i])
		v.push_back(p);
	}
}
void go(int b,int val)
{
	for (int i=0;i<n;i++)
	rnk[i]=aa[i];
	vector<pair<pair<int,int>,int> > v;
	for (int k=0;k<20;k++)
	{
		v.clear();
		for (int i=0;i<n;i++)
		v.push_back({{rnk[i],rnk[(i+(1<<k))%n]},i});
		sort(v);
		int cr=0;
		for (int i=0;i<n;i++)
		{
			if (!i)
			rnk[v[i].second]=0;
			else if (v[i].first!=v[i-1].first)
			cr++;
			rnk[v[i].second]=cr;
		}
	}
	int st=0,en=n;
	while (st!=en)
	{
		int mid=(st+en)/2;
		bool eq=1;
		for (int i=0;i<n;i++)
		{
			if (aa[(v[mid].second+i)%n]!=bb[i])
			{
				if (aa[(v[mid].second+i)%n]<bb[i])
				st=mid+1;
				else
				en=mid;
				eq=0;
				break;
			}
		}
		if (eq)
		en=mid;
	}
	for (int i=0;i<n;i++)
	{
		if (aa[(v[st].second+i)%n]!=bb[i])
		return;
	}
	for (int i=0;i<n;i++)
	{
		if (rnk[i]==rnk[v[st].second])
		{
			cnt[i]++;
			x[i]|=(val<<b);
		}
	}
}
