struct rolling_hash {
    using ull = unsigned long long;
    static constexpr ull MASK30 = (1ULL << 30) - 1;
    static constexpr ull MASK31 = (1ULL << 31) - 1;
    static constexpr ull MOD = (1ULL << 61) - 1;
    static constexpr ull POSITIVIZER = MOD << 2;
    static std::vector<std::pair<ull, ull>> pow_base;
    int n;
    std::vector<std::pair<ull, ull>> hash;
    static ull rng() {
        std::random_device rd;
        return std::uniform_int_distribution<ull>(MOD >> 1, MOD - 1)(rd);
    }
    static ull mul(ull a, ull b) {
        ull au = a >> 31;
        ull ad = a & MASK31;
        ull bu = b >> 31;
        ull bd = b & MASK31;
        ull mid = ad * bu + au * bd;
        return (au * bu << 1) + (mid >> 30) + ((mid & MASK30) << 31) + ad * bd;
    }
    static ull calc_mod(ull val) {
        val = (val & MOD) + (val >> 61);
        if (val >= MOD) { val -= MOD; }
        return val;
    }
    static std::pair<ull, ull> connect(const std::pair<ull, ull> &lhs, const std::pair<ull, ull> &rhs, int rn) {
        return {calc_mod(mul(lhs.first, pow_base[rn].first) + rhs.first),
                calc_mod(mul(lhs.second, pow_base[rn].second) + rhs.second)};
    }
    template<typename I> rolling_hash(I begin, I end): n(end - begin) {
        hash.push_back({0, 0});
        for (auto itr = begin; itr != end; itr++) {
            hash.push_back({calc_mod((mul(hash.back().first, pow_base[1].first) + *itr)),
                            calc_mod((mul(hash.back().second, pow_base[1].second) + *itr))});
        }
        while (pow_base.size() <= n) {
            pow_base.push_back({calc_mod(mul(pow_base.back().first, pow_base[1].first)),
                                calc_mod(mul(pow_base.back().second, pow_base[1].second))});
        }
    }
    std::pair<ull, ull> get_hash(int l, int r) const {
        return {calc_mod(POSITIVIZER - mul(hash[l].first, pow_base[r - l].first) + hash[r].first),
                calc_mod(POSITIVIZER - mul(hash[l].second, pow_base[r - l].second) + hash[r].second)};
    }
};
std::vector<std::pair<rolling_hash::ull, rolling_hash::ull>> rolling_hash::pow_base{{1, 1}, {rng(), rng()}};

