using namespace std;
const int p=123456789,f=987654321;
const int r=1000000021;
int binpow(int a,int b) {
    if (b==0)
        return 1;
    if (b%2==1)
        return ((long long)a*binpow(a,b-1))%r;
    int x=binpow(a,b/2);
    return ((long long)x*x)%r;
}
main() {
    int n;
    cin>>n;
    int a[n+1],b[n+1],c[2*n],d[2*n];
    for (int i=0;i<n;i++)
        cin>>a[i];
    a[n]=a[0];
    for (int i=0;i<n;i++)
        c[i]=c[i+n]=(a[i]^a[i+1])+1;
    for (int i=0;i<n;i++)
        cin>>b[i];
    b[n]=b[0];
    for (int i=0;i<n;i++)
        d[i]=d[i+n]=(b[i]^b[i+1])+1;
    int pp[2*n],ff[2*n],x[2*n],y[2*n],xf[2*n],yf[2*n];
    pp[0]=1;
    for (int i=1;i<(2*n);i++)
        pp[i]=((long long)p*pp[i-1])%r;
    ff[0]=1;
    for (int i=1;i<(2*n);i++)
        ff[i]=((long long)f*ff[i-1])%r;
    x[0]=xf[0]=c[0];
    for (int i=1;i<(2*n);i++) {
        x[i]=(x[i-1]+(long long)c[i]*pp[i])%r;
        xf[i]=(xf[i-1]+(long long)c[i]*ff[i])%r;
    }
    y[0]=yf[0]=d[0];
    for (int i=1;i<(2*n);i++) {
        y[i]=(y[i-1]+(long long)d[i]*pp[i])%r;
        yf[i]=(yf[i-1]+(long long)d[i]*ff[i])%r;
    }
    for (int i=0;i<n;i++)
        if (((long long)((x[i+n-1]-x[i]+(long long)c[i]*pp[i])%r)*binpow(pp[i],r-2))%r==y[n-1] &&
            ((long long)((xf[i+n-1]-xf[i]+(long long)c[i]*ff[i])%r)*binpow(ff[i],r-2))%r==yf[n-1])
            cout<<i<<" "<<(a[i]^b[0])<<endl;
}

