std::vector<mint> twopow;

struct Bin {
    std::vector<mint> acc;

    explicit Bin(const std::vector<int>& xs) {
        int n = xs.size();
        acc.resize(n + 1);
        acc[n] = 0;
        for (int i = n - 1; i >= 0; --i) {
            acc[i] = acc[i + 1] * 2 + xs[i];
        }
    }

    mint seg(int l, int r) {
        return acc[l] - acc[r] * twopow[r - l];
    }
};

