/* Zalgorithm */

// A[i] := S と S[i:|S|-1] の最長共通接頭辞の長さ

void Zalgorithm(const char *S, int *A) {
  int i = 1, j = 0, k, n = strlen(S);
  A[0] = n;
  while (i < n) {
    while (i + j < n && S[j] == S[i + j]) j++;
    A[i] = j;
    if (j == 0) {
      i++;
      continue;
    }
    for (k = 1; i + k < n && k + A[k] < j; k++) A[i + k] = A[k];
    i += k;
