#include <bits/stdc++.h>
using namespace std;
using uint = unsigned int;

int main() {

	uint N;
	cin >> N;

	vector<uint> a(N);
	uint eqAall = true;
	for(uint i=0; i<N; i++) {
		cin >> a[i];
		eqAall = (i == 0) ? eqAall : eqAall & (a[i-1] == a[i]); 
	}

	vector<uint> b(N);
	uint eqBall = true;
	for(uint i=0; i<N; i++) {
		cin >> b[i];
		eqBall = (i == 0) ? eqBall : eqBall & (b[i-1] == b[i]);
	}

	if(eqBall != eqAall) { // one is all same factor, other is not
		return 0;
	} else if (eqAall & eqBall) { // both have all same factor
		uint x = a[0] ^ b[0];
		for(uint i=0; i<N; i++) cout << i << " " << x << endl;
		return 0;
	} 

	deque<pair<uint, uint>> pla;
	uint cnt = 1;
	uint prv = UINT_MAX; 

	for(uint k=0; k<2*N; k++) {
		if(a[k] != prv) {
			if(pla.empty() || pla.back().first <= cnt) {
				pla.push_back(make_pair(cnt, k + 1 - cnt));
			}

			cnt = 1;
			prv = a[k];

			if(k >= N) break;

		} else {
			cnt++;
		}
	}

	while(!pla.empty() && pla.front().first < pla.back().first) {
		pla.pop_front();
	}

	deque<pair<uint, uint>> plb;
	cnt = 1;
	prv = UINT_MAX; 

	for(uint k=0; k<2*N; k++) {
		if(b[k] != prv) {
			if(plb.empty() || plb.back().first <= cnt) {
				plb.push_back(make_pair(cnt, k + 1 - cnt));
			}

			cnt = 1;
			prv = b[k];

			if(k >= N) break;

		} else {
			cnt++;
		}
	}

	while(!plb.empty() && plb.front().first < plb.back().first) {
		plb.pop_front();
	}

	if(pla.back().first != plb.back().first || pla.size() != plb.size()) {
		return 0;
	}

	uint bk = plb.front().second;
	uint ln = plb.front().first;

	set<pair<uint, uint>> ans;

	while(!pla.empty()) {
		uint ak = pla.front().second;
		uint k = (ak < bk) ? bk - ak : N + bk - ak;
		pla.pop_front();

		uint x = a[k] ^ b[0];
		bool mtc = true;

		for(uint i=ln; i<N; i++) {
			if((b[i] ^ a[(k+i)%N]) != x) {
				mtc = false;
				break;
			}
		}

		if(mtc) {
			ans.insert(make_pair(k, x));
		}
	}

	for(auto s : ans) cout << s.first << " " << s.second << endl;

	return 0;
}

