template <class T> class KMP {
    void build() {
        int m = pat.size();
        kmp.assign(m, -1);
        for (int i = 1, j = -1; i < m; ++i) {
            while (j > -1 && pat[j + 1] != pat[i]) j = kmp[j];
            if (pat[j + 1] == pat[i]) ++j;
            kmp[i] = j;
        }
    }

public:
    T pat;
    vector<int> kmp;

    KMP(const T& pat) : pat(pat) { build(); }

    // pat[0:i]の周期 (i: 0-indexed)
    int period(int i) { return i - kmp[i]; }

    // t[i:]の接頭辞がpatとなるiを列挙 (i: 0-indexed)
    vector<int> match(const T& t) {
        int n = t.size(), m = pat.size();
        vector<int> res;
        for (int i = 0, j = -1; i < n; ++i) {
            while (j > -1 && pat[j + 1] != t[i]) j = kmp[j];
            if (pat[j + 1] == t[i]) ++j;
            if (j == m - 1) {
                res.push_back(i - m + 1);
                j = kmp[j];
            }
        }
        return res;
    }
};

