vector<ll> build_z(const vector<ll>& s) {
  ll n = s.size();
  vector<ll> z(n, 0);
  ll l = -1, r = -1;
  for (ll i = 1; i < n; ++i) {
    if (i <= r) {
      z[i] = min<ll>(r - i + 1, z[i - l]);
    }
    while (i + z[i] < n && s[i + z[i]] == s[z[i]]) {
      ++z[i];
    }
    if (i + z[i] - 1 > r) {
      r = i + z[i] - 1;
      l = i;
    }
  }
  return z;
}


vector<ll> f(const vector<ll>& x) {
  ll n = x.size();
  vector<ll> res(n);
  rep(i,n) {
    res[i] = x[i]^x[(i+1)%n];
  }
  return res;
}

