typedef pair<ll,ll> SIGNATURE;

template <typename T>
struct RollingHash {
    T base1, base2;
    ll mod1, mod2;
    vector<ll> hash1, hash2;
    vector<ll> pow1, pow2;

    RollingHash() : base1(500009), base2(500029), mod1(1000000007), mod2(1000000009) {}

    void init(const vector<T> &ar) {
        int n = ar.size();

        hash1.assign(n+1,0);
        hash2.assign(n+1,0);
        pow1.assign(n+1,1);
        pow2.assign(n+1,1);

        for (int i=0; i<n; i++) {
            hash1[i+1] = (hash1[i] + ar[i]) * base1 % mod1;
            hash2[i+1] = (hash2[i] + ar[i]) * base2 % mod2;
            pow1[i+1] = pow1[i] * base1 % mod1;
            pow2[i+1] = pow2[i] * base2 % mod2;
        }
    }

    SIGNATURE get(int l,int r) {
        ll t1 = ((hash1[r] - hash1[l] * pow1[r-l]) % mod1 + mod1) % mod1;
        ll t2 = ((hash2[r] - hash2[l] * pow2[r-l]) % mod2 + mod2) % mod2;
        return SIGNATURE(t1, t2);
    }

    SIGNATURE concat(SIGNATURE h1, SIGNATURE h2, int h2_len) {
        return SIGNATURE(
            (h1.first * pow1[h2_len] + h2.first) % mod1,
            (h1.second * pow2[h2_len] + h2.second) % mod2
        );
    }
};


inline vvi bitsep(int N, vi& a, int bits){
    vvi an(bits, vi(N));
    rep(i,N){
        int x = a[i];
        rep(j,bits){
            an[j][i] = x & 1;
            x >>= 1;
        }
    }
    return an;
}

void solve(int N, vi& a, vi& b) {
    vvi an = bitsep(N, a, 30);
    vvi bn = bitsep(N, b, 30);

    vi possible(N, 0);
    vi mask(N, 0);

    rep(bit,30){
        int m = 1 << bit;
        vi an2 = an[bit];
        an2.insert(an2.end(), ALL(an[bit]));

        RollingHash<int> rha, rhb, rhb_;
        rha.init(an2);

        vi bn1 = bn[bit];
        rhb.init(bn1);
        rep(i,N) bn1[i] = 1-bn1[i];
        rhb_.init(bn1);

        SIGNATURE b0 = rhb.get(0, N);
        SIGNATURE b1 = rhb_.get(0, N);
        rep(rot,N){
            SIGNATURE sg = rha.get(rot, rot+N);
            if (sg == b0) {
                possible[rot]++;
            }
            else if (sg == b1) {
                possible[rot]++;
                mask[rot] |= m;
            }
        }
    }

    rep(k,N){
        if (possible[k] == 30){
            printf("%d %d\n", k, mask[k]);
        }
    }
}

