  const int n = s.size();
  vector<int> z(n + 1);
  z[0] = n;
  int i = 1;
  int h = 0;
  while (i < n) {
    while (i + h < n && s[h] == s[i + h]) h++;
    z[i++] = h;
    if (h == 0) continue;
    h--;
    int k = 1;
    while (z[k] < h) {
      z[i++] = z[k++];
      h--;
    }
  }
  return z;
}

