template<typename T, T MOD1, T MOD2, T B1, T B2>
struct RollingHash {
	vector<T>hash[2], p[2];
	T MOD[2] = { MOD1,MOD2 };
	T B[2] = { B1,B2 };
	//RollingHash(const string &s) {
	//	int N = s.size();
	//	for (int k = 0; k < 2; k++) {
	//		hash[k].assign(N + 1, 0);
	//		p[k].assign(N + 1, 1);
	//		for (int i = 0; i < N; i++) {
	//			hash[k][i + 1] = (hash[k][i] * B[k] + s[i]) % MOD[k];
	//			p[k][i + 1] = p[k][i] * B[k] % MOD[k];
	//		}
	//	}
	//}
	void init(const string &s) {
		int N = s.size();
		for (int k = 0; k < 2; k++) {
			hash[k].assign(N + 1, 0);
			p[k].assign(N + 1, 1);
			for (int i = 0; i < N; i++) {
				hash[k][i + 1] = (hash[k][i] * B[k] + s[i]) % MOD[k];
				p[k][i + 1] = p[k][i] * B[k] % MOD[k];
			}
		}
	}

	//S[l,r)
	pair<T, T>find(int l, int r) {
		T res1 = hash[0][r] + MOD[0] - hash[0][l] * p[0][r - l] % MOD[0];
		res1 = (res1 >= MOD[0]) ? res1 - MOD[0] : res1;
		T res2 = hash[1][r] + MOD[1] - hash[1][l] * p[1][r - l] % MOD[1];
		res2 = (res2 >= MOD[1]) ? res2 - MOD[1] : res2;

		return make_pair(res1, res2);
	}
	T find1(int l, int r) {
		T res1 = hash[0][r] + MOD[0] - hash[0][l] * p[0][r - l] % MOD[0];
		return (res1 >= MOD[0]) ? res1 - MOD[0] : res1;
	}
	T find2(int l, int r) {
		T res2 = hash[1][r] + MOD[1] - hash[1][l] * p[1][r - l] % MOD[1];
		return (res2 >= MOD[1]) ? res2 - MOD[1] : res2;
	}
};
