int const MAXN = 2e5;
int a[MAXN], b[MAXN];
int c[MAXN-1], d[MAXN+MAXN-2];

int main() {
  int N; std::cin >> N;
  for(int i = 0; i < N; ++i) std::cin >> a[i];
  for(int i = 0; i < N; ++i) std::cin >> b[i];
  for(int i = 0; i < N-1; ++i) c[i] = a[i]^a[i+1];
  for(int i = 0; i < 2*N-2; ++i) d[i] = b[i%N]^b[(i+1)%N];
  std::set<int> ans;
  // BM
  std::map<int, int> t;
  for(int i = 0; i < N-1; ++i) t[c[i]] = N-2-i;
  int skip = N-1;
  for(int i = N-2; i > 0; --i) if(c[i]==c[0]) skip = i;
  int i = N-2;
  int p = 0;
  while(i < 2*N-2) {
    p = N-2;
    while(p >= 0 && i < 2*N-2) {
      if(d[i] == c[p]) { --i; --p; } else break;
    }
    if(p < 0) {
      ans.insert((N-(i+1))%N);
      i += N-1 + skip;
    }else {
      int off = t.count(c[p])>0? t[c[p]]: N-1;
      i += std::max(off, N-1-p);
    }
  }
  // ans
  for(auto k: ans) {
    int x = a[0]^b[(N-k)%N];
    std::cout << k << " " << x << std::endl;
  }
