    int i = 1, j = 0;
    while (i < (int)s.size()) {
        while (i + j < (int)s.size() && s[j] == s[i + j]) ++j;
        ans[i] = j;
        if (!j) {
            ++i;
            continue;
        }
        int k = 1;
        while (i + k < (int)s.size() && k + ans[k] < j) ans[i + k] = ans[k], ++k;
        i += k;
        j -= k;
    }
    return ans;
}
int main()
{
    int N;
    cin >> N;
    vector<int> a(N), b(N);
    cin >> a >> b;
    vector<int> xx(N * 3 + 1);
    xx[N] = -1;
    REP(i, N) xx[i] = b[i] ^ b[(i + 1) % N];
    REP(i, N * 2) xx[i + N + 1] = a[(i) % N] ^ a[(i + 1) % N];
    vector<int> z = z_algorithm(xx);
    REP(i, N) {
        if (z[N + 1 + i] >= N - 1) {
            printf("%d %d\n", i, a[i] ^ b[0]);
        }
    }
}

