vector<int> prefixFunction(vector<int> s) {
  vector<int> p(sz(s));
  for (int i = 1; i < sz(s); i++) {
    int prev = p[i - 1];
    while (prev > 0 && s[prev] != s[i]) {
      prev = p[prev - 1];
    }
    if (s[prev] == s[i]) {
      prev++;
    }
    p[i] = prev;
  }
  return p;
}

