const int M = 1000000007;

vector<int> buildFail(vector<int> &p) {
  int m = p.size();
  vector<int> fail(m+1);
  int j = fail[0] = -1;
  for (int i = 1; i <= m; ++i) {
    while (j >= 0 && p[j] != p[i-1]) j = fail[j];
    fail[i] = ++j;
  }
  return fail;
}

vector<int> match(vector<int> &t, vector<int> &p, vector<int> &fail) {
  int n = t.size(), m = p.size();
  int count = 0;
  vector<int> res;
  for (int i = 0, k = 0; i < n; ++i) {
    while (k >= 0 && p[k] != t[i]) k = fail[k];
    if (++k >= m) {
      ++count; // match at t[i-m+1 .. i]
      res.push_back(i - m + 1);
      k = fail[k];
    }
  }
  return res;
}

