V<int> MorisPlatt(const V<int> s) {
    int n = s.size();
    V<int> ret(n + 1, -1);
    int j = -1;
    for (int i = 0; i < n; i++) {
        while (j >= 0 && s[i] != s[j]) j = ret[j];
        j++;
        ret[i + 1] = j;
    }
    return ret;
}

