vector<int> Zalgo(const vector<int> &s){
    int N=s.size();
    vector<int> z(N,0);
    z[0]=N;
    int i=1,j=0;
    while(i<N){
        int c = s[i]^s[0]; 
        while(i+j<N && (s[i+j]^s[j])==c)j++;
        z[i]=j;
        if(j==0){i++;continue;}
        int k=1;
        while(i+k<N && z[k]+k < j){
            z[i+k]=z[k];
            k++;
        }
        i+=k;j-=k;
    }
    return z;
}

