template<class T>
class KMP{
private:
    int size_s,size_p;
    vector<T> S,P;
    vector<int> res,table;
public:
    KMP(vector<T> _S,vector<T> _P):
        S(_S),P(_P),size_s(_S.size()),size_p(_P.size()),
        table(_P.size()){
            int i = 2;
            int j = 0;
            table[0] = -1,table[1] = 0;
            while(i < size_p){
                if(P[i-1] == P[j])table[i] = j + 1,i++,j++;
                else if(j > 0)j = table[j];
                else table[i] = 0,i++;
            }
        }
    int search(int m){
        int i = 0;
        while(m+i < size_s){
            if(P[i] == S[m+i]){
                i++;
                if(i == size_p)return m;
            }else{
                m = m + i - table[i];
                if(i > 0)i = table[i];
            }
        }
        return size_s;
    }
};
