typedef long long ll;


class Primes {
public:
	int size;
	vector<int> v, primes;
	Primes(int _size) : size(_size), v(_size,0), primes(){
		int sqrtsize = (int)sqrt((double)_size);

		for ( int i = 2; i < size; i++ ){
			if ( v[i] )
				continue;
			primes.push_back(i);
			if ( i <= sqrtsize )
				for ( int j = i*i; j < _size; j+=i )
					v[j] = 1;
		}
	}

	// map<prime,pow>
	map<int,int> factor(ll x){
		map<int,int> m;
		for ( auto it : primes ){
			int prime = it;
			if ( x < prime )
				break;

			int count = 0;
			while ( x % prime == 0 ){
				x /= prime;
				count++;
			}
			if ( count )
				m[prime] = count;
		}
		if ( x != 1 )
			m[x] = 1;
		return m;
	}


	vector<pair<int,int>> factorv(ll x){
		auto m = factor( x );
		vector<pair<int,int>> v;
		for ( auto it : m ){
			v.push_back({it.first,it.second});
		}
		return v;
	}

	// 約数を求める
	vector<int> divisor( ll x ){
		auto v = factorv( x );
		vector<int> div;
		divisor2( div, v, 0, 1 );
		sort(div.begin(), div.end());
		return div;
	}

	void divisor2( vector<int> &div, vector<pair<int,int>> &v, int i, int mul ){
		for ( int j = 0; j <= v[i].second; j++ ){
			if ( i == v.size()-1 ){
				div.push_back(mul);
			}
			else {
				divisor2( div, v, i+1, mul );
			}
			mul *= v[i].first;
		}
	}
};




int N;
vector<ll> A, B;



int main2(){

	cin >> N;
	A.resize(N+1);
	B.resize(N+1);

	for ( int i = 0; i < N; i++ ){
		cin >> A[i];
	}
	for ( int i = 0; i < N; i++ ){
		cin >> B[i];
	}
	A[N] = A[0];
	B[N] = B[0];


	vector<ll> AA(N), BB(N);
	for ( int i = 0; i < N; i++ ){
		AA[i] = A[i] ^ A[i+1];
		BB[i] = B[i] ^ B[i+1];
	}


	// A, Bの周期を調べる
	Primes p(200000);
	auto divs = p.divisor(N);

	int min_k = N;
	for ( int kk = 0; kk < divs.size(); kk++ ){
		int k = divs[kk];
		bool match = true;
		for ( int i = 0; i < N; i++ ){
			if ( A[i] != A[(i+k)%N] || B[i] != B[(i+k)%N] ){
				match = false;
				break;
			}
		}
		if ( match ){
			min_k = k;
			break;
		}
	}


	int offset = 0;
	vector<pair<int,int>> result;
	for ( int k = 0; k < min_k; k++ ){
		bool match = true;
		for ( int i = 0; i < min_k; i++ ){
			if ( AA[(i+offset+k)%N] != BB[(i+offset)%N] ){
				match = false;
				offset = (offset+N+i-1)%N;
				break;
			}
		}
		if ( match ){
			result.push_back({k,A[k]^B[0]});
		}
	}
	for ( int k = 0; k < N; k += min_k ){
		for ( auto it: result ){
			cout << (k+it.first) << " " << it.second << endl;
		}
	}


	return 0;
}

