void zalgo(vector<int> &S, vector<int> &A, int r){
    A = vi(S.size());
    int c = 0;
    for(int i = 1; i < r; i++){
        if(i + A[i - c] < c + A[c]){
            A[i] = A[i - c];
        }else{
            int j = max(0, c + A[c] - i);
            while(i + j < S.size() && S[j] == S[i + j]) ++j;
            A[i] = j;
        }
    }
    A[0] = S.size();
}

