        vector<RH> bRH;
        for (int i = 0; i < 32; ++i) {
            string a, ra, b;
            for (int j = 0; j < N; ++j) {
                if (A[j] >> i & 1) {
                    a += '1';
                } else {
                    a += '0';
                }
                ra += a.back() ^ 1;
                if (B[j] >> i & 1) {
                    b += '1';
                } else {
