            aRH.push_back(make_pair(RH7(a), RH9(a)));
            raRH.push_back(make_pair(RH7(ra), RH9(ra)));
            bRH.push_back(make_pair(RH7(b), RH9(b)));
        }

        vector<pair<Int, Int>> ans;

        for (int k = 0; k < N; ++k) {
            bool ok = true;
            for (int i = 0; i < 32; ++i) {
                bool flag1 = aRH[i].first.get(k, k + N) == bRH[i].first.get(0, N) &&
                             aRH[i].second.get(k, k + N) == bRH[i].second.get(0, N);
                bool flag2 = raRH[i].first.get(k, k + N) == bRH[i].first.get(0, N) &&
                             raRH[i].second.get(k, k + N) == bRH[i].second.get(0, N);
                if (!flag1 && !flag2) {
                    ok = false;
                }
            }

            if (ok) {
                Int x = A[k] ^B[0];
                ans.emplace_back(k, x);
            }
        }

        sort(all(ans));
        for (auto e : ans) {
            cout << e.first << ' ' << e.second << endl;
        }


    }

};


