static constexpr uint64_t base = 5ULL;
class roll {
//const uint64_t base = rand((uint64_t) 2, mask61 - 1);
    static constexpr uint64_t mask30 = ((uint64_t)1 << 30) - 1;
    static constexpr uint64_t mask31 = ((uint64_t)1 << 31) - 1;
    static constexpr uint64_t mask61 = ((uint64_t)1 << 61) - 1;
    static constexpr uint64_t offset = mask61 * 7;
    static constexpr uint64_t mod(const uint64_t x)    {        const uint64_t y = (x >> 61) + (x & mask61);        return y >= mask61 ? y - mask61 : y;    }
    static constexpr uint64_t mul(const uint64_t x, const uint64_t y)    {        const uint64_t xh = x >> 31, xl = x & mask31;        const uint64_t yh = y >> 31, yl = y & mask31;        const uint64_t z  = xl * yh + xh * yl;        const uint64_t zh = z >> 30, zl = z & mask30;        return ((xh * yh)<<1) + zh + (zl << 31) + xl * yl;    }    const std::size_t siz;
    std::vector<uint64_t> pow, h;
public:
    template<typename T>
    roll(T &A) : siz(sz(A)), pow(siz + 1, 1), h(siz + 1, 0) {for (std::size_t i = 1; i <= siz; i++) {pow[i] = mod(mul(pow[i - 1], base)), h[i] = mod(mul(h[i - 1], base) + A[i-1]);}}
    uint64_t operator()(const std::size_t l, const std::size_t r) const { return mod(h[r] + offset - mul(h[l], pow[r - l])); }
};

void solve() {
    in(N);
    na(A,N);
    na(B,N);
    if(all_of(A,==A[0]) && all_of(B,==B[0])){
        rep(i, N){
            out(i,A[0]^B[0]);
        }
        return;
    }

    vi callr(N);
    vi resr(N);

    auto DS = bget2(B,31);

    rep(b, 31) {
        roll rb(DS[b]);
//        bhash(db.begin(), db.end(), 5ULL);

        auto hb = rb(0, N);
        rep(x, 2) {
            vi C = bget1(A,b);
            C*=2;
            for_each(C,^=x);
            roll ra(C);
//            roll ra(C);
            rep(r, N) {
                if (ra(r, r + N) == hb) {
                    callr[r]++;
                    resr[r] += bit(b) * x;
                }
            }
        }
    }
    rep(r, N) {
        if (callr[r] == 31) {
            out(r, A[r] ^ B[0]);
        }
    }
}
