                if ((A[p+k] ^ x) != B[p])goto end;
            } else {
                if ((A[p+k-N] ^ x) != B[p])goto end;
            }
            if (++pi >= N)pi = 0;
        }
        ks += k;
        xs += x;
        end:;
    }
    auto part = calc_time_nano();
    auto can = nanoseconds(1800000000) - part;
    int ka= div(can, part);
    lim *=ka/2;
    pi=0;
    rep(k, N) {
        int x = A[k] ^B[0];
        rep(i, lim) {
            int p = P[pi];
            if (p+k < N) {
                if ((A[p+k] ^ x) != B[p])goto end2;
            } else {
                if ((A[p+k-N] ^ x) != B[p])goto end2;
            }
            if (++pi >= N)pi = 0;
        }
        out(k,x);
        end2:;
    }
}
