    REP(i, N) c[i] = a[i] ^ a[(i+1)%N];
    REP(i, N) d[i] = b[i] ^ b[(i+1)%N];

    vector<unsigned long long> cc(2*N);
    REP(i, N) cc[i] = cc[N+i] = c[i];
    RollingHash rh;
    auto hashB = rh.get(d);
    rh.set(cc);
    vector<int> ks;
    for(int k=0; k<N; k++){
