class RollingHash{
    const ll mod = 1e9+7;
    const ll base = 1007;
    V<> hash, power;
public:
    RollingHash(const V<> &s){
        ll n = SZ(s);
        hash.assign(n+1, 0);
        power.assign(n+1, 1);
        REP(i,n){
            hash[i+1] = (hash[i] * base + s[i]) % mod;
            power[i+1] = (power[i] * base) % mod;
        }
    }
    inline ll get(ll l, ll r) const {
        ll res = hash[r] - hash[l] * power[r-l] % mod;
        if(res < 0) res += mod;
        return res;
    }
    inline ll s_hash(){return get(0, SZ(hash) - 1);}
    inline ll getLCP (ll a, ll b) const {
        ll len = min(SZ(hash)-a, SZ(hash)-b);
        ll ok = 0, ng = len;
        while(abs(ok-ng) > 1){
            ll mid = (ok+ng) / 2;
            if(get(a, a+mid) != get(b, b+mid)) ng = mid;
            else ok = mid;
        }
        return ok;
    }
};

