#include <bits/stdc++.h>
using namespace std;
const long long int MOD = (1LL<<31) - 1;
const long long int base1 = 48271;
const long long int base2 = 69621;

vector<int> match;

void contain(vector<long long int> a, vector<long long int> b, long long int BASE){// find a from b
    if(a.size() > b.size()) return ;

    long long int powB = 1;
    for(int i=0; i<a.size(); i++){
        powB *= BASE;
        powB %= MOD;
    }

    // Hash
    long long int hash_a = 0;// a[0] * BASE^(la-1) + ... + a[la-2] * BASE + a[la-1] 
    long long int hash_b = 0;
    for(int i=0; i<a.size(); i++){
        hash_a = hash_a * BASE + a[i];
        hash_b = hash_b * BASE + b[i];// hash of b.substr(0, a.length())

        hash_a %= MOD;
        hash_b %= MOD;
    }

    // Roll
    for(int i=0; i+a.size()<=b.size(); i++){
        if(hash_a == hash_b){// b.substr(i,la) == a
            match[i] += 1;
        }
        if(i + a.size() < b.size()){
            hash_b = hash_b * BASE + b[i+a.size()] - b[i] * powB;
            hash_b = (hash_b % MOD + MOD) % MOD;
        }
    }
    return ;// i + a.length() == b.length() : coudln't find
}

int main(){
    int n;
    cin >> n;
    match.resize(n);

    vector<long long int> a(n+1), b(n+1);
    for(int i=0; i<n; i++){
        cin >> a[i];
    }
    for(int i=0; i<n; i++){
        cin >> b[i];
    }
    a[n] = a[0];
    b[n] = b[0];

    vector<long long int> xa(2*n-1), xb(n);
    for(int i=0; i<n; i++){
        xa[i] = (a[i] ^ a[i+1]);
        if(i == n-1) break;
        xa[n+i] = xa[i];
    }
    for(int i=0; i<n; i++){
        xb[i] = (b[i] ^ b[i+1]);
    }

    //for(int i=0; i<2*n-1; i++) cout << xa[i] << " ";
    //cout << endl;
    //for(int i=0; i<n; i++) cout << xb[i] << " ";
    //cout << endl;

    contain(xb, xa, base1);
    contain(xb, xa, base2);

    for(int k=0; k<n; k++){
        if(match[k] == 2){
            int x = a[k] ^ b[0];
            cout << k << " " << x << endl;
        }
    }
    return 0;
}

