//早い
struct rolling_hash {
    static constexpr int base1 = 1007, base2 = 2009;
    static constexpr int mod1 = 1000000007, mod2 = 1000000009;
    vector<long long> hash1, hash2, power1, power2;
    int n;
    rolling_hash(const string &S) {         n = (int) S.size();        hash1.assign(n + 1, 0);        hash2.assign(n + 1, 0);        power1.assign(n + 1, 1);        power2.assign(n + 1, 1);        for (int i = 0; i < n; ++i) {            hash1[i + 1] = (hash1[i] * base1 + S[i]) % mod1;            hash2[i + 1] = (hash2[i] * base2 + S[i]) % mod2;            power1[i + 1] = (power1[i] * base1) % mod1;            power2[i + 1] = (power2[i] * base2) % mod2;        }    }
    template<class T>rolling_hash(const vector<T> &S) {n = (int) S.size();        hash1.assign(n + 1, 0);        hash2.assign(n + 1, 0);        power1.assign(n + 1, 1);        power2.assign(n + 1, 1);        for (int i = 0; i < n; ++i) {            hash1[i + 1] = (hash1[i] * base1 + S[i]) % mod1;            hash2[i + 1] = (hash2[i] * base2 + S[i]) % mod2;            power1[i + 1] = (power1[i] * base1) % mod1;            power2[i + 1] = (power2[i] * base2) % mod2;        }    }
     pair<int, int> get(int l, int r) const {        long long res1 = hash1[r] - hash1[l] * power1[r - l] % mod1;        if (res1 < 0) res1 += mod1;        long long res2 = hash2[r] - hash2[l] * power2[r - l] % mod2;        if (res2 < 0) res2 += mod2;        return {res1, res2};    }
     pair<int, int> operator()(int l, int r) const { return get(l, r); }
     pair<int, int> operator()() const { return get(0,n); }
    // get lcp of S[a:] and T[b:]
    //接頭語がどれだけ一致するか
    //範囲の重複を含む
     int lcp_dup(int a, int b) const {        int len = min((int) hash1.size() - a, (int) hash1.size() - b);        int low = 0, high = len;        while (high - low > 1) {            int mid = (low + high) >> 1;            if (get(a, a + mid) != get(b, b + mid)) high = mid; else low = mid;        }        return low;    }
    //重複を認めない
     int lcp_not(int a, int b) const { return min(lcp_dup(a, b), b - a); }//@formatter:on
};
