vector<int64> zalgo(const vector<int64>& v) {
  vector<int64> ret(v.size()+1);
  ret[0] = v.size();
  int64 i = 1, j = 0;
  while (i < v.size()) {
    while (i+j < v.size() && v[j] == v[i+j]) ++j;
    ret[i] = j;
    if (j == 0) { ++i; continue; }
    int64 k = 1;
    while (i+k < v.size() && k+ret[k] < j) ret[i+k] = ret[k], ++k;
    i += k; j -= k;
  }
  return ret;
}

