int rotate(int x2, int i)
{
	x2 = add(x2, -mul(getval(b1[n - i]), p_pwr[n - 1].ff, mod1), mod1);
	x2 = mul(x2, p1, mod1);
	x2 = add(x2, getval(b1[n - i]), mod1);
	return x2;
}



void solve()
{
	cin >> n;
	lop(i, 0, n) cin >> arr[i];
	lop(i, 0, n) cin >> brr[i];

	lop(i, 0, n) a1[i] = (arr[i] ^ arr[ (i + 1) % n]);
	lop(i, 0, n) b1[i] = (brr[i] ^ brr[ (i + 1) % n]);

	// prarr(a1, 0, n);
	// prarr(b1, 0, n);
	hash_it h1, h2;
	h1.init(a1, 0, n);
	h2.init(b1, 0, n);

	int x1 = h1.hashes[n - 1].ff;
	int x2 = h2.hashes[n - 1].ff;

	// bug(x1, x2);
	x1 = h1.get(0, n - 1).ff;
	x2 = h2.get(0, n - 1).ff;

	// bug(x1, x2);
	vector<pii> vec;
	if ( x1 == x2 ) vec.pb({0, -1});
	for (int i = 1; i <= n; i++)
	{
		x2 = rotate(x2, i);
		// cout << x2 <<  " : " << b1[n - i] << endl;
		if ( i < n and x2 == x1 ) vec.pb({i, -1});
	}
	// bug(x2);

	for (auto &i : vec)
	{
		int x = (arr[i.ff] ^ brr[0]);
		i.ss = x;
	}

	for (auto &i : vec) cout << i.ff << " " << i.ss << endl;
	// cout << n << " " << vec.size() << endl;

}

