struct ZAlgorithm
{
	std::vector<int> z;
	ZAlgorithm(const std::vector<int>& s) : z(s.size(),0) {
		int n = s.size();
		int l=0,r=0;
		z[0] = n;
		for(int i=1;i<n;i++) {
			z[i] = std::max((int)0, std::min(z[i-l], r-i+1));
			while(i+z[i]<n && s[z[i]] == s[i+z[i]]) {
				l=i; r=i+z[i]; z[i]++;
			}
		}
	}
};

std::vector<int> KMP(std::vector<int> s, std::vector<int> w) {
	// first create table for w
	ZAlgorithm z(w);
	std::vector<int> t(w.size()+1,0);
	t[0]=-1;
	for(int i=1;i<w.size();i++) {
		if(z.z[i]>0) {
			t[i+z.z[i]]=std::max(t[i+z.z[i]],z.z[i]);
			t[i]=-1;
		}
	}
	// search over s (mod)
	std::vector<int> ans;
	int k=0;
	for(int i=0;i<w.size()&&k<s.size();) {
		debug(i,k);
		if(w[i]==s[(k+i)%s.size()]) i++;
		else {
			k=k+i-t[i];
			if(t[i]>=0) i=t[i];
			else i=0;
		}
		debug(i,k);
		if(i==w.size()) {
			ans.emplace_back(k);
			k=k+i-t[i];
			i=t[i];
		}
	}
	return ans;
}

