ll base[2] = {10007, 10009};
ll mod[2] = {1000000007, 1000000009};

int main(){
	cin.tie(0); ios::sync_with_stdio(false);

	ll n;
	cin >> n;
	ll a[n], b[n];
	zep(i, 0, n){cin >> a[i];}
	zep(i, 0, n){cin >> b[i];}
	ll aa[n][50], bb[n][50];
	zep(i, 0, n){
		zep(d, 0, 31){
			aa[i][d] = (a[i] & (1LL << d))? 1 : 0;	
			bb[i][d] = (b[i] & (1LL << d))? 1 : 0;	
		}
	}

	ll fb[2][n];
	fb[0][0] = 1;
	fb[1][0] = 1;
	zep(i, 1, n){
		zep(j, 0, 2){
			fb[j][i] = (fb[j][i-1]*base[j])%mod[j];
		}
	}

	bool ans[n];
	zep(k, 0, n){ans[k] = true;}
	ll x[n];
	memset(x, 0, sizeof(x));

	zep(d, 0, 31){
		ll hash[2] = {0, 0};

		zep(i, 0, n){
			zep(j, 0, 2){
				hash[j] += ((bb[i][d]+1)*fb[j][n-1-i])%mod[j];
				hash[j] %= mod[j];
			}
		}

		bool flag[n];
		memset(flag, 0, sizeof(flag));

		//0^
		ll tmp[2] = {0, 0};
		zep(i, 0, n){
			zep(j, 0, 2){
				tmp[j] += ((aa[i][d]+1)*fb[j][n-1-i])%mod[j];
				tmp[j] %= mod[j];
			}
		}

		rep(k, 0, n){
			if(tmp[0] == hash[0] && tmp[1] == hash[1]){
				flag[k] = true;
			}

			zep(j, 0, 2){
				tmp[j] += mod[j]-(fb[j][n-1]*(aa[k][d]+1))%mod[j];
				tmp[j] %= mod[j];
				tmp[j] *= base[j];
				tmp[j] %= mod[j];
				tmp[j] += aa[k][d]+1;
				tmp[j] %= mod[j];
			}
		}

		//1^
		tmp[0] = 0;
		tmp[1] = 0;
		zep(i, 0, n){
			zep(j, 0, 2){
				tmp[j] += ((2-aa[i][d])*fb[j][n-1-i])%mod[j];
				tmp[j] %= mod[j];
			}
		}

		rep(k, 0, n){
			if(tmp[0] == hash[0] && tmp[1] == hash[1]){
				flag[k] = true;
				x[k] |= (1LL << d);
			}
			zep(j, 0, 2){
				tmp[j] += mod[j]-(fb[j][n-1]*(2-aa[k][d]))%mod[j];
				tmp[j] %= mod[j];
				tmp[j] *= base[j];
				tmp[j] %= mod[j];
				tmp[j] += 2-aa[k][d];
				tmp[j] %= mod[j];
			}
		}

		zep(i, 0, n){
			if(!flag[i]){
				ans[i] = false;
			}
		}
	}

	zep(k, 0, n){
		if(ans[k]){
			cout << k << " " << x[k] << endl;
		}
	}
	return 0;
}

