template<class T> struct ruimax {template<typename Monoid>struct SegmentTree {        /*pairで処理*/        int siiiz;        vector<Monoid> seg;        const Monoid M1 = mp(MIN(T), -1);        Monoid f(Monoid a, Monoid b) {            return max(a, b);        }        void build(vector<T> &a) {            int n = siiiz(a);            siiiz = 1;            while (siiiz < n) siiiz <<= 1;            seg.assign(2 * siiiz, M1);            rep(i, n) { seg[i + siiiz] = mp(a[i], i); }            for (int k = siiiz - 1; k > 0; k--) {                seg[k] = f(seg[k << 1], seg[(k << 1) | 1]);            }        }        Monoid query(int a, int b) {            Monoid L = M1, R = M1;            for (a += siiiz, b += siiiz; a < b; a >>= 1, b >>= 1) {                if (a & 1) L = f(L, seg[a++]);                if (b & 1) R = f(seg[--b], R);            }            return f(L, R);        }        Monoid operator[](const int &k) const {            return seg[k + siiiz];        }    };private:vector<T> ve;SegmentTree<pair<T, int>> seg;vector<T> rv;vector<T> ri;bool build = false;
public:
    int n;
    ruimax(vector<T> &a) : ve(a), n(siiiz(a)) {        int index = -1;        int ma = MIN(T);        rv.resize(n + 1);        ri.resize(n + 1);        rv[0] = -linf;        ri[0] = -1;        rep(i, n) {            if (chma(ma, a[i])) {                index = i;            }            rv[i + 1] = ma;            ri[i + 1] = index;        }    }
    T operator()(int l, int r) {        if (!(l <= r && 0 <= l && r <= n)) {            deb(l, r, n);            assert(0);        }        if (l == 0) {            return rv[r];        } else {            if (!build)seg.build(ve), build = true;            return seg.query(l, r).first;        }    }
    T operator()(int r = inf) { return operator()(0, min(r, n)); }
    T operator[](int r) {        return operator()(0, r);    }
    T getv(int l, int r) {        return operator()(l, r);    }
    T geti(int l, int r) {        assert(l <= r && 0 <= l && r <= n);        if (l == 0) {            return ri[r];        } else {            if (!build)seg.build(ve), build = true;            return seg.query(l, r).second;        }    }
    T geti(int r = inf) { return geti(0, min(r,n)); };
    T getv(int r = inf) { return getv(0, min(r,n)); };
    auto begin(){return rv.begin();}
    auto end(){return rv.end();}
};
