    vector<int> Z(vec.size());
    for(int i = 1, l = 0, r = 0;i < (int) Z.size();i++) {
      if(r >= i) {
        Z[i] = min(Z[i-l], r-i+1);
      }

      while(i+Z[i] < vec.size() && vec[i+Z[i]] == vec[Z[i]]) Z[i]++;

      if(i+Z[i]-1 > r) {
        l = i;r = i+Z[i]-1;
      }
    }

    return Z;

}

