vector <int> prefix_f(vector <int> & s) {
    int n = s.size();
    vector <int> ans(n);
    loop1(i, n - 1) {
        int j = ans[i - 1];
        while (j && s[i] != s[j])
            j = ans[j - 1];
        ans[i] = (s[i] == s[j] ? j + 1 : 0);
    }
    return ans;
}

