        vector<long long> res;
        long long j = 0;
        for (long long i = 0; i < s.size(); i++)
        {
            while (j != -1 && this->query[j] != document[i])
            {
                j = this->table[j];
            }
            j++;
            if (j == this->n)
            {
                res.push_back(i - j + 1);
                j = this->table[j];
            }
        }
        return res;
    }
};

