void get_divisors(V<ll> &retlist, ll x)
{
    for (ll i = 1LL; i < sqrt(x) + 3LL; ++i) {
        if (x % i == 0LL) {
            retlist.push_back(i);
            retlist.push_back(x / i);
        }
    }
}

bool judge_freq(const V<ll> &xlist, ll n, ll d)
{
    rep (i, n) if (xlist[i] != xlist[i%d]) return false;
    return true;
}

ll freq(const V<ll> &xlist, const set<ll> &divs, ll n)
{
    for (auto d : divs) if (judge_freq(xlist, n, d)) return d;
    assert(false);
}

#define MOD (1945723918823LL)
//#define MLT (1759LL)
#define MLT (10LL)

ll hash_init(const V<ll> &xlist, ll f)
{
    ll ret = 0;
    rep (i, f) {
        ret *= MLT;
        ret %= MOD;
        ret += xlist[i];
        ret %= MOD;
    }
    return ret;
}

void _main()
{
    ll n; llin(n);
    V<ll> alist; llina(alist, n);
    V<ll> blist; llina(blist, n);

    V<ll> xlist;
    rep (i, n) xlist.pb(alist[i] ^ alist[(i+1)%n]);
    V<ll> ylist;
    rep (i, n) ylist.pb(blist[i] ^ blist[(i+1)%n]);

    debug_printf("---- xlist\n");
    debug_print(xlist);
    debug_printf("---- ylist\n");
    debug_print(ylist);

    V<ll> divlist;
    get_divisors(divlist, n);
    set<ll> divs; for (auto d : divlist) divs.insert(d);

    ll xf = freq(xlist, divs, n);
    ll yf = freq(ylist, divs, n);
    if (xf != yf) {
        debug_printf("------- no 1\n");
        return;
    }

    ll mltf = 1LL;
    rep (i, xf) {
        mltf *= MLT;
        mltf %= MOD;
    }

    debug_printf("---- mltf=%lld\n", mltf);

    ll hash = hash_init(xlist, xf);

    set<t2> xhashset;
    rep (i, xf) {
        xhashset.insert(t2(hash, i));
        hash *= MLT;
        hash %= MOD;
        ll decr = xlist[i] * mltf;
        decr %= MOD;
        hash -= decr;
        if (hash < 0) hash += MOD;
        hash += xlist[(i+xf)%n];
        hash %= MOD;
    }

    debug_printf("-------- xhashset\n");
    debug_print(xhashset);

    ll yhash = hash_init(ylist, xf);
    debug_printf("-------- yhash=%lld\n", yhash);

    auto iter = xhashset.lower_bound(t2(yhash, -1));
    if (iter == xhashset.end()) {
        debug_printf("------- no 2\n");
        return;
    }
    ll xhash = get<0>(*iter);
    ll xidx = get<1>(*iter);
    if (xhash != yhash) {
        debug_printf("------- no 3\n");
        return;
    }

    V<ll> ansidxs;
    while (xidx < n) {
        ansidxs.pb(xidx);
        xidx += xf;
    }

    for (auto ansidx : ansidxs) {
        cout << ansidx << " " << (alist[ansidx] ^ blist[0]) << endl;
    }
}

