std::vector<int> zarray(const vector<int> &s) {
    int c = 0;
    std::vector<int> A(s.size(), 0);
    for (int i = 1; i < (int)s.size(); i++) {
        if (i + A[i - c] < c + A[c]) {
            A[i] = A[i - c];
        } else {
            int j = std::max<int>(0, c + A[c] - i);
            while (i + j < (int)s.size() && s[j] == s[i + j])
                ++j;
            A[i] = j;
            c = i;
        }
    }
    A[0] = s.size();
    return A;
}

