template<class T>
struct KMP{
    T x;
    vector<int> table;

    KMP(const T &s){
        init(s);
    }
    void init(const T &s){
        x=s;
        int m=(int)s.size();
        table.assign(m+1,-1);
        int j=-1;
        for(int i=0;i<m;i++){
            while(j>=0 && x[i]!=x[j]) j=table[j];
            table[i+1]=++j;
        }
    }
    int period(int i){ //S[0:i-1]において、どれぐらいずらしたら一致するか
        return i-table[i];
    }

    vector<int> query(const T &S){
        int n=(int)S.size(),m=(int)x.size();
        vector<int> ans;
        int k=0;
        for(int i=0;i<n;i++){
            while(k>=0 && S[i]!=x[k]) k=table[k];
            k++;
            if(k>=m) ans.push_back(i-m+1),k=table[k];
        }
        return ans;
    }
};

