int main(){
    cin.tie(0);
    ios::sync_with_stdio(false);
    int N;
    cin >> N;
    vec<int> A(N),B(N);
    for(int i=0;i<N;i++) cin >> A[i];
    for(int i=0;i<N;i++) cin >> B[i];

    vec<unordered_map<int,int>> valid(30);
    auto prekmp = [&](string x,vector<int>& kmpnext){
        int m = x.size();
        int i = 0,j = kmpnext[0] = -1;
        while(i<m){
            while(j>-1 && x[i]!=x[j]) j = kmpnext[j];
            i++; j++;
            if(x[i]==x[j]) kmpnext[i] = kmpnext[j];
            else kmpnext[i] = j;
        }
    };
    auto KMP = [&](string x,string y,int bit,bool swapped){
        int m = x.size(),n = y.size();
        vector<int> kmpnext(m+1);
        int i = 0,j = 0;
        prekmp(x,kmpnext);
        while(j<n-1){
            while(i>-1 && x[i]!=y[j]) i = kmpnext[i];
            i++; j++;
            if(i>=m){
                valid[bit][j-m] = swapped;
                i = kmpnext[i];
            }
        }
    };


    auto check = [&](int bit){
        string S = "",T = "";
        for(int i=0;i<N;i++){
            char c;
            if(A[i]&(1<<bit)) S += '1';
            else S += '0';
            if(B[i]&(1<<bit)) T += '1';
            else T += '0';
        }
        S += S;
        KMP(T,S,bit,0);
        for(int i=0;i<2*N;i++) S[i] = (S[i]=='0'? '1':'0');
        KMP(T,S,bit,1);
    };

    for(int i=0;i<30;i++) check(i);
    vec<P<int,int>> ans;
    for(auto& x:valid[0]){
        bool ok = true;
        int res = (x.second? 1:0);
        for(int i=1;i<30;i++){
            if(!valid[i].count(x.first)){
                ok = false;
                break;
            }else if(valid[i][x.first]){
                res ^= (1<<i);
            }
        }
        if(ok) ans.push_back({x.first,res});
    }
    sort(ans.begin(),ans.end());
    for(auto& x:ans) cout << x.first << " " << x.second << endl;
}

