struct Zalgorithm{
    vector<int> Z;
    Zalgorithm(vi s){
        Z.resize(s.size());
        Z[0]=s.size();
    }

    vector<int> Zeach(vi s){
        int i=1,j=0;
        while(i<Z[0]){
            while(i+j<Z[0]&&s[j]==s[i+j]) j++;
            Z[i]=j;
            if(j==0){
                i++;
                continue;
            }
            int k=1;
            while(k+Z[k]<j){
                Z[i+k]=Z[k];
                k++;
            }
            i+=k;
            j-=k;
        }
        return Z;
    }

    int Zmax(vi s){
        int ans=0;
        for(auto can:Zeach(s)){
            ans=max(ans,can);
        }
        return ans;
    }
};
