	int t1=1,t2=0;
	nxt[1]=0;
	while(t1<=n){
		if(t2==0||b1[t1]==b1[t2]) nxt[++t1]=++t2;
		else t2=nxt[t2];
	}
}
void KMP(int lv,int v){
	int t1=1,t2=1;
	while(t1<=na){
		if(t2==0||a1[t1]==b1[t2]) ++t1,++t2;
		else t2=nxt[t2];
		if(t2==n+1){
			c[lv][t1-t2+1]=v;
			t2=nxt[t2];
		}
	}
}
