//Zアルゴリズム
template<class t>
void Zalgo(const vector<t>& S,const vector<t>& T,vector<ll>& ln1,const vector<ll>& ln2){
    ll i = 1;
    ll j = 0;
    ll k = 0;
    ll Sn = S.size();
    ll Tn = T.size();
    while(i<Sn){
        //printf("%lld %lld\n", i, j);
        if(i+ln2[i-j]<j+ln1[j]){
            ln1[i] = ln2[i - j];
        }else{
            k = max(j + ln1[j] - i, 0ll);
            while (k<Tn&&i + k < Sn && T[k] == S[i + k])
                k++;
            ln1[i] = k;
            j = i;
        }
        i++;
    }
    ll N = min(Sn, Tn);
    fornum(i,0,N){
        if(S[i]!=T[i])
            break;
    }
    ln1[0] = i;
}


