class RollingHash{
    const ull MASK30 = (1UL << 30) - 1;
    const ull MASK31 = (1UL << 31) - 1;
    const ull MOD = (1UL << 61) - 1;
    const ull POSITIVIZER = MOD * ((1UL << 3) - 1);
    ull powMemo[1000001];
    vector<ull> hash;

    void init(){


        powMemo[0] = 1;
        REP(i,1000000) powMemo[i+1] = calcMod(mul(powMemo[i], base));
    }
    ull mul(ull l, ull r){
        ull lu = l >> 31;
        ull ld = l & MASK31;
        ull ru = r >> 31;
        ull rd = r & MASK31;
        ull middle = ld * ru + lu * rd;
        return ((lu * ru) << 1) + ld * rd + ((middle & MASK30) << 31) + (middle >> 30);
    }
    ull calcMod(ull val){
        val = (val & MOD) + (val >> 61);
        return val > MOD ? val - MOD : val;
    }

public:
    RollingHash(string s){
        init();
        hash.resize(s.length()+1);
        REP(i, s.length()) hash[i+1] = calcMod(mul(hash[i], base) + s[i]);
    }
    ull slice(int b, int l){
        return calcMod(hash[b+l] + POSITIVIZER - mul(hash[b], powMemo[l]));
    }
};
