int kmp(const string &needle, const string &text) {
    const int n = needle.length(), m = text.length();
    int *const z = new int[n];
    memset(z, 0, sizeof(int) * n);
    int c = 0;
    for (int i = 1; i < n; i++) {
        z[i] = c;
        if (needle[c] == needle[i]) c++;
        else c = 0;
    }
    z[0] = -1;
    int s = 0, t = 0, r = -1;
    while (s + t < m) {
        if (needle[s] == text[s + t]) {
            s++;
            if (s == n) {
                r = t;
                break;
            }
        } else {
            t = s + t - z[s];
            if (s > 0) s = z[s];
        }
    }
    free(z);
    return r;
}

