struct RollingHash {
  long long Mod, Base;
  vector<long long> pow;
  vector<vector<long long>> hash;
  // mod : 1e9 + 9,base : 1007
  RollingHash(const long long len = 3000000,
              const long long mod = (1e9 + 7),
              const long long base = 1009) {
    Mod = mod;
    Base = base;
    pow.assign(len + 1, 0);
    pow[0] = 1;
    for(int i = 1; i <= len; ++i)
      pow[i] = pow[i - 1] * Base % Mod;
  }
  void add(const string &s) {
    int id = hash.size();
    hash.push_back(vector<long long>((int)s.size() + 1, 0));
    sethash(id, s);
  }
  void changestr(const int &id, const string &s) {
    assert(id < (int)hash.size());
    sethash(id, s);
  }
  void sethash(const int &id, const string &s) {
    int len = s.size();
    for(int i = 0; i < len; ++i) {
      if(i != 0) hash[id][i + 1] = hash[id][i] * Base % Mod;
      hash[id][i + 1] += s[i];
      hash[id][i + 1] %= Mod;
    }
  }
  // [l,r),0-indexed
  long long calchash(const int &id, const int &l,
                     const int &r) {
    long long res;
    res = hash[id][r];
    res -= hash[id][l] * pow[r - l] % Mod;
    while(res < 0) res += Mod;
    return res % Mod;
  }
  inline bool issame(const int &idl, const int &ll,
                     const int &lr, const int &idr,
                     const int &rl, const int &rr) {
    return calchash(idl, ll, lr) == calchash(idr, rl, rr);
  }
};

