class fast_rolling_hash
{
public:
    template<typename InIt>
    fast_rolling_hash(const InIt first, const InIt last, const u64 base = g_rng_xo64((u64)2, mask61 - 1)) : sz(std::distance(first, last)), pow(sz + 1, 1), h(sz + 1, 0)
    {
        for (usize i = 1; i <= sz; i++) { pow[i] = mod(mul(pow[i - 1], base)), h[i] = mod(mul(h[i - 1], base) + *std::next(first, i - 1)); }
    }
    u64 operator()(const usize l, const usize r) const { return mod(h[r] + offset - mul(h[l], pow[r - l])); }

private:
    static constexpr u64 mask30 = ((u64)1 << 30) - 1;
    static constexpr u64 mask31 = ((u64)1 << 31) - 1;
    static constexpr u64 mask61 = ((u64)1 << 61) - 1;
    static constexpr u64 offset = mask61 * 7;
    static constexpr u64 mod(const u64 x)
    {
        const u64 y = (x >> 61) + (x & mask61);
        return y >= mask61 ? y - mask61 : y;
    }
    static constexpr u64 mul(const u64 x, const u64 y)
    {
        const u64 xh = x >> 31, xl = x & mask31;
        const u64 yh = y >> 31, yl = y & mask31;
        const u64 z  = xl * yh + xh * yl;
        const u64 zh = z >> 30, zl = z & mask30;
        return xh * yh * 2 + zh + (zl << 31) + xl * yl;
    }
    const usize sz;
    std::vector<u64> pow, h;
};
