    for (int bit = 0; bit < LIM; bit++) {
    	vector<int> na(n);
    	vector<int> nb(n);
    	for (int i = 0; i < n; i++) {
    		na[i] = ((a[i] >> bit) & 1);
    		nb[i] = ((b[i] >> bit) & 1);
    	}
    	// for (auto t : na) {
    	// 	cerr << t << ' ';
    	// }
    	// cerr << endl;
    	// for (auto t : nb) {
    	// 	cerr << t << ' ';
    	// }
    	// cerr << endl;
    	vector<int> lol;
    	vector<int> hv(n);

    	lol = solve(na, nb);
    	for (auto t : lol) {
    		hv[t] = 1;
    	}

    	for (auto &t : na) {
    		t ^= 1;
    	}

    	lol = solve(na, nb);
    	for (auto t : lol) {
    		hv[t] = 1;
    	}

    	for (int i = 0; i < n; i++) {
    		cnt[i] += hv[i];
    	}
    }
    for (int i = 0; i < n; i++) {
    	if (cnt[i] == LIM) {
    		cout << (n - i) % n << ' ' << (a[0] ^ b[i]) << '\n';
