vector<ll> build_lps(vector<ll> p){
    ll sz = p.size();
    vector<ll> lps(sz,0);
    for(ll i=1,j=0;i<sz;i++){
        while(j >= 0 && p[i] != p[j]){
            if(j >= 1) j = lps[j - 1];
            else j = -1;
        }
        j++;
        lps[i] = j;
    }
    return lps;
}
vector<ll>ans;
void kmp(vector<ll> lps, vector<ll> s, vector<ll> p){
	ll psz = p.size(), sz = s.size();
	for(ll i=0,j=0;i<sz;i++){
		while(j>=0&&p[j]!=s[i]){
			if(j>=1)j=lps[j - 1];
			else j=-1;
		}
		j++;
		if(j==psz)j=lps[j - 1],ans.push_back(i-psz+1);
	}
}
