vector<Int> solve(vector<Int> a, vector<Int> b){
    Int hasha = 0, hashb = 0, hashaa = 0;

    Int poyo = 10;//141592;
    Int mod = 998244353;
    Int payo = 1;

    for(auto elem:a){
        hasha *= poyo;hasha %= mod;
        hasha += elem;
        hasha %= mod;

        hashaa *= poyo;hashaa %= mod;
        hashaa += 1-elem;
        hashaa %= mod;
    }
    for(auto elem:b){
        hashb *= poyo;hashb %= mod;
        hashb += elem;
        hashb %= mod;
    }

    for(int i = 0;i < b.size();i++){
        payo = poyo * payo;payo %= mod;
    }
    payo += mod - 1;payo %= mod;
    payo = mod - payo;payo %= mod;
    vector<Int> ans(a.size(), -1);
    for(int i = 0;i < b.size();i++){
        if(hasha == hashb)ans[(n-i)%n] = 0;
        if(hashaa == hashb)ans[(n-i)%n] = 1;
        hashb *= poyo;hashb %= mod;
        hashb += payo * b[i] % mod;
        hashb %= mod;
    }
    return ans;
}

