long long Calc(long long A, long long B, long long M) {
	if (B == 0) return 1 % M;
	if (B % 2 == 0) {
		long long C = Calc(A, B / 2, M);
		return (C * C) % M;
	}
	return (A * Calc(A, B - 1, M)) % M;
}

