struct LLRollingHash {
// long long に対するRollingHash
public:
    ll n1, n2;
    vector<ll> table11, table12, table21, table22;
    ll base1 = 128ll, base2 = 243ll;
    ll mod1 = 2000000011ll, mod2 = 2000000033ll;

    LLRollingHash(vector<ll> v1, vector<ll> v2) {
        n1 = v1.size();
        n2 = v2.size();
        table11.resize(n1 + 1, 0);table12.resize(n1 + 1, 0);
        table21.resize(n2 + 1, 0ll);table22.resize(n2 + 1, 0);
        ll tmp1 = 0, tmp2 = 0;
        for(ll i=0;i<n1;i++){
            tmp1 = tmp1 * base1 + v1[i];
            tmp1 %= mod1;
            table11[i+1] = tmp1;
            tmp2 = tmp2 * base2 + v1[i];
            tmp2 %= mod2;
            table12[i+1] = tmp2;
        }
        tmp1 = 0; tmp2 = 0;
        for(ll i=0;i<n2;i++){
            tmp1 = tmp1 * base1 + v2[i];
            tmp1 %= mod1;
            table21[i+1] = tmp1;
            tmp2 = tmp2 * base2 + v2[i];
            tmp2 %= mod2;
            table22[i+1] = tmp2;
        }
    }

    ll base_pow(ll base, ll n, ll mod){
        if(n == 0){
            return 1ll;
        }else{
            ll tmp = base_pow(base, n / 2, mod);
            tmp = tmp * tmp % mod;
            if(n % 2 == 1){
                tmp *= base;
                tmp %= mod;
            }
            return tmp;
        }
    }

    bool check(ll n, ll idx1, ll idx2){
        // 一つ目の配列のidx1番目(0-index)からn文字と
        // 二つ目の配列のidx2番目(0-index)からn文字が一致するかどうかを確かめる
        assert(idx1 + n <= n1);
        assert(idx2 + n <= n2);
        ll mod1pow = base_pow(base1, n, mod1);
        ll mod2pow = base_pow(base2, n, mod2);
        ll hash11, hash12, hash21, hash22;
        hash11 = (table11[n + idx1] + (mod1 - (table11[idx1] * mod1pow) % mod1)) % mod1;
        hash12 = (table12[n + idx1] + (mod2 - (table12[idx1] * mod2pow) % mod2)) % mod2;
        hash21 = (table21[n + idx2] + (mod1 - (table21[idx2] * mod1pow) % mod1)) % mod1;
        hash22 = (table22[n + idx2] + (mod2 - (table22[idx2] * mod2pow) % mod2)) % mod2;
        if(hash11 == hash21 && hash12 == hash22){
            return true;
        }else{
            //pe(hash11);p(hash21);
            return false;
        }
    }
};


