	for(uint i=0; i<N; i++) {
		cin >> b[i];
		eqBall = (i == 0) ? eqBall : eqBall & (b[i-1] == b[i]);
	}

	if(eqBall != eqAall) { // one is all same factor, other is not
		return 0;
	} else if (eqAall & eqBall) { // both have all same factor
		uint x = a[0] ^ b[0];
		for(uint i=0; i<N; i++) cout << i << " " << x << endl;
		return 0;
	} 

	deque<pair<uint, uint>> pl;
	uint cnt = 1;
	uint prv = UINT_MAX; 

	for(uint k=0; k<2*N; k++) {
		if(b[k] != prv) {
			if(pl.empty()){
				pl.push_back(make_pair(cnt, k + 1 - cnt));
			} else if(pl.back().first < cnt) {
				pl.clear();
				pl.push_back(make_pair(cnt, k + 1 - cnt));
			} else if(pl.back().first == cnt) {
				pl.push_back(make_pair(cnt, k + 1 - cnt));
			}

			cnt = 1;
			prv = b[k];

			if(k >= N) break;

		} else {
			cnt++;
		}
	}

	uint maxC = pl.back().first;

	while(!pl.empty()) {
		uint k = pl.front().second;
		uint l = pl.front().first;
		pl.pop_front();

		//if(l < maxC) continue;

		uint x = a[k] ^ b[0];
