		for(uint i=l; i<N; i++) {
			if((b[i] ^ a[(k+i)%N]) != x) {
				mtc = false;
				break;
			}
		}

		if(mtc) {
			cout << k << " " << x << endl;
		}
	}

	return 0;
}

