using namespace std;

class RollingHash
{
public:
	static const uint64_t kM = (1LL << 61) - 1;

	RollingHash(const vector<uint64_t>& vals, const array<uint64_t, 2> rs)
	{
		this->rs_ = rs;

		this->hashs_[0].resize(vals.size() + 1);
		this->hashs_[1].resize(vals.size() + 1);
		this->memop_[0].resize(vals.size() + 1);
		this->memop_[1].resize(vals.size() + 1);

		array<uint64_t, 2> val = { 0, 0 };
		this->hashs_[0][0] = val[0];
		this->hashs_[0][1] = val[1];
		this->memop_[0][0] = 1;
		this->memop_[1][0] = 1;

		FOR_LT(i, 0, (int)vals.size()) {
			val[0] = (Mul(val[0], this->rs_[0]) + vals[i]) % kM;
			val[1] = (Mul(val[1], this->rs_[1]) + vals[i]) % kM;

			this->hashs_[0][i + 1] = val[0];
			this->hashs_[1][i + 1] = val[1];
			this->memop_[0][i + 1] = Mul(this->memop_[0][i], this->rs_[0]) % kM;
			this->memop_[1][i + 1] = Mul(this->memop_[1][i], this->rs_[1]) % kM;
		}
	}

	RollingHash(const vector<uint64_t>& vals) : RollingHash(vals, RollingHash::GenerateRs()) {}


	// 先頭 i 文字のハッシュを取得する
	array<uint64_t, 2> Hash(int i) const
	{
		assert(i < (int)this->hashs_[0].size());

		return { this->hashs_[0][i], this->hashs_[1][i] };
	}

	// [i, j) のハッシュを取得する。
	array<uint64_t, 2> Hash(int i, int j) const
	{
		assert(i < j);
		assert(i < (int) this->hashs_[0].size());
		assert(j < (int) this->hashs_[0].size());

		array<uint64_t, 2> hi = this->Hash(i);
		array<uint64_t, 2> hj = this->Hash(j);

		if (hi[0] >= kM || hi[1] >= kM || this->memop_[0][j - i] >= kM || this->memop_[1][j - 1] >= kM) {
			assert(false);
		}

		{
			random_device rd;
			mt19937_64 mt(rd());
		}


		array<uint64_t, 2> ret = {
			(hj[0] + kM - Mul(hi[0], this->memop_[0][j - i])) % kM,
			(hj[1] + kM - Mul(hi[1], this->memop_[1][j - i])) % kM
		};

		return ret;
	}

	static uint64_t AddOnM(uint64_t a, uint64_t b)
	{
		return (a + b) % kM;
	}

	static uint64_t MulOnM(uint64_t a, uint64_t b)
	{
		return Mul(a, b);
	}

	const array<uint64_t, 2>& Rs() const {
		return this->rs_;
	}

	const array<vector<uint64_t>, 2>& MomoP() const {
		return this->memop_;
	}

	int N() const {
		return (int) (this->hashs_[0].size() - 1);
	}

	static array<uint64_t, 2> GenerateRs()
	{
		array<uint64_t, 2> rs;
		random_device seed;
		mt19937_64 mt(seed());
		for (auto& r : rs) {
			r = mt() % (kM >> 30) + 1001;
		}

		return rs;
	}

private:
	static uint64_t Mul(uint64_t a, uint64_t b)
	{
		uint64_t au = a >> 31;
		uint64_t ad = a & ((1UL << 31) - 1);
		uint64_t bu = b >> 31;
		uint64_t bd = b & ((1UL << 31) - 1);

		uint64_t cval = au * bd + ad * bu;
		uint64_t cu   = (cval >> 30);
		uint64_t cd   = cval & ((1UL << 30) - 1);

		return (au * bu * 2 + cu + (cd << 31) + ad * bd) % kM;
	}

	array<vector<uint64_t>, 2> hashs_;
	array<uint64_t, 2> rs_;
	array<vector<uint64_t>, 2> memop_;

};

static array<uint64_t, 2> CalcHash(const RollingHash& rh, int s)
{
	array<uint64_t, 2> hh = rh.Hash(s, rh.N());
	array<uint64_t, 2> hl = rh.Hash(s);

	return {
		RollingHash::AddOnM(hl[0], RollingHash::MulOnM(hh[0], rh.MomoP()[0][s])),
		RollingHash::AddOnM(hl[1], RollingHash::MulOnM(hh[1], rh.MomoP()[1][s]))
	};
}

