vector<ll> KMPSearch(string target, string pattern) {
	vector<ll> table(pattern.size() + 1);
	table[0] = 0;
	ll j = 0;
	for (int i = 1; i < pattern.size(); i++)
	{
		if (pattern[i] == pattern[j]) table[i] = j++;
		else {
			table[i] = j;
			j = 0;
		}
	}
	table[pattern.size()] = j;
	vector<ll> res;
	ll i = 0, p = 0;
	while (i < target.size())
	{
		if (p < pattern.size() and target[i] == pattern[p]) {
			i++; p++;
		}
		else {
			if (p == 0) i++;
			p = table[p];
		}
		if (p == pattern.size()) res.push_back(i - p);
	}
	return res;
}

