vector<int> zalgo(vector<int> s){
  vector<int> ret(s.size());
  int c=0;
  FOR(i,1,s.size()){
	if(i+ret[i-c]<c+ret[c]) ret[i]=ret[i-c];
	else{
	  int j=max(0ll,c+ret[c]-i);
	  while(i+j<s.size() && s[j]==s[i+j]) j++;
	  ret[i]=j;
	  c=i;
	}
  }
  ret[0]=s.size();
  return ret;
}

