template<class T> vector<int> z_algorithm(const T& s) {
  vector<int> prefix(s.size());
  prefix[0] = s.size();
  int i = 1, j = 0;
  while (i < s.size()) {
    while (i + j < s.size() && s[j] == s[i + j]) ++j;
    prefix[i] = j;
    if (j == 0) { ++i; continue; }
    int k = 1;
    while (i + k < s.size() && k + prefix[k] < j) { prefix[i + k] = prefix[k]; ++k; }
    i += k; j -= k;
  }
  return prefix;
}

