        return xs[i];
    }
};

struct SuffixArray {
    vector<int> sa;
    const vector<int> s;

    SuffixArray(const vector<int>& str) : s(str) {
        int n = s.size();
        sa.resize(n);
        iota(sa.begin(), sa.end(), 0);
        sort(sa.begin(), sa.end(), [&](int i, int j) {
            return s[i] == s[j] ? i > j : s[i] < s[j];
        });
        int cl = 0;
        vector<int> rank(n);
        for (int i = 1; i < n; i++) {
            if (s[sa[i-1]] != s[sa[i]]) cl++;
            rank[sa[i]] = cl;
        }
        vector<int> pn(n), tmp(n), cnt(n);
        for (int k = 1; k < n; k *= 2) {
            for (int i = 0; i < n; i++) {
                pn[i] = sa[i] - k;
                if (pn[i] < 0) pn[i] += n;
            }
            fill(cnt.begin(), cnt.end(), 0);
            for (int i = 0; i < n; i++) cnt[rank[pn[i]]]++;
            for (int i = 1; i < n; i++) cnt[i] += cnt[i-1];
            for (int i = n - 1; i >= 0; i--) sa[--cnt[rank[pn[i]]]] = pn[i];
            tmp[sa[0]] = 0;
            cl = 0;
            for (int i = 1; i < n; i++) {
                if (rank[sa[i-1]] != rank[sa[i]] || rank[(sa[i-1] + k) % n] != rank[(sa[i] + k) % n]) {
                    cl++;
                }
                tmp[sa[i]] = cl;
            }
            swap(rank, tmp);
        }
    }

    int operator[](int k) const {
        return sa[k];
    }

    bool lt_substr(const vector<int>& t, int si = 0, int ti = 0) {
        int n = s.size();
        for (int i = 0; i < min(s.size(), t.size()); i++) {
            if (s[(si + i) % n] < t[(ti + i) % n]) return true;
            if (s[(si + i) % n] > t[(ti + i) % n]) return false;
        }
        return false;
    }

    int lower_bound(const vector<int>& t) {
        int lb = -1, ub = sa.size();
        while (ub - lb > 1) {
            int m = (lb + ub) / 2;
            if (lt_substr(t, sa[m])) lb = m;
            else ub = m;
        }
        return ub;
    }

    int upper_bound(vector<int>& t) {
        t.back()++;
        int i = lower_bound(t);
        t.back()--;
        return i;
    }
};

