vector <int> build_zfunction(vector <int> &s){
	vector <int> z(s.size(),0);
	z[0]=(int)s.size();
	int j=1;
	for(int i=1;i<(int)s.size();i++){
		int u=max(0,min(j+z[j]-i,z[i-j]));
		while(s[u]==s[i+u]) u++;
		z[i]=u;
		if(i+z[i]>=j+z[j]) j=i;
	}
	return z;
}

