template <class T> vector<int> matc(const vector<T> &a, const vector<T> &b) {
    vector<int> r, p(b.size(), -1);
    int j;
    lp(i, 1, int(b.size() - 1)) {
        j = p[i - 1];
        for (; j != -1 && b[j + 1] != b[i]; j = p[j])
            ;
        p[i] = j + (b[j + 1] == b[i]);
    }
    j = -1;
    lv(i, a) {
        for (; j != -1 && b[j + 1] != a[i]; j = p[j])
            ;
        j += (b[j + 1] == a[i]);
        if (j + 1 == b.size()) {
            r.push_back(i - j);
            j = p[j];
        }
    }
    return r;
}
