  rep(i, N) A[i] *= 2;
  rep(i, N) B[i] *= 2;
  vector<ll> C(N), D(2 * N);
  rep(i, N){
    C[i] = A[i] ^ A[(i+1)%N];
    D[i] = B[i] ^ B[(i+1)%N];
  }
  rep(i, N){
    D[i+N] = D[i];
  }
  RollingHash RA;
  RollingHash RB;
  RA.getS(C);
  ll hash = RA.getHash(0, N);
  RB.getS(D);
  revrep(i, N){
    if(hash == RB.getHash(i, i+N)){
      cout << N - i << " " << ((A[0] / 2) ^ (B[i] / 2)) << endl;
    }
  }

}


