  Solver(LL n) : n(n), a(n), b(n){};

  void solve() {
    for (int i = 0; i < n; ++i) {
      cin >> a[i];
    }
    for (int i = 0; i < n; ++i) {
      cin >> b[i];
    }
    random_device rand;
    mt19937 mt(rand());
    uniform_int_distribution<LL> dist(1, 1e7);
    LL base[2] = {dist(mt), dist(mt)}, p[2] = {MOD, MOD + 2};
    vector<vector<vector<LL>>> hash(30, vector<vector<LL>>(n, vector<LL>(2)));
    for (int i = 0; i < 30; ++i) {
      vector<int> abit;
      for (int j = 0; j < n; ++j) {
        abit.push_back((a[j] >> i) & 1);
      }
      auto ahash = get_hash(abit, base, p);
      hash[i][0] = ahash;
      for (int j = 1; j < n; ++j) {
        auto tmp = hash[i][j - 1];
        for (int h = 0; h < 2; ++h) {
          tmp[h] -= abit[j - 1] * modpow(base[h], n - 1, p[h]);
          tmp[h] = (tmp[h] + p[h]) % p[h];
          tmp[h] = tmp[h] * base[h] % p[h];
          tmp[h] = (tmp[h] + abit[j - 1]) % p[h];
        }
        hash[i][j] = tmp;
      }
    }
    vector<vector<vector<LL>>> bhash(30, vector<vector<LL>>(2, vector<LL>(2)));
    for (int i = 0; i < 30; ++i) {
      vector<int> bbit, bnegbit;
      for (int j = 0; j < n; ++j) {
        bbit.push_back((b[j] >> i) & 1);
        bnegbit.push_back(1 - ((b[j] >> i) & 1));
      }
      bhash[i][0] = get_hash(bbit, base, p);
      bhash[i][1] = get_hash(bnegbit, base, p);
    }
    vector<LL> ans(n);
    for (int i = 0; i < 30; ++i) {
      for (int j = 0; j < n; ++j) {
        if (hash[i][j] == bhash[i][1]) {
          ans[j] += (1 << i);
        } else if (hash[i][j] == bhash[i][0]) {
        } else {
          ans[j] = -LINF;
        }
      }
    }
    for (int i = 0; i < n; ++i) {
      if (ans[i] >= 0) {
        cout << i << " " << ans[i] << endl;
      }
    }
  }
  long long modpow(long long a, long long n, long long mod = MOD) {
    long long i = 1, ret = 1, p = a;
    while (i <= n) {
      if (i & n) ret = (ret * p) % mod;
      i = (i << 1);
      p = (p * p) % mod;
    }
    return ret;
  }
  vector<LL> get_hash(vector<int> &a, LL b[], LL p[]) {
    vector<LL> ret{0ll, 0ll};
    for (int i = 0; i < n; ++i) {
      for (int j = 0; j < 2; ++j) {
        ret[j] = (ret[j] * b[j] + a[i]) % p[j];
      }
    }
    return ret;
  }
};  // namespace Problem

