class KMP
{
public:
    vector<long long> pattern;
    long long plen;
    vector<long long> table;
    KMP(const vector<long long>& s) : pattern(s), plen((long long)pattern.size()), table(plen+1){
        table[0] = -1;
        long long j = -1;
        for(long long i = 0; i < plen; i++){
            while(j >= 0 && pattern[i] != pattern[j]) j = table[j];
            if(pattern[i+1] == pattern[++j]) table[i+1] = table[j];
            else table[i+1] = j;
        }
    }
    void search(const vector<long long>& text, vector<long long>& res){
        long long head = 0, j = 0, tlen = (long long)text.size();
        while(head + j < tlen){
            if(pattern[j] == text[head + j]){
                if(++j != plen) continue;
                res.push_back(head);
            }
            head += j - table[j], j = max(table[j], (long long)0);
        }
    }
};

