    for(i=0; i<N-1; i++){
        AA.push_back(a[i]^a[i+1]);
    }
    AA.push_back(a[N-1]^a[0]);
    for(i=0; i<N-1; i++){
        AA.push_back(a[i]^a[i+1]);
    }
    AA.push_back(a[N-1]^a[0]);
    for(i=0; i<N-1; i++){
        BB.push_back(b[i]^b[i+1]);
    }
    KMP BBBB(BB);
    vector<long long> adj;
    BBBB.search(AA,adj);
    for(i=0; i<adj.size(); i++){
        if(adj[i]>=N) break;
        cout << adj[i] << " " << (a[adj[i]]^b[0]) << endl;
    }
    system("pause");
    return 0;
}

