template<class T> string out_m2(vector<T> &a, ll W = inf) {
    stringstream ss;
    if (W == inf)W = min(sz(a), 12ll);
    if (sz(a) == 0)return ss.str();
    rep(i, W) {
        ss << a[i];
        if (typeid(a[i]) == typeid(P)) {
            ss << endl;
        } else {
            ss << " ";
        }
    }
    return ss.str();
}
