typedef long long ll;

int table[200005];
bool ans[200005];

void pre_kmp(vector<ll> b, int n) {
  table[0] = -1;
  for(int i = 1; i <= n; i++) {
    int k = table[i-1];

    while(k >= 0) {
      if(b[k] == b[i-1]) break;
      else k = table[k];
    }
    table[i] = 1 + k;
  }
}

void kmp(vector<ll> a, vector<ll> b, int n) {
  int m = b.size();

  for(int i = 0, k = 0; i < 2 * n; i++) {
    while(k >= 0 && a[i] != b[k]) {
      k = table[k];
    }
    if(++k == m) {
      ans[i-m+1] = true;
      k = table[k];
    }
  }
}

int main() {
  int n;
  cin >> n;
  vector<ll> a(n);
  vector<ll> b(n);

  for(int i = 0; i < n; i++) cin >> a[i];
  for(int i = 0; i < n; i++) cin >> b[i];

  vector<ll> A(2*n);
  vector<ll> B(n);

  for(int i = 0; i < n; i++) {
    if(i == n-1) {
      A[i] = a[0] ^ a[i];
      A[i+n] = A[i];
    }
    else {
      A[i] = a[i] ^ a[i+1];
      A[i+n] = A[i];
    }
  }
  for(int i = 0; i < n; i++) {
    if(i == n-1) {
      B[i] = b[0] ^ b[i];
    }
    else B[i] = b[i] ^ b[i+1];
  }
  //  for(int i = 0; i < 2*n; i++) cout << A[i] << endl;

  pre_kmp(B,n);
  kmp(A,B,n);
  // for(int i = 0; i < n; i++) cout << ans[i] << endl;

  for(int i = 0; i < n; i++) {
    if(ans[i]) {
      cout << i <<' '<< (a[i] ^ b[0]) << endl;
    }
  }
}

