template<typename VEC>
void make_z(const VEC& s, vector<ll>& z) { 
    const ll n = s.size(); 
    ll L = 0, R = 0; 
    for (int i = 1; i < n; ++i) {
        if (i > R) { 
            L = R = i; 
            while (R < n && s[R-L] == s[R]){
                R++;
            }
            z[i] = R-L; 
            R--; 
        }else{  // i <= R
            const ll k = i-L; 
            if (z[k] < R-i+1){
                z[i] = z[k]; 
            }else{
                L = i; 
                while (R<n && s[R-L] == s[R]){
                    R++;
                }
                z[i] = R-L; 
                R--; 
            }
        } 
    } 
} 

