void solve(long long N, std::vector<long long> a, std::vector<long long> b){
    vector<ll> a2(N), b2(N);
    REP(i, N){
        a2.at(i) = a.at(i) ^ a.at((i + 1) % N);
        b2.at(i) = b.at(i) ^ b.at((i + 1) % N);
    }

    // z-search
    vector<ll> concat;
    concat.reserve(3 * N + 1);
    copy(b2.begin(), b2.end(), back_inserter(concat));
    concat.push_back(-1);
    copy(a2.begin(), a2.end(), back_inserter(concat));
    copy(a2.begin(), a2.end(), back_inserter(concat));
    vector<ll> z(concat.size());
    make_z(concat, z);

    vector<ll> tmp;
    for(ll i = N + 1; i < concat.size(); ++i){
        if(z.at(i) == b2.size()){
            const ll j = i - b2.size() - 1;
            if(j < N){
                tmp.push_back(j);
            }
        }
    }

    for(ll k : tmp){
        cout << k << ' ' << (a.at(k) ^ b.at(0)) << endl;
    }
}

