template<typename T,T MOD,T B>
struct RollingHash{
  using ll = long long;
  vector<T> hash,bpow;  // 1-index
  RollingHash(){}
  RollingHash(vector<T> vs){init(vs);}
  RollingHash(string &s){
    vector<T> vs;
    for(char c:s) vs.emplace_back(c);
    init(vs);
  }
  void init(vector<T> vs){
    int n=vs.size();
    hash.assign(n+1,0);
    bpow.assign(n+1,1);
    for(int i=0;i<n;i++){
      hash[i+1]=((ll)hash[i]*B+vs[i])%MOD;
      bpow[i+1]=(ll)bpow[i]*B%MOD;
    }
  }
  //S[l, r)
  T find(int l,int r){
    T res=(ll)hash[r]+MOD-(ll)hash[l]*bpow[r-l]%MOD;
    return res>=MOD?res-MOD:res;
  }
};

