    cin >> N;
    vector<int> a(2 * N), b(N);
    for (int i = 0; i < N; ++i)
        cin >> a[i], a[i + N] = a[i];
    for (int i = 0; i < N; ++i)
        cin >> b[i];

    RollingHash rhs(a);
    rhs.solve(a, b);

    return 0;
}

