using namespace std;
typedef long long ll;

template <typename T, ll mod>
class RollingHash {
   private:
    struct mPair {
        ll v0, v1;
        mPair operator*(const mPair &p) { return mPair{(v0 * p.v0) % mod, (v1 * p.v1) % mod}; }
        mPair operator+(const mPair &p) { return mPair{(v0 + p.v0) % mod, (v1 + p.v1) % mod}; }
        mPair operator-(const mPair &p) {
            return mPair{(v0 + mod - p.v0) % mod, (v1 + mod - p.v1) % mod};
        }
        mPair operator*(const ll &x) { return mPair{(v0 * x) % mod, (v1 * x) % mod}; }
        mPair operator+(const ll &x) { return mPair{(v0 + x) % mod, (v1 + x) % mod}; }
        mPair operator*(const pair<int, int> &p) {
            return mPair{(v0 * p.first) % mod, (v1 * p.second) % mod};
        }
        mPair operator+(const pair<int, int> &p) {
            return mPair{(v0 + p.first) % mod, (v1 + p.second) % mod};
        }
        pair<int, int> to_pair() { return make_pair(v0, v1); }
    };
    vector<mPair> hash, bpow;
    const mPair base = {1069, 10007};

   public:
    const int len;
    // O(|S|)
    RollingHash(T &s) : len(s.size()) {
        hash.assign(len + 1, {0, 0});
        bpow.assign(len + 1, {0, 0});
        bpow[0] = {1, 1};
        for (int i = 0; i < len; i++) {
            hash[i + 1] = hash[i] * base + s[i];
            bpow[i + 1] = bpow[i] * base;
        }
    }

    // 文字列[l,r)のハッシュ値を返す O(1)
    pair<int, int> get(int l, int r) { return (hash[r] - hash[l] * bpow[r - l]).to_pair(); }
    pair<int, int> get() { return get(0, len); }

    // h1 + h2(ハッシュ値h1とハッシュ値h2の結合) O(1)
    pair<int, int> connect(pair<int, int> h1, pair<int, int> h2, int len_h2) {
        return (bpow[len_h2] * h1 + h2).to_pair();
    }

    // [l1,r1)の文字列とbの[l2,r2)の文字列の最長共通接頭辞の長さを返す O(log(min(|S1|,|S2|)))
    int LCP(RollingHash &b, int l1, int r1, int l2, int r2) {
        int ok = -1, ng = min(r1 - l1, r2 - l2) + 1;
        while (abs(ok - ng) > 1) {
            int mid = (ok + ng) / 2;
            if (get(l1, l1 + mid) == b.get(l2, l2 + mid))
                ok = mid;
            else
                ng = mid;
        }
        return ok;
    }
};
