    vector<int> ret;
    u64 t = 1;
    u64 sh = 0, kh = 0;
    rep(i, n) {
        t *= m;
        sh = sh * m + s[i];
        kh = kh * m + key[i];
    }
    rep(i, n) {
        if(kh == sh) ret.push_back(i);
        sh = sh * m + s[i] - s[i] * t;
    }
    return ret;
}

