using namespace std;

bool center3(const pair<long double, long double>& p1,
             const pair<long double, long double>& p2,
             const pair<long double, long double>& p3,
             pair<long double, long double>& center,
             long double& r2) {
  auto ax = (p1.first + p2.first) / 2;
  auto ay = (p1.second + p2.second) / 2;

  auto ux = (p1.second - p2.second);

  auto uy = (p2.first - p1.first);

  auto bx = (p2.first + p3.first) / 2;
  auto by = (p2.second + p3.second) / 2;

  auto vx = (p2.second - p3.second);
  auto vy = (p3.first - p2.first);
  auto dx = ax - bx;
  auto dy = ay - by;
  auto vu = vx * uy - vy * ux;
  if (!vu)
    return false;
  auto g = (dx * uy - dy * ux) / vu;
  center = {
      bx + g * vx,
      by + g * vy,
  };
  auto ddx = p1.first - center.first;
  auto ddy = p1.second - center.second;
  r2 = ddx * ddx + ddy * ddy;
  return true;
}

vector<pair<long double, long double>> points;

bool contains_all(const pair<long double, long double>& c, long double r2) {
  for (auto&& p : points) {
    auto dx = p.first - c.first;
    auto dy = p.second - c.second;
    if (r2 < dx * dx + dy * dy) {
      return false;
    }
  }
  return true;
}

void solve() {
  int n;
  cin >> n;
  points.reserve(n);
  for (int i = 0; i < n; ++i) {
    int x, y;
    cin >> x >> y;
    points.emplace_back(x, y);
  }
  long double min_r2 = (long double)INT_MAX;

  for (size_t i = 0; i + 1 < points.size(); ++i) {
    for (size_t j = i + 1; j < points.size(); ++j) {
      auto cx = (points[i].first + points[j].first) / 2.;
      auto cy = (points[i].second + points[j].second) / 2.;
      auto dx = points[i].first - cx;
      auto dy = points[i].second - cy;
      auto r2 = dx * dx + dy * dy;
      if (0 <= r2 && r2 < min_r2 && contains_all({cx, cy}, r2)) {
        min_r2 = r2;
      }
    }
  }

  for (size_t i = 0; i + 2 < points.size(); ++i) {
    for (size_t j = i + 1; j + 1 < points.size(); ++j) {
      for (size_t k = j + 1; k < points.size(); ++k) {
        pair<long double, long double> c;
        long double r2;
        if (center3(points[i], points[j], points[k], c, r2) && 0 <= r2 &&
            r2 < min_r2 && contains_all(c, r2)) {
          min_r2 = r2;
        }
      }
    }
  }

  cout << setprecision(15) << sqrt(min_r2) << endl;
}

