    hh.hs.resize(K);
    for(int j = 0 ; j < K ; j++)
    {
        for(int i = 0 ; i < N ; i++)hh.hs[j] = (hh.hs[j]*random_hash.bas[j]+s[i])%random_hash.mod[j];
    }
