        if(a > b)swap(a,b);
        assert(a >= 0 && b < N);
        HASH tp;
        for(int j = 0 ; j < K ; j++)
        {
            tp.hs.push_back((H[b+1][j]+random_hash.mod[j]-H[a][j]*hash_powers.P[b-a+1][j]%random_hash.mod[j])%random_hash.mod[j]);
        }
        return tp;
