bool period(const V<ll> &xlist, ll div)
{
    ll n = xlist.size();

    rep (base, div) {
        rep (i, n / div) {
            if (xlist[base] != xlist[base+i*div]) return false;
        }
    }

    return true;
}

bool same(const V<ll> &clist, const V<ll> &dlist, ll div, ll shift)
{
    rep (i, div) {
        ll j = (i + shift) % div;
        if (clist[i] != dlist[j]) return false;
    }
    return true;
}

