constexpr ll base1 = 2, mod1 = 1000000007, mod2 = 1000000009;
struct RollingHash {
    vector<ll> hash1, hash2, pow1, pow2;
    RollingHash (vector<long long> v) {
        long long length = v.size();
        hash1.assign(length + 1, 0);
        hash2.assign(length + 1, 0);
        pow1.assign(length + 1, 1);
        pow2.assign(length + 1, 1);
        rep(i, length) {
            hash1[i + 1] = (hash1[i] * base1 + v[i]) % mod1;
            hash2[i + 1] = (hash2[i] * base1 + v[i]) % mod2;
            pow1[i + 1] = pow1[i] * base1 % mod1;
            pow2[i + 1] = pow2[i] * base1 % mod2;
        }
    }
    pair<ll, ll> get(long long l, long long r) const {
        ll res1 = hash1[r] - hash1[l] * pow1[r - l] % mod1;
        if (res1 < 0) res1 += mod1;
        ll res2 = hash2[r] - hash2[l] * pow2[r - l] % mod2;
        if (res2 < 0) res2 += mod2;
        return pair<ll, ll>{res1, res2};
    }
};


