/*!* [z_alg] *!*/
/*+* Zアルゴリズム
    最長共通接頭辞をO(N)で求める
    S : typename | コンテナの型
    str : S | 検索する列
    z_array : vector<int> | 結果（入力時は空のまま）
*+*/

template<typename S>
void ZAlgorithm(S str, vector<int> &z_array) {
    int n = str.size();
    int L = 0, R = 0;
    z_array.push_back(-1);
    for(int i = 1; i < n; i++) {
        if(i > R) {
            L = R = i;
            while(R < n && str[R - L] == str[R]) R++;
            z_array.push_back(R - L);
            R--;
        } else {
            int j = i - L;
            if(z_array[j] < R - i + 1) {
                z_array.push_back(z_array[j]);
            } else {
                L = i;
                while(R < n && str[R - L] == str[R]) R++;
                z_array.push_back(R - L);
                R--;
            }
        }
    }
}

// 方針: xor差分の一致部分を探す，初期位置でのxorをxとする．
int main() {
    int N;
    cin >> N;
    vector<int> A(N), B(N), A_diff(N), B_diff(N);
    for(int &a : A) cin >> a;
    for(int &b : B) cin >> b;
    for(int i = 0; i < N; i++) {
        A_diff[i] = A[i] ^ A[(i + 1) % N];
        B_diff[i] = B[i] ^ B[(i + 1) % N];
    }
    vector<int> s, result;
    for(int a : A_diff) s.push_back(a);
    s.push_back(1 << 30);
    for(int i = 0; i < 2; i++) for(int b : B_diff) s.push_back(b);
    ZAlgorithm(s, result);
    vector<pair<int, int>> ans;
    for(int j = 0; j < N; j++) {
        if(result[N + 1 + j] >= N) {
            // $k \equiv j \mod N$
            int k = (N - j) % N;
            int x = A[0] ^ B[j];
            ans.push_back({k, x});
        }
    }
    for(auto a : ans) {
        cout << a.first << " " << a.second << endl;
    }
    return 0;
}

