/*!* [z_alg] *!*/
/*+* Zアルゴリズム
    最長共通接頭辞をO(N)で求める
    S : typename | コンテナの型
    str : S | 検索する列
    z_array : vector<int> | 結果（入力時は空のまま）
*+*/

template<typename S>
void ZAlgorithm(S str, vector<int> &z_array) {
    int n = str.size();
    int L = 0, R = 0;
    z_array.push_back(-1);
    for(int i = 1; i < n; i++) {
        if(i > R) {
            L = R = i;
            while(R < n && str[R - L] == str[R]) R++;
            z_array.push_back(R - L);
            R--;
        } else {
            int j = i - L;
            if(z_array[j] < R - i + 1) {
                z_array.push_back(z_array[j]);
            } else {
                L = i;
                while(R < n && str[R - L] == str[R]) R++;
                z_array.push_back(R - L);
                R--;
            }
        }
    }
}

