        c[i] = a[i] ^ a[i+1];
        d[i] = b[i] ^ b[i+1];
      }
      c[n-1] = a[0] ^ a[n-1];
      d[n-1] = b[0] ^ b[n-1];

      vector<int> e(3*n);
      rep(i, n) {
        e[i] = c[i];
        e[n+i] = d[i];
        e[2*n+i] = d[i];
      }

      vector<int> f(3*n);
      Zalgorithm(f, e);

      vector<P> ans;

      rep(i, n) {
        if (f[n+i] >= n) {
          int x = a[0] ^ b[i];
          ans.emplace_back((n-i)%n, x);
        }
      }

      sort(all(ans));

      for(auto e : ans) {
        cout << e.first << ' ' << e.second << '\n';
      }
    }
};

