	vector<int> a(n), b(n);
	inc(i, n) { cin >> a[i]; }
	inc(i, n) { cin >> b[i]; }

	auto RA   = rotation_array(a);
	auto RLCP = rotation_lcp_array(a, RA);

	vector<pair<int, int>> ans;
	int s = 0;
	dec(i, n) {
		setmin(s, RLCP[i]);
		int x = a[RA[i]] ^ b[0];
		incID(j, s, n) {
			if((a[mo(j + RA[i], n)] ^ b[j]) == x) { setmax(s, j + 1); } else { break; }
		}
		if(s == n) { ans.EB(RA[i], x); }
	}
	sort(ALL(ans));

	RF(e, ans) { cout << e.FI << " " << e.SE << "\n"; }

	return 0;
}

