				z[i]++;
			}
			x = i, y = i + z[i] - 1;
		}
		else if(i + z[i-x] <= y) z[i] = z[i-x];
		else{
			z[i] = y-i+1;
			for(int j = y-i+1; j < s.size(); j++){
				if(i+j > s.size() || s[i+j] != s[j]) break;
				z[i]++;
			}
			x = i, y = i + z[i] - 1;
		}
	}
}

int main(void)
{
	ios::sync_with_stdio(0);
	cin.tie(0);

	cin >> n;
	for(int i = 0; i < n; i++) cin >> a[i];
	for(int i = 0; i < n; i++) cin >> b[i];

	for(int i = 0; i < n; i++){
		da[i] = a[i] ^ a[(i+1)%n];
		db[i] = b[i] ^ b[(i+1)%n];
	}
	for(int i = 0; i < n; i++) vec.push_back(db[i]);
	vec.push_back(-1);
	for(int i = 0; i < n; i++) vec.push_back(da[i]);
	for(int i = 0; i < n; i++) vec.push_back(da[i]);

	z_algorithm(vec, z);

	for(int i = n+1; i <= 2*n; i++){
		if(z[i] >= n){
			cout << i-(n+1) << " " << (a[i-(n+1)]^b[0]) << endl;
		}
	}

	return 0;
}

