#define REP(i,n) for (ll i = 0; i < n; ++i)
#define REPR(i,n) for (ll i = n-1; i >= 0; --i)
#define FOR(i,m,n) for (ll i = m; i < n; ++i)
#define FORR(i,m,n) for (ll i = n-1; i >= m; --i)
#define FORE(x,xs) for (const auto& x : xs)
#define ALL(v) v.begin(), v.end()

const int MAX = 2e5+10;
const int BITS = 31;

vi createTable(const vi& word) {
    int n = word.size();
    vi table(n+1);
    table[0] = -1;
    int j = -1;
    REP (i, n) {
        while (j >= 0 && word[i] != word[j]) j = table[j];
        table[i+1] = ++j;
    }
    return table;
}

vi kmp(const vi& str, const vi& word) {
    vi table = createTable(word), ret;
    int m = 0, i = 0, n = str.size();
    while (m+i < n) {
        if (word[i] == str[m+i]) {
            if (++i == (int)(word.size())) {
                ret.push_back(m);
                m = m+i-table[i];
                i = table[i];
            }
        } else {
            m = m + i - table[i];
            if (i > 0) i = table[i];
        }
    }
    return ret;
}

int N;
int A[MAX], B[MAX];

vi sub(int bit) {
    vi a(N), a_not(N), b(2*N-1);
    REP (i, N) {
        int n = (A[i] >> bit) & 1;
        a[i] = n;
        a_not[i] = (1^n);
    }
    REP (i, N-1) b[i] = b[i+N] = ((B[i] >> bit) & 1);
    b[N-1] = ((B[N-1] >> bit) & 1);

    vi ret;
    FORE (idx, kmp(b, a)) ret.push_back(idx);
    FORE (idx, kmp(b, a_not)) ret.push_back(idx);
    return ret;
}

vii solve() {
    map<int, int> shift_count;
    REP (bit, BITS) {
        FORE (s, sub(bit)) shift_count[s]++;
    }

    vii ret;
    for (auto iter = shift_count.begin(); iter != shift_count.end(); iter++) {
        int shift = iter->first;
        if (iter->second != BITS) continue;
        ret.push_back(make_pair((N-shift)%N, A[0] ^ B[shift]));
    }
    sort(ALL(ret));
    return ret;
}

int main() {
    cin >> N;
    REP (i, N) cin >> A[i];
    REP (i, N) cin >> B[i];
    FORE (x, solve()) cout << x.first << " " << x.second << endl;
}

