using ulong = unsigned long long;

const ulong MASK30 = (1ull << 30) - 1;
const ulong MASK31 = (1ull << 31) - 1;
const ulong MOD = (1ull << 61) - 1;
const ulong POSITIVIZER = MOD * 3;

ulong mul(ulong a, ulong b) {
    ulong au = a >> 31;
    ulong ad = a & MASK31;
    ulong bu = b >> 31;
    ulong bd = b & MASK31;
    ulong mid = ad * bu + au * bd;
    ulong midu = mid >> 30;
    ulong midd = mid & MASK30;
    return au * bu * 2 + midu + (midd << 31) + ad * bd;
}

ulong calc_mod(ulong val) {
    val = (val & MOD) + (val >> 61);
    if (val > MOD) val -= MOD;
    return val;
}

ulong power(ulong base, int N) {
  ulong res = 1;
  for (int i = 0; i < N; i++) res = calc_mod(mul(res, base));
  return res;
}

ulong calc_hash(const vector<int>& a, ulong base) {
  ulong hash = 0;
  for (int x : a) {
    hash = calc_mod(mul(hash, base) + x);
  }
  return hash;
}

