    for (int i = 0; i < N; i++) b2[i] = (b[i] ^ b[(i + 1) % N]) + 1;
    ulong base = 1e9 + 7;
    ulong pw = power(base, N);
    ulong hash = calc_hash(a2, base), target = calc_hash(b2, base);
    for (int k = 0; k < N; k++) {
      if (hash == target) {
        cout << k << " " << (a[k] ^ b[0]) << endl;
      }
      hash = calc_mod(mul(hash, base));
      hash = calc_mod(hash + POSITIVIZER - mul(pw, a2[k]));
      hash = calc_mod(hash + a2[k]);
    }
  }
  return 0;
}

