vec kmp_table(string W) {
    ll i = 2, j = 0;
    vec T(W.size(), -1);
    T[1] = 0;

    while (i < W.size()) {
        if (W[i-1] == W[j]) {
            T[i] = j+1;
            i++;
            j++;
        } else if (j > 0) j = T[j];
        else {
            T[i] = 0;
            i++;
        }
    }

    return T;
}

vec kmp_search (string S, string W, vec T) {
    vec ret;
    ll m = 0, i = 0;
    while (m+i < S.size()) {
        if (W[i] == S[m+i]) {
            i++;
            if (i == W.size()) {
                if (m % 32 == 0) ret.push_back(m/32);
                i--;
                m = m+i-T[i];
                i = T[i];
            }
        } else {
            m = m+i-T[i];
            if (i > 0) i = T[i];
        }
    } 
    return ret;
}

