using namespace std;

class Solution {
public:
    vector<pair<int,int>> solve(vector<int>&A, vector<int>& B) {
        int n = A.size();
        int MX = 0;
        for (int i = 0; i < n; ++i) {
            MX = max(MX, A[i]);
            MX = max(MX, B[i]);
        }
        int m = 0;
        while (1LL << (m + 1) <= MX) {
            ++m;
        }


        auto search = [&](string S, string& T) {
            vector<int> res;
            int n = S.length();
            S += S;
            // cout << S << " " << T << endl;
            int m = T.length();
            vector<int> next(m + 1, -1);
            for (int i = 0, j = -1; i < m; ++i) {
                while (j != -1 && T[j] != T[i]) {
                    j = next[j];
                }
                next[i + 1] = ++j;
            }

            for (int i = 0, j = 0; i < S.length(); ++i) {
                if (S[i] == T[j]) {
                    if (++j == m) {
                        int beg = i - m + 1;
                        if (beg < n) {
                            res.push_back(beg);
                        }
                        j = next[j];
                    }
                } else {
                    while (j != -1 && T[j] != S[i]) {
                        j = next[j];
                    }
                    if (j == -1) {
                        j = 0;
                    } else {
                        --i;
                    }
                }
            }
            return res;
        };

        vector<vector<int>> ok(n, vector<int>(m + 1, 0));

        string S(n, '0');
        string T(n, '0');
        for (int b = 0; b <= m; ++b) {
            for (int i = 0; i < n; ++i) {
                T[i] = '0' + ((B[i] >> b) & 1);
            }
            for (int j = 0; j < 2; ++j) {
                for (int i = 0; i < n; ++i) {
                    S[i] = '0' + (((A[i] >> b) & 0x1) ^ j);
                }
                auto P = search(S, T);
                for (auto p : P) {
                    ok[p][b] |= 1 << j;
                    // cout << p << " " << b << " " << j << endl;
                }
            }
        }

        vector<pair<int,int>> res;
        for (int i = 0; i < n; ++i) {
            int p = 1;
            for (int j = 0; j <= m; ++j) {
                p *= ok[i][j];
            }
            if (p == 0) {
                continue;
            }
            vector<int> cur;
            vector<int> nxt;
            cur.push_back(0);
            for (int j = 0; j <= m; ++j) {
                nxt.clear();
                int X = ok[i][j];
                for (auto x : cur) {
                    if (X & 0x1) {
                        nxt.push_back(x);
                    } 
                    if (X & 0x2) {
                        nxt.push_back(x | (1 << j));
                    }
                }
                swap(nxt, cur);
            }
            for (auto x : cur) {
                res.emplace_back(i, x);
            }
        }
        sort(res.begin(), res.end());
        return res;
    } 
};

int main(int argc, char** argv) {
    ios::sync_with_stdio(false);
    cin.tie(0);

    int n;
    cin >> n; 
    vector<int> A(n);
    vector<int> B(n);
    for (int i = 0; i < n; ++i) {
        cin >> A[i];
    }
    for (int i = 0; i < n; ++i) {
        cin >> B[i];
    }
    Solution sol;

    auto res = sol.solve(A, B);
    for (auto& p : res) {
        cout << p.first << " " << p.second << "\n";
    }

    return 0;
}

