    na(B,N);
    if(all_of(A,==A[0]) && all_of(B,==B[0])){
        rep(i, N){
            out(i,A[0]^B[0]);
        }
        return;
    }

    vi callr(N);
    vi resr(N);

    auto DS = bget2(B,31);

    rep(b, 31) {
        fast_rolling_hash rb(DS[b].begin(), DS[b].end(), 5ULL);
//        bhash(db.begin(), db.end(), 5ULL);

        auto hb = rb(0, N);
        rep(x, 2) {
            vi C = bget1(A,b);
            C*=2;
            for_each(C,^=x);
            fast_rolling_hash ra(C.begin(), C.end(), 5ULL);
//            roll ra(C);
            rep(r, N) {
                if (ra(r, r + N) == hb) {
                    callr[r]++;
                    resr[r] += bit(b) * x;
                }
            }
        }
    }
    rep(r, N) {
        if (callr[r] == 31) {
            out(r, A[r] ^ B[0]);
        }
    }
