bool period(const V<ll> &xlist, ll div)
{
    ll n = xlist.size();

    rep (base, div) {
        rep (i, n / div) {
            if (xlist[base] != xlist[base+i*div]) return false;
        }
    }

    return true;
}

bool same(const V<ll> &clist, const V<ll> &dlist, ll div, ll shift)
{
    rep (i, div) {
        ll j = (i + shift) % div;
        if (clist[i] != dlist[j]) return false;
    }
    return true;
}

void _main();
int main()
{
    cout << setprecision(12);
    _main();
    return 0;
}

void _main()
{
    ll n; llin(n);
    V<ll> alist; llina(alist, n);
    V<ll> blist; llina(blist, n);

    V<ll> clist;
    rep (i, n) {
        ll i0 = i;
        ll i1 = (i + 1) % n;
        clist.pb(alist[i0] ^ alist[i1]);
    }

    V<ll> dlist;
    rep (i, n) {
        ll i0 = i;
        ll i1 = (i + 1) % n;
        dlist.pb(blist[i0] ^ blist[i1]);
    }

    V<ll> divs;
    get_divisors(divs, n);
    set<t2> anslist;

    for (auto div : divs) {
        bool flag = period(clist, div);
        if (!flag) continue;
        rep (shift, div) {
            bool flag2 = same(clist, dlist, div, shift);
            if (flag2) {
                ll shift2 = (n-shift) % n;
                anslist.insert(t2(shift2, alist[shift2] ^ blist[0]));
            }
        }
    }

    for (auto ans : anslist) {
        printf("%lld %lld\n", get<0>(ans), get<1>(ans));
    }
}

