		cin >> b[i];
	}
	string bs[30], revbs[30];
	for(int bit = 0; bit < 30; ++bit) {
		rep(i, n) {
			bs[bit] += ((b[i] >> bit) & 1 ? '1' : '0');
			revbs[bit] += ((b[i] >> bit) & 1 ? '0' : '1');
		}
	}
	string as[30];
	for(int bit = 0; bit < 30; ++bit) {
		rep(i, n) {
			as[bit] += ((a[i] >> bit) & 1 ? '1' : '0');
		}
		as[bit] += as[bit];
	}
	vector<vector<int>> vec(n, vector<int>(30, -1));
	for(int bit = 0; bit < 30; ++bit) {
		RollingHash rha(as[bit]);
		RollingHash rhb(bs[bit]);
		RollingHash rhr(revbs[bit]);
		rep(i, n) {
			if(rha.get(i, i + n) == rhb.get(0, n)) {
				vec[i][bit] = 0;
			}
			if(rha.get(i, i + n) == rhr.get(0, n)) {
				vec[i][bit] = 1;
			}
		}
	}
	rep(i, n) {
