vector<int> f(vector<int> const &A)
{
  int N(A.size());
  vector<int> res(N);
  for (auto i = 0; i < N; i++)
  {
    res[i] = A[i] ^ A[(i + 1) % N];
  }
  return res;
}

int main()
{
  int N;
  cin >> N;
  vector<int> A(N), B(N);
  for (auto i = 0; i < N; i++)
  {
    cin >> A[i];
  }
  for (auto i = 0; i < N; i++)
  {
    cin >> B[i];
  }
  vector<int> xa{f(A)}, xb{f(B)};
  MP<vector<int>> mp(xa);
  xb.insert(xb.end(), xb.begin(), xb.end());
  auto res{mp.find_all(xb)};
  vector<int> ks;
  for (int p : res)
  {
    ks.push_back(N - p);
  }
  sort(ks.begin(), ks.end());
  for (int k : ks)
  {
    if (k >= N)
    {
      continue;
    }
    int x = A[k] ^ B[0];
    cout << k << " " << x << endl;
  }
}

