inline int add(int a, int b, int &mod) { int res = a + b;        return res > mod ? res - mod : res; }
inline int sub(int a, int b, int &mod) { int res = a - b;        return res < 0 ? res + mod : res; }
inline int mul(int a, int b, int &mod) { int res = (1LL * a * b) % mod;   return res; }

class hash_it {
public:
	static int cnt;
	int len, d; vector<pii> hashes;
	inline int get(int x) {   return x;    } // check  it( x-'a'+1)

	void init(int *s, int d1, int l)
	{
		len = l; d = d1;
		hashes.resize(len + 1);
		for (int i = 0, val1 = 0, val2 = 0; i < len; i++)
		{
			val1 = add(val1, mul( get(s[i]), p_pwr[i].ff, mod1), mod1);       hashes[i].ff = val1;
			if (d) val2 = add(val2, mul( get(s[i]), p_pwr[i].ss, mod2), mod2);         hashes[i].ss = val2;
		}
	}

	pii  get(int i,  int j)
	{
		pii v1 = {0, 0};
		v1.ff = mul( sub(hashes[j].ff, (i ? hashes[i - 1].ff : 0), mod1), p_pwr[0].ff, mod1);
		if (d)v1.ss = mul( sub(hashes[j].ss, (i ? hashes[i - 1].ss : 0), mod2), p_pwr[0].ss, mod2);
		return v1;
	}
};


