void inline z_init(string &s, vector<int> &z) {
	int len = (int) s.size();
	z = vector<int>(len, 0);
	for (int i = 1, l = 0, r = 0; i < len; ++i) {
		if (i <= r)  z[i] = min(r - i + 1, z[i - l]);
		for (; i + z[i] < len && s[z[i]] == s[i + z[i]]; ++z[i]);
		if (i + z[i] - 1 > r)  l = i, r = i + z[i] - 1;
	}
}

