template<typename InIt>
std::vector<usize> z_algorithm(const InIt first, const InIt last)
{
    const usize sz = std::distance(first, last);
    std::vector<usize> ans(sz, sz);
    for (usize i = 1, j = 0; i < sz;) {
        while (i + j < sz and *std::next(first, j) == *std::next(first, i + j)) { j++; }
        ans[i] = j;
        if (j == 0) {
            ++i;
            continue;
        }
        usize k = 1;
        while (i + k < sz and k + ans[k] < j) { ans[i + k] = ans[k], ++k; }
        i += k, j -= k;
    }
    return ans;
}
