		for(int i=1; i<n; i++){
			aidx++;
			bidx++;
			if(aidx >= n) aidx -= n;
			if(bidx >= n) bidx -= n;
			if((a[aidx]^b[bidx]) != x){
				ok = false;
				break;
			}
		}
		if(ok) ans.push_back(k);
		if((int)ans.size() >= 2) break;
	}
	if(ans.size() == 1){
		int x = a[ans[0]]^b[0];
		cout << ans[0] << " " << x << endl;
	}else if(ans.size() >= 2){
		int diff = ans[1] -ans[0];
		for(int k=ans[0]; k<n; k+=diff){
			int x = a[k]^b[0];
			cout << k << " " << x << endl;
		}
	}
	return 0;
}

