		h[i].resize(n);
		rev[i].resize(n);
	}
	for(int j = 0; j < 31; ++j) {
		for(int i = 0; i < n; ++i) {
			h[j][0] = h[j][0] * seed + (a[i] >> j & 1);	
			rev[j][0] = rev[j][0] * seed + ((a[i] >> j & 1) ^ 1);
		}
		for(int i = 1; i < n; ++i) {
			h[j][i] = (h[j][i - 1] - Pow[n - 1] * (a[i - 1] >> j & 1)) * seed + (a[i - 1] >> j & 1);
			rev[j][i] = (rev[j][i - 1] - Pow[n - 1] * ((a[i - 1] >> j & 1) ^ 1)) * seed + ((a[i - 1] >> j & 1) ^ 1);
		}
	}
	vector<unsigned long long> H;
	H.resize(31);
	for(int j = 0; j < 31; ++j) {
		for(int i = 0; i < n; ++i) {
