ll kmp(const vl &T, const vl &P, ll s, ll e) {
  if (P.empty())
    return 0;

  vector<ll> pi(P.size(), 0);
  for (ll i = 1, k = 0; i < P.size(); ++i) {
    while (k && P[k] != P[i])
      k = pi[k - 1];
    if (P[k] == P[i])
      ++k;
    pi[i] = k;
  }

  for (ll i = s, k = 0; i < e; ++i) {
    while (k && P[k] != T[i])
      k = pi[k - 1];
    if (P[k] == T[i])
      ++k;
    if (k == P.size())
      return i - k + 1;
  }

  return -1;
}

