struct KMP {
    vector<long long> pat;
    vector<int> fail;

    // construct
    KMP(const vector<long long> &p) { init(p); }
    void init(const vector<long long> &p) {
        pat = p;
        int m = (int)pat.size();
        fail.assign(m + 1, -1);
        for(int i = 0, j = -1; i < m; ++i) {
            while(j >= 0 && pat[i] != pat[j]) j = fail[j];
            fail[i + 1] = ++j;
        }
    }

    // the period of S[0:i]
    int period(int i) { return i - fail[i]; }

    // the index i such that S[i:] has the exact prefix p
    vector<int> match(const vector<long long> &S) {
        int n = (int)S.size(), m = (int)pat.size();
        vector<int> res;
        for(int i = 0, k = 0; i < n; ++i) {
            while(k >= 0 && S[i] != pat[k]) k = fail[k];
            ++k;
            if(k == m) res.push_back(i - m + 1);
        }
        return res;
    }
};

void solve() {
    LCIN(N);
    VL a(N), b(N);
    VECCIN(a);
    VECCIN(b);
    VL bb, aa;
    REP(i, N) bb.emplace_back(b[i] ^ b[(i + 1) % N]);
    KMP kmp(bb);
    REP(i, 2 * N) { aa.emplace_back(a[i % N] ^ a[(i + 1) % N]); }
    VL res = kmp.match(aa);
    VPL ans;
    FOREACH(idx, res) {
        if(idx >= N) continue;
        ans.emplace_back(idx, a[idx] ^ b[0]);
    }
    REP(i, sz(ans)) { COUT(ans[i].fi, ans[i].second); }
}

