vint Z_algorithm(vint &W) {
    int i = 1, j = 0;
    vint Z(W.size());
    Z[0] = W.size();
    while (i < W.size()) {
        while (i + j < W.size() && W[i + j] == W[j]) ++j;
        Z[i] = j; 
        if (j == 0) { ++i; continue; }
        int k = 1;
        while (Z[k] + k < j) Z[i + k] = Z[k], ++k;
        i += k, j -= k;
    }
    return (Z);
}
