int main(){
	cin.tie(nullptr);
	ios::sync_with_stdio(false);
	int n; cin >> n;
	vector<pair<int,ll>> ans;
	vector<ll> a(n),b(n);
	for(int i=0;i<n;i++){
		cin >> a[i];
	}
	for(int i=0;i<n;i++){
		cin >> b[i];
	}
	vector<ll> v(n);
	for(int i=0;i<n;i++){
		v[i]=(a[0]^b[(n-i)%n]);
	}
	map<ll,int> mp;
	for(int i=0;i<n;i++){
		if(mp[v[i]]==1){
			ans.push_back(make_pair(i,v[i]));
			continue;
		}
