ll t_mod(ll x,ll m){
  if(x>=0) return x%m;
  else{
    ll x2=x*(-1);
    x2/=m;
    x2+=2;
    return (x+m*x2)%m;
  }
}
vector<ll> contain(string b,string a){
  int al=a.length(),bl=b.length();

  ll t=1,t2=1,t3=1;
  for(int i=0;i<al;i++) {
    t*=B;
    t%=mod;
    t2*=B;
    t2%=mod2;
//    t3*=B;
//    t3%=mod3;
  }

  ll ah=0,bh=0,ah2=0,bh2=0,ah3=0,bh3=0;
  for(int i=0;i<al;i++) {
    ah=(ah*B)%mod+a[i];
    ah%=mod;
    ah2=(ah2*B)%mod2+a[i];
    ah2%=mod2;
//    ah3=(ah3*B)%mod3+a[i];
//    ah3%=mod3;
  }
  for(int i=0;i<al;i++) {
    bh=(bh*B)%mod+b[i];
    bh%=mod;
    bh2=(bh2*B)%mod2+b[i];
    bh2%=mod2;
//    bh3=(bh3*B)%mod3+b[i];
//    bh3%=mod3;
  }

  vector<int> ret;
  vector<ll> ans;
  for(int i=0;i+al<=bl;i++){
    if(ah==bh&&ah2==bh2/*&&ah3==bh3*/) {
      ans.push_back(i);
    }
    if(i+al<bl){
      bh=(bh*B)%mod+b[i+al]-b[i]*t;
      bh=t_mod(bh,mod);
      bh2=(bh2*B)%mod2+b[i+al]-b[i]*t2;
      bh2=t_mod(bh2,mod2);
//      bh3=(bh3*B)%mod3+b[i+al]-b[i]*t3;
//      bh3=t_mod(bh3,mod3);
    }
  }
  return ans;
}
