template <typename T, int64_t BASE, int64_t MOD> class RollingHash{
private:
  static std::vector<int64_t> pow;

public:
  static void init(int N){
    pow.assign(N+1,0);
    pow[0] = 1;
    for(int i = 1; i <= N; ++i){
      pow[i] = pow[i-1] * BASE % MOD;
    }
  }

  static std::vector<int64_t> generate_hash(const T &s){
    std::vector<int64_t> ret(s.size()+1);

    for(int i = 1; i <= (int)s.size(); ++i){
      ret[i] = (ret[i-1] * BASE + s[i-1]) % MOD;
    }

    return ret;
  }

  static int64_t hash(const std::vector<int64_t> &shash, int i, int j){ // [i, j)
    return (shash[j] - shash[i] * pow[j-i] + MOD * MOD) % MOD;
  }

  static int64_t hash(const T &p){
    int64_t phash = 0;
    for(int i = 0; i < (int)p.size(); ++i) phash = (phash * BASE + p[i]) % MOD;
    return phash;
  }

  static std::vector<int> find(const std::vector<int64_t> &shash, const T &p){
    std::vector<int> ret;
    int pl = p.size();
    int64_t phash = hash(p);
    for(int i = 0; i < (int)shash.size()-pl; ++i) if(hash(shash,i,i+pl) == phash) ret.push_back(i);
    return ret;
  }
};

