    REP(i,N){
        C[i]=A[i]^A[(i+1)%N];
        D[i]=B[i]^B[(i+1)%N];
    }
    REP(i,N){
        int k=0;
        while(k<N&&C[(i+k)%N]==D[k]){
            k++;
        }
