constexpr int P_MAX = 500000;

vector<int> table(P_MAX, 0); // ずらしテーブル

void make_table(vector<int> p, int m) {
    int j = 0;
    for(int i=1;i<m;++i) {
        table[i] = j;
        if(p[i] == p[j]) {
            ++j;
        } else {
            j = 0;
        }
    }
}

vector<int> kmp(vector<int> s, vector<int> p, int n, int m, int start=0) {
    int i = start, j = 0;
    vector<int> ret;
    while(i < n) {
        if(s[i] == p[j]) {
            if(j == m-1) {
                ret.push_back(i-j);
                j = table[j];
            } else {
                ++i;
                ++j;
            }
        } else if(j == 0) {
            ++i;
        } else {
            j = table[j];
        }
    }
    return ret;
}
