	//for (int i=1;i<=N;i++) printf("%d ",S[i]); printf("\n");
	tot=0;
	for (int i=1;i<=n;i++) {
		if (STQ(rk[1],rk[i+n])>=n) ans[++tot]=make_pair((n-i+1)%n,d[i]^c[1]);
	}
	sort(ans+1,ans+tot+1);
	for (int i=1;i<=tot;i++) printf("%d %d\n",ans[i].first,ans[i].second);
	return 0;
}
