const int p=500001023,f=800004091;
const int r=1000000021;
int binpow(int a,int b) {
    if (b==0)
        return 1;
    if (b%2==1)
        return ((long long)a*binpow(a,b-1))%r;
    int x=binpow(a,b/2);
    return ((long long)x*x)%r;
}
main() {
    int n;
    cin>>n;
