    for (int i=0;i<n;i++)
        c[i]=c[i+n]=(a[i]^a[i+1])+1;
    for (int i=0;i<n;i++)
        cin>>b[i];
    b[n]=b[0];
    for (int i=0;i<n;i++)
        d[i]=d[i+n]=(b[i]^b[i+1])+1;
    int pp[2*n],ff[2*n],x[2*n],y[2*n],xf[2*n],yf[2*n];
    pp[0]=1;
    for (int i=1;i<(2*n);i++)
        pp[i]=((long long)p*pp[i-1])%r;
    ff[0]=1;
    for (int i=1;i<(2*n);i++)
        ff[i]=((long long)f*ff[i-1])%r;
    x[0]=xf[0]=c[0];
    for (int i=1;i<(2*n);i++) {
