namespace Math{
  const ll MOD = 1000000007ll; // if inv is needed, this shold be prime.
  struct ModInt{
    ll val;
    ModInt():val(0ll){}
    ModInt(const ll& v):val(((v%MOD)+MOD)%MOD){}
    ModInt exp(ll y)const{
      if(!y)return ModInt(1ll);
      ModInt a = exp(y/2ll);
      a *= a;
      if(y&1)a*=(*this);
      return a;
    }
    bool operator==(const ModInt& x)const{return val==x.val;}
    bool operator!=(const ModInt& x)const{return !(*this==x);}
    bool operator<(const ModInt& x)const{return val<x.val;}
    bool operator>(const ModInt& x)const{return val>x.val;}
    bool operator>=(const ModInt& x)const{return !(*this<x);}
    bool operator<=(const ModInt& x)const{return !(*this>x);}
    ModInt& operator+=(const ModInt& x){if((val+=x.val)>=MOD)val-=MOD;return *this;}
    ModInt& operator-=(const ModInt& x){if((val+=MOD-x.val)>=MOD)val-=MOD;return *this;}
    ModInt& operator*=(const ModInt& x){(val*=x.val)%=MOD;return *this;}
    ModInt operator+(const ModInt& x)const{return ModInt(*this)+=x;}
    ModInt operator-(const ModInt& x)const{return ModInt(*this)-=x;}
    ModInt operator*(const ModInt& x)const{return ModInt(*this)*=x;}
    friend istream& operator>>(istream&i,ModInt& x){ll v;i>>v;x=v;return i;}
    friend ostream& operator<<(ostream&o,const ModInt& x){o<<x.val;return o;}
  };
  ModInt pow(ModInt a,ll x){
    ModInt res = ModInt(1ll);
    while(x){
      if(x&1)res *= a;
      x >>= 1;
      a = a*a;
    }
    return res;
  }
  vector<ModInt> inv,fac,facinv;
  // notice: 0C0 = 1 
  ModInt nCr(int n,int r){
    assert(!(n<r));
    assert(!(n<0||r<0));
    return fac[n]*facinv[r]*facinv[n-r];
  }
  void init(int SIZE){
    fac.resize(SIZE+10);
    inv.resize(SIZE+10);
    facinv.resize(SIZE+10);
    fac[0]=ModInt(1ll);
    for(int i=1;i<=SIZE;i++)fac[i]=fac[i-1]*ModInt(i);
    inv[1]=ModInt(1ll);
    for(int i=2;i<=SIZE;i++)inv[i]=ModInt(0ll)-ModInt(MOD/i)*inv[MOD%i];
    facinv[0]=ModInt(1ll);
    for(int i=1;i<=SIZE;i++)facinv[i]=facinv[i-1]*inv[i];
    return;
  }
}
namespace DS{
  template<class T>
  struct RangeSum{
    vector<T> vec;
    RangeSum(){}
    RangeSum(vector<T> elems):vec(elems){
      for(int i=1;i<vec.size();i++){
        vec[i] += vec[i-1];
      }
    }
    T sum(int l,int r){
      if(l>r)return T(0);
      if(l==0)return vec[r];
      else return vec[r]-vec[l-1];
    }
  };
  template<class T,int N>
  struct BIT{
    vector<T> bit;
    BIT(){
      bit = vector<T>(N+1,T(0));
    }
    void add(int i,T x){
      i++;
      while(i<=N){
        bit[i]+=x;
        i+=i&-i;
      }
      return;
    }
    T sum(int i){
      i++;
      T res = T(0);
      while(i>0){
        res+=bit[i];
        i-=i&-i;
      }
      return res;
    }
    T sum(int l,int r){// [l,r]
      assert(l<=r);
      if(l==0)return sum(r);
      else return sum(r)-sum(l-1);
    }
  };
}
template<class T>
struct RollingHash{
  using Hash = Math::ModInt;
  vector<Hash> hash; // hash[i] is hash of s[0,i)
  vector<Hash> powB;
  const Hash B = Hash(10007);
  T s;
  explicit RollingHash(T s):s(s){
    hash.assign(s.size()+1,Hash(0));
    powB.assign(s.size()+1,Hash(0));
    powB[0] = Hash(1);
    for(int i=0;i<s.size();i++){
      powB[i+1] = powB[i]*B;
      hash[i+1] = hash[i]*B+Hash(s[i]);
    }
  }
  Hash get(int l,int r){ // [l,r)
    assert(l<r);
    return hash[r]-hash[l]*powB[r-l];
  }
  Hash substr(int l,int len){ // [l,l+len)
    return get(l,l+len);
  }
};
