void zalgo(vector<int> &S, vector<int> &A){
    int c = 0;
    int sz = S.size();
    for(int i = 1; i < sz; i++){
        if(i + A[i - c] < c + A[c]){
            A[i] = A[i - c];
        }else{
            int j = max(0, c + A[c] - i);
            while(i + j < S.size() && S[j] == S[i + j]) ++j;
            A[i] = j;
        }
    }
    A[0] = S.size();
}

