int newnode() { ++cnt; g[cnt][0] = g[cnt][1] = val[cnt] = -1; return cnt; }
void addstr(const string& s, int vval) {
	int cur = 0;
	for (char x : s) {
		int lnk = (x == '0' ? 0 : 1);
		if (g[cur][lnk] == -1)
			g[cur][lnk] = newnode();
		cur = g[cur][lnk];
	}
	val[cur] = vval;
