void mklink() {
	queue<int> q;
	for (int i=0; i<2; ++i)
		if (g[0][i] != -1) {
			fail[g[0][i]] = 0;
			q.push(g[0][i]);
		}
	while (!q.empty()) {
		int s = q.front(); q.pop();
		for (int i=0; i<2; ++i)
			if (g[s][i] != -1) {
				int state = fail[s];
				while (state > 0 && g[state][i] == -1) state = fail[state];
				state = (g[state][i] == -1 ? state : g[state][i]);
				fail[g[s][i]] = state;
				q.push(g[s][i]);
			}
	}
}
