void z_function(int n){
	for(int i=0;i<n;i++)s[i]=s[i+1];
	int l=0,r=0;z[0]=n;
	for(int i=1;i<n;++i){
		if(i>r){
			l=r=i;
			while(r<n&&s[r-l]==s[r])++r;
			z[i]=r-l;--r;
		}
		else{
			int k=i-l;
			if(z[k]<r-i+1)z[i]=z[k];
			else{
				l=i;
				while(r<n&&s[r-l]==s[r])++r;
				z[i]=r-l;--r;
			}
		}
	}
}
