  }

  vector<u64> S(N), T(N);
  for (int i = 0; i < N; i++) {
    S[i] = A[i] ^ A[(i + 1) % N];
    T[i] = B[i] ^ B[(i + 1) % N];
  }
  copy(S.begin(), S.end(), back_inserter(S));

  RollingHash rha(S), rhb(T);
  for (int i = 0; i < N; i++) {
    if (rha.slice(i, i + N) == rhb.slice(0, N)) {
      cout << i << " " << (A[i] ^ B[0]) << '\n';
    }
  }
