class RollingHash {
    private:
        static const int base1 = 10007, base2 = 10009;
        static const int mod1 = 1000000007, mod2 = 1000000009;
        std::vector<long long> hash1, hash2, pow1, pow2;
    public:
        const int N;
        RollingHash(const std::vector<ll> &S) : N((int)S.size()) {
            hash1.resize(N+1);
            hash2.resize(N+1);
            pow1.resize(N+1);
            pow2.resize(N+1);
            hash1.at(0) = hash2.at(0) = 0;
            pow1.at(0) = pow2.at(0) = 1;
            for (int i=1; i<N+1; i++) {
                hash1.at(i) = (hash1.at(i-1) * base1 + S.at(i-1)) % mod1;
                hash2.at(i) = (hash2.at(i-1) * base2 + S.at(i-1)) % mod2;
                pow1.at(i) = (pow1.at(i-1) * base1) % mod1;
                pow2.at(i) = (pow2.at(i-1) * base2) % mod2;
            }
        }
        std::pair<long long, long long> get(int l, int r) const {
            long long res1 = (hash1.at(r) - hash1.at(l) * pow1.at(r-l)) % mod1;
            if (res1 < 0) res1 += mod1;
            long long res2 = (hash2.at(r) - hash2.at(l) * pow2.at(r-l)) % mod2;
            if (res2 < 0) res2 += mod2;
            return std::make_pair(res1, res2);
        }
        int getLCP(int a, int b) const {
            int len = std::min(N - a, N - b);
            int ok = 0, ng = len+1;
            while (abs(ok - ng) > 1) {
                int mid = (ok + ng) / 2;
                if (get(a, a+mid-1) == get(b, b+mid-1)) {
                    ok = mid;
                } else {
                    ng = mid;
                }
            }
            return ok;
        }
        int getLCP(const RollingHash &T, int a, int b) const {
            int len = std::min(N - a, T.N - b);
            int ok = 0, ng = len+1;
            while (abs(ok - ng) > 1) {
                int mid = (ok + ng) / 2;
                if (get(a, a+mid-1) == T.get(b, b+mid-1)) {
                    ok = mid;
                } else {
                    ng = mid;
                }
            }
            return ok;
        }
};

void solve() {
    int n;
    cin >> n;
    vector<ll> a(n);
    for (int i=0; i<n; i++) {
        cin >> a.at(i);
    }
    vector<ll> b(n);
    for (int i=0; i<n; i++) {
        cin >> b.at(i);
    }
    vector<ll> aa(2*n), bb(2*n);
    for (int i=0; i<n; i++) {
        if (i == 0) {
            aa.at(i) = aa.at(i+n) = a.at(0) ^ a.at(n-1);
            bb.at(i) = bb.at(i+n) = b.at(0) ^ b.at(n-1);
        } else {
            aa.at(i) = aa.at(i+n) = a.at(i) ^ a.at(i-1);
            bb.at(i) = bb.at(i+n) = b.at(i) ^ b.at(i-1);
        }
    }

    RollingHash A(aa), B(bb);
    for (int i=0; i<n; i++) {
        int lcp = A.getLCP(B, i, 0);
        if (lcp >= n) {
            cout << i << " " << (a.at(i) ^ b.at(0)) << "\n";
        }
    }
}

