ll kmp(const string &needle, const string &text) {
    const ll n = needle.length(), m = text.length();
    ll *const z = new ll[n];
    memset(z, 0, sizeof(ll) * n);
    ll c = 0;
    for (ll i = 1; i < n; i++) {
        z[i] = c;
        if (needle[c] == needle[i]) c++;
        else c = 0;
    }
    z[0] = -1;
    ll s = 0, t = 0, r = -1;
    while (s + t < m) {
        if (needle[s] == text[s + t]) {
            s++;
            if (s == n) {
                r = t;
                break;
            }
        } else {
            t = s + t - z[s];
            if (s > 0) s = z[s];
        }
    }
    free(z);
    return r;
}

