template<typename T>
std::vector<int> make_shift_table(const T& target) {
	std::vector<int> result(target.size());
	if (result.size() == 1) {
		result[0] = -1;
		return result;
	}
	int longest_prefix{ 0 };
	result[0] = -1; result[1] = 0;
	for (auto i = 2; i < target.size(); ++i) {
		while (longest_prefix >= 0 && target[i - 1] != target[longest_prefix]) {
			longest_prefix = result[longest_prefix];
		}
		result[i] = ++longest_prefix;
	}
	return result;
}
template<typename T>
std::vector<int> match_position(const T& target, const T& pattern) {
	const auto shift = make_shift_table(pattern);
	int it = 0;
	std::vector<int> result;
	for (auto iw = 0; iw < target.size(); ++iw) {
		while (it >= 0 && target[iw] != pattern[it]) {
			it = shift[it];
		}
		if (++it == pattern.size()) {
			result.push_back(iw - it + 1);
			it = shift.back();
			while (it >= 0 && target[iw] != pattern[it]) {
				it = shift[it];
			}
			++it;
		}
	}
	return result;
}
