template <typename T>
class MP
{
    long long n;
    T query;
    vector<long long> table;

public:
    MP(const T &str)
    {
        this->query = T(str);
        this->n = this->query.size();
        this->table = vector<long long>(this->n + 1, -1);
        long long j = -1;
        for (long long i = 0; i < this->n; i++)
        {
            while (j != -1 && this->query[j] != this->query[i])
            {
                j = this->table[j];
            }
            j++;
            this->table[i + 1] = j;
        }
    }

    int operator[](const int i)
    {
        return this->table[i];
    }

    vector<long long> find_from(const T &document)
    {
        vector<long long> res;
        long long j = 0;
        for (long long i = 0; i < document.size(); i++)
        {
            while (j != -1 && this->query[j] != document[i])
            {
                j = this->table[j];
            }
            j++;
            if (j == this->n)
            {
                res.push_back(i - j + 1);
                j = this->table[j];
            }
        }
        return res;
    }
};

