struct KnuthMorrisPratt {
  const int m;
  const vector<int64_t> p;
  vector<int> fail;
  KnuthMorrisPratt(vector<int64_t> p) : m(p.size()), p(p) {
    fail.resize(m+1, -1);
    for (int i = 1, j = -1; i <= m; ++i) {
      while (j >= 0 && p[j] != p[i-1]) j = fail[j];
      fail[i] = ++j;
    }
  }
  template <class F>
  void match(vector<int64_t> s, F f) {
    int n = s.size(), k = 0;
    for (int i = 0; i < n; ++i) {
      while (k == m || (k >= 0 && s[i] != p[k])) k = fail[k];
      if (++k == m) f(i-m+1, i+1); // p[0,m) matches to s[i-m+1,i+1)
    }
  }
};


int main() {
  int n;
  cin >> n;
  vector<int64_t> a(n), b(n);
  for (int i = 0; i < n; ++i) cin >> a[i];
  for (int i = 0; i < n; ++i) cin >> b[i];

  vector<int64_t> da(n), db(n);
  da[0] = a[n-1] ^ a[0];
  db[0] = b[n-1] ^ b[0];
  for (int i = 1; i < n; ++i) {
    da[i] = a[i-1] ^ a[i];
    db[i] = b[i-1] ^ b[i];
  }
  vector<int64_t> da2 = da;
  for (int i = 0; i < n-1; ++i) da2.emplace_back(da[i]);

  vector<int> candidate;
  KnuthMorrisPratt kmp(db);
  kmp.match(da2, [&](int i, int j) {
    candidate.emplace_back(i);
  });
  // a[i, i+n) == b[0,n)
  for (int k: candidate) {
    int64_t x = a[0+k] ^ b[0];
    printf("%d %ld\n", k, x);
  }
}

