	for (ll b = 0; b < 30; b++) {
		VLL AA(2 * N);
		VLL BB(N);
		for (ll n = 0; n < N; n++) {
			AA[n] = ((ll)1 << b) & A[n];
			AA[N + n] = ((ll)1 << b) & A[N + n];
			BB[n] = ((ll)1 << b) & B[n];
			AA[n] = (AA[n] >> b);
			AA[N + n] = (AA[N + n] >> b);
			BB[n] = (BB[n] >> b);
		}
		RollingHash ah(AA);
		HASH bh = ah.conv(BB);
		vector<bool> res(N,false);
		for (ll n = 0; n < N; n++) {
			HASH x = ah.get(n, n + N);
			if (x == bh)res[n] = res[n] | true;
