template<class T>
struct KMP
{
public:
  /**
   * @param N strのサイズ
   * @param K wordのサイズ
   */
  KMP(int N, int K);

  /** 検索対象の文字列 */
  vector<T> str;

  /** 検索元の文字列 */
  vector<T> word;

  /** 内部処理で使用する検索テーブル */
  vector<size_t> memo;

  /**
   * 前計算処理を行う. 
   * 本APIを呼ぶ前にstr, wordに入力する必要がある.
   */
  void preCalc();

  /**
   * prePos番目以降で、wordと一致するstrの部分文字列が開始されるindexを返す.
   * 本APIを呼ぶ前にKMP::preCalcを実行する必要がある.
   * 
   * @param prePos 探索を始めるindex
   * @return pos 見つからなかった場合は-1
   */
  ssize_t find(ssize_t prePos);
};

template<class T>
KMP<T>::KMP(int N, int K)
  : str(N)
  , word(K)
  , memo(K+1)
{}

template<class T>
void KMP<T>::preCalc()
{
  size_t i = 0;
  size_t j = 1;
  memo[0] = -1;
  while (j < word.size()) {
    auto isMatch = word[i] == word[j];
    if (!isMatch && i > 0) {
      i = memo[i];
    }
    else {
      if (isMatch) {
        ++i;
      }
      ++j;
      memo[j] = i;
    }
  }
  return;
}

template<class T>
ssize_t KMP<T>::find(ssize_t prePos)
{
  int i = prePos;
  int j = 0;
  while (i < (int)str.size() && j < (int)word.size()) {
    if (str[i] == word[j]) {
      ++i;
      ++j;
    }
    else if (j == 0) {
      ++i;
    }
    else {
      j = memo[j];
    }
  }
  return (j == (int)word.size()) ? (i - j) : -1;
}

void solve(void)
{
  int N; cin >> N;
  vector<int> A(N), B(N);
  for (auto& a : A) {
    cin >> a;
  }
  for (auto& b : B) {
    cin >> b;
  }

  KMP<int> k(N*2, N);
  for (int i = 0; i < N; ++i) {
    k.str[i] = A[i] ^ A[(i+1) % N];
    k.word[i] = B[i] ^ B[(i+1) % N];
  }
  std::copy(k.str.begin(), k.str.begin()+N, k.str.begin()+N);
  k.preCalc();

  auto itr = k.find(0);
  while (itr != -1 && itr < (int)A.size()) {
    int i = 0;
    int j = (i + itr) % N;
    int x = B[i] ^ A[j];
    cout
      << itr << SPACE
      << x << CRLF;

    itr = k.find(itr+1);
  }

  return;
}

int main(void)
{
  std::ios_base::sync_with_stdio(false);
  std::cin.tie(0);

  solve();

  return 0;
}

