/// KMP法(文字列検索)
template <class T>
struct KmpSearcher
{
	struct Pattern
	{
		vector<T> s;
		vector<int> t;

		Pattern(const vector<T>& s)
			: s(s), t(s.size() + 1)
		{
			int j = 0;
			FOR(i, 1, s.size())
			{
				if (s[i] == s[j]) { t[i] = j++; }
				else { t[i] = j; j = 0; }
			}
			t.back() = j;
		}
	};

	const vector<T> input;
	const Pattern p;
	const bool overlap{};

	int i{};
	int j{};

	KmpSearcher(const std::vector<T>& input, Pattern p, bool overlap = false)
		: input(input), p(p), overlap(overlap)
	{
	}

	int Next()
	{
		while (i < input.size() && j < p.s.size())
		{
			if (input[i] == p.s[j])
			{
				i++; j++;
			}
			else if (j == 0)
			{
				i++;
			}
			else
			{
				j = p.t[j];
			}
		}

		if (j == p.s.size())
		{
			auto ret = i - j;
			j = overlap ? p.t[j] : 0;
			return ret;
		}

		return -1;
	}

	vector<int> MatchAll()
	{
		vector<int> ret;
		while (true)
		{
			auto k = Next();
			if (k == -1) { break; }
			ret.push_back(k);
		}
		return ret;
	}
};
template <class T> int KmpSearch(const std::vector<T>& input, typename KmpSearcher<T>::Pattern p) { return KmpSearcher<T>(input, p).Next(); }
template <class T> auto KmpSearchAll(const std::vector<T>& input, typename KmpSearcher<T>::Pattern p, bool overlapped) { return KmpSearcher<T>(input, p, overlapped).MatchAll(); }


