void solve()
{
	READ(int, N);
	auto A0 = read<int>(N);
	auto B0 = read<int>(N);

	vector<int> A(N * 2), B(N);
	REP(i, N * 2) { A[i] = A0[i % N] ^ A0[(i + 1) % N]; }
	REP(i, N) { B[i] = B0[i % N] ^ B0[(i + 1) % N]; }

	A.pop_back();
	FORE(e : KmpSearchAll(A,B,true))
	{
		WRITE(e, B0[0] ^ A0[e]);
	}
}

