#define REP(i,n) for (ll i = 0; i < n; ++i)
#define REPR(i,n) for (ll i = n-1; i >= 0; --i)
#define FOR(i,m,n) for (ll i = m; i < n; ++i)
#define FORR(i,m,n) for (ll i = n-1; i >= m; --i)
#define FORE(x,xs) for (const auto& x : xs)
#define ALL(v) v.begin(), v.end()

const int MAX = 2e5+10;
const int BITS = 31;

vi createTable(vi word) {
    int n = word.size();
    vi table(n+1);
    table[0] = -1;
    int j = -1;
    REP (i, n) {
        while (j >= 0 && word[i] != word[j]) j = table[j];
        table[i+1] = ++j;
    }
    return table;
}

vi kmp(vi str, vi word) {
    vi table = createTable(word), ret;
    int m = 0, i = 0, n = str.size();
    while (m+i < n) {
        if (word[i] == str[m+i]) {
            if (++i == (int)(word.size())) {
                ret.push_back(m);
                m = m+i-table[i];
                i = table[i];
            }
        } else {
            m = m + i - table[i];
            if (i > 0) i = table[i];
        }
    }
    return ret;
}

int N;
int A[MAX], B[MAX];

vii sub(int bit) {
    vi a, a_not, b;
    REP (i, N) {
        int n = (A[i] >> bit) & 1;
        a.push_back(n);
        a_not.push_back(1^n);
    }
    REP (i, N) b.push_back((B[i] >> bit) & 1);
    REP (i, N-1) b.push_back((B[i] >> bit) & 1);

    vii ret;
    FORE (idx, kmp(b, a)) ret.push_back(make_pair(idx, 0));
    FORE (idx, kmp(b, a_not)) ret.push_back(make_pair(idx, 1));
    return ret;
}

vii solve() {
    map<int, map<int, vi>> res; // shift -> (bit -> {0, 1})

    REP (bit, BITS) {
        vii shift_x = sub(bit);
        FORE (sx, shift_x) {
            int shift = sx.first, x = sx.second;
            res[shift][bit].push_back(x);
        }
    }

    vii ret;
    for (auto iter_res = res.begin(); iter_res != res.end(); iter_res++) {
        int shift = iter_res->first;
        map<int, vi> bits = iter_res->second;
        if (bits.size() != BITS) continue;

        vi xs;
        xs.push_back(0);
        for (auto iter_bits = bits.begin(); iter_bits != bits.end(); iter_bits++) {
            int b = iter_bits->first;
            vi bit_result = iter_bits->second;
            int xs_size = xs.size();
            if (bit_result.size() == 2) REP (i, xs_size) xs.push_back(xs[i]);
            REP (i_b, bit_result.size() * xs_size) xs[i_b] |= (bit_result[i_b/xs_size] << b);
        }
        FORE (x, xs) ret.push_back(make_pair((N - shift) % N, x));
    }
    sort(ALL(ret));
    return ret;
}

int main() {
    cin >> N;
    REP (i, N) cin >> A[i];
    REP (i, N) cin >> B[i];
    FORE (x, solve()) {
        cout << x.first << " " << x.second << endl;
    }
}

