class RollingHash {
    int num = 10; // 基数と法の数
    int len;      // 文字列の長さ
    vector<int> base = {1000 + rand() % 1000000000, 1000 + rand() % 1000000000,
                        1000 + rand() % 1000000000, 1000 + rand() % 1000000000,
                        1000 + rand() % 1000000000, 1000 + rand() % 1000000000,
                        1000 + rand() % 1000000000, 1000 + rand() % 1000000000,
                        1000 + rand() % 1000000000, 1000 + rand() % 1000000000};
    const vector<int> mod = {999999797,  999999883,  999999893,  999999929,  999999937,
                             1000000007, 1000000009, 1000000021, 1000000033, 1000000087};
    vector<vector<long long>> hash, power;

  public:
    RollingHash(const string &str, const vector<int> &base_ = vector<int>()) {
        if (base_.size() != 0) base = base_;
        len = str.size();
        rep(i, num) {
            hash.emplace_back(len + 1);
            power.emplace_back(len + 1);
            power[i][0] = 1;
            hash[i][0] = 0;
        }
        repr(i, 1, len + 1) {
            rep(j, num) {
                hash[j][i] = (hash[j][i - 1] * base[j] + str[i - 1]) % mod[j];
                power[j][i] = power[j][i - 1] * base[j] % mod[j];
            }
        }
    }

    RollingHash(const vector<int> &str, const vector<int> &base_ = vector<int>()) {
        if (base_.size() != 0) base = base_;
        len = str.size();
        rep(i, num) {
            hash.emplace_back(len + 1);
            power.emplace_back(len + 1);
            power[i][0] = 1;
            hash[i][0] = 0;
        }
        repr(i, 1, len + 1) {
            rep(j, num) {
                hash[j][i] = (hash[j][i - 1] * base[j] + str[i - 1]) % mod[j];
                power[j][i] = power[j][i - 1] * base[j] % mod[j];
            }
        }
    }

    // [l, r) のハッシュ値を得る
    inline vector<long long> get_hash(int l, int r) {
        vector<long long> res(num);
        rep(i, num) {
            res[i] = (hash[i][r] - hash[i][l] * power[i][r - l]) % mod[i];
            if (res[i] < 0) res[i] += mod[i];
        }
        return res;
    }

    // str[a:], str[b:] の最長共通接頭辞の長さを O(log|str|) で計算
    inline int lcp(int a, int b) {
        int ok = 0, ng = min(len - a, len - b);
        while (ng - ok > 1) {
            int mid = (ok + ng) / 2;
            if (get_hash(a, a + mid) == get_hash(b, b + mid)) {
                ok = mid;
            } else {
                ng = mid;
            }
        }
        return ok;
    }

    auto get_base() {
        return base;
    }
};

int N;
vi a, b;

void solve(){
    vi a2(N), b2(2*N);
    map<int, int> ans;
    rep(i,N){
        a2[i] = a[i] ^ a[(i+1)%N];
        b2[i] = b2[i + N] = b[i] ^ b[(i+1)%N];
    }

    RollingHash rha(a2);
    RollingHash rhb(b2, rha.get_base());

    rep(i,N){
        if(rha.get_hash(0,N) == rhb.get_hash(i,i+N)){
            int k = (N-i)%N;
            ans[k] = a[k]^b[0];
        }
    }
    if(ans.size() == 0){
        cout<<-1<<endl;
        return;
    }
    for(auto p:ans){
        cout<<p.first<<' '<<p.second<<'\n';
    }
}

int main(void) {
    cin>>N;
    a = vi(N);
    b = vi(N);

    cin>>a>>b;
    solve();

    return 0;
}

#include <bits/stdc++.h>
using namespace std;
using ull=unsigned long long;

int N;ull* A;ull* B;ull base=10000000000007LL;

vector<pair<int,int>> rollinghash() {
  ull start_a=0LL;ull b_hash=0LL;ull bb=1LL;vector<pair<int,int>> Re(0);
  for (int i=N;i>0;i--) {
    start_a+=(A[i%N]^A[i-1])*bb;
    b_hash+=(B[i%N]^B[i-1])*bb;
    bb*=base;
  }
  if (start_a==b_hash) {
    Re.push_back(make_pair(0,(A[0]^B[0])));
  }
  ull x=start_a;
  for (int i=0;i<N-1;i++) {
    x=x*base-bb*(A[i]^A[i+1])+(A[i]^A[i+1]);
    if (x==b_hash) {
      Re.push_back(make_pair(i+1,(A[i+1]^B[0])));
    }
  }
  return Re;
}

