  cin >> N;A=new ull[N];B=new ull[N];
  for (int i=0;i<N;i++) {
    cin >> A[i];
  }
  for (int i=0;i<N;i++) {
    cin >> B[i];
  }
  vector<pair<int,int>> R=rollinghash();
  for (pair<int,int> pii:R) {
