VL Zalgo(const VL &S) {
    int N = (int)S.size();
    VL res(N);
    res[0] = N;
    int i = 1, j = 0;
    while(i < N) {
        while(i + j < N && S[j] == S[i + j]) ++j;
        res[i] = j;
        if(j == 0) {
            ++i;
            continue;
        }
        int k = 1;
        while(i + k < N && k + res[k] < j) res[i + k] = res[k], ++k;
        i += k, j -= k;
    }
    return res;
}

void solve() {
    LCIN(N);
    VL a(N), b(N);
    VECCIN(a);
    VECCIN(b);
    VL dif;
    REP(i, N - 1) dif.emplace_back(b[i] ^ b[i + 1]);
    dif.emplace_back(-1);
    REP(i, 2 * N) { dif.emplace_back(a[i % N] ^ a[(i + 1) % N]); }
    VL z = Zalgo(dif);
    VPL ans;
    REP(i, N) {
        if(z[i + N] == N - 1) {
            ans.emplace_back(i, a[i] ^ b[0]);
        }
    }
    REP(i, sz(ans)) { COUT(ans[i].fi, ans[i].second); }
}

