            string t(3 * n, '*');
            for (size_t i = 0; i < n; i++)
            {
                s[i] = (b[i] >> k & 1) + '0';
                t[i] = (~b[i] >> k & 1) + '0';
                t[i + n] = t[i + 2 * n] = s[i + n] = s[i + 2 * n] = (a[i] >> k & 1) + '0';
            }
            auto z0 = Z_function(s);
            auto z1 = Z_function(t);
            for (size_t i = 0; i < n; i++)
            {
                if (ans[i] == -1)
                    continue;
                if (z0[i + n] >= n)
                    continue;
                else if (z1[i + n] >= n)
                    ans[i] ^= 1 << k;
                else
                    ans[i] = -1;
            }
        }
        for (size_t i = 0; i < n; i++)
            if (ans[i] != -1)
                cout << i << ' ' << ans[i] << '\n';
    }
};

