struct KnuthMorrisPratt {
  const int m;
  const vector<int64_t> p;
  vector<int> fail;
  KnuthMorrisPratt(vector<int64_t> p) : m(p.size()), p(p) {
    fail.resize(m+1, -1);
    for (int i = 1, j = -1; i <= m; ++i) {
      while (j >= 0 && p[j] != p[i-1]) j = fail[j];
      fail[i] = ++j;
    }
  }
  template <class F>
  void match(vector<int64_t> s, F f) {
    int n = s.size(), k = 0;
    for (int i = 0; i < n; ++i) {
      while (k >= 0 && s[i] != p[k]) k = fail[k];
      if (++k == m) f(i-m+1, i+1); // p[0,m) matches to s[i-m+1,i+1)
    }
  }
};


