vector<int> rolling_hash(vector<int> a, vector<int> b) {
    typedef unsigned long long ull;
    ull B = 1000000007;



    ull ah = 0, t = 1;
    rep(j, sz(a)) t *= B;
    rep(j, sz(a)) {
        ah = ah * B + a[j];
    }

    ull bh = 0;
    rep(j, sz(a)) bh = bh * B + b[j];

    vector<ull> bhs;
    rep(i, sz(b)) {
        bhs.eb(bh);
        bh = bh * B - b[i] * t + b[i + sz(a)];
    }

    vector<int> ret;
    rep(i, sz(a)) if (ah == bhs[i]) ret.eb(i);
    return ret;
}
