vec kmp_table(vec &Pattern) {
    ll i = 2, j = 0;
    vec T(Pattern.size(), -1);
    T[1] = 0;

    while (i < Pattern.size()) {
        if (Pattern[i-1] == Pattern[j]) {
            T[i] = j+1;
            i++;
            j++;
        } else if (j > 0) {
            j = T[j];
        } else {
            T[i] = 0;
            i++;
        }
    }

    return T;
}

vec kmp_search (vec &Text, vec &Pattern, vec &kmptable) {
    vec ret;
    ll m = 0, i = 0;
    while (m+i < Text.size()) {
        if (Pattern[i] == Text[m+i]) {
            i++;
            if (i == Pattern.size()) {
                ret.push_back(m);
                i--;
                m = m+i-kmptable[i];
                i = kmptable[i];
            }
        } else {
            m = m+i-kmptable[i];
            if (i > 0) i = kmptable[i];
        }
    } 
    return ret;
}

