using namespace std;

long long rng(long long l, long long r) {
  static mt19937 mt(chrono::steady_clock::now().time_since_epoch().count());
  return uniform_int_distribution<long long>(l, r - 1)(mt);
}

struct RollingHash {
  static constexpr uint64_t m31 = (1LL << 31) - 1;
  static int mod_m31(uint64_t a) {
    a = (a >> 31) + (a & m31);
    return a >= m31 ? a - m31 : a;
  }
  static long long base[2];
  static vector<int> powb[2];
  vector<int> h[2];
  RollingHash(const string& s) : h{{0}, {0}} {
    for (int k : {0, 1}) {
      for (char c : s) h[k].push_back(mod_m31(h[k].back() * base[k] + c));
      while (powb[k].size() <= s.size())
        powb[k].push_back(mod_m31(powb[k].back() * base[k]));
    }
  }
  int get(int l, int r, int k) const {
    return mod_m31(h[k][r] + (m31 - h[k][l]) * powb[k][r - l]);
  }
  auto get(int l, int r) const { return make_pair(get(l, r, 0), get(l, r, 1)); }
  int size() const { return h[0].size() - 1; }
};
long long RollingHash::base[2] = {rng(1e9, 2e9), rng(1e9, 2e9)};
vector<int> RollingHash::powb[2] = {{1}, {1}};

int main() {
  cin.tie(nullptr);
  ios::sync_with_stdio(false);
  int n;
  cin >> n;
  vector<int> a(n);
  for (auto&& e : a) {
    cin >> e;
  }
  vector<int> b(n);
  for (auto&& e : b) {
    cin >> e;
  }
  vector<bool> ok(n, true);
  vector<int> res(n);
  for (int k = 0; k < 30; ++k) {
    string s, t;
    for (int i = 0; i < n; ++i) {
      s += a[i] >> k & 1 ? '1' : '0';
      t += b[i] >> k & 1 ? '1' : '0';
    }
    s += s;
    RollingHash rh(s);
    auto zero = RollingHash(t).get(0, n);
    for (auto&& e : t) {
      e ^= 1;
    }
    auto one = RollingHash(t).get(0, n);
    for (int i = 0; i < n; ++i) {
      if (rh.get(i, i + n) == zero) {
      } else if (rh.get(i, i + n) == one) {
        res[i] |= 1 << k;
      } else {
        ok[i] = false;
      }
    }
  }
  for (int i = 0; i < n; ++i) {
    if (ok[i]) {
      cout << i << ' ' << res[i] << '\n';
    }
  }
}

