struct rolling_hash {/*@formatter:on*/
    static constexpr int base1 = 1007, base2 = 2009;
    static constexpr int mod1 = 1000000007, mod2 = 1000000009;
    vector<long long> hash1, hash2, power1, power2;
    int n;
    rolling_hash(string &S) {
        n = (int) S.size();
        hash1.assign(n + 1, 0);
        hash2.assign(n + 1, 0);
        power1.assign(n + 1, 1);
        power2.assign(n + 1, 1);
        for (int i = 0; i < n; ++i) {
            hash1[i + 1] = (hash1[i] * base1 + S[i]) % mod1;
            hash2[i + 1] = (hash2[i] * base2 + S[i]) % mod2;
            power1[i + 1] = (power1[i] * base1) % mod1;
            power2[i + 1] = (power2[i] * base2) % mod2;
        }
    }
    template<class T> rolling_hash(vector<T> &S) {
        n = (int) S.size();
        hash1.assign(n + 1, 0);
        hash2.assign(n + 1, 0);
        power1.assign(n + 1, 1);
        power2.assign(n + 1, 1);
        for (int i = 0; i < n; ++i) {
            hash1[i + 1] = (hash1[i] * base1 + S[i]) % mod1;
            hash2[i + 1] = (hash2[i] * base2 + S[i]) % mod2;
            power1[i + 1] = (power1[i] * base1) % mod1;
            power2[i + 1] = (power2[i] * base2) % mod2;
        }
    }
    inline pair<int, int> get(int l, int r) {
        long long res1 = hash1[r] - hash1[l] * power1[r - l] % mod1;
        if (res1 < 0) res1 += mod1;
        long long res2 = hash2[r] - hash2[l] * power2[r - l] % mod2;
        if (res2 < 0) res2 += mod2;
        return {res1, res2};
    }
    inline pair<int, int> operator()(int l, int r) { return get(l, r); }
    inline pair<int, int> operator()() { return get(0, n); }
    // get lcp of S[a:] and T[b:]
    //接頭語がどれだけ一致するか
    //範囲の重複を含む
    inline int lcp_dup(int a, int b) {
        int len = min((int) hash1.size() - a, (int) hash1.size() - b);
        int low = 0, high = len;
        while (high - low > 1) {
            int mid = (low + high) >> 1;
            if (get(a, a + mid) != get(b, b + mid)) high = mid; else low = mid;
        }
        return low;
    }
    //重複を認めない
    inline int lcp_not(int a, int b) { return min(lcp_dup(a, b), b - a); }//@formatter:on
};

//安全で爆速なrollinghash
class roll {
    static constexpr uint64_t base = 5;//他のロリハとhashを共有したい場合
//    const uint64_t base = rand((uint64_t) 2, mask61 - 1);//共有したくない場合
    static constexpr uint64_t mask30 = ((uint64_t)1 << 30) - 1;
    static constexpr uint64_t mask31 = ((uint64_t)1 << 31) - 1;
    static constexpr uint64_t mask61 = ((uint64_t)1 << 61) - 1;
    static constexpr uint64_t offset = mask61 * 7;
    static constexpr uint64_t mod(const uint64_t x){        const uint64_t y = (x >> 61) + (x & mask61);        return y >= mask61 ? y - mask61 : y;    }
    static constexpr uint64_t mul(const uint64_t x, const uint64_t y)    {        const uint64_t xh = x >> 31, xl = x & mask31;        const uint64_t yh = y >> 31, yl = y & mask31;        const uint64_t z  = xl * yh + xh * yl;        const uint64_t zh = z >> 30, zl = z & mask30;        return xh * yh * 2 + zh + (zl << 31) + xl * yl;    }
    const std::size_t siz;
    vector<uint64_t> pow, h;
public:
    template<typename T>roll(T &A) : siz(sz(A)), pow(siz + 1, 1), h(siz + 1, 0) {for (std::size_t i = 1; i <= siz; i++) {pow[i] = mod(mul(pow[i - 1], base)), h[i] = mod(mul(h[i - 1], base) + A[i-1]);}}
    uint64_t operator()(const std::size_t l, const std::size_t r) { return mod(h[r] + offset - mul(h[l], pow[r - l])); }
    uint64_t operator()(int r = inf){return operator()(0,min(siz,r));}
    // get lcp of S[a:] and T[b:]
    //接頭語がどれだけ一致するか
    //範囲の重複を含む
    inline int lcp_dup(int a, int b) {        int len = min((int) siz - a, (int) siz - b);        int low = 0, high = len;        while (high - low > 1) {            int mid = (low + high) >> 1;            if (operator()(a, a + mid) != operator()(b, b + mid)) high = mid; else low = mid;        }        return low;    }
    //重複を認めない
    inline int lcp_not(int a, int b) { return min(lcp_dup(a, b), b - a); }//@formatter:on
};
