#define MOD  (793512LL)
#define MLT  (5173LL)

bool check_period(const V<ll> &xlist, ll n, ll div)
{
    rep (base, div) {
        srep (i, 1, n / div) {
            if (xlist[base] != xlist[base+i*div]) return false;
        }
    }

    return true;
}

ll init_hash(const V<ll> &xlist, ll period)
{
    ll ret = 0LL;
    ll mlt = 1LL;

    rep (i, period) {
        ret += xlist[i] * mlt;
        ret %= MOD;
        mlt *= MLT;
        mlt %= MOD;
    }

    return ret;
}

bool cmp(const V<ll> &clist, const V<ll> &dlist, ll period, ll shift)
{
    rep (i, period) {
        ll ic = (i + shift) % period;
        ll id = i;
        if (clist[ic] != dlist[id]) return false;
    }

    return true;
}

void _main();
int main()
{
    cout << setprecision(12);
    _main();
    return 0;
}

void _main()
{
    ll n; llin(n);
    V<ll> alist; llina(alist, n);
    V<ll> blist; llina(blist, n);

    V<ll> clist;
    rep (i, n) {
        ll i0 = i;
        ll i1 = (i + 1) % n;
        clist.pb(alist[i0] ^ alist[i1]);
    }

    V<ll> dlist;
    rep (i, n) {
        ll i0 = i;
        ll i1 = (i + 1) % n;
        dlist.pb(blist[i0] ^ blist[i1]);
    }

    V<ll> divs;
    get_divisors(divs, n);
    set<ll> divset;
    for (auto div : divs) divset.insert(div);
    ll period = n;

    for (auto div : divset) {
        bool cflag = check_period(clist, n, div);
        bool dflag = check_period(dlist, n, div);
        if (cflag && dflag) {
            period = div;
            break;
        }
    }

    ll coef = 1LL;
    rep (i, period) {
        coef *= MLT;
        coef %= MOD;
    }

    ll chash = init_hash(clist, period);
    ll dhash = init_hash(dlist, period);
    ll shift = -1LL;

    rep (lshift, period) {
        if (chash == dhash) {
            if (cmp(clist, dlist, period, lshift)) {
                shift = lshift;
                break;
            }
        }
        dhash *= MLT;
        dhash %= MOD;
        dhash += dlist[n-lshift-1LL];
        dhash %= MOD;
        dhash -= (dlist[n-lshift-1LL] * coef) % MOD;
        while (dhash < 0LL) dhash += MOD;
    }

    debug_printf("period=%lld shift=%lld\n", period, shift);

    if (shift < 0LL) {
        cout << endl;
        return;
    }

    rep (i, n) {
        ll idx = shift + i * period;
        if (idx >= n) break;
        printf("%lld %lld\n", idx, alist[idx] ^ blist[0]);
    }
}

