        string as = "", bs = "", bs2 = "";
        for (int j = 0; j < n; ++j) {
            as += (a[j] >> i & 1 ? '1' : '0');
            bs += (b[j] >> i & 1 ? '1' : '0');
            bs2 += (b[j] >> i & 1 ? '0' : '1');
        }
        as += as;

        KMP kmp(bs);
        vector<int> ids;
        kmp.search(as, ids);
        vector<int> hoge(n, -1);
        for (int j : ids) {
            if (j >= n) break;
            if (ans[j] == -1) continue;
            hoge[j] = 0;
        }

