vector<int> k(vector<int> a, vector<int> b) {
	vector<int> s;
	for (int x : b) {
		s.push_back(x);
	}
	for (int x : a) {
		s.push_back(x);
	}
	for (int x : a) {
		s.push_back(x);
	} 
	int n = sz(s);
	vector<int> z(n, 0);
	for (int i = 1, l = 0, r = 0; i < n; ++i) {
		if (i <= r) {
			z[i] = min(z[i - l], r - i + 1);
		} 
		while (i + z[i] < n && s[i + z[i]] == s[z[i]]) {
			++z[i];
		} 
		if (i + z[i] - 1 > r) {
			l = i;
			r = i + z[i] - 1;
		} 
	} 
	vector<int> res;
	for (int k = 0; k < sz(a); ++k) {
		if (z[sz(b) + k] >= sz(b)) {
			res.push_back(k);
		} 
	} 
	return res;
}

