struct RollingHash {
	static const int base1 = 1007, base2 = 2009;
	static const int mod1 = 1000000007, mod2 = 1000000009;
	vector<long long> hash1, hash2;
	string S;
	int idx;
	long long pow1, pow2;

	// construct
	RollingHash(const string &S):S(S),idx(0) {
		int n = (int)S.size();
		hash1.assign(n + 1, 0);
		hash2.assign(n + 1, 0);
		for (int i = 0; i < n; ++i) {
			hash1[i + 1] = (hash1[i] * base1 + S[i]) % mod1;
			hash2[i + 1] = (hash2[i] * base2 + S[i]) % mod2;
		}
		pow1 = modpow(base1, SZ(S) - 1, mod1);
		pow2 = modpow(base2, SZ(S) - 1, mod2);
	}

	void Shift()
	{
		hash1[SZ(S)] = (hash1[SZ(S)] - ((S[idx] * pow1) % mod1) + mod1) % mod1;
		hash1[SZ(S)] *= base1;
		hash1[SZ(S)] %= mod1;
		hash1[SZ(S)] += S[idx];
		hash1[SZ(S)] %= mod1;

		hash2[SZ(S)] = (hash2[SZ(S)] - ((S[idx] * pow2) % mod2) + mod2) % mod2;
		hash2[SZ(S)] *= base2;
		hash2[SZ(S)] %= mod2;
		hash2[SZ(S)] += S[idx];
		hash2[SZ(S)] %= mod2;
		idx++;
	}
};

