const ll MAX_N = 200005;
bool okay = false;
ll answer = 0;
ll n;
vl as, bs, ab;
vpl ans;

vl z_algorithm(const vl &s){
    ll n = s.size(); vl res(n);
    res[0] = n;
    ll i1 = 1, i2 = 0;

    while(i1 < n){
        while (i1 + i2 < n && s[i2] == s[i1 + i2]) ++i2;
        res[i1] = i2; if (i2 == 0){++i1; continue;}
        ll i3 = 1;

        while (i1 + i3 < n && i3 + res[i3] < i2){res[i1 + i3] = res[i3]; ++i3;}
        i1 += i3, i2 -= i3;
    }
    return res;
}

void solve(){
    as = bs = vl(n);
    rep(i, n) in1(as[i]);
    rep(i, n) in1(bs[i]);

    ab = vl(n * 3);
    rep(i, n){
        ab[i] = (bs[i] ^ bs[(i + 1) % n]);
        ab[n + i] = (as[i] ^ as[(i + 1) % n]);
        ab[2 * n + i] = ab[n + i];
    }

    vl ret = z_algorithm(ab);
    rep(k, n){
        ll x = bs[0] ^ as[k];
        if (ret[n + k] >= n) ans.pb({k, x});
    }

    rep(i, ans.size())
        prl2(ans[i].e1, ans[i].e2);
}

int main(void){
    in1(n);
    // assert(k <= 100000);
    solve();
    return 0;
}

