vector<int> get(vector<int>& a) {
	int l = 0, r = 0;
	vector<int> z(a.size());
	for (int i = 1; i < a.size(); i++) {
		if (r >= i) {
			z[i] = min(z[i - l], r - i + 1);
		}
		while (i + z[i] < a.size() && a[i + z[i]] == a[z[i]]) {
			z[i]++;
		}
		if (i + z[i] - 1 > r) {
			l = i;
			r = i + z[i] - 1;
		}
	}
	return z;
}

void solve() {
	int n;
	cin >> n;
	vector<int> a(n), b(n);
	for (int i = 0; i < n; i++) {
		cin >> a[i];
	}
	for (int i = 0; i < n; i++) {
		cin >> b[i];
	}

	vector<int> one(n - 1), two(n - 1);
	for (int i = 0; i < n - 1; i++) {
		one[i] = a[i] ^ a[i + 1];
		two[i] = b[i] ^ b[i + 1];
	}
	one.pb(a[n - 1] ^ a[0]);
	two.pb(b[n - 1] ^ b[0]);
	vector<int> q = two;
	q.pb(-1);
	for (int i : one) q.pb(i);
	for (int i : one) q.pb(i);

	vector<int> z = get(q);
	vector<pair<int, int>> ans;
	for (int i = n + 1; i <= 2 * n; i++) {
		if (z[i] >= n) {
			ans.pb({ i - n - 1, a[i - n - 1] ^ b[0]});
		}
	}
	for (auto& p : ans) {
		cout << p.first << " " << p.second << '\n';
	}
}

