  REP(i, N) Ax[i] = A[i] ^ A[(i+1)%N];
  REP(i, N) Ax[i+N] = Ax[i];
  REP(i, N) Bx[i] = B[i] ^ B[(i+1)%N];

  RollingHash AA(2*N, Ax);
