class KMP {
  private:
    int len;

    /// @details pat 検索したいパターン
    VL pat;

    // table to use kmp
    vector<int> table;

  public:
    /// @param _pat 検索したいパターン
    KMP(const VL _pat) {
        len = _pat.size();
        pat = _pat;
        table = vector<int>(len + 1);
        make_table();
    }

    /// @details S[0, i)の文字列の 接頭辞と接尾辞の最大の共通の長さ(min(i-1))
    void make_table() {
        table[0] = -1;
        int j = -1;
        for(int i = 0; i < len; i++) {
            while(j >= 0 && pat[i] != pat[j]) j = table[j];
            table[i + 1] = ++j;
        }
    }

    /// @param S patが含まれる文字列
    /// @details pstがSに含まれる位置のvectorを返す
    vector<int> kmp(const VL &S) {
        vector<int> ret;
        int m = 0, i = 0, n = S.size();
        while(m + i < n) {
            if(pat[i] == S[m + i]) {
                if(++i == len) {
                    ret.push_back(m);
                    m = m + i - table[i];
                    i = table[i];
                }
            } else {
                m = m + i - table[i];
                if(i > 0) i = table[i];
            }
        }
        return ret;
    }

    /// @param S patが含まれる文字列
    /// @details pstがSに含まれる最初の位置を返す -1は含まれない
    int contain(const VL &S) {
        int m = 0, i = 0, n = S.size();
        while(m + i < n) {
            if(pat[i] == S[m + i]) {
                if(++i == len) {
                    return m;
                }
            } else {
                m = m + i - table[i];
                if(i > 0) i = table[i];
            }
        }
        return -1;
    }

    void show_table() {
        printf("i:");
        for(int i = 0; i <= len; i++) printf("%3d ", i);
        printf("\n");
        printf("R:");
        for(int i = 0; i <= len; i++) printf("%3d ", table[i]);
        printf("\n");
    }
};
void solve() {
    LCIN(N);
    VL a(N), b(N);
    VECCIN(a);
    VECCIN(b);
    VL dif;
    REP(i, N - 1) dif.emplace_back(b[i] ^ b[i + 1]);
    KMP kmp(dif);
    VL aa;
    REP(i, 2 * N) { aa.emplace_back(a[i % N] ^ a[(i + 1) % N]); }
    VL res = kmp.kmp(aa);
    VPL ans;
    FOREACH(idx, res) if(idx <= N - 1) ans.emplace_back(idx, a[idx] ^ b[0]);
    REP(i, sz(ans)) { COUT(ans[i].fi, ans[i].second); }
}

