#define sc second

const LL MOD = 1e9+7;


struct RollingHash {
    const int base = 9973;
    const int mod[2] = {999999937, 1000000007};
    vector<int> s;
    vector<LL> hash[2], pow[2];

    RollingHash(const vector<int> &cs) : s(cs) {
        int n = s.size();
        for (int id = 0; id < 2; ++id) {
            hash[id].assign(n+1, 0);
            pow[id].assign(n+1, 1);
            for (int i = 0; i < n; ++i) {
                hash[id][i+1] = (hash[id][i] * base + s[i]) % mod[id];
                pow[id][i+1] = pow[id][i] * base % mod[id];
            }
        }
    }

    // get hash of s[l:r)
    LL get(int l, int r, int id = 0) {
        LL res = hash[id][r] - hash[id][l] * pow[id][r-l] % mod[id];
        if (res < 0) res += mod[id];
        return res;
    }
};

int main()
{
    cin.tie(0);
    ios::sync_with_stdio(false);

    int N; cin >> N;
    vector<LL> a(N), b(N);
    cin >> a >> b;

    map<LL,int> mp;
    for (int i = 0; i < N; ++i) {
        mp[a[(i+1)%N] ^ a[i]];
        mp[b[(i+1)%N] ^ b[i]];
    }
    int cnt = 0;
    for (auto& p: mp) {
        p.sc = cnt++;
    }

    vector<int> A(2*N), B(N);
    for (int i = 0; i < 2*N; ++i) {
        A[i] = mp[a[(i+1)%N] ^ a[i%N]];
    }
    for (int i = 0; i < 2*N; ++i) {
        B[i] = mp[b[(i+1)%N] ^ b[i]];
    }

    RollingHash r1(A), r2(B);
    vector<pair<int,LL>> ans;
    for (int k = 0; k < N; ++k) {
        if (r1.get(k,k+N,0) == r2.get(0,N,0) &&
            r1.get(k,k+N,1) == r2.get(0,N,1)) {
            ans.push_back({k, a[k] ^ b[0]});
        }
    }

    for (auto& p : ans) {
        cout << p.fs << " " << p.sc << endl;
    }
    return 0;
}

