const int MAXN = 2 * 105000;

int n;
int a[MAXN], b[MAXN];
int an[MAXN], bn[MAXN];
int sLen;
int s[4 * MAXN];
int p[4 * MAXN];

int main() { 

  scanf("%d", &n);
  for (int i = 0; i < n; i++) {
    scanf("%d", &a[i]);
  }
  for (int i = 0; i < n; i++) {
    scanf("%d", &b[i]);
  }

  for (int i = 0; i < n; i++) {
    an[i] = a[i] ^ a[(i + 1) % n];
  }

  for (int i = 0; i < n; i++) {
    bn[i] = b[i] ^ b[(i + 1) % n];
  }

  sLen = 3 * n + 1;
  for (int i = 0; i < n; i++) {
    s[i] = bn[i];
  }
  s[n] = -1;
  for (int i = 0; i < n; i++) {
    s[n + 1 + i] = an[i];
  }
  for (int i = 0; i < n; i++) {
    s[2 * n + 1 + i] = an[i];
  }

  for (int i = 2; i <= sLen; i++) {
    int prev = p[i - 1];
    while (prev > 0 && s[prev] != s[i - 1])
      prev = p[prev];
    if (s[prev] == s[i - 1])
      prev++;
    p[i] = prev;
  }

  for (int i = n + 1; i < sLen; i++) {
    if (p[i] == n) {
      cout << i - (2 * n + 1) << " " << (a[i - (2 * n + 1)] ^ b[0]) << endl;
