long double tolerance(const long double& a, const long double& b, const long double& epsilon = eps) {
    return epsilon * max({1.l, abs(a), abs(b)});
}

// a<0なら-1, a==0なら0, a>0なら1
int sgn(const long double a, const long double& epsilon = eps) {
    return (a > epsilon) - (a < -epsilon);
}

// a<bなら-1, a==bなら0, a>bなら1
int compare(const long double& a, const long double& b, const long double& epsilon = eps, bool is_relative = true) {
    return sgn(a - b, is_relative ? tolerance(a, b, epsilon) : epsilon);
}

// a==bか?
bool is_equal(const long double& a, const long double& b, const long double& epsilon = eps, bool is_relative = true) {
    return compare(a, b, epsilon, is_relative) == 0;
}

// a<bか?
bool is_less(const long double& a, const long double& b, const long double& epsilon = eps, bool is_relative = true) {
    return compare(a, b, epsilon, is_relative) == -1;
}

// a<=bか?
bool is_less_or_equal(const long double& a, const long double& b, const long double& epsilon = eps, bool is_relative = true) {
    return compare(a, b, epsilon, is_relative) <= 0;
}

// a>bか?
bool is_greater(const long double& a, const long double& b, const long double& epsilon = eps, bool is_relative = true) {
    return compare(a, b, epsilon, is_relative) == 1;
}

// a>=bか?
bool is_greater_or_equal(const long double& a, const long double& b, const long double& epsilon = eps, bool is_relative = true) {
    return compare(a, b, epsilon, is_relative) >= 0;
}

template<typename T>
struct rolling_hash {
    int mnum;
    T s;
    i64 base;
    std::vector<i64> mod;
    std::vector<vector<i64>> hash, pow;

    rolling_hash(const T& s, i64 base = 9973, std::vector<i64> mod = {999999937LL, 1000000007LL}) : mnum(mod.size()), s(s), base(base), mod(mod) {
        int size = s.size();
        hash = std::vector<std::vector<i64>>(mnum, std::vector<i64>(size + 1));
        pow = std::vector<std::vector<i64>>(mnum, std::vector<i64>(size + 1));

        for (int i = 0; i < mnum; ++i) {
            hash[i][0] = 0;
            pow[i][0] = 1;
        }
        for (int i = 0; i < mnum; ++i) {
            i64 m = mod[i];
            for (int j = 1; j < size + 1; ++j) {
                pow[i][j] = pow[i][j - 1] * base % m;
                hash[i][j] = (hash[i][j - 1] * base + s[j - 1]) % m;
            }
        }
    }

    i64 compute_hash(int l, int r, int i /* 何番目のmodにおけるハッシュを計算するか */) {  //[l,r)
        return (hash[i][r] - hash[i][l] * pow[i][r - l] % mod[i] + mod[i]) % mod[i];
    }

    // [l, r)を左方向に指定された回数だけ回転させた文字列のハッシュを計算する.
    i64 left_rotated_hash(int l,int r,int i /* 何番目のmodにおけるハッシュを計算するか */,int rotation /* 左方向に回転する回数 */){
        return (compute_hash(l,l+rotation,i)+compute_hash(l+rotation,r,i)*pow[i][rotation]%mod[i])%mod[i];
    }

    bool match(int l, int r, const std::vector<i64> &hs) {
        for (int i = 0; i < mnum; ++i)
            if (compute_hash(l, r, i) != hs[i]) return false;
        return true;
    }
};

typedef unsigned long long int ull;

void solve() {
    //constexpr i64 mod = 1'000'000'007;
    i64 N;
    cin >> N;

    vector<i64> a(N),b(N);
    rep(i,0,N) cin >> a[i];
    rep(i,0,N) cin >> b[i];

    vector<i64> s(N),t(N);
    rep(i,0,N) s[i]=a[i]^a[(i+1)%N];
    rep(i,0,N) t[i]=b[i]^b[(i+1)%N];

    rolling_hash<vector<i64>> sh(s),th(t);

    auto calc_hs=[&](i64 k){
        vector<i64> hs;
        rep(i, 0, sh.mod.size()) {
            hs.emplace_back(sh.left_rotated_hash(0,N,i,k));
        }
        return hs;
    };

    vector<i64> ks;
    rep(k,0,N){
        auto hs=calc_hs(k);
        if(th.match(0, N, hs)) ks.emplace_back(k);
    }

    vector<i64> xs(ks.size());
    rep(i,0,ks.size()){
        xs[i]=a[ks[i]]^b[0];
    }

    rep(i,0,ks.size()){
        cout << ks[i] << " " << xs[i] << endl;
    }
}

