  ll ans=1LL,aa=a,beki=n;
  for(int i=0;i<64;i++){
    if (beki%2==1) ans=ans*aa%MOD;
    aa=aa*aa%MOD;
    beki/=2;
    if (beki==0)break;
  }
  return ans;
}


const ll HASH_P=2013265921;
const ll HASH_Wn=52278;
void makehash(vector<ll> &array,vector<ll> &outarray)
{
  ll asz=array.size();

  ll alast=0;
  ll wi=1;
  for(ll i=0;;i++){
    i%=asz;
    alast=(alast+array[(asz-1+i)%asz]%HASH_P*wi)%HASH_P;
    if (i==asz-1)break;
    wi*=HASH_Wn;
    wi%=HASH_P;
  }
  outarray[asz-1]=alast;

  for(ll i=asz-2;i>=0;i--){
    outarray[i]=(((outarray[i+1]-array[i]*wi)%HASH_P)*HASH_Wn%HASH_P+array[i]+HASH_P)%HASH_P;
  }
}




