using namespace std;
using namespace boost;
using namespace boost::adaptors;

int64_t period(const vector<uint64_t>& s) {
    constexpr auto B1 = 100000007L;
    constexpr auto B2 = 1000000007L;

    uint64_t m = s.size();

    uint64_t pow_B_m_1 = 1, pow_B_m_2 = 1;
    for (uint64_t k = 0; k < m; k++) {
        pow_B_m_1 *= B1, pow_B_m_2 *= B2;
    }

    uint64_t h1 = 0, h2 = 0;
    for (uint64_t k = 0; k < m; k++) {
        h1 = h1 * B1 + s[k];
        h2 = h2 * B2 + s[k];
    }

    uint64_t s1 = h1, s2 = h2;
    for (uint64_t k = 1; k < m; ++k) {
        s1 = s1 * B1 + s[(m + k) % m] - s[(m + k) % m] * pow_B_m_1;
        s2 = s2 * B2 + s[(m + k) % m] - s[(m + k) % m] * pow_B_m_2;

        if (h1 == s1 && h2 == s2) {
            return k;
        }
    }

    return m;
}

int main() {
    int64_t n;
    cin >> n;

    vector<uint64_t> a(n), b(n);
    for (auto i : irange(0L, n)) {
        cin >> a[i];
    }
    for (auto i : irange(0L, n)) {
        cin >> b[i];
    }

    for (auto i : irange(0L, n)) {
        uint64_t x = a[i] ^ b[0];

        bool ok = true;
        for (auto j : irange(1L, n)) {
            if ((a[(j + i) % n] ^ x) != b[j]) {
                ok = false;
                break;
            }
        }
        if (ok) {
            auto p = period(a);
            if (p % 2 == 0) {
                p /= 2;
            }
            cout << i << " " << (a[i] ^ b[0]) << endl;
            if (p <= n) {
                for (auto j : irange(1L, n / p)) {
                    cout << i + j * p << " " << (a[i + j * p] ^ b[0]) << endl;
                }
            }
            return 0;
        }
    }
}

