vector<ll>prefix_function(vector<ll> s) {
	vector<ll> p(s.size());
	ll n = s.size();
	for (ll i = 1; i < n; i++) {
		ll j = p[i - 1];
		while (s[j] != s[i] && j > 0) {
			j = p[j - 1];
		}
		if (s[i] == s[j]) {
			j++;
		}
		p[i] = j;
	}
	return p;
}

void inter(unordered_set<ll> &s1, unordered_set<ll> &s2) {
	vector<ll>to_del;
	for (auto x : s1) {
		if (!s2.count(x)) {
			to_del.push_back(x);
		}
	}
	for (auto x : to_del) {
		s1.erase(x);
	}
}

