    vector<int64_t> k;
    int64_t idx = -1;
    const auto& t = prekmp(d);
    while ((idx = kmp(c, d, t, idx)) >= 0) {
        k.push_back(idx);
    }

    for (auto kk : k) {
        cout << kk << " " << (a[kk] ^ b[0]) << "\n";
    }
}

