template <typename T>
std::vector<int> prefix_function(const T& s) {
    std::vector <int> ans = {0};
    int k = 0;
    for (int i = 1; i < s.size(); i++) {
        while (k > 0 && s[k] != s[i]) {
            k = ans[k - 1];
        }
        k += (s[k] == s[i]);
        ans.push_back(k);
    }
    return ans;
}


