void solve() {
    in(N);
    na(A, N);
    na(B, N);
    auto ta = A, tb = B;
    A *= 3;
    B *= 3;
    rep(i, N * 3 - 1) {
        A[i] ^= A[i + 1];
        B[i] ^= B[i + 1];
    }
    roll ra(A), rb(B);
    deb(A);
    deb(B);
    rep(k, N) {
        if (ra(k, k + N) == rb(0, N)) {
            out(k, ta[k] ^ tb[0]);
        }
    }
}

