void getnxt(int bt) {
	memset(nxt, 0, sizeof(nxt));
	for(int i = 2, j = 0; i <= n; ++i) {
		while(j && bit(a[j + 1]) != bit(a[i]))
			j = nxt[j];
		if(bit(a[j + 1]) == bit(a[i])) j++;
		nxt[i] = j;
	}
}
void kmp(int bt) {
	getnxt(bt);
	for(int i = 1, j = 0; i < 2 * n; ++i) {
		while(j && bit(b[i]) != bit(a[j + 1]))
			j = nxt[j];
		if(bit(b[i]) == bit(a[j + 1])) j++;
		if(j == n) {
			cnt[i - n + 1]++;
			j = nxt[j];
		}
	}
	for(int i = 1, j = 0; i < 2 * n; ++i) {
		while(j && bit(b[i]) != !bit(a[j + 1]))
			j = nxt[j];
		if(bit(b[i]) == !bit(a[j + 1])) j++;
		if(j == n) {
			cnt[i - n + 1]++;
			j = nxt[j];
		}
	}
}
