    mint operator-() const { return mint(-x);}
    mint& operator+=(const mint a) {
        if ((x += a.x) >= MOD) x -= MOD;
        return *this;
    }
    mint& operator-=(const mint a) {
        if ((x += MOD-a.x) >= MOD) x -= MOD;
    	return *this;
    }
    mint& operator*=(const mint a) {
    	(x *= a.x) %= MOD;
    	return *this;
    }
    mint operator+(const mint a) const {
        mint res(*this);
        return res+=a;
    }
    mint operator-(const mint a) const {
        mint res(*this);
        return res-=a;
    }
    mint operator*(const mint a) const {
        mint res(*this);
        return res*=a;
    }
    mint pow(long long t) const {
        if (!t) return 1;
        mint a = pow(t>>1);
        a *= a;
    	if (t&1) a *= *this;
        return a;
    }
    // for prime MOD
    mint inv() const {
        return pow(MOD-2);
    }
    mint& operator/=(const mint a) {
    	return (*this) *= a.inv();
    }
    mint operator/(const mint a) const {
        mint res(*this);
        return res/=a;
    }
};

int main(void){
    ll base = 2;
    int N; cin >> N;
    VI a(N), b(N); REP(i,N) cin >> a[i]; REP(i,N) cin >> b[i];
    vector<mint> Ha(30), Hra(30), Hb(30);
    vector<mint> p(N);
    p[0] = 1; REP(i,N-1) p[i+1] = p[i]*base;
    REP(i,30){
        REP(j,N) Ha[i] += p[j]*((a[j]>>i) & 1);
        REP(j,N) Hra[i] += p[j]*(((a[j]>>i) & 1)^1);
        REP(j,N) Hb[i] += p[j]*((b[j]>>i) & 1);
    }

    vector<P> ans;
    REP(k,N){
        REP(i,30){
            Ha[i] -= p[N-1]*((a[N-1-k]>>i) & 1);
            Ha[i] *= base;
            Ha[i] += (a[N-1-k]>>i) & 1;
            Hra[i] -= p[N-1]*(((a[N-1-k]>>i) & 1)^1);
            Hra[i] *= base;
            Hra[i] += ((a[N-1-k]>>i) & 1)^1;
        }
        int x = 0;
        bool flag = true;
        REP(i,30){
            if(Ha[i].x == Hb[i].x) continue;
            else if(Hra[i].x == Hb[i].x) x += 1<<i;
            else{
                flag = false;
                break;
            }
        }
        if(flag){
            ans.emplace_back(N-1-k, x);
        }
    }

    SORT(ans);
    REP(i,ans.size()) cout << ans[i].first << " " << ans[i].second << en;
    return 0;
}

