//text内でpatternに一致する文字列の先頭のインデックスすべてを返す
vector<int> kmp(const vi &text, const vi &pattern) {
    int pN = pattern.size(), tN = text.size();
    vector<int> table(pN + 1);
    table[0] = -1;
    int j = -1;
    for (int i = 0; i < pN; i++) {
        while (j >= 0 && pattern[i] != pattern[j])
            j = table[j];
        j++;
        if (pattern[i + 1] == pattern[j])
            table[i + 1] = table[j];
        else
            table[i + 1] = j;
    }
    int i = 0;
    j = 0;
    vi res;
    while (j < tN) {
        while (i > -1 && pattern[i] != text[j])
            i = table[i];
        i++;
        j++;
        if (i >= pN) {
            res.push_back(j - i);
            i = table[i];
        }
    }
    return res;
}

