template<typename E>
struct SeqSearchTable {
	vector<E> v;
	vector<UL> t;
	SeqSearchTable(vector<E> seq) { init(move(seq)); }
	void init(vector<E> seq) {
		v = move(seq);
		t.resize(v.size());
		t[0] = (UL)-1;
		UL p = 1, q = -1;
		while (p < v.size()) {
			if (q == (UL)-1) { t[p] = 0; p++; q = 0; }
			else if (v[q] == v[p - 1]) { t[p] = t[p - 1] + 1; p++; q++; }
			else { q = t[q]; }
		}
	}
};
template<typename E>
struct SeqSearch {
	vector<UL> query(const vector<E> &seq, const SeqSearchTable<E> &tg) {
		vector<UL> f;
		UL p = 0, q = 0;
		while (p < seq.size()) {
			if (seq[p] == tg.v[q]) {
				p++; q++;
				if (q == tg.v.size()) {
					f.push_back(p - tg.v.size());
					q = tg.t[q - 1] + 1;
				}
			}
			else {
				q = tg.t[q];
				if (q == (UL)-1) { p++; q = 0; }
			}
		}
		return move(f);
	}
};

