// 前計算 [0-i)の接頭辞と接尾辞が何文字まであっているか
vector<ll> makeTable(vector<ll> s) {
    ll n = s.size();
    vector<ll> ret(n+1);
    ret[0] = -1;
    ll j = -1;
    rep(i,n){
        while ( j>=0 and s[i]!=s[j] ) j = ret[j];
        ret[i+1] = ++j;
    }
    return ret;
}
// str の中に word と一致する場所を返す
vector<ll> kmp(vector<ll>& str, vector<ll>& word) {
    vector<ll> table = makeTable(word), ret;
    ll m=0, i=0, n=str.size();
    while ( m+i < n) {
        if (word[i] == str[m+i]) {
            if (++i == (ll)(word.size())) {
                ret.emplace_back(m);
                m = m+i-table[i];
                i = table[i];
            }
        }
        else{
            m = m+i-table[i];
            if (i > 0) i = table[i];
        }
    }
    return ret;
}

