#include <bits/stdc++.h>

using namespace std;

#define REP(i,n) for(int i = 0; i < (int)(n); i++)

vector<int> solve(vector<int> a, vector<int> b, int n){
  REP(i, n){
    b.push_back(b[i]);
  }
  a.push_back(2);
  vector<int> e;
  vector<int> t(n + 1);
  t[0] = -1, t[1] = 0;
  int p = 2;
  int q = 0;
  while(p < n + 1){
    if(a[p - 1] == a[q]){
      t[p++] = ++q;
    }else if(q > 0){
      q = t[q];
    }else{
      t[p++] = 0;
    }
  }
  int m = 0;
  p = 0;
  while(m + p < 2 * n){
    if(a[p] == b[m + p]){
      ++p;
    }else{
      m += p - t[p];
      if(p > 0){
        p = t[p];
      }
    }
    if(p == n){
      e.push_back(m);
    }
  }
  return e;
}

