//pre[i]: length of longest proper prefix of the prefix of 
//p of length i that is also a suffix
int pre[N]; //prefix function

void preprocess(vi& p) {
    int m = p.size();
    pre[1] = 0;
    int k = 0; //widest border of the previous string
    for(int i=2; i<=m; i++) {
        while(k > 0 && p[k] != p[i-1])
            k = pre[k];
        if(p[k] == p[i-1])
            k++;
        pre[i] = k;
    }
}

vector<int> kmp(vi& t, vi& p) {
    vector<int> v;
    int n = t.size(), m = p.size();

    preprocess(p);

    int q = 0; //number of chars matched so far
    for(int i=0; i<n; i++) {
        //db(i), db(q);
        while(q > 0 && p[q] != t[i])
            q = pre[q];
        if(p[q] == t[i])
            q++;
        if(q == m) {
            v.push_back(i - m + 1);
            q = pre[q];
        }
    }
    return v;
}

