vector<int> to_xor(vector<int> x)
{
    int n = x.size();
    vector<int> ret(n);
    for (int i = 0; i < n; i++)
    {
        ret[i] = x[i] ^ x[(i + 1) % n];
    }
    return ret;
}

template <typename T>
struct MP
{
    int n;
    T t;
    vector<int> a;
    MP() {}
    MP(const T &t) : t(t)
    {
        n = t.size();
        a = vector<int>(n + 1);
        a[0] = -1;
        int j = -1;
        for (int i = 0; i < n; ++i)
        {
            while (j != -1 && t[j] != t[i])
                j = a[j];
            j++;
            a[i + 1] = j;
        }
    }
    int operator[](int i) { return a[i]; }
    vector<int> find_from(const T &s)
    {
        vector<int> res;
        int j = 0;
        for (int i = 0; i < s.size(); ++i)
        {
            while (j != -1 && t[j] != s[i])
                j = a[j];
            j++;
            if (j == n)
            {
                res.push_back(i - j + 1);
                j = a[j];
            }
        }
        return res;
    }
};

