#include <bits/stdc++.h>
using namespace std;

bitset <200010> ans, tmp;
int a[200010], b[200010];
int z[400010], s[400010];
int val[200010];
int n;

void get_z() {
	int L = 0, R = 0;
	for (int i = 1; i < 3 * n; i++) {
		if (i > R) {
			L = R = i;
			while (R < 3 * n && s[R - L] == s[R]) R++;
			z[i] = R - L, R--;
			continue;
		}
		if (i + z[i - L] - 1 < R) {
			z[i] = z[i - L];
			continue;
		}
		L = i;
		while (R < 3 * n && s[R - L] == s[R]) R++;
		z[i] = R - L, R--;
	}
}

void solve(int k) {
	for (int i = 0; i < n; i++) {
		s[i] = a[i] >> k & 1;
	}
	for (int i = n; i < n * 3; i++) {
		s[i] = b[i % n] >> k & 1;
	}
	get_z(), tmp.reset();
	for (int i = n; i < n + n; i++) {
		if (z[i] >= n) tmp.set(i - n, 1);
	}
	for (int i = n; i < n * 3; i++) {
		s[i] ^= 1;
	}
	get_z();
	for (int i = n; i < n + n; i++) {
		if (z[i] >= n) tmp.set(i - n, 1), val[i - n] |= 1 << k;
	}
	ans &= tmp;
}

int main () {
	scanf("%d", &n);
	for (int i = 0; i < n; i++) {
		scanf("%d", &a[i]);
	}
	for (int i = 0; i < n; i++) {
		scanf("%d", &b[i]);
	}
	for (int i = 0; i < n; i++) {
		ans.set(i);
	}
	for (int i = 0; i < 30; i++) {
		solve(i);
	}
	if (ans[0]) printf("%d %d\n", 0, val[0]);
	for (int i = n - 1; i >= 1; i--) {
		if (ans[i]) {
			printf("%d %d\n", (n - i) % n, val[i]);
		}
	}
	return 0;
}

