	REPC(x, bv) { rab.emplace_back(x); }
	rab.emplace_back(-1);
	REPC(x, av) { rab.emplace_back(x); }
	auto rz = ZAlgorithm(rab).getZArray();

	REP(it, n) {
		ll rev = sz[n + it + 1];
