vector < int > preffix(vector < int > &a) {
	vector < int > pf(a.size(), 0);
	for(int i = 1; i < a.size(); i++) {
		int j = pf[i - 1];
		while(j > 0 && a[j] != a[i])
			j = pf[j - 1];
		if(a[j] == a[i])
			pf[i] = j + 1;
	}
	return pf;
}

vector < int > kmp(vector < int > &s, vector < int > &t) {
	vector < int > ans;
	auto pf = preffix(t);
	int j = 0;
	for(int i = 0; i < s.size(); i++) {
		while(j > 0 && s[i] != t[j])
			j = pf[j - 1];
		if(s[i] == t[j]) {
			j++;
			if(j == t.size()) {
				ans.push_back(i - j + 1);
				j = pf[j - 1];
			}
		}		
	}
	return ans;
}

