void pre()
{
	p_pwr[0].ff = 1; for (int i = 1; i < MAX_LEN; i++) p_pwr[i].ff = (1LL * p_pwr[i - 1].ff * p1) % mod1;
	p_pwr[0].ss = 1; for (int i = 1; i < MAX_LEN; i++) p_pwr[i].ss = (1LL * p_pwr[i - 1].ss * p2) % mod2;
}

inline int add(int a, int b, int &mod) { int res = a + b; if (res < 0) res += mod; return res >= mod ? res - mod : res; }
inline int mul(int a, int b, int &mod) { int res = (1LL * a * b) % mod;   return res; }
inline int getval(int x) {    return  x + 1;    } // check  it( x-'a'+1)

class hash_it {
public:
	static int cnt;
	int len, d; vector<pii> hashes;

	void init(int *s, int d1, int l)
	{
		len = l; d = d1;
		hashes.resize(len + 1);
		for (int i = 0, val1 = 0, val2 = 0; i < len; i++)
		{
			val1 = add(val1, mul( getval(s[i]), p_pwr[i].ff, mod1), mod1);       hashes[i].ff = val1;
			if (d) val2 = add(val2, mul( getval(s[i]), p_pwr[i].ss, mod2), mod2);         hashes[i].ss = val2;
		}
	}

	// return hash_multiplied by p^mxp, if want actual hash use h1.
	pii  get(int i,  int j)
	{
		pii v1 = {0, 0};
		v1.ff = mul( add(hashes[j].ff, -(i ? hashes[i - 1].ff : 0), mod1), p_pwr[mxp - i].ff, mod1);
		if (d)v1.ss = mul( add(hashes[j].ss, -(i ? hashes[i - 1].ss : 0), mod2), p_pwr[mxp - i].ss, mod2);
		return v1;
	}

};


