int KMP(const std::vector<int>& S, const std::vector<int>& W){
  std::vector<int> T(W.size());
  T[0] = -1;
  int i = 2, j = 0;
  while(i < W.size()){
    if(W[i-1] == W[j]){
      T[i] = j+1;
      i++;
      j++;
    }else if(j > 0){
      j = T[j];
    }else{
      T[i] = 0;
      i++;
    }
  }
  i = 0;
  int m = 0;
  while(m+i < S.size()){
    if(W[i] == S[m+i]){
      i++;
      if(i == W.size()) return m;
    }else{
      m = m+i-T[i];
      if(i > 0) i = T[i];
    }
  }
  return -1;
}

