  }
  i = 0;
  int m = 0;
  int ns = S.size();
  std::vector<int> ans(ns);
  while(m < ns){
    if(W[i] == S[(m+i)%ns]){
      i++;
      if(i == W.size()){
        i--;
        ans[m] = 1;
        m = m+i-T[i];
        if(i > 0) i = T[i];
      }
    }else{
      m = m+i-T[i];
      if(i > 0) i = T[i];
    }
  }
  return ans;
}

