template<class T>
struct Kmp
{
public:
  /**
   * @param N strのサイズ
   * @param K wordのサイズ
   */
  Kmp(int N, int K);

  /** 検索対象の文字列 */
  vector<T> str;

  /** 検索元の文字列 */
  vector<T> word;

  /** 内部処理で使用する検索テーブル */
  vector<size_t> memo;

  /**
   * 前計算処理を行う. 
   * 本APIを呼ぶ前にstr, wordに入力する必要がある.
   */
  void preCalc();

  /**
   * prePos番目以降で、wordと一致するstrの部分文字列が開始されるindexを返す.
   * 本APIを呼ぶ前にKmp::preCalcを実行する必要がある.
   * 
   * @param prePos 探索を始めるindex
   * @return pos 見つからなかった場合は-1
   */
  ssize_t find(ssize_t prePos);

  /**
   * @return 見つからない場合、空のvector
   */
  vector<int> findAll();
};

template<class T>
Kmp<T>::Kmp(int N, int K)
  : str(N)
  , word(K)
  , memo(K+1)
{}

template<class T>
void Kmp<T>::preCalc()
{
  size_t i = 0;
  size_t j = 1;
  memo[0] = -1;
  while (j < word.size()) {
    auto isMatch = word[i] == word[j];
    if (!isMatch && i > 0) {
      i = memo[i];
    }
    else {
      if (isMatch) {
        ++i;
      }
      ++j;
      memo[j] = i;
    }
  }
  return;
}

template<class T>
ssize_t Kmp<T>::find(ssize_t prePos)
{
  int i = prePos;
  int j = 0;
  while (i < (int)str.size() && j < (int)word.size()) {
    if (str[i] == word[j]) {
      ++i;
      ++j;
    }
    else if (j == 0) {
      ++i;
    }
    else {
      j = memo[j];
    }
  }
  return (j == (int)word.size()) ? (i - j) : -1;
}

template<class T>
vector<int> Kmp<T>::findAll()
{
  vector<int> res{};

  int i = 0;
  int j = 0;
  while (i < (int)str.size() && j < (int)word.size()) {
    if (str[i] == word[j]) {
      ++i;
      ++j;
    }
    else if (j == 0) {
      ++i;
    }
    else {
      j = memo[j];
    }
    if (j == (int)word.size()) {
      res.push_back(i-j);
      j = memo[j];
    }
  }
  return std::move(res);
}

void solve(void)
{
  int N; cin >> N;
  vector<int> A(N), B(N);
  for (auto& a : A) {
    cin >> a;
  }
  for (auto& b : B) {
    cin >> b;
  }

  Kmp<int> k(N*2, N);
  for (int i = 0; i < N; ++i) {
    k.str[i] = A[i] ^ A[(i+1) % N];
    k.word[i] = B[i] ^ B[(i+1) % N];
  }
  std::copy(k.str.begin(), k.str.begin()+N, k.str.begin()+N);
  k.preCalc();

  auto res = k.findAll();
  for (const auto& itr : res) {
    if (itr >= N) break;
    int i = 0;
    int j = (i + itr) % N;
    int x = B[i] ^ A[j];
    cout
      << itr << SPACE
      << x << CRLF;
  }

  return;
}

