int gcd(int a, int b) {
    if (a < b) return gcd(b, a);
    if (a % b == 0) return b;
    return gcd(b, a % b);
}

int main() {
    int n;
    scanf("%d", &n);
    for(int i = 0; i < n; i++) scanf("%d", &a[i]);

    int a_cyc = n;
    for(int k = 1; k < n; k++) {
        if (n % k != 0) continue;
        bool eq = true;
        int x = a[0] ^ a[k];
        for(int j = 0; j < k; j++) {
            for(int p = j; p < n; p+= k) if ((a[p] ^ a[j]) != x) eq = false;
        }

        if (eq) {
            a_cyc = k;
            break;
        }
    }

    for(int i = 0; i < n; i++) scanf("%d", &b[i]);

    int b_cyc = n;
    for(int k = 1; k < n; k++) {
        if (n % k != 0) continue;
        bool eq = true;
        int x = b[0] ^ b[k];
        for(int j = 0; j < k; j++) {
            for(int p = j; p < n; p+= k) if ((b[p] ^ b[j]) != x) eq = false;
        }

        if (eq) {
            b_cyc = k;
            break;
        }
    }

    int cyc = (a_cyc / gcd(a_cyc, b_cyc)) * b_cyc;

    for(int k = 0; k < cyc; k++) {
        int x = a[k] ^ b[0];

        int j;
        for(j = 0; j < n; j++) {
            if ((a[(j + k) % n] ^ b[j]) != x) break;
        }

        if (j == n) {
            for(int r = k; r < n; r += cyc) {
                printf("%d %d\n", r, a[r] ^ b[0]);
            }
        }
    }

    return 0;
}

