// A[i] : S と S[i:] の先頭が何文字共通しているか
long long int A[1000000];

// O(|S|)
void Z_algorithm(vector<long long int> S){
	A[0] = S.size();
	int i = 1, j = 0;
	while (i < S.size()) {
		while (i + j < S.size() && S[j] == S[i + j]){
			j += 1;
		}
		A[i] = j;
		if (j == 0) {
			++i;
			continue;
		}
		int k = 1;
		while (i + k < S.size() && k + A[k] < j){
			A[i + k] = A[k];
			k += 1;
		}
		i += k; j -= k;
	}
}

