    }
    for (int i = 0; i < N; i++) {
        int b;
        cin >> b;
        for (int j = 0; b > 0; b >>= 1, j++)
            B[j][i] = b % 2;
    }

    fill(&ans[0][0], &ans[29][MAXN], -1);
    for (int i = 0; i < 30; i++) {
        vector<int> prefix = prefix_function(i);
        kmp(i, prefix, false);
        kmp(i, prefix, true);
    }

    for (int i = N - 1; i >= 0; i--) {
        bool flag = ans[0][i] >= 0;
        for (int j = 1; j < 30; j++) {
