template <typename T>
int get_next(const T *P, const vector<int> &fail, const T ch, int i) {
  while (i != -1 && P[i] != ch)
    i = fail[i];
  return i + 1;
}

template <typename T>
vector<int> get_fail(const T *pattern, const int len_pattern) {
  assert(len_pattern > 0);
  vector<int> fail(len_pattern + 1);
  fail[0] = -1;
  for (int i = 1; i <= len_pattern; i++) {
    fail[i] = get_next(pattern, fail, pattern[i - 1], fail[i - 1]);
  }
  return fail;
}

template <typename T>
vector<int> KMP_match(const T *pattern, const int len_pattern, const T *text,
                      const int len_text, const vector<int> &fail) {
  vector<int> match_positions;
  for (int i = 0, j = 0; i < len_text; ++i) {
    j = get_next(pattern, fail, text[i], j);
    if (j == len_pattern) {
      j = fail[j];
      match_positions.push_back(i + 1 - len_pattern);
    }
  }
  return match_positions;
}

