template<typename X>
void kmp_ready(vi&t, const X*k, int kl)
{
	t.resize(kl);
	int j=0;
	t[0]=0;
	for(int i=1;i<kl;i++)
	{
		t[i]=j;
		if(k[i]==k[j]) j++;
		else j=0;
	}
}


template<typename X>
int kmp_common(const X *s, int sl, const X *k, int kl, const vi&t)
{
	int i=0;
	int j=0;
	for(;i<sl;)
	{
		if(s[i]==k[j])
		{
			i++;
			j++;
			if(j>=kl) return i-j;
		}
		else if(j==0)
		{
			i++;
		}
		else
		{
			j=t[j];
		}
	}
	return -1;
}


template<typename X>
vi kmp_r(const X *s, int sl, const X *k, int kl, int lim=0)
{
	vi ret;

	if(kl<=0) return ret;
	if(sl<=0) return ret;

	vi t;
	kmp_ready(t, k, kl);

	int i=0;
	int j=0;
	for(;i<sl;)
	{
		if(s[i]==k[j])
		{
			i++;
			j++;
			if(j>=kl)
			{
				ret.push_back(i-j);
				i--;
				j=t[j-1];
			}
		}
		else if(j==0)
		{
			i++;
		}
		else
		{
			j=t[j];
		}
	}
	return ret;
}


template<typename X>
int kmp(const X *s, int sl, const X *k, int kl)
{
	if(kl<=0) return 0;
	if(sl<=0) return -1;

	vi t;
	kmp_ready(t, k, kl);

	return kmp_common(s, sl, k, kl, t);
}


int msb(unsigned long long v)
{
	int ret=0;

	if(v & 0xFFFFFFFF00000000LL) ret+=32,v>>=32;
	if(v & 0xFFFF0000) ret+=16,v>>=16;
	if(v & 0xFF00) ret+=8,v>>=8;
	if(v & 0xF0) ret+=4,v>>=4;
	if(v & 0xC) ret+=2,v>>=2;
	if(v & 0x2) ret+=1;
	return ret;
}


int lsb(unsigned long long v)
{
	int ret=0;

	if(!v) return 0;

	if(!(v & 0xFFFFFFFF)) ret+=32,v>>=32;
	if(!(v & 0xFFFF)) ret+=16,v>>=16;
	if(!(v & 0xFF)) ret+=8,v>>=8;
	if(!(v & 0xF)) ret+=4,v>>=4;
	if(!(v & 0x3)) ret+=2,v>>=2;
	if(!(v & 0x1)) ret+=1;
	return ret;
}


int bit_count(unsigned long long v)
{
	int ret=0;

	while(v)
	{
		ret++;
		v&=v-1;
	}
	return ret;
}


