template<typename T>
vector<int> kmp(T &str){
	int n=str.size();
	vector<int> res(n+1,-1);
	for(int i=0,j=-1;i<n;res[++i]=++j){
		while(j>=0 && str[i]!=str[j]) j=res[j];
	}
	return res;
}
vector<int> sol(vector<long long> a,vector<long long> b){
	int n=a.size();
	vector<int> res;
	vector<long long> aa(n),bb(n*2);
	for(int i=0;i<n;i++){
		aa[i]=a[i]^a[(i+1)%n];
		bb[i]=b[i]^b[(i+1)%n];
	}
	for(int i=0;i<n;i++){
		bb[i+n]=bb[i];
	}
	vector<int> k=kmp(aa);
	aa.push_back(-1);
	int i=0,p=0;
	while(i<bb.size() && p<aa.size()){
		if(bb[i]==aa[p]){
			i++;
			p++;
		}else if(p==0){
			i++;
		}else{
			p=k[p];
		}
		if(p==n){
			//cout << "! " << i << "\n";
			res.push_back(i-n);
		}
	}
	return res;
}
