template <typename Type>
struct KMP{
    Type S;
    Vec A;

    KMP(Type S) : S(S){
        A.resize(S.size()+1);
        A[0] = -1;
        ll j = -1;
        for(int i = 0; i < S.size(); ++i){
            while(j >= 0 && S[i] != S[j]) j = A[j];
            ++j;
            // ce(i, j);
            // if(S[i + 1] == S[j]) A[i + 1] = A[j];
            A[i + 1] = j;
        }
    }

    vector<ll> search(Type T, ll pos = 0){
        vector<ll> res;
        ll i = 0, j = pos;
        while(i < S.size() && j < T.size()){
            if(S[i] == T[j]) ++i, ++j;
            else if(!i) ++j;
            else i = A[i];
            if(i == S.size()){
                res.push_back(j - i);
                i = A[i];
                // ce(i, j);
            }
        }
        return res;
    }
};

