/**
    a(i+k) ^ x = b(i)
    a(i+k+1) ^ x = b(i+1)
    a(i+k) ^ a(i+k+1) = b(i) ^ b(i+1)
**/

int F[N];
vector<int> pat ,str ;
int getNextLen(int len, int c){
  while(len && c != pat[len])
    len = F[len-1];
  if(c == pat[len]) ++len;
  return len;
}

void computeF(){
  for(int i = 1 ; i<pat.size(); ++i)
    F[i] = getNextLen(F[i-1], pat[i]);
}

vector<int> search(){
  int len = 0;
  vector<int> res;
  for(int i = 0 ; i<str.size() ; ++i){
    len = getNextLen(len, str[i]);
    if(len==pat.size()) res.push_back(i-len+1);
  }
  return res;
}
void kmp(vector<int> aa,vector<int> bb){
    pat = aa ;
    str = bb ;
    computeF();
    auto ans = search();
    vector<pair<int,int>> out ;
    for(auto go:ans) out.push_back({go,b[0]^a[go]});
    sort(out.begin(),out.end());
    for(auto go:out) printf("%d %d\n",go.first,go.second);
}
