template <typename Monoid>
class foldable_deque {
public:
  using value_type = Monoid;
  using size_type = size_t;

private:
  using stack_type = std::stack<value_type, std::vector<value_type>>;
  stack_type M_front, M_back, M_front_folded, M_back_folded;

  void M_balance() {
    // precondition: (M_front.empty() || M_back.empty())
    std::deque<value_type> whole;
    while (!M_front.empty()) {
      whole.push_back(M_front.top());
      M_front.pop();
      M_front_folded.pop();
    }
    while (!M_back.empty()) {
      whole.push_front(M_back.top());
      M_back.pop();
      M_back_folded.pop();
    }

    size_type half = whole.size() / 2;
    for (size_type i = half; i--;) {
      value_type x = std::move(whole[i]);
      M_front.push(x);
      if (!M_front_folded.empty()) x.fold_eq(M_front_folded.top());
      M_front_folded.push(x);
    }
    for (size_type i = half; i < whole.size(); ++i) {
      value_type x = std::move(whole[i]);
      M_back.push(x);
      if (!M_back_folded.empty()) x = M_back_folded.top().fold(x);
      M_back_folded.push(x);
    }
  }

public:
  foldable_deque() = default;
  foldable_deque(foldable_deque const&) = default;
  foldable_deque(foldable_deque&&) = default;

  // TODO: construct from initializer list, assign(), etc.

  foldable_deque& operator =(foldable_deque const&) = default;
  foldable_deque& operator =(foldable_deque&&) = default;

  bool empty() const noexcept { return M_front.empty() && M_back.empty(); }
  size_type size() const noexcept { return M_front.size() + M_back.size(); }

  void push_back(value_type const& x) {
    M_back.push(x);
    if (M_back_folded.empty()) {
      M_back_folded.push(x);
    } else {
      value_type tmp = M_back_folded.top();
      tmp.fold_eq(x);
      M_back_folded.push(tmp);
    }
  }
  void push_front(value_type const& x) {
    M_front.push(x);
    if (M_front_folded.empty()) {
      M_front_folded.push(x);
    } else {
      value_type tmp = x;
      tmp.fold_eq(M_front_folded.top());
      M_front_folded.push(tmp);
    }
  }

  template <typename... Args>
  void emplace_back(Args&&... args) { push_back(value_type(args...)); }
  template <typename... Args>
  void emplace_front(Args&&... args) { push_front(value_type(args...)); }

  void pop_back() {
    if (M_back.empty()) M_balance();
    M_back.pop();
    M_back_folded.pop();
  }
  void pop_front() {
    if (M_front.empty()) M_balance();
    M_front.pop();
    M_front_folded.pop();
  }

  value_type fold() const {
    value_type res;
    if (!M_front_folded.empty()) res.fold_eq(M_front_folded.top());
    if (!M_back_folded.empty()) res.fold_eq(M_back_folded.top());
    return res;
  }
};

template <intmax_t Base = 943681729, intmax_t Modulo = 1000000007>
class monoid_rolling_hash {
public:
  using value_type = intmax_t;

private:
  value_type M_hash = 0;
  value_type M_basepow = 1;

public:
  monoid_rolling_hash() = default;
  monoid_rolling_hash(monoid_rolling_hash const&) = default;
  monoid_rolling_hash(monoid_rolling_hash&&) = default;

  monoid_rolling_hash& operator =(monoid_rolling_hash const&) = default;
  monoid_rolling_hash& operator =(monoid_rolling_hash&&) = default;

  template <typename Tp>
  monoid_rolling_hash(Tp x) {
    if ((x %= Modulo) < 0) x += Modulo;
    M_hash = x;
    M_basepow = Base % Modulo;
  }

  template <typename InputIt>
  monoid_rolling_hash(InputIt first, InputIt last) {
    while (first != last) {
      (M_hash = M_hash * Base + *first++) %= Modulo;
      (M_basepow *= Base) %= Modulo;
    }
    if (M_hash < 0) M_hash += Modulo;
  }

  monoid_rolling_hash& fold_eq(monoid_rolling_hash const& other) {
    // (h1, b1) + (h2, b2) = (h1*b2 + h2, b1*b2)
    (M_hash = M_hash * other.M_basepow + other.M_hash) %= Modulo;
    (M_basepow *= other.M_basepow) %= Modulo;
    return *this;
  }

  monoid_rolling_hash fold(monoid_rolling_hash const& other) const {
    return monoid_rolling_hash(*this).fold_eq(other);
  }

  value_type get() const { return M_hash; }
};

class monoid_rolling_hashes {
public:
  using value_type = std::tuple<intmax_t, intmax_t, intmax_t>;

private:
  using rh1 = monoid_rolling_hash<>;
  using rh2 = monoid_rolling_hash<943681729, 998244353>;
  using rh3 = monoid_rolling_hash<943681729, 1000000009>;

  rh1 M_h1;
  rh2 M_h2;
  rh3 M_h3;

public:
  monoid_rolling_hashes() = default;
  monoid_rolling_hashes(monoid_rolling_hashes const&) = default;
  monoid_rolling_hashes(monoid_rolling_hashes&&) = default;

  template <typename Tp>
  monoid_rolling_hashes(Tp x): M_h1(x), M_h2(x), M_h3(x) {}

  monoid_rolling_hashes& operator =(monoid_rolling_hashes const&) = default;
  monoid_rolling_hashes& operator =(monoid_rolling_hashes&&) = default;

  monoid_rolling_hashes& fold_eq(monoid_rolling_hashes const& other) {
    M_h1.fold_eq(other.M_h1);
    M_h2.fold_eq(other.M_h2);
    M_h3.fold_eq(other.M_h3);
    return *this;
  }

  monoid_rolling_hashes fold(monoid_rolling_hashes const& other) const {
    return monoid_rolling_hashes(*this).fold_eq(other);
  }

  value_type get() const { return std::make_tuple(M_h1.get(), M_h2.get(), M_h3.get()); }
};

std::map<size_t, int> f(std::vector<intmax_t> const& a, std::vector<intmax_t> const& b) {
  size_t n = a.size();
  foldable_deque<monoid_rolling_hashes> fa0, fa1, fb;
  for (size_t i = 0; i < n; ++i) {
    fa0.push_back(a[i]);
    fa1.push_back(a[i] ^ 1);
    fb.push_back(b[i]);
  }
  std::map<size_t, int> res;
  if (fa0.fold().get() == fb.fold().get()) res[0] = 0;
  if (fa1.fold().get() == fb.fold().get()) res[0] = 1;
  for (size_t k = 1; k < n; ++k) {
    fa0.pop_front();
    fa0.push_back(a[k-1]);
    fa1.pop_front();
    fa1.push_back(a[k-1] ^ 1);
    if (fa0.fold().get() == fb.fold().get()) res[k] = 0;
    if (fa1.fold().get() == fb.fold().get()) res[k] = 1;
  }
  return res;
}

