int P[3*SIZE];
int z_algorithm[3*SIZE];

//文字列aの後ろに文字列bをくっつけた場合に、何文字重なるかを計算する関数
void calc(){

	for(int i = 0; i < N; i++){

		P[i] = B[i];
	}
	P[N] = -1;
	for(int i = 0; i < 2*N; i++){
		P[N+1+i] = A[i];
	}

	int P_length = 3*N+1;

	z_algorithm[0] = P_length;
	int index = 1,diff = 0,diff_2;

	while(index < P_length){
		while(index+diff < P_length && P[index+diff] == P[diff])diff++; //不一致箇所はP[diff]とP[index+diff]
		z_algorithm[index] = diff;

		if(diff == 0){ //1文字も一致しない場合
			index++;
			continue;
		}else{ //先頭からdiff文字一致したという事実を利用する

			diff_2 = 1;

			//一致長が[比較の先頭をずらした分だけ]減っていく間、以前の計算結果を再利用する
			while(index+diff_2 < P_length && z_algorithm[diff_2] < diff-diff_2){

				z_algorithm[index+diff_2] = z_algorithm[diff_2];
				diff_2++;
			}

			index += diff_2;
			diff -= diff_2;
		}
	}
}

