  }
  REP(i, N) {
    d[i] = d[i + N] = b[i] ^ b[(i + 1) % N];
  }

  vector<int> s;
  s.insert(s.end(), c.begin(), c.end());
  s.push_back(-1);
  s.insert(s.end(), d.begin(), d.end());

  vector<int> ret(s.size() + 1, 0);
