    int m = p.size(), j = 0;
    for (int i=1; i<m; i++) {
        while (j != 0 && p[i] != p[j])
            j = lps[j-1];
        lps[i] = (j += (p[i] == p[j]));
    }
}

void kmp() {
    preprocess();
    int n = t.size(), m = p.size(), j = 0;
    for (int i=0; i<n; i++) {
        while (j != 0 && t[i] != p[j])
            j = lps[j-1];
        if ((j += (t[i] == p[j])) == m) {
            ret.push_back(i - j + 1);
            j = lps[j-1];
        }
    }
}

