//z-algorithm
//https://snuke.hatenablog.com/entry/2014/12/03/214243

//longest prefix between S & s_i s_i+1 ... s_l
void z_algorithm(long long s[],long long l,long long arr[]){
  long long i,j,k;
  arr[0]=l;
  i=1;j=0;
  while(i<l){
    while((i+j)<l){
      if(s[j]!=s[i+j]){break;}
      j++;
    }
    arr[i]=j;
    if(j==0){i++;continue;}
    k=1;
    while((i+k)<l){
      if(k+arr[k]>=arr[i]){break;}
      arr[i+k]=arr[k];
      k++;
    }
    j=arr[i]-k;
    i+=k;
  }
}

