                int x = (a[i] & (1 << bit)) != 0 ? 1 : 0;
                if (x == 1) {
                    bits[bit] = ADD(bits[bit], two[i]);
                }
            }
        }
        for (int k = 0; k < n; k++) {
            boolean can = true;
            long res = 0;
            for (int bit = 0; bit < BITS; bit++) {
                if (hash[bit][1] == bits[bit]) {
                    res |= 1 << bit;
                } else if (hash[bit][0] != bits[bit]) {
                    can = false;
                }
                int x = (a[k] & (1 << bit)) != 0 ? 1 : 0;
                if (x == 1) {
                    bits[bit] = SUB(bits[bit], two[k]);
                    bits[bit] = ADD(bits[bit], two[n + k]);
                }
                hash[bit][0] = MULT(hash[bit][0], 2);
                hash[bit][1] = MULT(hash[bit][1], 2);
            }
            if (can) {
                out.println(k + " " + res);
            }
        }
        out.close();
    }

    /* MOD_CALCULATION */
    static long MOD = 1000000009L;
    static long ADD(long a, long b) {
        return (a + b) % MOD;
    }

    static long SUB(long a, long b) {
        return (a - b + MOD) % MOD;
    }

    static long MULT(long a, long b) {
        return ((a % MOD) * (b % MOD)) % MOD;
    }

    static long POW(long a, long x) {
        long res = 1;
        for ( ; x > 0; x >>= 1) {
            if (x % 2 == 1) res = MULT(res, a);
            a = MULT(a, a);
        }

        return res;
    }

    static long DIV(long a, long b) {
        return MULT(a, POW(b, MOD - 2));
    }
    /* end */

