    String INPUT = "";

    static int mod = 1_000_000_007;
    // int mod = 998244353;
    // long inf = Long.MAX_VALUE/2;
    int inf = Integer.MAX_VALUE/2;

    void solve(){
        int n = ni();
        long[] a = new long[n];
        long[] b = new long[n];
        for(int i = 0; i < n; i++){
            a[i] = nl();
        }
        for(int i = 0; i < n; i++){
            b[i] = nl();
        }
        long[] xa = new long[n];
        for(int i = 0; i < n; i++){
            xa[i] = a[i] ^ a[(i+1)%n];
        }
        long[] xb = new long[n];
        for(int i = 0; i < n; i++){
            xb[i] = b[i] ^ b[(i+1)%n];
        }
        long[] xd = new long[3*n];
        System.arraycopy(xb, 0, xd, 0, n);
        System.arraycopy(xa, 0, xd, n, n);
        System.arraycopy(xa, 0, xd, 2*n, n);
        int[] ret = zalgo(xd);
        for(int i = n; i < 2*n; i++){
            if(ret[i]>=n){
                long x = a[i-n]^b[0];
                out.println(i-n+" "+x);
            }
        }

    }

    int[] zalgo(long[] s) {
		int n = s.length;
		int[] ret = new int[n];
		ret[0] = n;
		int i = 1, j = 0;
		while (i < n) {
			while (i + j < n && s[j] == s[i + j])
				++j;
			ret[i] = j;
			if (j == 0) {
				++i;
				continue;
			}
			int k = 1;
			while (i + k < n && k + ret[k] < j) {
				ret[i + k] = ret[k];
				++k;
			}
			i += k;
			j -= k;
		}
		return ret;
	}

    void run() throws Exception
    {
        is = INPUT.isEmpty() ? System.in : new ByteArrayInputStream(INPUT.getBytes());
        out = new PrintWriter(System.out);
        long s = System.currentTimeMillis();
        solve();
        out.flush();
        if(!INPUT.isEmpty())tr(System.currentTimeMillis()-s+"ms");
    }

    public static void main(String[] args) throws Exception { new Main().run(); }

    private byte[] inbuf = new byte[1024];
    private int lenbuf = 0, ptrbuf = 0;

    private int readByte()
    {
        if(lenbuf == -1)throw new InputMismatchException();
        if(ptrbuf >= lenbuf){
            ptrbuf = 0;
            try { lenbuf = is.read(inbuf); } catch (IOException e) { throw new InputMismatchException(); }
            if(lenbuf <= 0)return -1;
        }
        return inbuf[ptrbuf++];
    }

    private boolean isSpaceChar(int c) { return !(c >= 33 && c <= 126); }
    private int skip() { int b; while((b = readByte()) != -1 && isSpaceChar(b)); return b; }

    private double nd() { return Double.parseDouble(ns()); }
    private char nc() { return (char)skip(); }

    private String ns()
    {
        int b = skip();
        StringBuilder sb = new StringBuilder();
        while(!(isSpaceChar(b) && b != ' ')){
            sb.appendCodePoint(b);
            b = readByte();
        }
        return sb.toString();
    }

    private char[] ns(int n)
    {
        char[] buf = new char[n];
        int b = skip(), p = 0;
        while(p < n && !(isSpaceChar(b))){
            buf[p++] = (char)b;
            b = readByte();
        }
        return n == p ? buf : Arrays.copyOf(buf, p);
    }

    private char[][] nm(int n, int m)
    {
        char[][] map = new char[n][];
        for(int i = 0;i < n;i++)map[i] = ns(m);
        return map;
    }

    private int[] na(int n)
    {
        int[] a = new int[n];
        for(int i = 0;i < n;i++)a[i] = ni();
        return a;
    }

    private int ni()
    {
        int num = 0, b;
        boolean minus = false;
        while((b = readByte()) != -1 && !((b >= '0' && b <= '9') || b == '-'));
        if(b == '-'){
            minus = true;
            b = readByte();
        }

        while(true){
            if(b >= '0' && b <= '9'){
                num = num * 10 + (b - '0');
            }else{
                return minus ? -num : num;
            }
            b = readByte();
        }
    }

    private long nl()
    {
        long num = 0;
        int b;
        boolean minus = false;
        while((b = readByte()) != -1 && !((b >= '0' && b <= '9') || b == '-'));
        if(b == '-'){
            minus = true;
            b = readByte();
        }

        while(true){
            if(b >= '0' && b <= '9'){
                num = num * 10 + (b - '0');
            }else{
                return minus ? -num : num;
            }
            b = readByte();
        }
    }

    private static void tr(Object... o) { System.out.println(Arrays.deepToString(o)); }

}

import java.util.*;
class Main {
	Scanner sc;
	int N;
	int[] a, b, c, d;
	int base;
	static final Set<Integer> PRIMES;
	static {
		PRIMES = new TreeSet<>();
		int n = (int)Math.sqrt(200000);
		for (int i = 1; i <= n; i++) {
			int m = (int)Math.sqrt(i);
			int j = 2;
			for (; j <= m; j++)
				if (i%j == 0) break;
			if (j > m) PRIMES.add(i);
		}
	}

	static Comparator<int[]> comp = Comparator.comparingInt(e -> e[0]);

	private void calc() {
		sc = new Scanner(System.in);
		N = sc.nextInt();
		a = new int[N];
		b = new int[N];
		c = new int[N];
		d = new int[N];
		for (int i = 0; i < N; i++) a[i] = sc.nextInt();
		for (int i = 0; i < N; i++)	b[i] = sc.nextInt();
		for (int i = 0; i < N; i++) c[i] = a[i] ^ a[(i+1)%N];
		for (int i = 0; i < N; i++) d[i] = b[i] ^ b[(i+1)%N];

		int[][] cmap = new int[N][2];
		for (int i = 0; i < N; i++) { cmap[i][0] = c[i]; cmap[i][1] = i; }
		Arrays.sort(cmap, comp);
		int s = 0;
		int min = Integer.MAX_VALUE;
		int minv = -1;
		int cnt = 1;
		int idx = -1;
		for (int i = 0; i < N; i++) {
			if (i == N-1 || cmap[i][0] != cmap[i+1][0]) {
				if (cnt < min) {
					min = cnt;
					minv = cmap[i][0];
					idx = s;
				}
				s = i;
				cnt = 0;
			}
			cnt++;
		}
		int[][] dmap = new int[N][2];
		for (int i = 0; i < N; i++) { dmap[i][0] = d[i]*2; dmap[i][1] = i; }
		Arrays.sort(dmap, comp);
		int didx = -1-Arrays.binarySearch(dmap, 0, N, new int[] {2*minv-1}, comp);
		int dcnt = -1-Arrays.binarySearch(dmap, 0, N, new int[] {2*minv+1}, comp)-didx;
		base = -1;
	lp:
		for (int i = 0; i < cnt; i++) {
			for (int j = 0; j < dcnt; j++) {
				int k = 0;
				for (; k < N; k++)
					if (c[(cmap[i+idx][1]+k)%N] != d[(dmap[j+didx][1]+k)%N]) break;
				if (k == N) {
					base = (N+cmap[i+idx][1]-dmap[j+didx][1])%N;
					break lp;
				}
			}
		}
		if (base == -1) return;

		Set<Integer> divs = new TreeSet<>();
		for (int i = 1; i <= Math.sqrt(N); i++) {
			if ((N%i)!=0) continue;
			if (PRIMES.contains(i)) divs.add(i);
			if (PRIMES.contains(N/i)) divs.add(N/i);
		}
		Map<Integer, Integer> ans = new TreeMap<>();
		ans.put( base, a[base]^b[0] );
		for (int div : divs) {
			if (ans.containsKey(div)) continue;
			if (checkSeq(div))
				for (int i = div; i <= N; i += div)
					ans.put( (base+i)%N, a[(base+i)%N]^b[0] );
		}
		for (int k : ans.keySet()) System.out.println(k+" "+ans.get(k));
	}

	private boolean checkSeq(int div) {
		if (div == N) return true;
		for (int i = 0; i < N; i++)
			if (c[i] != c[(i+div)%N]) return false;
		return true;
	}

