// Morris-Pratt
// 文字列Sに、文字列Tが1つ以上含まれれば、その開始位置全てを返す
// 探したいパターンをコンストラクタに渡す
class MP{
	int n, a[];
	char[] searchPattern; //探すパターン。SからTを探す時のT
	MP(String searchPattern){
		this(searchPattern.toCharArray());
	}
	MP(char[] searchPattern){
		this.searchPattern = searchPattern;
		n = searchPattern.length;
		a = new int[n+1];//1-indexed
		a[0] = -1;
		int j = -1;
		for(int i=0;i<n;i++) {
			while(j != -1 && searchPattern[j] != searchPattern[i]) {
				j = a[j];
			}
			j++;
			a[i+1] = j;
		}
	}

	List<Integer> findAll(String target){
		return findAll(target.toCharArray());
	}

	//targetに含まれるsearchPatternの開始点全てを、Listで返す
	List<Integer> findAll(char[] target){
		List<Integer> res = new ArrayList<>();
		int j = 0;
		for(int i=0;i<target.length;i++) {
			while(j != -1 && searchPattern[j] != target[i]) j =a[j];
			j++;
			if(j == n) {
				res.add(i-j+1);
				j = a[j];
			}
		}
		return res;
	}
}

