int[] kmp(long s[], long p[]) { // O(|S|)
	int sLen = s.length;
	long sInt[] = new long[sLen];
	for(int i = 0; i < sLen; i ++) { sInt[i] = s[i]; }
	int pLen = p.length;
	long pInt[] = new long[pLen];
	for(int i = 0; i < pLen; i ++) { pInt[i] = p[i]; }

	int sIndex = 1;
	int pIndex = 0;

	int skip[] = new int[pLen + 1];
	fill(skip, 0);
	while(sIndex < pLen) {
		if(pInt[sIndex] == pInt[pIndex]) {
			sIndex ++;
			pIndex ++;
			skip[sIndex] = pIndex;
		}else if(pIndex == 0) {
			sIndex ++;
			skip[sIndex] = 0;
		}else {
			pIndex = skip[pIndex];
		}
	}

	ArrayList<Integer> matchIndex = new ArrayList<Integer>();
	sIndex = 0;
	pIndex = 0;
	end: while(true) {
		while(sIndex < sLen && pIndex < pLen && sInt[sIndex] == pInt[pIndex]) {
			sIndex ++;
			pIndex ++;
		}
		if(pIndex >= pLen) {
			matchIndex.add(sIndex - pLen);
			pIndex = skip[pIndex];
		}else if(pIndex == 0){
			sIndex ++;
		}else {
			pIndex = skip[pIndex];
		}
		if(sIndex >= sLen) { break end; }
	}

	int matchIndexList[] = new int[matchIndex.size()];
	for(int i = 0; i < matchIndex.size(); i ++) {
		matchIndexList[i] = matchIndex.get(i);
	}
	return matchIndexList;
}

	}
}

