    public void solve() {
        // System.out.println(BigInteger.probablePrime(60, new Random(123)));
        int n = in.nextInt();
        int[] a = in.nextIntArray(n);
        int[] b = in.nextIntArray(n);

        final int BITS = 30;
        long[][] hash = new long[BITS][2];
        long[] two = new long[n];
        two[0] = 1;
        for (int i = 0; i < n - 1; i++) {
            two[i+1] = MULT(two[i], 2);
        }
        for (int bit = 0; bit < BITS; bit++) {
            long h1 = 0;
            long h2 = 0;
            for (int i = 0; i < n; i++) {
                int x = (b[i] & (1 << bit)) != 0 ? 1 : 0;
                int y = x ^ 1;
                h1 = ADD(h1, MULT(x, two[i]));
                h2 = ADD(h2, MULT(y, two[i]));
            }
            hash[bit][0] = h1;
            hash[bit][1] = h2;
        }

        long[] bits = new long[BITS];
        for (int bit = 0; bit < BITS; bit++) {
            for (int i = 0; i < n; i++) {
                int x = (a[i] & (1 << bit)) != 0 ? 1 : 0;
                bits[bit] = ADD(bits[bit], MULT(x, two[i]));
            }
        }
        for (int k = 0; k < n; k++) {
            boolean can = true;
            long res = 0;
            for (int bit = 0; bit < BITS; bit++) {
                if (hash[bit][1] == bits[bit]) {
                    res |= 1 << bit;
                } else if (hash[bit][0] == bits[bit]) {
                    // ok
                } else {
                    can = false;
                }
                int x = (a[k] & (1 << bit)) != 0 ? 1 : 0;
                bits[bit] = SUB(bits[bit], x);
                bits[bit] = DIV(bits[bit], 2);
                bits[bit] = ADD(bits[bit], MULT(x, two[n-1]));
            }
            if (can) {
                out.println(k + " " + res);
            }
        }
        out.close();
    }

    /* MOD_CALCULATION */
    static long MOD = 1000000009L;
    static long ADD(long a, long b) {
        return (a + b) % MOD;
    }

    static long SUB(long a, long b) {
        return (a - b + MOD) % MOD;
    }

    static long MULT(long a, long b) {
        return ((a % MOD) * (b % MOD)) % MOD;
    }

    static long POW(long a, long x) {
        long res = 1;
        for ( ; x > 0; x >>= 1) {
            if (x % 2 == 1) res = MULT(res, a);
            a = MULT(a, a);
        }

        return res;
    }

    static long DIV(long a, long b) {
        return MULT(a, POW(b, MOD - 2));
    }
