    static void solve(PrintWriter pw) {
        // kmpとか使うのだろうとはわかるのだけど Ai + Ai+1 = Bi + Bi+1 にはたどり着けなかった
        // xorのときの典型なんだろうか...
        int[] U = new int[N*2];
        int[] V = new int[N];
        for (int i = 0; i < N; i++) {
            int u = A[i] ^ A[(i+1)%N];
            U[i] = u;
            U[i+N] = u;
            V[i] = B[i] ^ B[(i+1)%N];
        }

        IntKMP kmp = IntKMP.create(U);
        int[] ks = kmp.findMatchIndice(V);
        // debug(ks);

        for (int k : ks) {
            if( k >= N ) continue;
            int x = A[k] ^ B[0];
            pw.println(k + " " + x);
        }
    }

    static class IntKMP {
        public static IntKMP create(int[] s) {
            int n = s.length;
            int[] table = new int[n+1];
            table[0] = -1;
            for (int i = 0; i < n; i++) {
                int t = table[i];
                while( t != -1 && s[i] != s[t] ) {
                    t = table[t];
                }
                table[i+1] = t+1;
            }
            return new IntKMP(s, table);
        }

        final int[] s;
        final int[] table;

        public IntKMP(int[] S, int[] table) {
            this.s = S;
            this.table = table;
        }

        public int[] findMatchIndice(int[] w) {
            int n = s.length;
            boolean[] match = new boolean[n];
            int cnt = 0;
            {
                int i = 0, j = 0;
                while(i < n) {
                    if( s[i] == w[j] ) {
                        i++; j++;

                        if( j == w.length ) {
                            int idx = i-w.length;
                            match[idx] = true;
                            cnt++;
                            j = table[j];
                        }

                    } else {
                        if( j != 0 ) {
                            j = table[j];
                        } else {
                            i++;
                        }
                    }
                }
            }
            int idx = 0;
            int[] indice = new int[cnt];
            for (int i = 0; i < n; i++) {
                if( match[i] ) {
                    indice[idx++] = i;
                }
            }
            return indice;
        }
    }

