public class Main {

  private static void solve() {
    int n = ni();
    int[] a = na(n);
    int[] b = na(n);

    int[] c = new int[n];
    int[] d = new int[n];
    for (int i = 0; i < n; i++) {
      c[i] = a[i] ^ a[(i + 1) % n];
      d[i] = b[i] ^ b[(i + 1) % n];
    }

    int[] x = new int[n * 3 + 1];
    int p = 0;
    for (int i = 0; i < n; i++) {
      x[p] = d[i];
      p++;
    }
    x[p++] = -1;
    for (int i = 0; i < n; i++) {
      x[p] = x[p + n] = c[i];
      p++;
    }

    int[] z = Z(x);

    for (int i = n + 1, j = 0; j < n; i++, j++) {
      if (z[i] >= n) {
        out.println(j + " " + (a[j] ^ b[0]));
      }
    }
  }

  public static int[] Z(int[] str) {
    int n = str.length;
    int[] z = new int[n];
    if (n == 0)
      return z;
    z[0] = n;
    int l = 0, r = 0;
    for (int i = 1; i < n; i++) {
      if (i > r) {
        l = r = i;
        while (r < n && str[r - l] == str[r])
          r++;
        z[i] = r - l;
        r--;
      } else {
        if (z[i - l] < r - i + 1) {
          z[i] = z[i - l];
        } else {
          l = i;
          while (r < n && str[r - l] == str[r])
            r++;
          z[i] = r - l;
          r--;
        }
      }
    }

    return z;
  }

