			a.h1=(a.h1*b1+c)%mod1;
			a.h2=(a.h2*b2+c)%mod2;
			a.d++;
			return a;
		}
		public static Hs operator+(Hs a,Hs p){
			a.h1=(a.h1*r1[p.d]+p.h1)%mod1;
			a.h2=(a.h2*r2[p.d]+p.h2)%mod2;
			a.d+=p.d;
			return a;
		}
		public static Hs operator-(Hs a,int c){
			a.d--;
			a.h1=(a.h1+mod1-(r1[a.d]*c%mod1))%mod1;
			a.h2=(a.h2+mod2-(r2[a.d]*c%mod2))%mod2;
			return a;
		}
		public static Hs operator-(Hs a,Hs p){
			a.d-=p.d;
			a.h1=(a.h1+mod1-(r1[a.d]*p.h1%mod1))%mod1;
			a.h2=(a.h2+mod2-(r2[a.d]*p.h2%mod2))%mod2;
			return a;
		}
		public static bool operator==(Hs a,Hs b){return a.h1==b.h1&&a.h2==b.h2&&a.d==b.d;}
		public static bool operator!=(Hs a,Hs b){return a.h1!=b.h1||a.h2!=b.h2||a.d!=b.d;}
