			n=s.Length;
			da=new Tuple<Hs,int>[n];
			for(int i = 0;i<n;i++) {da[i]=Tuple.Create((Hs)s[i],i);}
			Array.Sort(da,(u,v)=>u.Item1.h1.CompareTo(v.Item1.h1));
		}
		public int Eq(Hs h){
			int lb=-1,mid=0,ub=n-1;
			while(ub-lb>1){
				mid=(ub+lb)/2;
				if(da[mid].Item1.h1>=h.h1){ub=mid;}
				else{lb=mid;}
			}
			for(int i = ub;i<n&&da[i].Item1.h1==h.h1;i++) {if(da[i].Item1==h){return da[i].Item2;}}
			return -1;
		}
	}
