	static class Program
	{
		public static void Solve(Scanner cin)
		{
			int n = cin.ReadInt();
			var a = cin.ReadIntArray(n);
			var b = cin.ReadIntArray(n);
			var adiff = new int[n];
			var bdiff = new int[n];
			for (int i = 0; i < n; i++)
			{
				adiff[i] = a[i] ^ a[(i + 1) % n];
				bdiff[i] = b[i] ^ b[(i + 1) % n];
			}

			var factor = new List<int>();
			for (int i = 1; i * i <= n; i++)
			{
				if(n % i == 0)
				{
					factor.Add(i);
					if (i * i != n) factor.Add(n / i);
				}
			}
			factor.Sort();

			int minrepeat = 0;
			foreach (var e in factor)
			{
				bool ok = true;
				for (int i = 0; i < e; i++)
				{
					for (int j = 1; j < n / e; j++)
					{
						if (adiff[i] != adiff[i + e * j]) ok = false;
						if (bdiff[i] != bdiff[i + e * j]) ok = false;
					}
				}
				if (ok)
				{
					minrepeat = e;
					break;
				}
			}

			int mink = -1;
			for (int i = 0; i < minrepeat; i++)
			{
				bool ok = true;
				for (int j = 0; j < minrepeat; j++)
				{
					if (adiff[(i + j) % n] != bdiff[j])
					{
						ok = false;
						break;
					}
				}
				if (ok)
				{
					mink = i;
				}
			}

			if(mink >= 0)
			{
				for (int i = 0; i < n / minrepeat; i++)
				{
					var x = a[mink + minrepeat * i] ^ b[0];
					Console.WriteLine($"{mink + minrepeat * i} {x}");
				}
			}
			else
			{
				// do nothing
			}
		}

