    class F
    {
        static void Main(string[] args)
        {
            var sw = new System.IO.StreamWriter(OpenStandardOutput()) { AutoFlush = false };
            SetOut(sw);

            Method(args);

            Out.Flush();
        }

        static void Method(string[] args)
        {
            int n = ReadInt();
            int[] aArray = ReadInts();
            int[] bArray = ReadInts();
            int[] aDeltas = new int[2 * n];
            int[] bDeltas = new int[n];
            for (int i = 0; i < n; i++)
            {
                aDeltas[i] = aArray[i % n] ^ aArray[(i + 1) % n];
                aDeltas[i + n] = aDeltas[i];
                bDeltas[i] = bArray[i % n] ^ bArray[(i + 1) % n];
            }

            RollingHash aHash = new RollingHash(aDeltas);
            RollingHash bHash = new RollingHash(bDeltas);
            for(int i = 0; i < n; i++)
            {
                if(bHash.ValidateRange(0, n, aHash.GetRangeHash(i, n)))
                {
                    WriteLine(i + " " + (aArray[i] ^ bArray[0]));
                }
            }
        }

        class RollingHash
        {
            long mod = 1000000007;
            long[] bases = new long[3] { 1009, 2003, 3001 };
            long[,] pows;
            long[,] hashes;

            public RollingHash(int[] s)
            {
                pows = new long[s.Length, bases.Length];
                hashes = new long[s.Length, bases.Length];

                for (int i = 0; i < s.Length; i++)
                {
                    for (int j = 0; j < bases.Length; j++)
                    {
                        if (i == 0) pows[i, j] = 1;
                        else pows[i, j] = (pows[i - 1, j] * bases[j]) % mod;
                    }
                }

                for (int i = 0; i < s.Length; i++)
                {
                    for (int j = 0; j < bases.Length; j++)
                    {
                        if (i > 0) hashes[i, j] = (hashes[i - 1, j] * bases[j]) % mod;
                        hashes[i, j] += s[i];
                        hashes[i, j] %= mod;
                    }
                }
            }

            public long[] GetRangeHash(int l, int length)
            {
                long[] hash = new long[bases.Length];
                for (int i = 0; i < bases.Length; i++)
                {
                    hash[i] = hashes[l + length - 1, i];
                    if (l > 0)
                    {
                        hash[i] += mod - (hashes[l - 1, i] * pows[length, i]) % mod;
                        hash[i] %= mod;
                    }
                }
                return hash;
            }

            public bool ValidateRange(int l, int length, long[] hash)
            {
                int r = l + length - 1;
                long[] rangeHash = GetRangeHash(l, length);
                for (int i = 0; i < bases.Length; i++)
                {
                    if (rangeHash[i] != hash[i]) return false;
                }
                return true;
            }

            public long[] GetStringHash(string s)
            {
                long[] vals = new long[bases.Length];
                for (int i = 0; i < s.Length; i++)
                {
                    for (int j = 0; j < bases.Length; j++)
                    {
                        vals[j] = (vals[j] * bases[j] + s[i]) % mod;
                    }
                }

                return vals;
            }
        }

