public class Program
{
    [System.Diagnostics.DebuggerBrowsable(System.Diagnostics.DebuggerBrowsableState.Never)] private ConsoleReader cr; public Program(ConsoleReader consoleReader) { this.cr = consoleReader; }
    static void Main() => Console.WriteLine(new Program(new ConsoleReader(Console.OpenStandardInput())).Result());
    #endregion
    public string Result() { var obj = Calc(); if (obj is bool) return (bool)obj ? "Yes" : "No"; if (obj is double) return ((double)obj).ToString("0.####################"); return obj.ToString(); }
    private object Calc()
    {

        N = cr;
        arr = cr.Repeat(N);
        brr = cr.Repeat(N);
        var crr = arr.Prepend(arr[N - 1]).Zip(arr, (x, y) => x ^ y).ToArray();
        var drr = brr.Prepend(brr[N - 1]).Zip(brr, (x, y) => x ^ y).ToArray();
        crr = crr.Concat(crr.Take(N - 1)).ToArray();
        //Console.WriteLine(AllJoin(crr));
        //Console.WriteLine(AllJoin(drr));
        var kmp = new KMP(drr);
        var res = new List<Pair>();
        foreach (var k in kmp.Matches(crr))
        {
            res.Add(new Pair { k = k, x = brr[0] ^ arr[k] });
        }
        res.Sort();
        return AllLines(res);
    }
    int N;
    int[] arr;
    int[] brr;
}
