class KMP
{
    int[] pattern;
    int[] table;
    public KMP(int[] pattern) { this.pattern = pattern; table = CreateTable(pattern); }
    static int[] CreateTable(int[] pattern)
    {
        var table = new int[pattern.Length + 1];
        table[0] = -1;
        int j = -1;
        for (int i = 0; i < pattern.Length; i++)
        {
            while (j >= 0 && pattern[i] != pattern[j]) j = table[j];
            table[i + 1] = ++j;
        }
        return table;
    }

    public IEnumerable<int> Matches(int[] target)
    {
        for (int i = 0, p = 0; i < target.Length;)
        {
            if (target[i] == pattern[p])
            { i++; p++; }
            else if (p == 0)
                i++;
            else
                p = table[p];

            if (p == pattern.Length)
            {
                yield return i - p;
                p = table[p];
            }
        }
    }
}

