    public class Program
    {
        [System.Diagnostics.DebuggerBrowsable(System.Diagnostics.DebuggerBrowsableState.Never)] private ConsoleReader cr;
        public Program(ConsoleReader consoleReader) { this.cr = consoleReader; }
        static void Main() => Console.WriteLine(new Program(new ConsoleReader(Console.In)).Calc());

        #endregion
        public object Calc()
        {
            var N = cr.Int;
            var a = cr.Split.Int;
            var b = cr.Split.Int;

            var aDiff = new int[2 * N - 1];
            var bDiff = new int[N];

            for (var j = 0; j < N - 1; j++)
            {
                aDiff[j] = aDiff[j + N] = a[j] ^ a[j + 1];
                bDiff[j] = b[j] ^ b[j + 1];
            }
            aDiff[N - 1] = a[0] ^ a[N - 1];
            bDiff[N - 1] = b[0] ^ b[N - 1];

            var table = CreateTable(bDiff);
            var ks = new List<int>();

            int i = 0;
            int p = 0;
            // 文字列探索
            while (i < aDiff.Length)
            {
                while (p < bDiff.Length)
                {
                    if (aDiff[i] == bDiff[p])
                    {
                        i++; p++;
                    }
                    else if (p != 0)
                    {
                        p = table[p];
                    }
                    else break;
                }
                if (p == bDiff.Length)
                {
                    ks.Add(i - p);
                    p = table[p];
                }
            }

            foreach (var k in ks)
            {
                Console.WriteLine($"{k} {b[0] ^ a[k]}");
            }

            return "";
        }
        int[] CreateTable(int[] search)
        {
            var table = new int[search.Length + 1];
            table[0] = 0;

            var j = 0;
            for (int i = 1; i < search.Length; i++)
            {
                if (search[i] == search[j])
                {
                    table[i] = j++;
                }
                else
                {
                    table[i] = j;
                    j = 0;
                }
            }
            table[search.Length] = j;
            return table;
        }
    }
}

