class Solver
{
    public void Solve(Scanner sc)
    {
        var N = sc.Int;
        var A = sc.ArrInt;
        var B = sc.ArrInt;
        StringBuilder sa = new StringBuilder(), sb = new StringBuilder();
        var idx = new int[N];
        for (int i = 0; i < N; i++)
        {
            int a = A[i] ^ A[(i - 1 + N) % N], b = B[i] ^ B[(i - 1 + N) % N];
            idx[i] = sa.Length;
            sa.Append(a.ToString() + '|');
            sb.Append(b.ToString() + '|');
        }
        var ra = new RollingHash(sa.ToString() + sa.ToString());
        var rb = new RollingHash(sb.ToString());
        for(int i = 0; i < N; i++)
        {
            if (ra.GetHash(idx[i], idx[i] + sa.Length) == rb.GetHash())
            {
                WriteLine($"{i} {A[i] ^ B[0]}");
            }
        }

    }
}

public class RollingHash
{
    public string str { get; }
    private ulong[] hashTable;
    private static ulong[] pow;
    private static uint Base { get; }
    const ulong MASK30 = (1UL << 30) - 1;
    const ulong MASK31 = (1UL << 31) - 1;
    private const ulong MOD = (1UL << 61) - 1;
    public RollingHash(string str)
    {
        this.str = str;
        hashTable = new ulong[str.Length + 1];
        for (var j = 1; j <= str.Length; j++)
            hashTable[j] = CalcMod(Mul(hashTable[j - 1], Base) + str[j - 1]);
    }
    static RollingHash()
    {
        var rnd = new Random(); int min = 150, max = int.MaxValue;
        Base = (uint)rnd.Next(min, max);
        pow = new ulong[1001001];
        pow[0] = 1;
        for (var j = 1; j < pow.Length; j++)
            pow[j] = Mul(pow[j - 1], Base);
    }

    private static ulong Mul(ulong a, ulong b)
    {
        var au = a >> 31;
        var ad = a & MASK31;
        var bu = b >> 31;
        var bd = b & MASK31;
        var mid = ad * bu + au * bd;
        var midu = mid >> 30;
        var midd = (mid & MASK30);
        return CalcMod(au * bu * 2 + midu + (midd << 31) + ad * bd);
    }
    private static ulong CalcMod(ulong val)
    {
        val = (val & MOD) + (val >> 61);
        if (val > MOD) val -= MOD;
        return val;
    }

    public ulong GetHash(int l = 0, int r = -1)
    {
        if (r < 0) r = str.Length;
        return CalcMod(hashTable[r] + MOD * ((1UL << 3) - 1) - Mul(hashTable[l], pow[r - l]));
    }
}
