public class Kmp {
    public static int[] CreateKmpTable<T>(IList<T> s) where T : IEquatable<T> {
        int[] table = new int[s.Count];
        table[0] = 0;
        for (int i = 1; i < s.Count; i++) {
            int failure = table[i - 1];
            while (failure > 0 && !s[i].Equals(s[failure])) {
                failure = table[failure - 1];
            }

            if (s[i].Equals(s[failure])) {
                failure++;
            }

            table[i] = failure;
        }
        return table;
    }

    public static List<int> GetMatchIndexes<T>(IList<T> s, IList<T> pattern) where T : IEquatable<T> {
        return GetMatchIndexes(s, CreateKmpTable(pattern), pattern);
    }

    public static List<int> GetMatchIndexes<T>(IList<T> s, int[] kmpTable, IList<T> pattern) where T : IEquatable<T> {
        int k = 0;
        var matchIndex = new List<int>();
        for (int i = 0; i < s.Count; i++) {
            while (k > 0 && !pattern[k].Equals(s[i])) k = kmpTable[k - 1];
            if (pattern[k].Equals(s[i]) && ++k == pattern.Count) {
                matchIndex.Add(i - pattern.Count + 1);
                k = kmpTable[k - 1];
            }
        }
        return matchIndex;
    }

    public static int FindPeriod<T>(IList<T> s) where T : IEquatable<T> {
        if (s.Count == 0) {
            return 0;
        }

        int[] table = CreateKmpTable(s);
        return s.Count - table[s.Count - 1];
    }

    public static int FindPeriod(string s) {
        return FindPeriod(s.ToCharArray());
    }

    public static List<int> GetMatchIndexes(string s, string pattern) {
        return GetMatchIndexes(s.ToCharArray(), pattern.ToCharArray());
    }
}
