public static class P
{
    public static void Main()
    {
        int n = int.Parse(Console.ReadLine());
        var a = Console.ReadLine().Split().Select(uint.Parse).ToArray();
        var b = Console.ReadLine().Split().Select(uint.Parse).ToArray();
        //奇数なら固定 偶数なら任意
        var xorDiff = a.Aggregate((x, y) => x ^ y) ^ b.Aggregate((x, y) => x ^ y);
        List<Tuple<int, int>> res = new List<Tuple<int, int>>();
        if (n % 2 == 1)
        {
            for (int i = 0; i < n; i++)
                a[i] ^= xorDiff;
            ModInt hashA = 0;
            ModInt hashB = 0;
            for (int i = 0; i < n; i++)
            {
                hashA = hashA * ModInt.Base + a[i];
                hashB = hashB * ModInt.Base + b[i];
            }
            for (int i = n - 1; i >= 0; i--)
            {
                if (hashA.data == hashB.data)
                {
                    res.Add(new Tuple<int, int>(i, (int)xorDiff));
                }
                hashA = (hashA - (a[n - i - 1] * ModInt.powMemo[n - 1])) * ModInt.Base + a[n - i - 1];
            }
        }
        else
        {
            int[] shifts = new int[n];
            for (int i = 0; i < 30; i++)
            {
                ModInt hashA = 0;
                ModInt hashARev = 0;
                ModInt hashB = 0;
                for (int j = 0; j < n; j++)
                {
                    var abit = (a[j] >> i & 1);
                    var bbit = (b[j] >> i & 1);
                    hashA = hashA * ModInt.Base + abit;
                    hashARev = hashARev * ModInt.Base + (abit ^ 1);
                    hashB = hashB * ModInt.Base + bbit;
                }
                for (int j = n - 1; j >= 0; j--)
                {
                    if (0 <= shifts[j])
                    {
                        if (hashA.data == hashB.data) ;
                        else if (hashARev.data == hashB.data) shifts[j] |= 1 << i;
                        else shifts[j] = -1;
                    }

                    var bit = (a[n - j - 1] >> i & 1);
                    hashA = (hashA - (bit * ModInt.powMemo[n - 1])) * ModInt.Base + bit;
                    hashARev = (hashARev - ((bit ^ 1) * ModInt.powMemo[n - 1])) * ModInt.Base + (bit ^ 1);
                }
            }
            for (int i = 0; i < shifts.Length; i++)
            {
                if (shifts[i] < 0) continue;
                res.Add(new Tuple<int, int>(n - i - 1, shifts[i]));
            }
        }
        res.Reverse();
        Console.WriteLine(string.Join("\n", res.Select(x => $"{x.Item1} {x.Item2}")));
    }
}


class FoldableQueue<T>
{
    public int Count { get; private set; }
    public T Value
    {
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        get
        {
            return
                TailValueStack.Count == 0 ? FrontValue :
                FrontIsEmpty ? TailValueStack.Peek() :
                Merge(TailValueStack.Peek(), FrontValue);
        }
    }

    bool FrontIsEmpty = true;
    T FrontValue;
    Stack<T> Fronts = new Stack<T>();
    Stack<T> TailValueStack = new Stack<T>();

    Func<T, T, T> Merge;

    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    public FoldableQueue(Func<T, T, T> merge) { Merge = merge; }

    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    public void Pop()
    {
        Validate();
        if (TailValueStack.Count == 0) Move();
        TailValueStack.Pop();
        Count--;
    }

    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    public void Push(T item)
    {
        Fronts.Push(item);
        Count++;
        FrontValue = FrontIsEmpty ? item : Merge(FrontValue, item);
        FrontIsEmpty = false;
    }

    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    private void Move()
    {
        TailValueStack.Push(Fronts.Pop());
        while (0 < Fronts.Count)
            TailValueStack.Push(Merge(Fronts.Pop(), TailValueStack.Peek()));
        FrontIsEmpty = true;
    }

    private void Validate() { if (Count == 0) throw new Exception(); }
}

class ModInt
{
    const ulong MASK30 = (1UL << 30) - 1;
    const ulong MASK31 = (1UL << 31) - 1;
    const ulong MOD = (1UL << 61) - 1;
    const ulong POSITIVIZER = MOD * ((1UL << 3) - 1);
    public static ModInt Base;
    public static ModInt[] powMemo = new ModInt[500000 + 1];
    static ModInt()
    {
        Base = (ulong)new Random().Next(1 << 30, int.MaxValue);
        //Base = 10;
        powMemo[0] = 1;
        for (int i = 1; i < powMemo.Length; i++)
            powMemo[i] = powMemo[i - 1] * Base;
    }
   public  ulong data;
    public ModInt(ulong n) { data = CalcMod(n); }
    public static ulong operator *(ModInt l, ModInt r) => Mul(l.data, r.data);
    public static ulong Mul(ulong l, ulong r)
    {
        var lu = l >> 31;
        var ld = l & MASK31;
        var ru = r >> 31;
        var rd = r & MASK31;
        var middleBit = ld * ru + lu * rd;
        return CalcMod(((lu * ru) << 1) + ld * rd + ((middleBit & MASK30) << 31) + (middleBit >> 30));
    }
    public static ulong operator +(ModInt l, ModInt r) => CalcMod(l.data + r.data);
    public static ulong operator -(ModInt l, ModInt r) => CalcMod(l.data + POSITIVIZER - r.data);
    public static implicit operator ulong(ModInt n) => n.data;
    public static implicit operator ModInt(ulong n) => new ModInt(n);

    public static ulong CalcMod(ulong val)
    {
        val = (val & MOD) + (val >> 61);
        if (val >= MOD) val -= MOD;
        return val;
    }

    public override string ToString() => data.ToString();
}

using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;
using System.Diagnostics;

namespace AtCoder
{
    class Program
    {
        private static string Read() { return Console.ReadLine(); }
        private static int ReadInt() { return int.Parse(Read()); }
        private static long ReadLong() { return long.Parse(Read()); }
        private static double ReadDouble() { return double.Parse(Read()); }
        private static int[] ReadInts() { return Array.ConvertAll(Read().Split(), int.Parse); }
        private static long[] ReadLongs() { return Array.ConvertAll(Read().Split(), long.Parse); }
        private static double[] ReadDoubles() { return Array.ConvertAll(Read().Split(), double.Parse); }

        static bool Cyclic(int n, int[] C)
        {
            int N = C.Length;
            for (int i = n; i < N; ++i)
            {
                if (C[i] != C[i % n]) { return false; }
            }
            return true;
        }

        static int Cycle(int[] C)
        {
            int N = C.Length;
            for (int i = 1; i <= N; ++i)
            {
                if (N % i == 0 && Cyclic(i, C)) { return i; }
            }
            return N;
        }

        static bool Perfect(int[] A, int[] B, int n)
        {
            int N = A.Length;
            int xor = A[n] ^ B[0];
            for (int i = 1; i < N; ++i)
            {
                if ((A[(n + i) % N] ^ B[i]) != xor) { return false; }
            }
            return true;
        }

        static int[][] Solve(int N, int[] A, int[] B)
        {
            int[] C = Enumerable.Range(0, N).Select(i => A[i] ^ B[i]).ToArray();
            int cycle = Cycle(C);
            var ans = new List<int[]>();
            for (int i = 0; i < cycle; ++i)
            {
                if (Perfect(A, B, i))
                {
                    for (int j = i; j < N; j += cycle)
                    {
                        ans.Add(new int[] { j, A[j] ^ B[0] });
                    }
                    break;
                }
            }
            return ans.ToArray();
        }

        static void Main(string[] args)
        {
            int N = ReadInt();
            int[] A = ReadInts();
            int[] B = ReadInts();
            var ans = Solve(N, A, B);
            foreach (var a in ans)
            {
                Console.WriteLine(string.Join(" ", a));
            }
        }
    }
}

using System;
using System.Collections.Generic;
using System.IO;
