using System;

public class Program
{
    private int N;
    private int[] A, B;

    public void Solve()
    {
        var sc = new Scanner();
        N = sc.NextInt();
        A = sc.IntArray();
        B = sc.IntArray();
// Aをk個ずらす　xとxor bと一致

        for (int k = 0; k < N; k++)
        {
            bool f = true;
