package main

import "fmt"

const D int = 30

func to_binary_matrix(a []int, N int) [][D]bool {
	A := make([][D]bool, N)
	for i := 0; i < N; i++ {
		A[i] = [D]bool{}
		for d := 0; d < D; d++ {
			A[i][d] = a[i]%2 == 1
			a[i] /= 2
			if a[i] == 0 {
				break
			}
		}
	}
	return A
}

func print_binary_matrix(A [][D]bool, N int) {
	for i := 0; i < N; i++ {
		for d := D - 1; d >= 0; d-- {
			x := 0
			if A[i][d] {
				x = 1
			}
			fmt.Printf("%d ", x)
		}
		fmt.Println()
	}
}

func to_int(x [D]bool) int {
	y := 0
	if x[D-1] {
		y = 1
	}
	for d := D - 2; d >= 0; d-- {
		if x[d] {
			y = y*2 + 1
		} else {
			y = y * 2
		}

	}
	return y
}

func calc_x(a, b [D]bool) [D]bool {
	x := [D]bool{}
	for d := 0; d < D; d++ {
		x[d] = a[d] != b[d]
	}
	return x
}

func check_x(a, b, x [D]bool) bool {
	for d := 0; d < D; d++ {
		if (a[d] != b[d]) != x[d] {
			return false
		}
	}
	return true
}

func check_x_digit(a, b, x [D]bool, dd int) bool {
	return (a[dd] != b[dd]) == x[dd]
}

func main() {
	var N int
	fmt.Scan(&N)
	a := make([]int, N)
	for i := 0; i < N; i++ {
		fmt.Scan(&a[i])
	}
	b := make([]int, N)
	for i := 0; i < N; i++ {
		fmt.Scan(&b[i])
	}

	A := to_binary_matrix(a, N)
	B := to_binary_matrix(b, N)

	for k := 0; k < N; k++ {
		// calc x
		x := calc_x(A[k], B[0])

		// check
		ok := true
		if N > D {
			// probabilistic
			for j := 1; j < D; j++ {
				if !check_x_digit(A[(k+j)%N], B[j], x, (7*j)%D) {
					ok = false
					break
				}
				if !check_x_digit(A[(k+j)%N], B[j], x, (13*j)%D) {
					ok = false
					break
				}
			}
		} else {
			// deterministic
			for j := 1; j < N; j++ {
				if !check_x(A[(k+j)%N], B[j], x) {
					ok = false
					break
				}
			}
		}

		if ok {
			fmt.Printf("%d %d\n", k, to_int(x))
		}
	}
}

