func equal(k int, c, d []int) (bool, int) {
	n := len(c)
	s := 1
	for i := range c {
		if d[i] != c[(i+k)%n] {
			return false, s
		}
	}
	return true, s
}

func xorArr(a []int) []int {
	n := len(a)
	c := make([]int, n, n)
	for i := range a {
		c[i] = a[i] ^ a[(i+1)%n]
	}
	return c
}

