import "fmt"

const D int = 30

func xor(a, b int) int {
	v := [D]bool{}
	for d := 0; d < D; d++ {
		v[d] = (a%2 == 1) != (b%2 == 1)
		a /= 2
		b /= 2
		if a == 0 && b == 0 {
			break
		}
	}

	y := 0
	if v[D-1] {
		y = 1
	}
	for d := D - 2; d >= 0; d-- {
		if v[d] {
			y = y*2 + 1
		} else {
			y = y * 2
		}

	}

	return y
}

func kmp_table(W []int, N int) []int {
	T := make([]int, N+1)
	i, j := 2, 0
	T[0], T[1] = -1, 0
	for i < N+1 {
		if W[i-1] == W[j] {
			T[i] = j + 1
			i++
			j++
		} else if j > 0 {
			j = T[j]
		} else {
			T[i] = 0
			i++
		}
	}
	return T
}

func kmp_search(S, W []int, N int) []int {
	var list_k []int
	// len(S') = 2N - 1,  S'[m] = S[m%N]
	m, i := 0, 0
	T := kmp_table(W, N)

	// fmt.Print("T: ")
	// for i := 0; i < N+1; i++ {
	// 	fmt.Printf("%d ", T[i])
	// }
	// fmt.Println()

	for m < N {
		if W[i] == S[(m+i)%N] {
			i++
			if i == N {
				list_k = append(list_k, m)
			} else {
				continue
			}
		}
		m = m + i - T[i]
		if i > 0 {
			i = T[i]
		}
	}
	return list_k
}

func main() {
	var N int
	fmt.Scan(&N)
	A := make([]int, N)
	for i := 0; i < N; i++ {
		fmt.Scan(&A[i])
	}
	B := make([]int, N)
	for i := 0; i < N; i++ {
		fmt.Scan(&B[i])
	}
	C := make([]int, N)
	for i := 0; i < N; i++ {
		C[i] = A[i] ^ A[(i+1)%N] // xor(A[i], A[(i+1)%N])
	}
	D := make([]int, N)
	for i := 0; i < N; i++ {
		D[i] = B[i] ^ B[(i+1)%N] // xor(B[i], B[(i+1)%N])
	}

	k_list := kmp_search(C, D, N)

	for _, k := range k_list {
		x := A[k] ^ B[0] // xor(A[k], B[0])
		fmt.Printf("%d %d\n", k, x)
	}
}

