			bbit[j] = b[j] >> uint(i) & 1
		}
		bbit = append(bbit, -1)

		memo1[i] = zalgorithm(append(bbit, abit1...))[n+1 : n+n+1]
		memo2[i] = zalgorithm(append(bbit, abit2...))[n+1 : n+n+1]
