var reader = bufio.NewReaderSize(os.Stdin, 1000000)
var writer = bufio.NewWriter(os.Stdout)
func NextLine() string {
  buffer := make([]byte, 0)
  for true {
    line, isPrefix, err := reader.ReadLine()
    if err != nil { panic(err) }
    buffer = append(buffer, line...)
    if !isPrefix { break }
  }
  return string(buffer)
}
func NextInt() int {
  n, _ := strconv.Atoi(NextLine())
  return n
}
func NextIntVec() []int {
  L := strings.Split(NextLine(), " ")
  N := make([]int, len(L))
  for i := range N {
    N[i], _ = strconv.Atoi(L[i])
  }
  return N
}
func Write(s interface{}) {
  fmt.Fprintln(writer, s)
}
func WriteIntVec(A []int) {
  S := make([]string, len(A))
  for i, a := range A {
    S[i] = strconv.Itoa(a)
  }
  Write(strings.Join(S, " "))
}
func Output() {
  _ = writer.Flush()
}

func KMP(A, B []interface{}) []int {
  N := len(B)
  PMT := make([]int, N + 1)
  PMT[0] = -1
  for i, j := 2, 0; i <= N; {
    if B[i - 1] == B[j] {
      PMT[i] = j + 1
      i++
      j++
    } else if 0 < j {
      j = PMT[j]
    } else {
      PMT[i] = 0
      i++
    }
  }
  M := make([]int, 0)
  for i, j := 0, 0; i + j < len(A); {
    if A[i + j] == B[j] {
      j++
      if j == N {
        M = append(M, i)
        i += N - PMT[N]
        j = PMT[j]
      }
    } else {
      i += j - PMT[j]
      if 0 < j { j = PMT[j] }
    }
  }
  return M
}

func main() {
  N := NextInt()
  A := NextIntVec()
  B := NextIntVec()
  XA := make([]interface{}, N)
  XB := make([]interface{}, N)
  for i, a := range A {
    XA[i] = a ^ A[(i + 1) % N]
    XB[i] = B[i] ^ B[(i + 1) % N]
  }
  XA = append(XA, XA...)
  K := KMP(XA, XB)
  for _, k := range K {
    if N <= k { break }
    x := A[k] ^ B[0]
    WriteIntVec([]int{k, x})
  }
  Output()
}

