func solve(scanner *bufio.Scanner, writer *bufio.Writer) {
	n := getNextInt(scanner)
	aa := make([]int, n)
	xa := make([]int, n)
	bb := make([]int, n)
	xb := make([]int, n)

	for i := 0; i < n; i++ {
		aa[i] = getNextInt(scanner)
	}
	for i := 0; i < n; i++ {
		xa[i] = aa[i] ^ aa[(i+1)%n]
	}
	for i := 0; i < n; i++ {
		bb[i] = getNextInt(scanner)
	}
	for i := 0; i < n; i++ {
		xb[i] = bb[i] ^ bb[(i+1)%n]
	}

	table := make([]int, n+1)
	table[0] = -1
	j := -1
	for i := 0; i < n; i++ {
		for j >= 0 && xb[i] != xb[j] {
			j = table[j]
		}
		j++
		table[i+1] = j
	}

	j = 0
	for i := 0; i < n*2; i++ {
		if j == n {
			fmt.Fprintln(writer, fmt.Sprintf("%d %d", i%n, aa[i%n]^bb[0]))
			j = table[j]
		}
		for j >= 0 && xa[i%n] != xb[j] {
			j = table[j]
		}
		j++
	}
}

