func zalgorithm(s []int) []int {
	n := len(s)
	res := make([]int, n)
	i, j := 1, 0
	res[0] = n
	for i < n {
		for i+j < n && s[j] == s[i+j] {
			j++
		}
		res[i] = j
		if j == 0 {
			i++
			continue
		}
		k := 1
		for i+k < n && k+res[k] < j {
			res[i+k] = res[k]
			k++
		}
		i += k
		j -= k
	}
	return res
}

