def z_algo(S: str) -> list:
    N = len(S)
    if N == 0:
        return []
    ln = [0] * N
    ln[0] = N  
    i = 1
    w = 0
    while i < N:
        while i + w < N and S[w] == S[i + w]:
            w += 1
        ln[i] = w  
        if w == 0:
            i += 1
        else:
            j = 1
            while i + j < N and j + ln[j] < w:
                ln[i+j] = ln[j]
                j += 1
            i += j
            w -= j
    return ln

