class BMSearch:
	def __init__(self, target, pattern):
		self.target = target
		self.pattern = pattern
		self.__table = self.__create_BM_table()

	def search(self, start=0):

		if len(self.pattern) > len(self.target):
			return -1

		i = len(self.pattern) - 1 + start
		p = len(self.pattern) - 1
		while i < len(self.target):
			if self.pattern[p] == self.target[i]:
				i -= 1
				p -= 1

				if p == -1:
					return i + 1
			else:
				t = self.__table[self.target[i]] if (self.target[i] in self.__table) else len(self.pattern)
				i += max(t, len(self.pattern) - p)
				p = len(self.pattern) - 1

		return -1

	def __create_BM_table(self):
		table = {}

		for i in range(len(self.pattern)):
			table[self.pattern[i]] = len(self.pattern) - i - 1

		return table

