    m = len(word)
    ret = [0] * (m + 1)
    cur = 0
    for i in range(1, m):
        ret[i] = cur
        if word[i] == word[cur]:
            cur += 1
        else:
            cur = 0
    ret[m] = cur
    return ret

def kmp(word, doc):
    table = make_kmp_table(word)
    ret = []
    n = len(doc)
    m = len(word)
    i, p = 0, 0
    while i < n:
        if doc[i] == word[p]:
            i += 1
            p += 1
            if p == m:
                ret.append(i - m)
                p = table[m]
        elif p > 0:
            p = table[p]
        else:
            i += 1
    return ret

def solve(N: int, a: "List[int]", b: "List[int]"):
    tmp = [[-1 for _ in range(N)] for _ in range(32)]
    for i in range(32):
        a_bits = [(v & (1 << i)) > 0 for v in a]
        b_bits = [(v & (1 << i)) > 0 for v in b]
        pos = kmp(a_bits, b_bits + b_bits)
        for p in pos:
            tmp[i][(N - p) % N] = 0
        a_bits = [not v for v in a_bits]
        pos = kmp(a_bits, b_bits + b_bits)
        for p in pos:
            tmp[i][(N - p) % N] = 1

