        for i in range(N):
            if k_cand[i]:
                k_cand[i] = Z2[i+N+1] == N or Z1[i+N+1] == N
        # print(k_cand)

    for i in range(N):
        if k_cand[i]:
            print(i, b[0] ^ a[i])
    return


