def contain(T, S):
    # TはSに含まれているか
    if len(T) > len(S):
        return len(S)
    t = 1
    for i in range(len(T)):
        t *= B
        t %= MOD
    th, sh = 0, 0
    for i in range(len(T)):
        th = th*B+T[i]
        th %= MOD
    for i in range(len(T)):
        sh = sh*B+S[i]
        sh %= MOD

    for i in range(len(S)-len(T)):
        if th == sh:
            if T == S[i:i+len(T)]:
                return i
        if i + len(T) < len(S):
            sh = sh*B+S[i+len(T)]-S[i]*t
            sh %= MOD
    return len(S)


def solve(N: int, a: "List[int]", b: "List[int]"):

    K = [True]*N
    for i in range(3):
        a_pat = []
        a_pat2 = []
        b_pat = []
        for n, (aa, bb) in enumerate(zip(a, b)):
            a_pat.append((aa >> i) & 1)
            a_pat2.append(1-((aa >> i) & 1))
            b_pat.append((bb >> i) & 1)
        b_pat = b_pat*2
        cand = [False]*(2*N)
        cand2 = [False]*(2*N)
        j = -1
        while j < N:
            j = j+1+contain(a_pat, b_pat[j+1:])
            if j < 2*N:
                cand[j] = True
        j = -1
        while j < N:
            j = j+1+contain(a_pat2, b_pat[j+1:])
            if j < 2*N:
                cand2[j] = True
        for j in range(N):
            if cand[j] == False and cand2[j] == False:
