import sys
from pprint import pprint
sys.setrecursionlimit(300000)

def make_kmp_table(word):
    m = len(word)
    ret = [0] * (m + 1)
    cur = 0
    for i in range(1, m):
        ret[i] = cur
        if word[i] == word[cur]:
            cur += 1
        else:
            cur = 0
    ret[m] = cur
    return ret

def kmp(word, doc):
    table = make_kmp_table(word)
    ret = []
    n = len(doc)
    m = len(word)
    i, p = 0, 0
    while i < n:
        if doc[i] == word[p]:
            i += 1
            p += 1
            if p == m:
                ret.append(i - m)
                p = table[m]
        elif p > 0:
            p = table[p]
        else:
            i += 1
    return ret

def solve(N: int, a: "List[int]", b: "List[int]"):
    tmp = [[-1 for _ in range(N)] for _ in range(32)]
    for i in range(32):
        a_bits = [1 if v & (1 << i) else 0 for v in a]
        b_bits = [1 if v & (1 << i) else 0 for v in b]
        s_a = sum(a_bits)
        s_b = sum(b_bits)
        if s_a == s_b:
            pos = kmp(a_bits, b_bits + b_bits)
            for p in pos:
                tmp[i][(N - p) % N] = 0
        if N - s_a == s_b:
            a_bits = [0 if v else 1 for v in a_bits]
            pos = kmp(a_bits, b_bits + b_bits)
            for p in pos:
                tmp[i][(N - p) % N] = 1

    #pprint(tmp)
    for i in range(N):
        ret = 0
        for j in range(32):
            if tmp[j][i] < 0:
                break
            else:
                ret += (2 ** j) * tmp[j][i]
        else:
            print(i, ret)
    return

