def kmp_search(T, P):
    m = len(P)
    matches = []
    pi = compute_prefix_func(P)
    q = 0  # number of characters matched
    for i, t in enumerate(T):
        while q > 0 and P[q] != t:
            q = pi[q]  # next character does not match
        if P[q] == t:
            q += 1     # next character matches
        if q == m:
            matches.append(i - (m - 1))
            q = pi[q]  # look for the next match
    return matches

def compute_prefix_func(P):
    m = len(P)
    pi = [0] * (m + 1)
    k = 0
    for q in range(1, m):
        while k > 0 and P[k] != P[q]:
            k = pi[k]
        if P[k] == P[q]:
            k += 1
        pi[q + 1] = k
    return pi

    # pi : {1,2,...,m} -> {0,1,...,m-1}
    # pi[q] = max {k : k < q and P[:q].endswith(P[:k])}

