fn kmp_table<T: Eq>(pattern: &[T], m: usize, mut kmp: Vec<usize>) -> Vec<usize> {
    let mut len: usize = 0;
    kmp[0] = 0;
    let mut i: usize = 1;
    while i < m {
        if pattern[i] == pattern[len] {
            len = len + 1;
            kmp[i] = len;
            i = i + 1;
        } else {
            if len != 0 {
                len = kmp[len - 1];
            } else {
                kmp[i] = 0;
                i = i + 1;
            }
        }
    }
    kmp
}

fn kmp<T: Eq>(string: &[T], pattern: &[T]) -> Option<usize> {
    let n = string.len();
    let m = pattern.len();
    let kmp = kmp_table(pattern, m, vec![0usize; m]);
    let mut i: usize = 0;
    let mut j: usize = 0;
    while i < n {
        if pattern[j] == string[i] {
            i = i + 1;
            j = j + 1;
        }
        if j == m {
            return Some(i - j);
        } else if i < n && pattern[j] != string[i] {
            if j != 0 {
                j = kmp[j - 1];
            } else {
                i = i + 1;
            }
        }
    }
    None
}

fn main() {
    input! {
        n: usize,
        a: [i32; n],
        b: [i32; n],
    }

    let mut xa = a.clone();
    let mut xb = b.clone();

    for i in 0..n {
        xa[i] = a[i] ^ a[(i + 1) % n];
        xb[i] = b[i] ^ b[(i + 1) % n];
    }

    let mut xxa = xa.clone();
    for r in xa.iter() {
        xxa.push(*r);
    }

    let ix = kmp(&xxa, &xb);

    if ix == None {
        return;
    }

    let ix = ix.unwrap();

    let mut sol = vec![false; n];

    for span in 1..n + 1 {
        if n % span != 0 {
            continue;
        }

        let rep = n / span;
        let mut ok = true;
        for i in 0..span {
            let c = xa[i];
            for j in 1..rep {
                if c != xa[i + j * span] {
                    ok = false;
                    break;
                }
            }
            if !ok {
                break;
            }
        }

        if !ok {
            continue;
        }

        for i in 0..rep {
            sol[(ix + i * span) % n] = true;
        }
    }

    for i in 0..n {
        if sol[i] {
            let cur = a[i] ^ b[0];
            println!("{} {}", i, cur);
        }
    }
}

