struct MP {
    next: Vec<i32>,
}

impl MP {
    fn new(s: &Vec<usize>) -> MP {
        let n = s.len();
        let mut next = Vec::with_capacity(n + 1);
        next.push(-1);
        let mut j = -1;
        for i in 0..n {
            while j >= 0 && s[i] != s[j as usize] {
                j = next[j as usize];
            }
            j += 1;
            next.push(j);
        }

        MP { next }
    }
}

