fn kmp_tab(s: &[usize]) -> Vec<usize> {
    let m = s.len();
    let mut tab: Vec<usize> = vec![0; m + 1];
    let mut i = 2;
    let mut j = 0;
    while i <= m {
        if s[i - 1] == s[j] {
            tab[i] = j + 1;
            i += 1;
            j += 1;
        } else if j > 0 {
            j = tab[j];
        } else {
            i += 1;
        }
    }
    tab
}

fn kmp_all(s: &[usize], sub: &[usize]) -> Vec<usize> {
    let m = sub.len();
    let tab = kmp_tab(sub);
    let mut ret = vec![];
    let mut i = 0;
    let mut j = 0;
    while i + j < s.len() {
        if sub[j] == s[i + j] {
            j += 1;
            if j == m {
                ret.push(i);
                i += j - tab[j];
                j = tab[j];
            }
        } else {
            if j == 0 {
                i += 1;
            } else {
                i += j - tab[j];
                j = tab[j];
            }
        }
    }
    ret
}

