const MOD: i64 = 1_000_000_007;
define_mod!(P, MOD);
type ModInt = mod_int::ModInt<P>;

fn solve() {
    let out = std::io::stdout();
    let mut out = BufWriter::new(out.lock());
    macro_rules! puts {
        ($($format:tt)*) => (write!(out,$($format)*).unwrap());
    }
    input! {
        n: usize,
        a: [i32; n],
        b: [i32; n],
    }
    let base = ModInt::new(31415);
    let mut ax = vec![ModInt::new(0); 2 * n + 1];
    let mut bx = vec![ModInt::new(0); n + 1];
    for i in 0..2 * n {
        ax[i + 1] = ax[i] * base + ((a[i % n] ^ a[(i + 1) % n]) as i64);
    }
    for i in 0..n {
        bx[i + 1] = bx[i] * base + ((b[i] ^ b[(i + 1) % n]) as i64);
    }
    let mut ans = vec![];
    let bn = base.pow(n as i64);
    for k in 0..n {
        if ax[k] * bn - ax[k + n] == bx[0] * bn - bx[n] {
            ans.push((k, a[k] ^ b[0]));
        }
    }
    for (k, x) in ans {
        puts!("{} {}\n", k, x);
    }
}

