	let mut out = std::io::BufWriter::new(out.lock());
	for i in n..2 * n {
		if z[i] >= n - 1 {
			writeln!(out, "{} {}", i - n, b[0] ^ a[i - n]).unwrap();
		}
	}
}

pub fn z_algorithm<T>(s: &[T]) -> Vec<usize>
where
	T: Ord,
{
	if s.len() == 0 {
		Vec::new()
	} else {
		let mut r = vec![0; s.len()];
		let mut j = 0;
		for i in 1..s.len() {
			r[i] = if j + r[j] <= i {
				0
			} else {
				std::cmp::min(j + r[j] - i, r[i - j])
			};
			while i + r[i] < s.len() && s[r[i]] == s[i + r[i]] {
				r[i] += 1;
			}
			if j + r[j] < i + r[i] {
				j = i;
			}
		}
		r[0] = s.len();
		r
	}
}

