// (z[idx] := longest common prefix of ([idx,n), [0,n))
fn z(a: &Vec<i64>) -> Vec<usize> {
    let n = a.len();
    let mut z = vec![0; n];
    if n == 0 {
        return z;
    }
    z[0] = n;
    let mut l = 0;
    let mut r = 0;
    for i in 1..n {
        if i > r {
            l = i;
            r = i;
            while r < n && a[r-l] == a[r] {
                r += 1;
            }
            z[i] = r - l;
            r -= 1;
        } else {
            let k = i-l;
            if z[k] < r-i+1 {
                z[i] = z[k];
            } else {
                l = i;
                while r < n && a[r-l] == a[r] {
                    r += 1;
                }
                z[i] = r-l;
                r -= 1;
            }
        }
    }
    z
}

fn main() {
    input! {
        n: usize,
        a: [i64; n],
        b: [i64; n]
    };

    let al = (0..n).map(|i| a[i] ^ a[(i+1)%n]).collect::<Vec<_>>();
    let bl = (0..n).map(|i| b[i] ^ b[(i+1)%n]).collect::<Vec<_>>();
    let mut list = vec![];
    list.append(&mut al.clone());
    list.push(-1);
    list.append(&mut bl.clone());
    list.append(&mut bl.clone());

    let zidx = z(&list);

    let mut ans = vec![];
    for i in n+1..2*n+1 {
        if zidx[i] == n {
            let k = (n-(i-n-1))%n;
            let w = a[k] ^ b[0];
            ans.push((k, w));
        }
    }
    ans.sort();
    for (k, w) in ans {
        println!("{} {}", k, w);
    }
}

