fn solve(s: &str) {
    let mut it = s.split_whitespace();
    parse!(it, n: usize, a: [usize; n], mut b: [usize; n]);
    let d = (0..n).map(|i| a[i] ^ a[(i + 1) % n]).collect::<Vec<_>>();
    let c = (0..n).map(|i| b[i] ^ b[(i + 1) % n]).collect::<Vec<_>>();
    let mut table = vec![0; n + 1];

    table[0] = !0;
    let mut j = !0usize;
    for i in 0..n {
        while j < c.len() && c[i] != c[j] {
            j = table[j]
        }
        j = j.wrapping_add(1);
        table[i + 1] = j;
    }

    let mut i = 0;
    let mut j = 0;
    let mut pos = vec![];
    while i < n {
        while j < n && c[j] == d[(i + j) % n] {
            j += 1;
        }
        if j == n {
            pos.push(i);
        }
        if j == 0 {
            i += 1;
        } else {
            i += j - table[j];
            j = table[j];
        }
    }
    for i in pos {
        println!("{} {}", i, a[i] ^ b[0]);
    }
}

