fn matches(mut a_bits: Vec<u8>, b_bits: Vec<u8>) -> Vec<Option<u8>> {
    let mut ans = vec![None; a_bits.len()];
    let cloned = a_bits.clone();
    a_bits.extend(cloned);
    let len = a_bits.len();
    a_bits.remove(len - 1);
    for i in a_bits.z_match_indices(&b_bits) {
        ans[i] = Some(0);
    }
    let b_bits_neg: Vec<u8> = b_bits.into_iter().map(|b| if b == 0 { 1 } else { 0 }).collect();
    for i in a_bits.z_match_indices(&b_bits_neg) {
        ans[i] = Some(1);
    }
    ans
}

