#[derive(Debug)]
struct KnuthMorrisPratt<T: Eq> {
    n: usize,
    pattern: Vec<T>,
    table: Vec<isize>,
}
impl<T: Eq> KnuthMorrisPratt<T> {
    fn new(pattern: Vec<T>) -> KnuthMorrisPratt<T> {
        let n = pattern.len();
        let mut table = vec![-1isize; n + 1];
        let mut j = 0;
        for i in 1..n {
            table[i] = j;
            j += if pattern[i] == pattern[j as usize] {
                1
            } else {
                -j
            };
        }
        table[n] = j;
        KnuthMorrisPratt {
            n: n,
            pattern: pattern,
            table: table,
        }
    }
    #[allow(dead_code)]
    fn search(&self, s: &Vec<T>) -> Option<usize> {
        let mut i = 0;
        let mut m = 0;
        while m + i < s.len() {
            if self.pattern[i] == s[m + i] {
                i += 1;
                if i != self.n {
                    continue;
                }
                return Some(m);
            }
            m = (m as isize + i as isize - self.table[i]) as usize;
            i = std::cmp::max(0, self.table[i]) as usize;
        }
        None
    }
    fn search_all(&self, s: &Vec<T>) -> Vec<usize> {
        let mut i = 0;
        let mut m = 0;
        let mut res = vec![];
        while m + i < s.len() {
            if self.pattern[i] == s[m + i] {
                i += 1;
                if i != self.n {
                    continue;
                }
                res.push(m);
            }
            m = (m as isize + i as isize - self.table[i]) as usize;
            i = std::cmp::max(0, self.table[i]) as usize;
        }
        res
    }
}
fn main() {
    input! { n, a: [usize; n], b: [usize; n] };
    let mut c = (0..n).map(|i| a[i] ^ a[(i + 1) % n]).collect::<Vec<_>>();
    let v = c.iter().take(n - 1).cloned().collect::<Vec<_>>();
    c.extend(v);
    let d = (0..n).map(|i| b[i] ^ b[(i + 1) % n]).collect::<Vec<_>>();
    let kmp = KnuthMorrisPratt::new(d);
    let res = kmp.search_all(&c);
    for r in res.into_iter() {
