use std::io::Write;

fn run() {
    let out = std::io::stdout();
    let mut out = std::io::BufWriter::new(out.lock());
    input! {
        n: usize,
        a: [usize; n],
        b: [usize; n],
    }
    let mut ans = vec![true; n];
    for k in 0usize..30 {
        let mut dp = vec![false; n];
        for x in 0usize..2 {
            let mut c = vec![];
            for a in b.iter() {
                c.push(x ^ ((a >> k) & 1));
            }
            c.push(2);
            for _ in 0..2 {
                for b in a.iter() {
                    c.push((b >> k) & 1);
                }
            }
            let z = z_algorithm(&c);
            for i in (n + 1)..(n + 1 + n) {
                if z[i] >= n {
                    dp[i - n - 1] = true;
                }
            }
        }
        for i in 0..n {
            ans[i] &= dp[i];
        }
    }
    for k in 0..n {
        if ans[k] {
            let x = a[k] ^ b[0];
            writeln!(out, "{} {}", k, x).ok();
        }
    }
}

fn main() {
    run();
}
